#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ElevationBrushMode {
    Target,
    Raise,
    Lower,
}

impl ElevationBrushMode {
    fn runtime_id(self) -> u8 {
        match self {
            Self::Target => 0,
            Self::Raise => 1,
            Self::Lower => 2,
        }
    }
}

impl Tool {
    fn runtime(self) -> RuntimeTool {
        match self {
            Self::Pan => RuntimeTool::Pan,
            Self::Terrain => RuntimeTool::Terrain,
            Self::Elevation => RuntimeTool::Elevation,
            Self::Territory => RuntimeTool::Territory,
            Self::Road => RuntimeTool::Road,
            Self::Place => RuntimeTool::Place,
            Self::Event => RuntimeTool::Event,
            Self::PlaceName => RuntimeTool::PlaceName,
        }
    }
}

