#[derive(Clone)]
struct CompactStrings {
    dictionary: Vec<String>,
    indices: Vec<u16>,
}

impl CompactStrings {
    fn pack(values: &[String]) -> Self {
        let mut dictionary = Vec::<String>::new();
        let mut lookup = std::collections::HashMap::<&str, u16>::new();
        let mut indices = Vec::with_capacity(values.len());
        for value in values {
            let index = if let Some(index) = lookup.get(value.as_str()).copied() {
                index
            } else {
                let index = u16::try_from(dictionary.len()).unwrap_or(u16::MAX);
                if index == u16::MAX {
                    u16::MAX
                } else {
                    dictionary.push(value.clone());
                    lookup.insert(value.as_str(), index);
                    index
                }
            };
            indices.push(index);
        }
        Self {
            dictionary,
            indices,
        }
    }

    fn unpack(self) -> Vec<String> {
        self.indices
            .into_iter()
            .map(|index| {
                self.dictionary
                    .get(index as usize)
                    .cloned()
                    .unwrap_or_default()
            })
            .collect()
    }
}

