fn append_refinement_timings(map: &mut crate::model::NativeMap, timings: &RegionRefinementTimings) {
    for (name, elapsed_micros) in [
        ("regional-validation", timings.validation_micros),
        ("regional-preflight", timings.preflight_micros),
        ("regional-detail-coverage", timings.detail_coverage_micros),
        ("regional-provenance", timings.provenance_micros),
        (
            "regional-inherited-settings",
            timings.inherited_settings_micros,
        ),
        ("regional-prepare-total", timings.total_micros),
    ] {
        map.generation_diagnostics
            .stages
            .push(crate::procedural::GenerationStageDiagnostic {
                name: name.to_owned(),
                elapsed_micros,
                stage_seed: map.environment_seed,
            });
    }
}

fn log_generation_stages(map: &crate::model::NativeMap) {
    for stage in &map.generation_diagnostics.stages {
        crate::diagnostics::event(
            "map_generation",
            "pipeline_stage",
            "completed",
            &[
                ("map_id", map.source_id.clone()),
                ("stage", stage.name.clone()),
                ("elapsed_micros", stage.elapsed_micros.to_string()),
                (
                    "analysis_grid",
                    format!("{}x{}", map.grid_width, map.grid_height),
                ),
                (
                    "canonical_surface",
                    map.canonical_surface
                        .as_ref()
                        .map(|surface| format!("{}x{}", surface.width, surface.height))
                        .unwrap_or_else(|| "none".to_owned()),
                ),
            ],
        );
    }
}

