    fn create_world_from_draft(&mut self) {
        let title = self.new_world.title.trim().to_owned();
        if title.is_empty() {
            return;
        }
        let Some(planet) = self.planet_preview.clone() else {
            self.schedule_planet_preview(true);
            return;
        };
        let expected_key = serde_json::to_string(&self.new_world.planet).unwrap_or_default();
        if expected_key != self.planet_preview_key {
            self.schedule_planet_preview(true);
            return;
        }
        let description = self.new_world.description.trim().to_owned();
        let rpg_enabled = self.new_world.rpg_enabled;
        let magic_enabled = rpg_enabled && self.new_world.magic_enabled;
        let planet_config = planet.generation_config.clone();
        let planet_summary = planet_config.derived_summary();
        self.load_demo(self.language);
        self.world.title = title;
        self.world.description = description;
        self.world.rpg_enabled = rpg_enabled;
        self.world.magic_enabled = magic_enabled;
        self.world.latitude_deg = self.new_world.latitude_deg;
        self.world.axial_tilt_deg = planet_config.physical.axial_tilt_deg as f32;
        self.world.day_length_hours = planet_config.physical.rotation_period_hours as f32;
        self.world.gravity_ms2 = planet_summary.surface_gravity_ms2 as f32;
        self.world.orbital_period_days = planet_config.physical.orbital_period_days as f32;
        self.world.planet = planet;
        self.environment_planet_selected = true;
        self.planet_environment_summary = None;
        self.world.articles.clear();
        self.world.factions.clear();
        self.world.events.clear();
        self.world.heraldic_assets.clear();
        self.world.map.locations.clear();
        self.world.map.causal_geology = self.world.planet.geology.clone();
        self.world.map.current_year = 0;
        self.world.map.title = tr(self.language, "행성 개요", "Planet Overview").to_owned();
        self.world.map.source_id = "__planet_only__".to_owned();
        self.world.map.region_id = None;
        self.world.map.map_view_id = None;
        self.world.maps.clear();
        self.world.regions.clear();
        self.world.detailed_regions.clear();
        self.world.map_views.clear();
        self.environment_map_index = 0;
        self.environment_pins.clear();
        self.year = 0;
        self.generator_preview = None;
        self.generator_preview_textures.clear();
        if let Some(job) = self.generator_job.take() {
            job.cancel.store(true, AtomicOrdering::Relaxed);
        }
        self.generator_commit_when_ready = false;
        self.pending_map_creation = None;
        self.map_page = MapPage::Planet;
        self.section = Section::Map;
        self.screen = Screen::Workspace;
        self.planet_region_selecting = false;
        self.planet_region_draft = None;
        self.new_world_open = false;
        self.new_world_step = NewWorldStep::World;
        self.planet_preview = None;
        self.planet_preview_key.clear();
        self.notify(tr(
            self.language,
            "행성 생성이 완료되었습니다.",
            "Planet generation completed.",
        ));
    }

    fn create_map_from_draft(&mut self) {
        let title = self.new_map.title.trim().to_owned();
        if title.is_empty() {
            return;
        }
        self.sync_active_map_snapshot();
        let serial = self.world.maps.len() + 1;
        let source_id = unique_map_source_id(&self.world.maps, serial);
        self.pending_map_creation = Some(PendingMapCreation {
            title,
            source_id: source_id.clone(),
            replace_index: None,
            center: PlanetPosition::from_latitude_longitude_deg(
                f64::from(self.world.latitude_deg),
                0.0,
            ),
            selection: RegionSelection::LocalRectangle {
                center: PlanetPosition::from_latitude_longitude_deg(
                    f64::from(self.world.latitude_deg),
                    0.0,
                ),
                width_m: 500_000.0,
                height_m: 312_500.0,
                selection_bearing_deg: 0.0,
            },
            generation_config: RegionGenerationConfig::default(),
            prepared_region: None,
            detailed_region: None,
            refinement_timings: None,
        });
        self.generator = GeneratorSettings::default();
        self.generator.settings.center_latitude_deg = self.world.latitude_deg as f64;
        let planet_config = &self.world.planet.generation_config;
        let planet_summary = planet_config.derived_summary();
        self.generator.settings.seed =
            planet_config.stable_subseed("planet-regional-refinement") as u32;
        self.generator.settings.reference_temperature_c = planet_summary.mean_surface_temperature_c;
        self.generator.settings.reference_humidity_percent =
            (25.0 + planet_config.surface.moisture_bias * 65.0).clamp(0.0, 100.0);
        self.generator.settings.base_precipitation_mm =
            12.0 + planet_config.surface.moisture_bias * 84.0;
        self.generator_preview = None;
        self.generator_preview_textures.clear();
        if let Some(job) = self.generator_job.take() {
            job.cancel.store(true, AtomicOrdering::Relaxed);
        }
        self.generator_commit_when_ready = false;
        self.generator.dirty_since = Some(Instant::now() - Duration::from_millis(200));
        self.map_page = MapPage::Generator;
        self.section = Section::Map;
        self.utility_page = None;
        self.new_map_open = false;
        if let Some(runtime) = &mut self.runtime {
            runtime.hide();
        }
        self.notify(tr(
            self.language,
            "새 지도 설정을 열었습니다. 기존 지도는 변경되지 않습니다.",
            "New map settings opened. Existing maps remain unchanged.",
        ));
    }

    fn begin_region_map_creation(&mut self, draft: PlanetRegionDraft) {
        if !self.world.maps.is_empty() {
            self.sync_active_map_snapshot();
        }
        let serial = self.world.maps.len() + 1;
        let source_id = unique_map_source_id(&self.world.maps, serial);
        let title = format!("{} {serial}", tr(self.language, "지역", "Region"));
        let selection = RegionSelection::LocalRectangle {
            center: draft.center,
            width_m: draft.width_km.clamp(1.0, 4_000.0) * 1_000.0,
            height_m: draft.height_km.clamp(1.0, 4_000.0) * 1_000.0,
            selection_bearing_deg: draft.rotation_deg,
        };
        let plan = match RegionalRefinementPipeline::prepare(
            &mut self.world.planet,
            &source_id,
            &title,
            selection.clone(),
            draft.generation_config.clone(),
        ) {
            Ok(plan) => plan,
            Err(error) => {
                self.notify(&format!(
                    "{}: {error}",
                    tr(
                        self.language,
                        "지역 상세화 실패",
                        "Regional refinement failed"
                    )
                ));
                return;
            }
        };
        crate::diagnostics::event(
            "map_generation",
            "regional_preflight",
            "completed",
            &[
                ("map_id", source_id.clone()),
                (
                    "requested_cells",
                    plan.preflight.requested_cells.to_string(),
                ),
                ("analysis_cells", plan.preflight.analysis_cells.to_string()),
                (
                    "estimated_cpu_peak_bytes",
                    plan.preflight.estimated_cpu_peak_bytes.to_string(),
                ),
                ("validation_us", plan.timings.validation_micros.to_string()),
                ("preflight_us", plan.timings.preflight_micros.to_string()),
                (
                    "detail_coverage_us",
                    plan.timings.detail_coverage_micros.to_string(),
                ),
                ("total_us", plan.timings.total_micros.to_string()),
            ],
        );
        self.generator = GeneratorSettings::default();
        self.generator.settings = plan.settings;
        self.status = format!(
            "{} {:.0}% · {} {} · {} cells · {:.1} MiB",
            tr(self.language, "상세 데이터 재사용", "Detailed data reuse"),
            plan.coverage.existing_percent(),
            plan.coverage.patch_refs.len(),
            tr(self.language, "패치", "patches"),
            plan.preflight.requested_cells,
            plan.preflight.estimated_cpu_peak_bytes as f64 / (1024.0 * 1024.0),
        );
        self.pending_map_creation = Some(PendingMapCreation {
            title,
            source_id,
            replace_index: None,
            center: draft.center,
            selection,
            generation_config: draft.generation_config,
            prepared_region: Some(plan.region),
            detailed_region: Some(plan.detailed_region),
            refinement_timings: Some(plan.timings),
        });
        self.generator_preview = None;
        self.generator_preview_textures.clear();
        if let Some(job) = self.generator_job.take() {
            job.cancel.store(true, AtomicOrdering::Relaxed);
        }
        self.generator_commit_when_ready = false;
        self.generator.dirty_since = Some(Instant::now() - Duration::from_millis(220));
        self.planet_region_selecting = false;
        self.planet_region_drag_start = None;
        self.planet_region_draft = None;
        self.map_page = MapPage::Generator;
        self.section = Section::Map;
    }

    fn save_project(&mut self, export: bool) {
        match self.save_project_inner(export) {
            Ok(path) => {
                if !export {
                    self.project_path = Some(path.clone());
                }
                self.notify(&format!(
                    "{}: {}",
                    if export {
                        tr(self.language, "내보냈습니다", "Exported")
                    } else {
                        tr(self.language, "저장했습니다", "Saved")
                    },
                    path.display()
                ));
            }
            Err(error) => self.notify(&format!(
                "{}: {error}",
                tr(self.language, "저장 실패", "Save failed")
            )),
        }
    }

    fn save_project_inner(&mut self, export: bool) -> Result<PathBuf, String> {
        self.sync_active_map_snapshot();
        self.world.reconcile_spatial_architecture();
        self.world.speech_assets = self.speech.export_embedded_assets()?;
        let root = project_storage_root();
        let directory = root.join(if export { "Exports" } else { "Projects" });
        std::fs::create_dir_all(&directory).map_err(|error| error.to_string())?;
        let path = if !export {
            self.project_path
                .as_ref()
                .filter(|path| path.extension().and_then(|value| value.to_str()) == Some("urdr"))
                .cloned()
                .unwrap_or_else(|| {
                    directory.join(format!("{}.urdr", safe_file_name(&self.world.title)))
                })
        } else {
            directory.join(format!(
                "{}-{}.urdr",
                safe_file_name(&self.world.title),
                env!("CARGO_PKG_VERSION")
            ))
        };
        let rpg_overrides = self
            .rpg_builtin_overrides
            .iter()
            .map(|(&(group, entry), name)| RpgOverrideRecord {
                group,
                entry,
                name: name.clone(),
            })
            .collect();
        let mut serializable_world = self.world.clone();
        let active_map_source_id = serializable_world
            .maps
            .iter()
            .any(|map| map.source_id == serializable_world.map.source_id)
            .then(|| serializable_world.map.source_id.clone());
        let mut surface_blobs = BTreeMap::<String, Vec<u8>>::new();
        for stored_map in &serializable_world.maps {
            if let Some(surface) = stored_map.canonical_surface.as_ref() {
                surface_blobs.insert(
                    surface_blob_name(&stored_map.source_id),
                    surface.to_streamed_binary()?,
                );
            }
        }
        for stored_map in &mut serializable_world.maps {
            stored_map.canonical_surface = None;
        }
        strip_active_map_payload(&mut serializable_world.map);
        let save = NativeProjectSaveRef {
            format_version: "urdr-native-4.4",
            language: self.language,
            active_map_source_id: active_map_source_id.as_deref(),
            world: &serializable_world,
            flag_design: &self.flag_design,
            emblem_design: &self.emblem_design,
            rpg_overrides,
            rpg_custom_entries: &self.rpg_custom_entries,
            rpg_rule_set: &self.rpg_rule_set,
            show_table_of_contents: self.show_table_of_contents,
        };
        let data = serde_json::to_vec(&save).map_err(|error| error.to_string())?;
        storage_v4::write_archive(
            &path,
            &data,
            surface_blobs
                .into_iter()
                .map(|(name, data)| ArchiveBlob { name, data }),
        )?;
        Ok(path)
    }

    fn import_latest_project(&mut self) {
        self.begin_load(LoadKind::Project);
    }

    fn apply_project(&mut self, prepared: PreparedProject) {
        let PreparedProject {
            path,
            save,
            render_cache,
        } = prepared;
        if let Some(runtime) = &mut self.runtime {
            runtime.hide();
        }
        self.runtime = None;
        self.runtime_ready = false;
        self.reset_map_visual_state();
        self.language = save.language;
        self.year = save.world.map.current_year;
        self.map_render = render_cache;
        self.overlay_mesh = Arc::new(Mesh::default());
        self.scene_rect = Rect::from_min_size(
            Pos2::ZERO,
            Vec2::new(save.world.map.width, save.world.map.height),
        );
        self.environment_point = Point {
            x: save.world.map.width * 0.5,
            y: save.world.map.height * 0.5,
        };
        self.set_home_background_map(save.world.map.clone());
        self.world = save.world;
        self.environment_planet_selected = false;
        self.planet_environment_summary = None;
        if let Err(error) = self
            .speech
            .restore_embedded_assets(&self.world.speech_assets)
        {
            self.notify(&format!(
                "{}: {error}",
                tr(
                    self.language,
                    "저장된 IPA 음성을 복원하지 못했습니다",
                    "Could not restore saved IPA speech"
                )
            ));
        }
        self.world.migrate_language_document_data();
        migrate_engine_2_world(&mut self.world, self.language);
        self.dictionary_language_id = first_dictionary_language_id(&self.world);
        self.dictionary_tab = 0;
        self.dictionary_search.clear();
        self.dictionary_ui = Default::default();
        self.selected_faction_index = first_country_index(&self.world);
        self.environment_map_index = self
            .world
            .maps
            .iter()
            .position(|map| map.source_id == self.world.map.source_id)
            .unwrap_or(0);
        self.timeline_fraction = 0.5;
        self.timeline_precision = 0;
        let calendar = self.world.display_calendar(self.language);
        let coordinates = calendar::calendar_coordinates(
            &calendar,
            TimelineMoment::new(self.year, self.timeline_fraction),
            self.world.orbital_period_days as f64,
        );
        self.calendar_date_values = calendar::day_units(&calendar, coordinates.year_fraction);
        self.calendar_time_values = calendar::time_units(&calendar, coordinates.year_fraction);
        self.environment_month = calendar::climate_month(&calendar, coordinates.year_fraction);
        self.flag_design = save.flag_design;
        self.emblem_design = save.emblem_design;
        self.reload_heraldry_designs();
        self.rpg_builtin_overrides = save
            .rpg_overrides
            .into_iter()
            .map(|record| ((record.group, record.entry), record.name))
            .collect();
        self.rpg_custom_entries = save.rpg_custom_entries;
        self.rpg_rule_set = if save.rpg_rule_set.categories.is_empty() {
            migrate_legacy_rpg_rules(&self.rpg_builtin_overrides, &self.rpg_custom_entries)
        } else {
            save.rpg_rule_set
        };
        self.rpg_rules_editing = false;
        self.rpg_rules_snapshot = None;
        self.show_table_of_contents = save.show_table_of_contents;
        self.selected_article = 0;
        self.selected_category = None;
        self.edited_cells.clear();
        self.screen = Screen::Workspace;
        self.section = Section::Map;
        self.map_page = if self.world.maps.is_empty() {
            MapPage::Planet
        } else {
            MapPage::Editor
        };
        self.map_edit_mode = MapEditMode::View;
        self.utility_page = None;
        self.project_path = Some(path.clone());
        self.runtime_requested = false;
        self.notify(&format!(
            "{}: {}",
            tr(self.language, "프로젝트를 불러왔습니다", "Project imported"),
            path.display()
        ));
    }

    fn begin_load(&mut self, kind: LoadKind) {
        if self.load_state.is_some() {
            return;
        }
        let kind_name = match kind {
            LoadKind::Demo(Language::Korean) => "demo_ko",
            LoadKind::Demo(Language::English) => "demo_en",
            LoadKind::Project => "project",
        };
        crate::diagnostics::event(
            "map_loading",
            "project_prepare",
            "queued",
            &[("kind", kind_name.to_owned())],
        );
        let (sender, receiver) = mpsc::channel();
        self.load_state = Some(LoadState {
            kind,
            started: Instant::now(),
            error: None,
        });
        self.load_receiver = Some(receiver);
        self.load_payload = None;
        let spawn_result = thread::Builder::new()
            .name("urdr-project-loader".to_owned())
            .spawn(move || {
                let started = Instant::now();
                crate::diagnostics::event(
                    "map_loading",
                    "project_prepare",
                    "started",
                    &[("kind", kind_name.to_owned())],
                );
                let result = match kind {
                    LoadKind::Demo(language) => prepare_demo(language).map(LoadPayload::Demo),
                    LoadKind::Project => prepare_latest_project().map(LoadPayload::Project),
                };
                let phase = if result.is_ok() {
                    "completed"
                } else {
                    "failed"
                };
                let mut fields = vec![
                    ("kind", kind_name.to_owned()),
                    ("elapsed_ms", started.elapsed().as_millis().to_string()),
                ];
                if let Err(error) = &result {
                    fields.push(("error", error.clone()));
                }
                if result.is_ok() {
                    crate::diagnostics::event("map_loading", "project_prepare", phase, &fields);
                } else {
                    crate::diagnostics::error("map_loading", "project_prepare", phase, &fields);
                }
                let _ = sender.send(result);
            });
        if let Err(error) = spawn_result {
            self.load_receiver = None;
            if let Some(state) = &mut self.load_state {
                state.error = Some(error.to_string());
            }
        }
    }

    fn process_load(&mut self) {
        let Some(state) = &self.load_state else {
            return;
        };
        if state.error.is_some() {
            return;
        }
        if self.load_payload.is_none() {
            let received =
                self.load_receiver
                    .as_ref()
                    .and_then(|receiver| match receiver.try_recv() {
                        Ok(result) => Some(result),
                        Err(TryRecvError::Empty) => None,
                        Err(TryRecvError::Disconnected) => Some(Err(
                            "The project loading worker stopped unexpectedly.".to_owned(),
                        )),
                    });
            if let Some(result) = received {
                self.load_payload = Some(result);
                self.load_receiver = None;
            }
        }
        if self
            .load_state
            .as_ref()
            .is_some_and(|state| state.started.elapsed() < Duration::from_millis(450))
        {
            return;
        }
        let Some(result) = self.load_payload.take() else {
            return;
        };
        let elapsed_ms = self
            .load_state
            .as_ref()
            .map(|state| state.started.elapsed().as_millis())
            .unwrap_or_default();
        match result {
            Ok(LoadPayload::Demo(prepared)) => {
                self.load_state = None;
                self.apply_demo(prepared);
                crate::diagnostics::event(
                    "map_loading",
                    "project_apply",
                    "completed",
                    &[
                        ("kind", "demo".to_owned()),
                        ("elapsed_ms", elapsed_ms.to_string()),
                    ],
                );
            }
            Ok(LoadPayload::Project(prepared)) => {
                self.load_state = None;
                self.apply_project(prepared);
                crate::diagnostics::event(
                    "map_loading",
                    "project_apply",
                    "completed",
                    &[
                        ("kind", "project".to_owned()),
                        ("elapsed_ms", elapsed_ms.to_string()),
                    ],
                );
            }
            Err(error) => {
                crate::diagnostics::error(
                    "map_loading",
                    "project_apply",
                    "failed",
                    &[
                        ("elapsed_ms", elapsed_ms.to_string()),
                        ("error", error.clone()),
                    ],
                );
                if let Some(state) = &mut self.load_state {
                    state.error = Some(error);
                }
            }
        }
    }

    fn notify(&mut self, message: &str) {
        self.status = message.to_owned();
        self.toast_until = Some(Instant::now() + Duration::from_secs(4));
    }

    fn begin_visual_validation_export(&mut self) {
        if self.visual_validation_job.is_some() {
            return;
        }
        let map = self.world.map.clone();
        let (sender, receiver) = mpsc::channel();
        self.visual_validation_job = Some(receiver);
        self.notify(tr(
            self.language,
            "지도 시각 검증 PNG를 생성하는 중입니다.",
            "Generating map visual validation PNGs.",
        ));
        let _ = thread::Builder::new()
            .name("urdr-map-visual-validation".to_owned())
            .spawn(move || {
                let _ = sender.send(crate::map_debug::export_visual_validation(&map));
            });
    }

    fn process_visual_validation_export(&mut self) {
        let Some(receiver) = &self.visual_validation_job else {
            return;
        };
        match receiver.try_recv() {
            Ok(Ok(path)) => {
                self.visual_validation_job = None;
                self.notify(&format!("Map visual validation: {}", path.display()));
            }
            Ok(Err(error)) => {
                self.visual_validation_job = None;
                self.notify(&format!("Map visual validation failed: {error}"));
            }
            Err(TryRecvError::Disconnected) => {
                self.visual_validation_job = None;
                self.notify("Map visual validation worker disconnected.");
            }
            Err(TryRecvError::Empty) => {}
        }
    }

    fn loading_overlay(&mut self, context: &egui::Context) {
        let Some(state) = &self.load_state else {
            return;
        };
        let kind = state.kind;
        let error = state.error.clone();
        let elapsed = state.started.elapsed().as_secs_f32();
        let language = match kind {
            LoadKind::Demo(language) => language,
            LoadKind::Project => self.language,
        };
        let colors = self.colors();
        let screen = context.content_rect();
        let mut retry = false;
        let mut dismiss = false;
        egui::Area::new("project_loading_overlay".into())
            .order(egui::Order::Foreground)
            .fixed_pos(screen.min)
            .show(context, |ui| {
                ui.set_min_size(screen.size());
                let full = Rect::from_min_size(ui.min_rect().min, screen.size());
                ui.allocate_rect(full, Sense::click_and_drag());
                ui.painter().rect_filled(
                    full,
                    0.0,
                    Color32::from_rgba_premultiplied(2, 8, 13, 206),
                );
                let card = Rect::from_center_size(
                    full.center(),
                    Vec2::new(440.0_f32.min(full.width() - 32.0), 236.0),
                );
                ui.scope_builder(egui::UiBuilder::new().max_rect(card), |ui| {
                    egui::Frame::new()
                        .fill(colors.surface)
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(CornerRadius::same(8))
                        .inner_margin(Margin::same(28))
                        .show(ui, |ui| {
                            ui.set_min_size(card.size() - Vec2::splat(56.0));
                            ui.vertical_centered(|ui| {
                                ui.label(
                                    RichText::new("URDR")
                                        .size(30.0)
                                        .strong()
                                        .color(colors.title),
                                );
                                ui.add_space(14.0);
                                let title = match kind {
                                    LoadKind::Demo(_) => tr(
                                        language,
                                        "데모 프로젝트를 불러오는 중",
                                        "Loading demo project",
                                    ),
                                    LoadKind::Project => {
                                        tr(language, "프로젝트를 불러오는 중", "Loading project")
                                    }
                                };
                                ui.label(RichText::new(title).size(15.0).color(colors.text));
                                ui.add_space(14.0);
                                if let Some(error) = &error {
                                    ui.label(
                                        RichText::new(tr(
                                            language,
                                            "프로젝트를 불러오지 못했습니다.",
                                            "The project could not be loaded.",
                                        ))
                                        .size(12.0)
                                        .color(colors.danger),
                                    );
                                    ui.add_space(5.0);
                                    ui.label(RichText::new(error).size(10.0).color(colors.muted));
                                    ui.add_space(14.0);
                                    ui.horizontal(|ui| {
                                        let retry_label = tr(language, "다시 시도", "Retry");
                                        let close_label = tr(language, "닫기", "Close");
                                        retry = ui
                                            .add_sized(
                                                [132.0, 34.0],
                                                egui::Button::new(retry_label),
                                            )
                                            .clicked();
                                        dismiss = ui
                                            .add_sized(
                                                [132.0, 34.0],
                                                egui::Button::new(close_label),
                                            )
                                            .clicked();
                                    });
                                } else {
                                    paint_indeterminate_loading_bar(ui, elapsed, colors);
                                    ui.add_space(14.0);
                                    let detail = if self.load_payload.is_some() || elapsed > 0.7 {
                                        tr(
                                            language,
                                            "지도 화면을 준비하는 중",
                                            "Preparing the map view",
                                        )
                                    } else {
                                        tr(
                                            language,
                                            "프로젝트 데이터와 지도를 읽는 중",
                                            "Reading project data and map",
                                        )
                                    };
                                    ui.label(RichText::new(detail).size(11.0).color(colors.muted));
                                }
                            });
                        });
                });
            });
        if retry {
            self.load_state = None;
            self.load_receiver = None;
            self.load_payload = None;
            self.begin_load(kind);
        } else if dismiss {
            self.load_state = None;
            self.load_receiver = None;
            self.load_payload = None;
        }
    }

    fn launch_runtime_if_requested(&mut self) {
        if !self.runtime_requested || self.runtime.is_some() {
            return;
        }
        if self
            .runtime_retry_at
            .is_some_and(|deadline| deadline > Instant::now())
        {
            return;
        }
        if self.runtime_retry_at.is_none() {
            self.runtime_attempts = 0;
        }
        self.runtime_retry_at = None;
        self.runtime_requested = false;
        self.runtime_attempts = self.runtime_attempts.saturating_add(1);
        match NativeRuntimeBridge::launch(&self.world.map) {
            Ok(runtime) => {
                runtime.send_layers(
                    self.show_rivers,
                    self.show_roads,
                    self.show_locations,
                    self.show_environment_layer,
                    self.show_territories,
                    self.language == Language::English,
                );
                runtime.send_tool(
                    self.tool.runtime(),
                    self.brush_radius,
                    self.brush_value(),
                    self.elevation_mode.runtime_id(),
                    self.brush_strength,
                    self.brush_falloff,
                    self.terrain_brush_noise,
                );
                runtime.send_year(self.year);
                self.runtime = Some(runtime);
                self.runtime_ready = false;
                self.runtime_embedded = false;
                self.runtime_started_at = Some(Instant::now());
                self.status = tr(
                    self.language,
                    "고성능 지도 렌더러 연결 중",
                    "Connecting high-performance map renderer",
                )
                .to_owned();
            }
            Err(error) => {
                self.runtime_failure(error);
            }
        }
    }

    fn runtime_failure(&mut self, error: String) {
        NativeRuntimeBridge::trace_lifecycle(format!(
            "host-runtime-failure attempt={} error={error}",
            self.runtime_attempts,
        ));
        if let Some(runtime) = &mut self.runtime {
            runtime.hide();
        }
        self.runtime = None;
        self.runtime_ready = false;
        self.runtime_embedded = false;
        self.runtime_started_at = None;
        self.runtime_fps = None;
        if self.runtime_attempts < 3 && NativeRuntimeBridge::available().is_some() {
            NativeRuntimeBridge::trace_lifecycle(format!(
                "host-retry-scheduled next_attempt={}",
                self.runtime_attempts + 1,
            ));
            self.runtime_requested = false;
            self.runtime_retry_at = Some(Instant::now() + Duration::from_millis(750));
            self.status = format!(
                "{} ({}/3): {error}",
                tr(
                    self.language,
                    "지도 렌더러 재연결 예약",
                    "Map renderer retry scheduled"
                ),
                self.runtime_attempts + 1,
            );
        } else {
            NativeRuntimeBridge::trace_lifecycle("native-renderer-active");
            self.runtime_requested = false;
            self.runtime_retry_at = None;
            self.status = format!(
                "{}: {error}",
                tr(
                    self.language,
                    "기본 지도 렌더러로 전환했습니다",
                    "Switched to the built-in map renderer"
                )
            );
        }
    }

    fn brush_value(&self) -> f32 {
        match self.tool {
            Tool::Terrain => terrain_id(self.selected_terrain) as f32,
            Tool::Elevation => self.elevation_delta,
            Tool::Territory => self.selected_faction_index as f32,
            Tool::Pan | Tool::Road | Tool::Place | Tool::Event | Tool::PlaceName => 0.0,
        }
    }

    fn process_runtime_events(&mut self) {
        let mut rebuild = false;
        let mut rebuild_territory = false;
        let mut elevation_changed = false;
        let mut environment_transaction = false;
        let mut disconnected = None;
        while let Some(event) = self
            .runtime
            .as_ref()
            .and_then(NativeRuntimeBridge::try_event)
        {
            match event {
                RuntimeEvent::Ready(ready) => {
                    let valid = self
                        .runtime
                        .as_ref()
                        .is_some_and(|runtime| runtime.ready_matches(ready))
                        && ready.environment_visible == self.show_environment_layer;
                    if valid {
                        NativeRuntimeBridge::trace_lifecycle("host-ready verified-first-frame");
                        self.runtime_ready = true;
                        self.status =
                            tr(self.language, "네이티브 지도 활성", "Native map active").to_owned();
                    } else {
                        disconnected = Some(format!(
                            "Native first-frame validation failed: protocol={}, checksum={:016x}, cells={}, shoreline={}, terrain={}, environment={}, frames={}",
                            ready.protocol_version,
                            ready.snapshot_checksum,
                            ready.cells,
                            ready.shoreline_segments,
                            ready.terrain_visible,
                            ready.environment_visible,
                            ready.rendered_frames,
                        ));
                        break;
                    }
                }
                RuntimeEvent::Metrics { fps, frame_ms } => self.runtime_fps = Some((fps, frame_ms)),
                RuntimeEvent::BrushPatch {
                    tool,
                    indices,
                    value,
                } => {
                    if tool == RuntimeTool::Territory {
                        self.begin_civilization_transaction();
                    } else if matches!(tool, RuntimeTool::Terrain | RuntimeTool::Elevation) {
                        self.begin_civilization_transaction();
                        environment_transaction = true;
                    }
                    for index in &indices {
                        if *index >= self.world.map.terrain.len() {
                            continue;
                        }
                        match tool {
                            RuntimeTool::Terrain => {
                                self.world.map.terrain[*index] =
                                    terrain_from_id(value as u8).to_owned();
                            }
                            RuntimeTool::Elevation => {
                                self.world.map.elevation[*index] =
                                    self.world.map.elevation[*index] + value;
                            }
                            RuntimeTool::Territory => {
                                let grid_width = self.world.map.grid_width.max(1);
                                let grid_height = self.world.map.grid_height.max(1);
                                let world_point = Point {
                                    x: (*index % grid_width) as f32 * self.world.map.width
                                        / grid_width as f32
                                        + self.world.map.width / grid_width as f32 * 0.5,
                                    y: (*index / grid_width) as f32 * self.world.map.height
                                        / grid_height as f32
                                        + self.world.map.height / grid_height as f32 * 0.5,
                                };
                                if self.world.map.surface_sample_at_world(world_point).water
                                    == "land"
                                {
                                    if self.world.map.territory_owners.len()
                                        != self
                                            .world
                                            .map
                                            .grid_width
                                            .saturating_mul(self.world.map.grid_height)
                                    {
                                        self.world.map.territory_owners =
                                            vec![
                                                -1;
                                                self.world
                                                    .map
                                                    .grid_width
                                                    .saturating_mul(self.world.map.grid_height)
                                            ];
                                    }
                                    self.world.map.territory_owners[*index] = value.round() as i32;
                                    rebuild_territory = true;
                                }
                            }
                            RuntimeTool::Pan
                            | RuntimeTool::Road
                            | RuntimeTool::Place
                            | RuntimeTool::Event
                            | RuntimeTool::PlaceName => {}
                        }
                    }
                    rebuild = !matches!(tool, RuntimeTool::Territory | RuntimeTool::Pan);
                    elevation_changed = matches!(tool, RuntimeTool::Elevation);
                    if tool == RuntimeTool::Territory {
                        self.finish_civilization_transaction();
                    }
                    self.notify(&format!(
                        "{} {}",
                        indices.len(),
                        tr(self.language, "개 셀 변경", "cells changed")
                    ));
                }
                RuntimeEvent::EnvironmentPatch {
                    tool,
                    elevation_mode,
                    radius,
                    brush_value,
                    strength,
                    falloff,
                    terrain_noise,
                    values,
                } => {
                    if !matches!(tool, RuntimeTool::Terrain | RuntimeTool::Elevation) {
                        continue;
                    }
                    self.begin_civilization_transaction();
                    environment_transaction = true;
                    self.brush_radius = radius.clamp(0.5, 18.0);
                    if tool == RuntimeTool::Elevation {
                        self.elevation_delta = brush_value;
                        self.elevation_mode = match elevation_mode {
                            1 => ElevationBrushMode::Raise,
                            2 => ElevationBrushMode::Lower,
                            _ => ElevationBrushMode::Target,
                        };
                    } else {
                        self.selected_terrain = terrain_from_id(brush_value as u8);
                    }
                    self.brush_strength = strength.clamp(0.05, 1.0);
                    self.brush_falloff = falloff.clamp(0.0, 1.0);
                    self.terrain_brush_noise = terrain_noise.clamp(0.0, 1.0);
                    for (index, value) in &values {
                        if *index >= self.world.map.terrain.len()
                            || self
                                .world
                                .map
                                .water
                                .get(*index)
                                .is_some_and(|water| water != "land")
                        {
                            continue;
                        }
                        match tool {
                            RuntimeTool::Terrain => {
                                self.world.map.terrain[*index] =
                                    terrain_from_id(*value as u8).to_owned();
                            }
                            RuntimeTool::Elevation => self.world.map.elevation[*index] = *value,
                            _ => {}
                        }
                    }
                    rebuild = true;
                    elevation_changed = tool == RuntimeTool::Elevation;
                    self.notify(&format!(
                        "{} {}",
                        values.len(),
                        tr(
                            self.language,
                            "개 환경 셀 변경",
                            "environment cells changed"
                        )
                    ));
                }
                RuntimeEvent::Generated { seed } => {
                    self.notify(&format!(
                        "{} {seed}",
                        tr(
                            self.language,
                            "WGPU 미리보기 생성 완료, 시드",
                            "WGPU preview generated, seed"
                        )
                    ));
                }
                RuntimeEvent::GeneratedSnapshot {
                    seed,
                    grid_width,
                    grid_height,
                    world_width,
                    world_height,
                    sea_level,
                    elevation,
                    surfaces,
                } => {
                    if elevation.len() == grid_width.saturating_mul(grid_height)
                        && surfaces.len() == elevation.len()
                    {
                        self.world.map.grid_width = grid_width;
                        self.world.map.grid_height = grid_height;
                        self.world.map.width = world_width;
                        self.world.map.height = world_height;
                        self.world.map.sea_level = sea_level;
                        self.world.map.climate_model =
                            self.generator.settings.koppen_climate.climate_model_id();
                        self.world.map.environment_seed = seed;
                        self.world.map.elevation = elevation;
                        self.world.map.water = surfaces
                            .iter()
                            .map(|surface| match surface {
                                0 => "saltwater".to_owned(),
                                1 => "freshwater".to_owned(),
                                _ => "land".to_owned(),
                            })
                            .collect();
                        self.world.map.terrain = surfaces
                            .iter()
                            .map(|surface| terrain_from_id(*surface).to_owned())
                            .collect();
                        let climate = climate_from_id(self.world.map.climate_model);
                        populate_environment_fields(&mut self.world.map, climate, seed);
                        self.world.map.canonical_surface = None;
                        self.world.map.rebuild_canonical_surface();
                        self.world.map.rivers.clear();
                        self.world.map.roads.clear();
                        self.world.map.territories.clear();
                        self.world.map.territory_owners =
                            vec![-1; grid_width.saturating_mul(grid_height)];
                        self.map_render =
                            MapRenderCache::build(&self.world.map, self.layer_opacity);
                        self.overlay_mesh = Arc::new(Mesh::default());
                        self.scene_rect =
                            Rect::from_min_size(Pos2::ZERO, Vec2::new(world_width, world_height));
                        self.map_page = MapPage::Editor;
                        self.sync_active_map_snapshot();
                        self.notify(&format!(
                            "{} {seed}",
                            tr(
                                self.language,
                                "생성 지도를 프로젝트에 확정했습니다. 시드",
                                "Generated map committed to the project. Seed"
                            )
                        ));
                    }
                }
                RuntimeEvent::Pointer {
                    x,
                    y,
                    elevation,
                    zoom,
                    surface,
                } => {
                    self.pointer_sample = Some((Point { x, y }, elevation, zoom, surface));
                }
                RuntimeEvent::CameraChanged(camera) => {
                    let viewport_size = self.map_viewport_rect.size();
                    self.scene_rect = scene_rect_from_runtime_camera(
                        camera,
                        viewport_size,
                        Vec2::new(self.world.map.width, self.world.map.height),
                    );
                }
                RuntimeEvent::CivilizationStroke { tool, points } => {
                    self.apply_civilization_stroke(tool, points);
                }
                RuntimeEvent::EditHistory { redo } => {
                    if redo {
                        self.redo_civilization_transaction();
                    } else {
                        self.undo_civilization_transaction();
                    }
                }
                RuntimeEvent::Disconnected(error) => {
                    disconnected = Some(error);
                    break;
                }
            }
        }
        if let Some(error) = disconnected {
            self.runtime_failure(error);
        }
        if elevation_changed {
            self.world.map.canonical_surface = None;
            self.world.map.rebuild_canonical_surface();
            generator::regenerate_hydrology_and_roads(&mut self.world.map);
            rebuild = true;
            rebuild_territory = true;
        }
        if rebuild {
            self.map_render
                .rebuild_all(&self.world.map, self.layer_opacity);
        } else if rebuild_territory {
            self.map_render
                .rebuild_territory(&self.world.map, self.layer_opacity);
        }
        if environment_transaction {
            // The native renderer already owns the edited cell buffer; keep its dirty-chunk update intact.
            // instead of echoing a full snapshot and rebuilding every map chunk.
            self.sync_active_map_snapshot();
        }
    }

    fn send_runtime_tool(&self) {
        if let Some(runtime) = &self.runtime {
            runtime.send_tool(
                self.tool.runtime(),
                self.brush_radius,
                self.brush_value(),
                self.elevation_mode.runtime_id(),
                self.brush_strength,
                self.brush_falloff,
                self.terrain_brush_noise,
            );
        }
    }

    fn home(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        egui::CentralPanel::default()
            .frame(egui::Frame::new().fill(colors.map_background))
            .show(root, |ui| {
                let rect = ui.max_rect();
                self.paint_home_background(ui, rect);
                let veil = if self.dark_mode {
                    Color32::from_rgba_premultiplied(4, 12, 20, 112)
                } else {
                    Color32::from_rgba_premultiplied(238, 247, 250, 92)
                };
                ui.painter().rect_filled(rect, 0.0, veil);

                let panel_width = theme::Metrics::HOME_PANEL_WIDTH.min(rect.width() - 36.0);
                let panel_height = theme::Metrics::HOME_PANEL_HEIGHT.min(rect.height() - 36.0);
                let menu_rect =
                    Rect::from_center_size(rect.center(), Vec2::new(panel_width, panel_height));
                ui.scope_builder(egui::UiBuilder::new().max_rect(menu_rect), |ui| {
                    egui::Frame::new()
                        .fill(if self.dark_mode {
                            Color32::from_rgb(8, 21, 33)
                        } else {
                            Color32::from_rgb(248, 252, 253)
                        })
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(CornerRadius::same(8))
                        .inner_margin(Margin::same(42))
                        .show(ui, |ui| {
                            ui.set_min_size(menu_rect.size() - Vec2::splat(84.0));
                            ui.vertical_centered(|ui| {
                                ui.add_space(4.0);
                                ui.label(
                                    RichText::new("URDR")
                                        .font(FontId::proportional(46.0))
                                        .strong()
                                        .color(colors.title),
                                );
                                ui.add_space(26.0);
                                if home_menu_button(
                                    ui,
                                    tr(self.language, "세계 생성", "Create World"),
                                    360.0,
                                )
                                .clicked()
                                {
                                    self.new_world = NewWorldDraft::for_language(self.language);
                                    self.new_world_step = NewWorldStep::World;
                                    self.planet_preview = None;
                                    self.planet_preview_key.clear();
                                    self.planet_preview_dirty_since = None;
                                    self.planet_preview_job = None;
                                    self.new_world_open = true;
                                }
                                ui.add_space(5.0);
                                if home_menu_button(
                                    ui,
                                    tr(self.language, "세계 열기", "Open World"),
                                    360.0,
                                )
                                .clicked()
                                {
                                    self.import_latest_project();
                                }
                                ui.add_space(5.0);
                                ui.allocate_ui_with_layout(
                                    Vec2::new(360.0, 52.0),
                                    Layout::left_to_right(Align::Center),
                                    |ui| {
                                        ui.spacing_mut().item_spacing.x = 7.0;
                                        let width = 176.5;
                                        if ui
                                            .add_sized(
                                                [width, 52.0],
                                                egui::Button::new(tr(
                                                    self.language,
                                                    "한국어 데모",
                                                    "Korean Demo",
                                                )),
                                            )
                                            .clicked()
                                        {
                                            self.begin_demo_load(Language::Korean);
                                        }
                                        if ui
                                            .add_sized(
                                                [width, 52.0],
                                                egui::Button::new("English Demo"),
                                            )
                                            .clicked()
                                        {
                                            self.begin_demo_load(Language::English);
                                        }
                                    },
                                );
                                ui.add_space(5.0);
                                if home_menu_button(
                                    ui,
                                    tr(self.language, "설정", "Settings"),
                                    360.0,
                                )
                                .clicked()
                                {
                                    self.settings_open = true;
                                }
                                ui.add_space(5.0);
                                if home_menu_button(ui, tr(self.language, "종료", "Exit"), 360.0)
                                    .clicked()
                                {
                                    ui.ctx().send_viewport_cmd(egui::ViewportCommand::Close);
                                }
                            });
                        });
                });

                let footer_y = rect.bottom() - 48.0;
                let history_rect = Rect::from_min_size(
                    Pos2::new(rect.left() + 24.0, footer_y),
                    Vec2::new(112.0, 24.0),
                );
                if ui
                    .put(
                        history_rect,
                        egui::Button::new(
                            RichText::new(tr(self.language, "업데이트 내역", "Update history"))
                                .size(11.0),
                        )
                        .frame(false),
                    )
                    .clicked()
                {
                    self.update_history_open = true;
                }
                let theme_rect = Rect::from_min_size(
                    Pos2::new(rect.right() - 132.0, footer_y),
                    Vec2::new(108.0, 24.0),
                );
                if ui
                    .put(
                        theme_rect,
                        egui::Button::new(if self.dark_mode {
                            tr(self.language, "라이트 모드", "Light mode")
                        } else {
                            tr(self.language, "다크 모드", "Dark mode")
                        }),
                    )
                    .clicked()
                {
                    self.dark_mode = !self.dark_mode;
                    theme::apply(ui.ctx(), self.dark_mode, self.ui_scale);
                }
            });
    }

    fn set_home_background_map(&mut self, map: crate::model::NativeMap) {
        self.home_background_render = MapRenderCache::build(&map, 0.0);
        self.home_background_textures.clear();
        self.home_background_map = map;
    }

    fn paint_home_background(&mut self, ui: &egui::Ui, rect: Rect) {
        let map = &self.home_background_map;
        let screen_aspect = rect.width() / rect.height().max(1.0);
        let mut view_width = map.width / 3.0;
        let mut view_height = view_width / screen_aspect.max(0.1);
        if view_height > map.height / 3.0 {
            view_height = map.height / 3.0;
            view_width = view_height * screen_aspect;
        }
        view_width = view_width.clamp(0.1, map.width.max(0.1));
        view_height = view_height.clamp(0.1, map.height.max(0.1));
        let mut interest_sum = Vec2::ZERO;
        let mut interest_count = 0.0;
        for location in &map.locations {
            if let Some(state) = location.state_at(map.current_year) {
                interest_sum += Vec2::new(state.position.x, state.position.y);
                interest_count += 1.0;
            }
        }
        for event in &map.events {
            if event.start_year <= map.current_year
                && event.end_year.is_none_or(|end| map.current_year <= end)
                && let Some(position) = event.position_at(map.current_year)
            {
                interest_sum += Vec2::new(position.x, position.y);
                interest_count += 1.0;
            }
        }
        let interest = if interest_count > 0.0 {
            (interest_sum / interest_count).to_pos2()
        } else {
            Pos2::new(map.width * 0.5, map.height * 0.5)
        };
        let minimum = Pos2::new(view_width * 0.5, view_height * 0.5);
        let maximum = Pos2::new(
            (map.width - view_width * 0.5).max(minimum.x),
            (map.height - view_height * 0.5).max(minimum.y),
        );
        let anchor = Pos2::new(
            interest.x.clamp(minimum.x, maximum.x),
            interest.y.clamp(minimum.y, maximum.y),
        );
        let travel_x = (anchor.x - minimum.x).min(maximum.x - anchor.x).max(0.0) * 0.55;
        let travel_y = (anchor.y - minimum.y).min(maximum.y - anchor.y).max(0.0) * 0.55;
        let elapsed = self.home_animation_seconds;
        let center = Pos2::new(
            anchor.x + (elapsed * 0.018).sin() * travel_x,
            anchor.y + (elapsed * 0.013 + 0.4).sin() * travel_y,
        );
        let world_view = Rect::from_center_size(center, Vec2::new(view_width, view_height));
        let screen_scale = (rect.width() / view_width).min(rect.height() / view_height);
        self.home_background_textures
            .ensure(ui.ctx(), map, screen_scale, world_view, true);
        let tiles = self.home_background_textures.draw_commands(world_view);
        self.home_background_render
            .ensure_river_mesh(map, screen_scale);
        paint_home_map_rect(
            ui,
            rect,
            world_view,
            map,
            &tiles,
            Arc::clone(&self.home_background_render.river_mesh),
            Arc::clone(&self.home_background_render.road_mesh),
        );
    }

    fn workspace(&mut self, root: &mut egui::Ui) {
        self.top_bar(root);
        self.status_bar(root);
        if self.timeline_expanded {
            self.timeline(root);
        } else {
            egui::Panel::bottom("timeline_collapsed")
                .exact_size(theme::Metrics::TIMELINE_COLLAPSED_HEIGHT)
                .frame(
                    egui::Frame::new()
                        .fill(self.colors().panel)
                        .stroke(Stroke::new(1.0, self.colors().border)),
                )
                .show(root, |ui| {
                    ui.add_space(4.0);
                    if vector_icon_button(
                        ui,
                        UiIcon::ChevronUp,
                        tr(self.language, "타임라인 펼치기", "Expand timeline"),
                        32.0,
                    )
                    .on_hover_text(tr(self.language, "타임라인 펼치기", "Expand timeline"))
                    .clicked()
                    {
                        self.timeline_expanded = true;
                    }
                });
        }
        if !self.explorer_collapsed {
            match self.utility_page {
                Some(UtilityPage::Flags) => self.heraldry_library_explorer(root, false),
                Some(UtilityPage::Emblems) => self.heraldry_library_explorer(root, true),
                Some(UtilityPage::Scripts) => self.script_library_explorer(root),
                Some(UtilityPage::Dictionary) => self.dictionary_explorer(root),
                _ => self.project_explorer(root),
            }
        }
        // Document tabs belong to the wiki workspace. Utility, map, environment,
        // and project screens reclaim the full tab-bar height.
        if self.utility_page.is_none() && self.section == Section::World {
            self.document_tabs(root);
        }
        match self.utility_page {
            Some(UtilityPage::ProjectHome) => self.project_home_workspace(root),
            Some(UtilityPage::RpgRules) => self.rpg_rules_workspace(root),
            Some(UtilityPage::Flags) => self.heraldry_workspace(root, false),
            Some(UtilityPage::Emblems) => self.heraldry_workspace(root, true),
            Some(UtilityPage::Scripts) => self.script_workspace(root),
            Some(UtilityPage::Dictionary) => self.dictionary_workspace(root),
            None => match self.section {
                Section::Map => self.map_workspace(root),
                Section::World => self.wiki_workspace(root),
                Section::Environment => self.environment_workspace(root),
            },
        }
    }

    fn top_bar(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        egui::Panel::top("top_bar")
            .exact_size(theme::Metrics::TOP_BAR_HEIGHT)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel)
                    .stroke(Stroke::new(1.0, colors.border)),
            )
            .show(root, |ui| {
                ui.columns(3, |columns| {
                    columns[0].horizontal_centered(|ui| {
                        if vector_icon_button(
                            ui,
                            UiIcon::Explorer,
                            tr(
                                self.language,
                                if self.explorer_collapsed {
                                    "탐색기 펼치기"
                                } else {
                                    "탐색기 접기"
                                },
                                if self.explorer_collapsed {
                                    "Show Explorer"
                                } else {
                                    "Hide Explorer"
                                },
                            ),
                            32.0,
                        )
                        .clicked()
                        {
                            self.explorer_collapsed = !self.explorer_collapsed;
                        }
                        ui.add_sized(
                            [42.0, 28.0],
                            egui::Label::new(
                                RichText::new("URDR")
                                    .size(11.0)
                                    .strong()
                                    .color(colors.title),
                            )
                            .sense(Sense::hover()),
                        );
                        ui.separator();
                        if topbar_button(ui, tr(self.language, "프로젝트 홈", "Project Home"))
                            .clicked()
                        {
                            self.utility_page = Some(UtilityPage::ProjectHome);
                        }
                        if self.world.rpg_enabled
                            && topbar_button(ui, tr(self.language, "RPG 규칙", "RPG Rules"))
                                .clicked()
                        {
                            self.utility_page = Some(UtilityPage::RpgRules);
                        }
                        if topbar_button(ui, tr(self.language, "깃발", "Flags")).clicked() {
                            self.utility_page = Some(UtilityPage::Flags);
                        }
                        if topbar_button(ui, tr(self.language, "문장", "Emblems")).clicked() {
                            self.utility_page = Some(UtilityPage::Emblems);
                        }
                        if topbar_button(ui, tr(self.language, "문자", "Scripts")).clicked() {
                            self.utility_page = Some(UtilityPage::Scripts);
                        }
                        if topbar_button(ui, tr(self.language, "사전", "Dictionary")).clicked() {
                            self.utility_page = Some(UtilityPage::Dictionary);
                        }
                    });
                    columns[1].vertical_centered(|ui| {
                        ui.add_space(7.0);
                        ui.label(
                            RichText::new(&self.world.title)
                                .size(12.0)
                                .strong()
                                .color(colors.title),
                        );
                    });
                    columns[2].with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if vector_icon_button(
                            ui,
                            UiIcon::Home,
                            tr(self.language, "시작 화면", "Start Screen"),
                            32.0,
                        )
                        .clicked()
                        {
                            self.set_home_background_map(self.world.map.clone());
                            self.screen = Screen::Home;
                            if let Some(runtime) = &mut self.runtime {
                                runtime.hide();
                            }
                        }
                        if topbar_icon_button(ui, "⚙", tr(self.language, "설정", "Settings"))
                            .clicked()
                        {
                            self.settings_open = true;
                        }
                        if topbar_icon_button(
                            ui,
                            "◐",
                            tr(self.language, "테마 전환", "Toggle theme"),
                        )
                        .clicked()
                        {
                            self.dark_mode = !self.dark_mode;
                            theme::apply(ui.ctx(), self.dark_mode, self.ui_scale);
                        }
                        if topbar_button(ui, tr(self.language, "불러오기", "Import")).clicked()
                        {
                            self.import_latest_project();
                        }
                        if topbar_button(ui, tr(self.language, "내보내기", "Export")).clicked()
                        {
                            self.save_project(true);
                        }
                        if topbar_button(ui, tr(self.language, "저장", "Save")).clicked() {
                            self.save_project(false);
                        }
                    });
                });
            });
    }

    fn status_bar(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        egui::Panel::bottom("status_bar")
            .exact_size(theme::Metrics::STATUS_BAR_HEIGHT)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel_alt)
                    .stroke(Stroke::new(1.0, colors.border)),
            )
            .show(root, |ui| {
                ui.horizontal_centered(|ui| {
                    ui.label(
                        RichText::new(format!(
                            "{} {}    {} {}    {} {}",
                            tr(self.language, "지도", "Maps"),
                            1,
                            tr(self.language, "문서", "Documents"),
                            self.world.articles.len(),
                            tr(self.language, "사건", "Events"),
                            self.world.events.len(),
                        ))
                        .size(9.0)
                        .color(colors.muted),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if let Some((fps, frame_ms)) = self.runtime_fps {
                            ui.label(
                                RichText::new(format!("{fps:.0} FPS · {frame_ms:.1} ms"))
                                    .size(9.0)
                                    .color(colors.muted),
                            );
                        } else if self.runtime.is_some() {
                            ui.label(
                                RichText::new(tr(self.language, "지도 준비 중", "Preparing map"))
                                    .size(9.0)
                                    .color(colors.muted),
                            );
                        } else {
                            ui.label(
                                RichText::new(tr(self.language, "지도 준비됨", "Map ready"))
                                    .size(9.0)
                                    .color(colors.muted),
                            );
                        }
                    });
                });
            });
    }

    fn timeline(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let (minimum, maximum) = self.world.year_bounds();
        let calendar = self.world.display_calendar(self.language);
        let mut calendar_options = self
            .world
            .articles
            .iter()
            .filter_map(|article| {
                article
                    .calendar_profile
                    .as_ref()
                    .map(|profile| (article.id.clone(), profile.calendar_name.clone()))
            })
            .collect::<Vec<_>>();
        calendar_options.push((
            "__standard_orbital__".to_owned(),
            tr(self.language, "표준 공전 주기", "Standard Orbital Period").to_owned(),
        ));
        let moment = TimelineMoment::new(self.year, self.timeline_fraction);
        let calendar_coordinates = calendar::calendar_coordinates(
            &calendar,
            moment,
            self.world.orbital_period_days as f64,
        );
        let event_years = self.world.planet_timeline_years();
        egui::Panel::bottom("timeline")
            .exact_size(theme::Metrics::TIMELINE_HEIGHT)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel)
                    .stroke(Stroke::new(1.0, colors.border)),
            )
            .show(root, |ui| {
                ui.add_space(8.0);
                ui.horizontal(|ui| {
                    ui.allocate_ui_with_layout(
                        Vec2::new(48.0, 104.0),
                        Layout::top_down(Align::Center),
                        |ui| {
                            if vector_icon_button(
                                ui,
                                UiIcon::ChevronDown,
                                tr(self.language, "타임라인 접기", "Collapse timeline"),
                                30.0,
                            )
                            .on_hover_text(tr(self.language, "타임라인 접기", "Collapse timeline"))
                            .clicked()
                            {
                                self.timeline_expanded = false;
                            }
                            ui.add_space(4.0);
                            if ui
                                .add_sized(
                                    [42.0, 42.0],
                                    egui::Button::new(if self.playing { "Ⅱ" } else { "▶" }),
                                )
                                .on_hover_text(if self.playing {
                                    tr(self.language, "일시정지", "Pause")
                                } else {
                                    tr(self.language, "재생", "Play")
                                })
                                .clicked()
                            {
                                self.playing = !self.playing;
                            }
                        },
                    );
                    ui.add_space(4.0);
                    let available = (ui.available_width() - 10.0).max(560.0);
                    let controls_width = (available * 0.27).clamp(300.0, 360.0);
                    let rail_width = (available - controls_width - 10.0).max(280.0);
                    ui.allocate_ui_with_layout(
                        Vec2::new(rail_width, 104.0),
                        Layout::top_down(Align::Min),
                        |ui| {
                            let (label_rect, precision_response) = ui.allocate_exact_size(
                                Vec2::new(ui.available_width(), 34.0),
                                Sense::click(),
                            );
                            if precision_response
                                .on_hover_text(tr(
                                    self.language,
                                    "날짜·시간 표시 단위 순환",
                                    "Cycle date and time precision",
                                ))
                                .clicked()
                            {
                                let precision_count = calendar.date_units.len().saturating_sub(1)
                                    + calendar.time_units.len();
                                self.timeline_precision =
                                    if self.timeline_precision >= precision_count {
                                        0
                                    } else {
                                        self.timeline_precision + 1
                                    };
                            }
                            ui.painter().text(
                                label_rect.left_center(),
                                Align2::LEFT_CENTER,
                                &calendar.calendar_name,
                                FontId::proportional(9.0),
                                colors.muted,
                            );
                            let date_precision = calendar.date_units.len().saturating_sub(1);
                            let date_text = calendar::format_absolute_moment_precision(
                                &calendar,
                                self.language,
                                moment,
                                self.world.orbital_period_days as f64,
                                self.timeline_precision.min(date_precision),
                            );
                            let full_text = calendar::format_absolute_moment_precision(
                                &calendar,
                                self.language,
                                moment,
                                self.world.orbital_period_days as f64,
                                self.timeline_precision,
                            );
                            ui.painter().text(
                                Pos2::new(label_rect.center().x, label_rect.top() + 10.0),
                                Align2::CENTER_CENTER,
                                &date_text,
                                FontId::proportional(12.0),
                                colors.title,
                            );
                            if self.timeline_precision > date_precision {
                                let time_text = full_text
                                    .strip_prefix(&date_text)
                                    .map(str::trim)
                                    .unwrap_or_default();
                                ui.painter().text(
                                    Pos2::new(label_rect.center().x, label_rect.top() + 25.0),
                                    Align2::CENTER_CENTER,
                                    time_text,
                                    FontId::proportional(10.0),
                                    colors.accent,
                                );
                            }
                            ui.painter().text(
                                label_rect.right_center(),
                                Align2::RIGHT_CENTER,
                                format!(
                                    "{:.3} {}",
                                    self.year as f64 + self.timeline_fraction,
                                    tr(self.language, "공전년", "orbital yr"),
                                ),
                                FontId::proportional(9.0),
                                colors.muted,
                            );
                            let previous_year = self.year;
                            ui.add_space(10.0);
                            let changed = timeline_scrubber(
                                ui,
                                &mut self.year,
                                minimum,
                                maximum,
                                &event_years,
                                colors,
                            )
                            .changed();
                            if changed {
                                self.refresh_timeline_territories(previous_year);
                                if let Some(runtime) = &self.runtime {
                                    runtime.send_year(self.year);
                                }
                            }
                            ui.horizontal(|ui| {
                                ui.label(
                                    RichText::new(calendar::format_absolute_moment_precision(
                                        &calendar,
                                        self.language,
                                        TimelineMoment::new(minimum, 0.0),
                                        self.world.orbital_period_days as f64,
                                        0,
                                    ))
                                    .size(8.5)
                                    .color(colors.muted),
                                );
                                if let Some(event) = self.world.events.iter().find(|event| {
                                    event.start_year <= self.year
                                        && event.end_year.unwrap_or(event.start_year) >= self.year
                                }) {
                                    ui.add_space(12.0);
                                    ui.label(
                                        RichText::new(&event.title).size(9.0).color(colors.accent),
                                    );
                                }
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    ui.label(
                                        RichText::new(calendar::format_absolute_moment_precision(
                                            &calendar,
                                            self.language,
                                            TimelineMoment::new(maximum, 0.0),
                                            self.world.orbital_period_days as f64,
                                            0,
                                        ))
                                        .size(8.5)
                                        .color(colors.muted),
                                    );
                                });
                            });
                        },
                    );
                    ui.add_space(10.0);
                    ui.allocate_ui_with_layout(
                        Vec2::new(controls_width, 104.0),
                        Layout::top_down(Align::Min),
                        |ui| {
                            ui.label(
                                RichText::new(tr(
                                    self.language,
                                    "현재 역법 단위",
                                    "Calendar Units",
                                ))
                                .size(8.5)
                                .color(colors.muted),
                            );
                            egui::ScrollArea::horizontal()
                                .scroll_bar_visibility(
                                    egui::scroll_area::ScrollBarVisibility::AlwaysHidden,
                                )
                                .show(ui, |ui| {
                                    ui.set_min_width(
                                        ((calendar.date_units.len() + calendar.time_units.len())
                                            as f32
                                            * 54.0)
                                            .max(controls_width),
                                    );
                                    if calendar_unit_buttons(
                                        ui,
                                        self.language,
                                        &calendar,
                                        calendar_coordinates.year,
                                        &mut self.calendar_date_values,
                                        &mut self.calendar_time_values,
                                    ) {
                                        let converted = calendar::timeline_moment_from_calendar(
                                            &calendar,
                                            calendar_coordinates.year,
                                            &self.calendar_date_values,
                                            &self.calendar_time_values,
                                            self.world.orbital_period_days as f64,
                                        );
                                        let previous_year = self.year;
                                        self.year = converted.world_year;
                                        self.timeline_fraction = converted.day_fraction;
                                        self.refresh_timeline_territories(previous_year);
                                        self.environment_month = calendar::climate_month(
                                            &calendar,
                                            calendar_coordinates.year_fraction,
                                        );
                                    }
                                });
                            ui.add_space(4.0);
                            ui.columns(2, |columns| {
                                columns[0].label(
                                    RichText::new(tr(self.language, "표시 역법", "Calendar"))
                                        .size(8.5)
                                        .color(colors.muted),
                                );
                                columns[1].label(
                                    RichText::new(tr(self.language, "재생 속도", "Playback"))
                                        .size(8.5)
                                        .color(colors.muted),
                                );
                            });
                            ui.columns(2, |columns| {
                                egui::ComboBox::from_id_salt("calendar")
                                    .selected_text(&calendar.calendar_name)
                                    .width((columns[0].available_width() - 2.0).max(96.0))
                                    .show_ui(&mut columns[0], |ui| {
                                        for (id, name) in &calendar_options {
                                            let selected =
                                                self.world.timeline_calendar_article_id.as_deref()
                                                    == Some(id.as_str());
                                            if ui.selectable_label(selected, name).clicked() {
                                                self.world.timeline_calendar_article_id =
                                                    Some(id.clone());
                                                self.timeline_precision = 0;
                                                if id == "__standard_orbital__" {
                                                    self.calendar_date_values.clear();
                                                    self.calendar_time_values.clear();
                                                }
                                                if let Some(profile) = self
                                                    .world
                                                    .articles
                                                    .iter()
                                                    .find(|article| article.id == *id)
                                                    .and_then(|article| {
                                                        article.calendar_profile.as_ref()
                                                    })
                                                {
                                                    let converted = calendar::calendar_coordinates(
                                                        profile,
                                                        moment,
                                                        self.world.orbital_period_days as f64,
                                                    );
                                                    self.calendar_date_values = calendar::day_units(
                                                        profile,
                                                        converted.year_fraction,
                                                    );
                                                    self.calendar_time_values =
                                                        calendar::time_units(
                                                            profile,
                                                            converted.year_fraction,
                                                        );
                                                    self.environment_month =
                                                        calendar::climate_month(
                                                            profile,
                                                            converted.year_fraction,
                                                        );
                                                }
                                            }
                                        }
                                    });
                                egui::ComboBox::from_id_salt("speed")
                                    .selected_text(format!("{}×", self.playback_speed))
                                    .width((columns[1].available_width() - 2.0).max(86.0))
                                    .show_ui(&mut columns[1], |ui| {
                                        for speed in [0.25, 0.5, 1.0, 2.0, 4.0, 8.0] {
                                            ui.selectable_value(
                                                &mut self.playback_speed,
                                                speed,
                                                format!("{speed}×"),
                                            );
                                        }
                                    });
                            });
                        },
                    );
                });
            });
    }

    fn document_tabs(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let current_article = self
            .world
            .articles
            .get(self.selected_article)
            .map(|article| article.title.as_str())
            .unwrap_or_else(|| tr(self.language, "세계관 문서", "World Document"));
        egui::Panel::top("document_tabs")
            .exact_size(theme::Metrics::TAB_BAR_HEIGHT)
            .frame(
                egui::Frame::new()
                    .fill(colors.surface_soft)
                    .stroke(Stroke::new(1.0, colors.border)),
            )
            .show(root, |ui| {
                ui.spacing_mut().item_spacing.x = 0.0;
                egui::ScrollArea::horizontal()
                    .scroll_source(egui::scroll_area::ScrollSource::ALL)
                    .scroll_bar_visibility(egui::scroll_area::ScrollBarVisibility::AlwaysHidden)
                    .show(ui, |ui| {
                        ui.horizontal(|ui| {
                            if workspace_tab(
                                ui,
                                tr(self.language, "프로젝트 홈", "Project Home"),
                                self.utility_page == Some(UtilityPage::ProjectHome),
                                colors,
                            )
                            .clicked()
                            {
                                self.utility_page = Some(UtilityPage::ProjectHome);
                            }
                            if workspace_tab(
                                ui,
                                &self.world.map.title,
                                self.utility_page.is_none() && self.section == Section::Map,
                                colors,
                            )
                            .clicked()
                            {
                                self.utility_page = None;
                                self.section = Section::Map;
                            }
                            if workspace_tab(
                                ui,
                                current_article,
                                self.utility_page.is_none() && self.section == Section::World,
                                colors,
                            )
                            .clicked()
                            {
                                self.utility_page = None;
                                self.section = Section::World;
                            }
                            if workspace_tab(
                                ui,
                                tr(self.language, "환경", "Environment"),
                                self.utility_page.is_none() && self.section == Section::Environment,
                                colors,
                            )
                            .clicked()
                            {
                                self.utility_page = None;
                                self.section = Section::Environment;
                            }
                            if matches!(self.utility_page, Some(UtilityPage::RpgRules)) {
                                let _ = workspace_tab(
                                    ui,
                                    tr(self.language, "RPG 규칙", "RPG Rules"),
                                    true,
                                    colors,
                                );
                            }
                            if matches!(self.utility_page, Some(UtilityPage::Flags)) {
                                let _ = workspace_tab(
                                    ui,
                                    tr(self.language, "깃발", "Flags"),
                                    true,
                                    colors,
                                );
                            }
                            if matches!(self.utility_page, Some(UtilityPage::Scripts)) {
                                let _ = workspace_tab(
                                    ui,
                                    tr(self.language, "문자", "Scripts"),
                                    true,
                                    colors,
                                );
                            }
                            if matches!(self.utility_page, Some(UtilityPage::Dictionary)) {
                                let _ = workspace_tab(
                                    ui,
                                    tr(self.language, "사전", "Dictionary"),
                                    true,
                                    colors,
                                );
                            }
                            if matches!(self.utility_page, Some(UtilityPage::Emblems)) {
                                let _ = workspace_tab(
                                    ui,
                                    tr(self.language, "문장", "Emblems"),
                                    true,
                                    colors,
                                );
                            }
                        });
                    });
            });
    }

    fn script_library_explorer(&mut self, root: &mut egui::Ui) {
        if let Some(article_id) = crate::scripts::explorer(
            root,
            self.dark_mode,
            self.language,
            &mut self.world.character_folders,
            &mut self.world.generated_glyphs,
            &mut self.script_workspace,
        ) {
            if let Some(index) = self
                .world
                .articles
                .iter()
                .position(|article| article.id == article_id)
            {
                self.selected_article = index;
                self.selected_category = self.world.articles[index].category_id.clone();
                self.section = Section::World;
                self.utility_page = None;
            }
        }
    }

    fn script_workspace(&mut self, root: &mut egui::Ui) {
        let voice_profile = self
            .world
            .dictionaries
            .first()
            .map(|book| book.voice_profile.clone())
            .unwrap_or_default();
        crate::scripts::workspace(
            root,
            self.dark_mode,
            self.language,
            &self.world.character_folders,
            &mut self.world.generated_glyphs,
            &mut self.script_workspace,
            &mut self.dictionary_ipa,
            &mut self.speech,
            &voice_profile,
        );
    }

    fn dictionary_explorer(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let language = self.language;
        let languages = self
            .world
            .articles
            .iter()
            .filter(|article| {
                category_is_language(&article.category)
                    && canonical_language_category(&article.category) == "language"
            })
            .map(|article| (article.id.clone(), article.title.clone()))
            .collect::<Vec<_>>();
        if self
            .dictionary_language_id
            .as_ref()
            .is_none_or(|id| !languages.iter().any(|(candidate, _)| candidate == id))
        {
            self.dictionary_language_id = languages.first().map(|(id, _)| id.clone());
        }
        let selected = self.dictionary_language_id.clone();
        egui::Panel::left("dictionary_explorer")
            .exact_size(theme::Metrics::EXPLORER_WIDTH)
            .resizable(false)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel_alt)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::same(12)),
            )
            .show(root, |ui| {
                ui.label(
                    RichText::new(tr(language, "언어 사전", "LANGUAGE DICTIONARIES"))
                        .size(12.0)
                        .strong()
                        .color(colors.title),
                );
                ui.separator();
                egui::ScrollArea::vertical()
                    .scroll_bar_visibility(egui::scroll_area::ScrollBarVisibility::AlwaysHidden)
                    .show(ui, |ui| {
                        for (id, title) in &languages {
                            if ui
                                .add_sized(
                                    [ui.available_width(), 34.0],
                                    egui::Button::selectable(selected.as_ref() == Some(id), title),
                                )
                                .clicked()
                            {
                                self.dictionary_language_id = Some(id.clone());
                                self.dictionary_search.clear();
                            }
                        }
                    });
                if languages.is_empty() {
                    ui.label(
                        RichText::new(tr(
                            language,
                            "언어 문서를 먼저 생성하세요.",
                            "Create a Language document first.",
                        ))
                        .size(9.5)
                        .color(colors.muted),
                    );
                }
            });
    }

    fn dictionary_workspace(&mut self, root: &mut egui::Ui) {
        let Some(language_id) = self.dictionary_language_id.clone() else {
            egui::CentralPanel::default().show(root, |ui| {
                ui.centered_and_justified(|ui| {
                    ui.label(tr(
                        self.language,
                        "사전을 연결할 언어 문서가 없습니다.",
                        "No Language document is available for a dictionary.",
                    ));
                });
            });
            return;
        };
        let title = self
            .world
            .articles
            .iter()
            .find(|article| article.id == language_id)
            .map(|article| article.title.clone())
            .unwrap_or_else(|| language_id.clone());
        let dark = self.dark_mode;
        let language = self.language;
        let tab = &mut self.dictionary_tab;
        let search = &mut self.dictionary_search;
        let state = &mut self.dictionary_ui;
        let ipa_state = &mut self.dictionary_ipa;
        let speech = &mut self.speech;
        let book_index = self
            .world
            .dictionaries
            .iter()
            .position(|book| book.language_article_id == language_id)
            .unwrap_or_else(|| {
                self.world.dictionaries.push(crate::model::DictionaryBook {
                    language_article_id: language_id.clone(),
                    ..Default::default()
                });
                self.world.dictionaries.len() - 1
            });
        let glyphs = &self.world.generated_glyphs;
        let book = &mut self.world.dictionaries[book_index];
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(theme::palette(dark).background)
                    .inner_margin(Margin::symmetric(28, 20)),
            )
            .show(root, |ui| {
                crate::dictionary::workspace(
                    ui, dark, language, &title, tab, search, state, book, glyphs, ipa_state, speech,
                );
            });
    }

    fn heraldry_library_explorer(&mut self, root: &mut egui::Ui, emblem: bool) {
        self.ensure_heraldry_selection(emblem);
        let colors = self.colors();
        let selected_id = self.heraldry_selected_asset_id.clone();
        let assets = self
            .world
            .heraldic_assets
            .iter()
            .filter(|asset| asset.is_emblem() == emblem)
            .cloned()
            .collect::<Vec<_>>();
        let mut selected_name = assets
            .iter()
            .find(|asset| Some(asset.id.as_str()) == selected_id.as_deref())
            .map(|asset| asset.name.clone())
            .unwrap_or_default();
        let mut selected_next = None;
        let mut create = false;
        let mut duplicate = false;
        let mut delete = false;
        let mut rename_changed = false;
        egui::Panel::left("heraldry_library")
            .exact_size(theme::Metrics::EXPLORER_WIDTH)
            .resizable(false)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::symmetric(9, 12)),
            )
            .show(root, |ui| {
                ui.label(
                    RichText::new(if emblem {
                        tr(self.language, "문장 목록", "EMBLEM LIBRARY")
                    } else {
                        tr(self.language, "깃발 목록", "FLAG LIBRARY")
                    })
                    .size(9.0)
                    .strong()
                    .color(colors.muted),
                );
                ui.add_space(6.0);
                ui.horizontal(|ui| {
                    let action_width = (ui.available_width() - 8.0) / 3.0;
                    create = vector_icon_button_sized(
                        ui,
                        UiIcon::Plus,
                        tr(self.language, "새로 만들기", "New"),
                        Vec2::new(action_width, 29.0),
                    )
                    .clicked();
                    duplicate = vector_icon_button_sized(
                        ui,
                        UiIcon::Duplicate,
                        tr(self.language, "복제", "Duplicate"),
                        Vec2::new(action_width, 29.0),
                    )
                    .clicked();
                    delete = vector_icon_button_sized(
                        ui,
                        UiIcon::Close,
                        tr(self.language, "삭제", "Delete"),
                        Vec2::new(action_width, 29.0),
                    )
                    .on_hover_text(tr(self.language, "삭제", "Delete"))
                    .clicked();
                });
                ui.add_space(6.0);
                rename_changed = ui
                    .add_sized(
                        [ui.available_width(), 28.0],
                        egui::TextEdit::singleline(&mut selected_name).hint_text(tr(
                            self.language,
                            "이름",
                            "Name",
                        )),
                    )
                    .changed();
                ui.separator();
                egui::ScrollArea::vertical()
                    .scroll_bar_visibility(egui::scroll_area::ScrollBarVisibility::AlwaysHidden)
                    .show(ui, |ui| {
                        for asset in &assets {
                            if heraldry_asset_library_row(
                                ui,
                                asset,
                                Some(asset.id.as_str()) == selected_id.as_deref(),
                                colors,
                            )
                            .clicked()
                            {
                                selected_next = Some(asset.id.clone());
                            }
                        }
                    });
            });
        if rename_changed {
            if let Some(asset) = self
                .world
                .heraldic_assets
                .iter_mut()
                .find(|asset| Some(asset.id.as_str()) == selected_id.as_deref())
            {
                asset.name = selected_name;
            }
        }
        if create {
            let design = if emblem {
                HeraldryDesign::emblem()
            } else {
                HeraldryDesign::flag()
            };
            let id = self.unique_heraldry_id(emblem);
            self.world.heraldic_assets.push(HeraldicAsset {
                id: id.clone(),
                kind: if emblem { "coatOfArms" } else { "flag" }.to_owned(),
                name: tr(
                    self.language,
                    if emblem { "새 문장" } else { "새 깃발" },
                    if emblem { "New Emblem" } else { "New Flag" },
                )
                .to_owned(),
                design,
            });
            selected_next = Some(id);
        } else if duplicate {
            if let Some(mut asset) = self
                .world
                .heraldic_assets
                .iter()
                .find(|asset| Some(asset.id.as_str()) == selected_id.as_deref())
                .cloned()
            {
                asset.id = self.unique_heraldry_id(emblem);
                asset.name = format!("{} {}", asset.name, tr(self.language, "복제본", "Copy"));
                selected_next = Some(asset.id.clone());
                self.world.heraldic_assets.push(asset);
            }
        } else if delete && assets.len() > 1 {
            if let Some(id) = selected_id.as_deref() {
                self.world.heraldic_assets.retain(|asset| asset.id != id);
                selected_next = self
                    .world
                    .heraldic_assets
                    .iter()
                    .find(|asset| asset.is_emblem() == emblem)
                    .map(|asset| asset.id.clone());
            }
        }
        if let Some(id) = selected_next {
            self.select_heraldry_asset(&id);
        }
    }

    fn ensure_heraldry_selection(&mut self, emblem: bool) {
        let valid = self
            .heraldry_selected_asset_id
            .as_deref()
            .is_some_and(|id| {
                self.world
                    .heraldic_assets
                    .iter()
                    .any(|asset| asset.id == id && asset.is_emblem() == emblem)
            });
        if valid {
            return;
        }
        if let Some(id) = self
            .world
            .heraldic_assets
            .iter()
            .find(|asset| asset.is_emblem() == emblem)
            .map(|asset| asset.id.clone())
        {
            self.select_heraldry_asset(&id);
            return;
        }
        let id = self.unique_heraldry_id(emblem);
        let design = if emblem {
            HeraldryDesign::emblem()
        } else {
            HeraldryDesign::flag()
        };
        self.world.heraldic_assets.push(HeraldicAsset {
            id: id.clone(),
            kind: if emblem { "coatOfArms" } else { "flag" }.to_owned(),
            name: tr(
                self.language,
                if emblem {
                    "기본 문장"
                } else {
                    "기본 깃발"
                },
                if emblem {
                    "Default Emblem"
                } else {
                    "Default Flag"
                },
            )
            .to_owned(),
            design,
        });
        self.select_heraldry_asset(&id);
    }

    fn reload_heraldry_designs(&mut self) {
        let flag = self
            .world
            .heraldic_assets
            .iter()
            .find(|asset| !asset.is_emblem())
            .cloned();
        let emblem = self
            .world
            .heraldic_assets
            .iter()
            .find(|asset| asset.is_emblem())
            .cloned();
        if let Some(asset) = flag {
            self.heraldry_selected_asset_id = Some(asset.id);
            self.flag_design = asset.design;
        } else if let Some(asset) = emblem.as_ref() {
            self.heraldry_selected_asset_id = Some(asset.id.clone());
        } else {
            self.heraldry_selected_asset_id = None;
        }
        if let Some(asset) = emblem {
            self.emblem_design = asset.design;
        }
    }

    fn select_heraldry_asset(&mut self, id: &str) {
        let Some(asset) = self
            .world
            .heraldic_assets
            .iter()
            .find(|asset| asset.id == id)
            .cloned()
        else {
            return;
        };
        let emblem = asset.is_emblem();
        self.heraldry_selected_asset_id = Some(asset.id);
        if emblem {
            self.emblem_design = asset.design;
        } else {
            self.flag_design = asset.design;
        }
        self.heraldry_selected_layer = 0;
        self.heraldry_layer_selected = true;
        self.heraldry_add_mode = None;
    }

    fn unique_heraldry_id(&self, emblem: bool) -> String {
        let prefix = if emblem { "emblem" } else { "flag" };
        let mut sequence = self.world.heraldic_assets.len() + 1;
        loop {
            let candidate = format!("native-{prefix}-{sequence}");
            if self
                .world
                .heraldic_assets
                .iter()
                .all(|asset| asset.id != candidate)
            {
                return candidate;
            }
            sequence += 1;
        }
    }

    fn project_explorer(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        egui::Panel::left("project_explorer")
            .exact_size(theme::Metrics::EXPLORER_WIDTH)
            .resizable(false)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::symmetric(9, 12)),
            )
            .show(root, |ui| {
                ui.label(
                    RichText::new(tr(self.language, "프로젝트", "PROJECT"))
                        .size(9.0)
                        .strong()
                        .color(colors.muted),
                );
                ui.label(
                    RichText::new(&self.world.title)
                        .size(13.0 * self.ui_scale)
                        .strong()
                        .color(colors.title),
                );
                ui.add_space(8.0);
                ui.separator();
                ui.add_space(5.0);
                ui.horizontal(|ui| {
                    let map = section_button(
                        ui,
                        &mut self.section,
                        Section::Map,
                        tr(self.language, "지도", "Map"),
                    );
                    let world = section_button(
                        ui,
                        &mut self.section,
                        Section::World,
                        tr(self.language, "세계관", "World"),
                    );
                    let environment = section_button(
                        ui,
                        &mut self.section,
                        Section::Environment,
                        tr(self.language, "환경", "Environment"),
                    );
                    if map || world || environment {
                        self.utility_page = None;
                    }
                });
                ui.add_space(6.0);
                egui::ScrollArea::vertical()
                    .scroll_bar_visibility(egui::scroll_area::ScrollBarVisibility::AlwaysHidden)
                    .show(ui, |ui| match self.section {
                        Section::Map => {
                            if tree_button(
                                ui,
                                "◉",
                                tr(self.language, "행성", "Planet"),
                                tr(self.language, "전역", "Global"),
                                self.map_page == MapPage::Planet,
                                colors,
                            )
                            .clicked()
                            {
                                self.map_page = MapPage::Planet;
                                self.utility_page = None;
                            }
                            ui.add_space(3.0);
                            explorer_heading(ui, tr(self.language, "지도", "MAPS"), colors);
                            for index in 0..self.world.maps.len() {
                                let trailing = if self.environment_map_index == index {
                                    tr(self.language, "현재", "Current")
                                } else {
                                    ""
                                };
                                if self.map_explorer_row(
                                    ui,
                                    index,
                                    trailing,
                                    self.environment_map_index == index
                                        && self.map_page == MapPage::Editor,
                                    colors,
                                ) {
                                    self.activate_map(index);
                                    self.map_page = MapPage::Editor;
                                }
                            }
                        }
                        Section::World => {
                            if timeline_explorer_row(
                                ui,
                                tr(self.language, "연표", "Timeline"),
                                &format!("{}", self.world.events.len()),
                                colors,
                            )
                            .clicked()
                            {
                                self.utility_page = None;
                            }
                            if self.world.categories.is_empty() {
                                for category in WORLD_CATEGORIES {
                                    if let Some(key) = category.key {
                                        let selected =
                                            self.selected_category.as_deref() == Some(key);
                                        let count = self
                                            .world
                                            .articles
                                            .iter()
                                            .filter(|article| article.category == key)
                                            .count();
                                        if tree_button_indented(
                                            ui,
                                            category.depth,
                                            category.label(self.language),
                                            &count.to_string(),
                                            selected,
                                            colors,
                                        )
                                        .clicked()
                                        {
                                            self.selected_category = Some(key.to_owned());
                                        }
                                    } else {
                                        tree_group_row(
                                            ui,
                                            category.depth,
                                            category.label(self.language),
                                            colors,
                                        );
                                    }
                                }
                            } else {
                                let categories = self.world.categories.clone();
                                for category_id in category_depth_first_order(&categories) {
                                    let Some(category) = categories
                                        .iter()
                                        .find(|category| category.id == category_id)
                                    else {
                                        continue;
                                    };
                                    if category_has_collapsed_ancestor(
                                        &categories,
                                        &category.id,
                                        &self.collapsed_category_ids,
                                    ) {
                                        continue;
                                    }
                                    let selected = self.selected_category.as_deref()
                                        == Some(category.id.as_str());
                                    let count =
                                        recursive_category_article_count(&self.world, &category.id);
                                    let has_children = categories.iter().any(|candidate| {
                                        candidate.parent_id.as_deref() == Some(category.id.as_str())
                                    });
                                    let (response, toggle) = category_tree_row(
                                        ui,
                                        category_depth(&self.world, &category.id),
                                        &category.name,
                                        &count.to_string(),
                                        selected,
                                        has_children,
                                        self.collapsed_category_ids.contains(&category.id),
                                        colors,
                                    );
                                    if toggle || (has_children && response.clicked()) {
                                        if !self.collapsed_category_ids.remove(&category.id) {
                                            self.collapsed_category_ids.insert(category.id.clone());
                                        }
                                    }
                                    if response.clicked() && !has_children {
                                        self.selected_category = Some(category.id.clone());
                                    }
                                }
                            }
                        }
                        Section::Environment => {
                            if tree_button(
                                ui,
                                "◎",
                                tr(self.language, "행성", "Planet"),
                                tr(self.language, "전체 환경", "Global climate"),
                                self.environment_planet_selected,
                                colors,
                            )
                            .clicked()
                            {
                                self.environment_planet_selected = true;
                            }
                            ui.add_space(3.0);
                            explorer_heading(ui, tr(self.language, "지도 목록", "MAPS"), colors);
                            for index in 0..self.world.maps.len() {
                                if self.map_explorer_row(
                                    ui,
                                    index,
                                    "",
                                    !self.environment_planet_selected
                                        && self.environment_map_index == index,
                                    colors,
                                ) {
                                    self.environment_planet_selected = false;
                                    self.activate_map(index);
                                }
                            }
                        }
                    });
            });
    }

    fn map_workspace(&mut self, root: &mut egui::Ui) {
        if self.map_page == MapPage::Planet {
            self.planet_workspace_v40(root);
            return;
        }
        if self.map_page == MapPage::Generator {
            self.generator_workspace_v25(root);
            return;
        }
        let colors = self.colors();
        egui::CentralPanel::default()
            .frame(egui::Frame::new().fill(colors.map_background))
            .show(root, |ui| {
                let rect = ui.available_rect_before_wrap();
                self.map_viewport_rect = rect;
                self.runtime_map_rect = None;
                self.fallback_map(ui);
            });
        self.fallback_map_overlays(root.ctx());
        self.fallback_map_mode_controls(root.ctx());
        self.fallback_tool_context_panel(root.ctx());
        self.fallback_map_entity_summary(root.ctx());
    }

    fn planet_workspace_v40(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let planet_texture = self.planet_surface_texture_id(root.ctx());
        let planet = self.world.planet.clone();
        let regions = self
            .world
            .regions
            .iter()
            .filter(|region| self.world.region_active_at(&region.id, self.year))
            .cloned()
            .collect::<Vec<_>>();
        let mut create_region = None;
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.map_background)
                    .inner_margin(Margin::same(18)),
            )
            .show(root, |ui| {
                ui.horizontal(|ui| {
                    ui.label(
                        RichText::new(format!(
                            "{} · {}",
                            self.world.title,
                            tr(self.language, "행성", "Planet")
                        ))
                        .size(19.0)
                        .strong()
                        .color(colors.title),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if filled_vector_icon_button(
                            ui,
                            UiIcon::Information,
                            tr(self.language, "행성 정보", "Planet Information"),
                            theme::Metrics::MAP_OVERLAY_ICON_SIZE,
                        )
                        .clicked()
                        {
                            self.planet_info_open = !self.planet_info_open;
                        }
                        if ui
                            .add_sized(
                                [104.0, 30.0],
                                egui::Button::selectable(
                                    !self.planet_globe_view,
                                    tr(self.language, "행성 지도", "Planet Map"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_globe_view = false;
                            self.planet_region_moving = false;
                        }
                        if ui
                            .add_sized(
                                [104.0, 30.0],
                                egui::Button::selectable(
                                    self.planet_globe_view,
                                    tr(self.language, "구체 보기", "Globe"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_globe_view = true;
                            self.planet_region_moving = false;
                        }
                    });
                });
                ui.add_space(10.0);
                let available = ui.available_rect_before_wrap();
                let canvas = Rect::from_center_size(
                    available.center(),
                    Vec2::new(available.width(), available.height().max(1.0)),
                );
                let response = ui.allocate_rect(canvas, Sense::click_and_drag());
                let planet_painter = ui.painter().with_clip_rect(canvas);
                planet_painter.rect_filled(canvas, 4.0, colors.panel_alt);
                let map_rect = planet_map_rect(canvas, self.planet_map_zoom, self.planet_map_pan);

                if self.planet_globe_view {
                    paint_planet_surface_globe(
                        &planet_painter,
                        canvas,
                        &planet.surface,
                        planet.physical.radius_m,
                        self.planet_globe_yaw,
                        self.planet_globe_pitch,
                        self.planet_globe_zoom,
                        &regions,
                        self.planet_region_draft.as_ref(),
                        colors,
                    );
                    paint_planet_rotation_axis(
                        &planet_painter,
                        canvas,
                        self.planet_globe_yaw,
                        self.planet_globe_pitch,
                        self.planet_globe_zoom,
                        PlanetReferenceFrame::from_physical(&planet.physical),
                        colors,
                    );
                } else {
                    paint_planet_surface_map(
                        &planet_painter,
                        map_rect,
                        &planet.surface,
                        planet_texture,
                        planet.physical.radius_m,
                        &regions,
                        self.planet_region_draft.as_ref(),
                        colors,
                    );
                }

                let select_button_rect = Rect::from_min_size(
                    Pos2::new(canvas.left() + 14.0, canvas.bottom() - 48.0),
                    Vec2::new(150.0, 34.0),
                );
                let mut toggle_selection = false;
                ui.scope_builder(egui::UiBuilder::new().max_rect(select_button_rect), |ui| {
                    if ui
                        .add_sized(
                            select_button_rect.size(),
                            egui::Button::selectable(
                                self.planet_region_selecting,
                                tr(self.language, "새 지도", "New Map"),
                            ),
                        )
                        .clicked()
                    {
                        toggle_selection = true;
                    }
                });
                if toggle_selection {
                    self.planet_region_selecting = !self.planet_region_selecting;
                    self.planet_region_moving = false;
                    if self.planet_region_selecting && self.planet_region_draft.is_none() {
                        let center = if self.planet_globe_view {
                            planet_position_from_globe(
                                canvas.center(),
                                canvas,
                                self.planet_globe_yaw,
                                self.planet_globe_pitch,
                                self.planet_globe_zoom,
                            )
                            .unwrap_or_default()
                        } else {
                            PlanetPosition::from_latitude_longitude_deg(0.0, 0.0)
                        };
                        self.planet_region_draft = Some(PlanetRegionDraft {
                            center,
                            width_km: self.planet_region_width_km,
                            height_km: self.planet_region_height_km,
                            rotation_deg: 0.0,
                            generation_config: RegionGenerationConfig::default(),
                        });
                    } else if !self.planet_region_selecting {
                        self.planet_region_draft = None;
                    }
                }

                let pointer_position = response.interact_pointer_pos();
                let hovered_planet_position = pointer_position.and_then(|pointer| {
                    if self.planet_globe_view {
                        planet_position_from_globe(
                            pointer,
                            canvas,
                            self.planet_globe_yaw,
                            self.planet_globe_pitch,
                            self.planet_globe_zoom,
                        )
                    } else {
                        planet_position_from_map(pointer, map_rect)
                    }
                });
                if self.planet_region_selecting {
                    if response.drag_started() {
                        self.planet_region_moving = hovered_planet_position.is_some();
                        self.planet_region_drag_start = hovered_planet_position;
                    }
                    if response.dragged() {
                        if self.planet_region_moving {
                            if self.planet_globe_view
                                && let Some(pointer) = pointer_position
                            {
                                let edge = 34.0;
                                let mut rotated = false;
                                if pointer.x < canvas.left() + edge {
                                    self.planet_globe_yaw += 0.018;
                                    rotated = true;
                                } else if pointer.x > canvas.right() - edge {
                                    self.planet_globe_yaw -= 0.018;
                                    rotated = true;
                                }
                                if pointer.y < canvas.top() + edge {
                                    self.planet_globe_pitch =
                                        (self.planet_globe_pitch - 0.012).clamp(-1.35, 1.35);
                                    rotated = true;
                                } else if pointer.y > canvas.bottom() - edge {
                                    self.planet_globe_pitch =
                                        (self.planet_globe_pitch + 0.012).clamp(-1.35, 1.35);
                                    rotated = true;
                                }
                                if rotated {
                                    ui.ctx().request_repaint();
                                }
                            }
                            let target = pointer_position.and_then(|pointer| {
                                if self.planet_globe_view {
                                    planet_position_from_globe(
                                        pointer,
                                        canvas,
                                        self.planet_globe_yaw,
                                        self.planet_globe_pitch,
                                        self.planet_globe_zoom,
                                    )
                                } else {
                                    planet_position_from_map(pointer, map_rect)
                                }
                            });
                            if let (Some(draft), Some(target)) =
                                (self.planet_region_draft.as_mut(), target)
                            {
                                draft.center = target;
                            }
                        } else if self.planet_globe_view {
                            let delta = ui.input(|input| input.pointer.delta());
                            self.planet_globe_yaw -= delta.x * 0.006;
                            self.planet_globe_pitch =
                                (self.planet_globe_pitch + delta.y * 0.006).clamp(-1.35, 1.35);
                        }
                    }
                    if response.drag_stopped() {
                        self.planet_region_moving = false;
                        self.planet_region_drag_start = None;
                    }
                } else if response.dragged() {
                    let delta = ui.input(|input| input.pointer.delta());
                    if self.planet_globe_view {
                        self.planet_globe_yaw -= delta.x * 0.006;
                        self.planet_globe_pitch =
                            (self.planet_globe_pitch + delta.y * 0.006).clamp(-1.35, 1.35);
                    } else {
                        self.planet_map_pan = clamp_planet_map_pan(
                            canvas,
                            self.planet_map_zoom,
                            self.planet_map_pan + delta,
                        );
                    }
                }
                if response.hovered() {
                    let scroll = ui.input(|input| input.smooth_scroll_delta.y);
                    if scroll != 0.0 {
                        if self.planet_globe_view {
                            self.planet_globe_zoom = (self.planet_globe_zoom
                                * (scroll * 0.0025).exp())
                            .clamp(0.65, 2.75);
                        } else if let Some(pointer) = pointer_position {
                            zoom_planet_map_at_pointer(
                                canvas,
                                pointer,
                                scroll,
                                &mut self.planet_map_zoom,
                                &mut self.planet_map_pan,
                            );
                        }
                        ui.ctx().request_repaint();
                    }
                }

                if self.planet_region_selecting
                    && let Some(mut draft) = self.planet_region_draft.clone()
                {
                    let panel_rect = Rect::from_min_size(
                        Pos2::new(canvas.left() + 14.0, canvas.top() + 14.0),
                        Vec2::new(318.0, 286.0),
                    );
                    let mut size_mode = self.planet_region_size_mode;
                    let mut width_km = self.planet_region_width_km;
                    let mut height_km = self.planet_region_height_km;
                    let mut aspect_ratio = self.planet_region_aspect_ratio;
                    ui.scope_builder(egui::UiBuilder::new().max_rect(panel_rect), |ui| {
                        overlay_frame(colors).show(ui, |ui| {
                            ui.set_min_width(panel_rect.width() - 18.0);
                            ui.label(
                                RichText::new(tr(
                                    self.language,
                                    "지도 영역 설정",
                                    "Map Area Settings",
                                ))
                                .size(15.0)
                                .strong()
                                .color(colors.title),
                            );
                            ui.add_space(8.0);
                            ui.horizontal(|ui| {
                                ui.selectable_value(
                                    &mut size_mode,
                                    PlanetRegionSizeMode::WidthAndAspect,
                                    tr(self.language, "폭 + 비율", "Width + Ratio"),
                                );
                                ui.selectable_value(
                                    &mut size_mode,
                                    PlanetRegionSizeMode::Independent,
                                    tr(self.language, "폭 + 높이", "Width + Height"),
                                );
                            });
                            ui.add_space(6.0);
                            ui.horizontal(|ui| {
                                ui.label(tr(self.language, "가로", "Width"));
                                ui.add_sized(
                                    [82.0, 26.0],
                                    egui::DragValue::new(&mut width_km)
                                        .range(1.0..=4_000.0)
                                        .suffix(" km"),
                                );
                                ui.label(tr(self.language, "세로", "Height"));
                                ui.add_enabled_ui(
                                    size_mode == PlanetRegionSizeMode::Independent,
                                    |ui| {
                                        ui.add_sized(
                                            [82.0, 26.0],
                                            egui::DragValue::new(&mut height_km)
                                                .range(1.0..=4_000.0)
                                                .suffix(" km"),
                                        );
                                    },
                                );
                            });
                            if size_mode == PlanetRegionSizeMode::WidthAndAspect {
                                height_km = (width_km / aspect_ratio.max(0.25)).clamp(1.0, 4_000.0);
                            } else {
                                aspect_ratio = (width_km / height_km.max(1.0)).clamp(0.25, 4.0);
                            }
                            ui.horizontal(|ui| {
                                ui.label(tr(self.language, "가로세로 비율", "Aspect"));
                                ui.add_enabled_ui(
                                    size_mode == PlanetRegionSizeMode::WidthAndAspect,
                                    |ui| {
                                        ui.add_sized(
                                            [176.0, 26.0],
                                            egui::DragValue::new(&mut aspect_ratio)
                                                .range(0.25..=4.0)
                                                .speed(0.01),
                                        );
                                    },
                                );
                            });
                            ui.horizontal(|ui| {
                                ui.label(tr(self.language, "회전", "Rotation"));
                                ui.add_sized(
                                    [176.0, 26.0],
                                    egui::DragValue::new(&mut draft.rotation_deg)
                                        .range(-180.0..=180.0)
                                        .speed(1.0)
                                        .suffix("°"),
                                );
                            });
                            ui.label(
                                RichText::new(format!(
                                    "{:.0} × {:.0} km · {:.2}:1",
                                    width_km, height_km, aspect_ratio
                                ))
                                .size(10.0)
                                .color(colors.muted),
                            );
                            ui.add_space(8.0);
                            if ui
                                .add_sized(
                                    [ui.available_width(), 32.0],
                                    egui::Button::new(tr(
                                        self.language,
                                        "지역 지도 생성",
                                        "Create Region Map",
                                    )),
                                )
                                .clicked()
                            {
                                create_region = Some(draft.clone());
                            }
                        });
                    });
                    self.planet_region_size_mode = size_mode;
                    self.planet_region_width_km = width_km.clamp(1.0, 4_000.0);
                    self.planet_region_height_km = height_km.clamp(1.0, 4_000.0);
                    self.planet_region_aspect_ratio = aspect_ratio.clamp(0.25, 4.0);
                    draft.width_km = self.planet_region_width_km;
                    draft.height_km = self.planet_region_height_km;
                    self.planet_region_draft = Some(draft);
                }

                if self.planet_info_open {
                    let panel_rect = Rect::from_min_size(
                        Pos2::new(canvas.right() - 304.0, canvas.top() + 14.0),
                        Vec2::new(290.0, 306.0),
                    );
                    ui.scope_builder(egui::UiBuilder::new().max_rect(panel_rect), |ui| {
                        overlay_frame(colors).show(ui, |ui| {
                            ui.set_min_width(panel_rect.width() - 18.0);
                            ui.horizontal(|ui| {
                                ui.label(
                                    RichText::new(tr(
                                        self.language,
                                        "행성 정보",
                                        "Planet Information",
                                    ))
                                    .size(16.0)
                                    .strong()
                                    .color(colors.title),
                                );
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    if vector_icon_button(
                                        ui,
                                        UiIcon::Close,
                                        tr(self.language, "닫기", "Close"),
                                        24.0,
                                    )
                                    .clicked()
                                    {
                                        self.planet_info_open = false;
                                    }
                                });
                            });
                            ui.separator();
                            let derived = planet.generation_config.derived_summary();
                            info_row(
                                ui,
                                tr(self.language, "반지름", "Radius"),
                                format!("{:.0} km", planet.physical.radius_m / 1_000.0),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "중력", "Gravity"),
                                format!("{:.2} m/s²", derived.surface_gravity_ms2),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "평균 기압", "Mean Pressure"),
                                format!("{:.1} kPa", derived.mean_surface_pressure_pa / 1_000.0),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "해양 면적", "Ocean Area"),
                                format!("{:.0}%", planet.surface.ocean_coverage() * 100.0),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "자전축 기울기", "Axial Tilt"),
                                format!("{:.1}°", planet.physical.axial_tilt_deg),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "지역 지도", "Regional Maps"),
                                regions.len().to_string(),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "공유 세부 타일", "Shared Detail Tiles"),
                                planet.detail_store.tiles.len().to_string(),
                                false,
                            );
                        });
                    });
                }
            });
        if let Some(draft) = create_region {
            self.begin_region_map_creation(draft);
        }
    }

    fn planet_workspace(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let planet = self.world.planet.clone();
        let config = planet.generation_config.clone();
        let derived = config.derived_summary();
        let regions = self.world.regions.clone();
        let mut create_region = None;
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.map_background)
                    .inner_margin(Margin::same(18)),
            )
            .show(root, |ui| {
                ui.horizontal(|ui| {
                    ui.label(
                        RichText::new(format!(
                            "{} · {}",
                            self.world.title,
                            tr(self.language, "행성", "Planet")
                        ))
                        .size(19.0)
                        .strong()
                        .color(colors.title),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if ui
                            .add_sized(
                                [132.0, 32.0],
                                egui::Button::selectable(
                                    self.planet_region_selecting,
                                    tr(self.language, "지도 영역 선택", "Select Map Area"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_region_selecting = !self.planet_region_selecting;
                            self.planet_region_drag_start = None;
                            if !self.planet_region_selecting {
                                self.planet_region_draft = None;
                            }
                        }
                        if ui
                            .add_sized(
                                [104.0, 30.0],
                                egui::Button::selectable(
                                    !self.planet_globe_view,
                                    tr(self.language, "행성 지도", "Planet Map"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_globe_view = false;
                            self.planet_region_drag_start = None;
                        }
                        if ui
                            .add_sized(
                                [104.0, 30.0],
                                egui::Button::selectable(
                                    self.planet_globe_view,
                                    tr(self.language, "구체 보기", "Globe"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_globe_view = true;
                            self.planet_region_drag_start = None;
                        }
                    });
                });
                ui.add_space(8.0);
                ui.columns(5, |columns| {
                    planet_metric(
                        &mut columns[0],
                        tr(self.language, "반지름", "Radius"),
                        &format!("{:.0} km", config.physical.radius_m / 1_000.0),
                        colors,
                    );
                    planet_metric(
                        &mut columns[1],
                        tr(self.language, "중력", "Gravity"),
                        &format!("{:.2} m/s2", derived.surface_gravity_ms2),
                        colors,
                    );
                    planet_metric(
                        &mut columns[2],
                        tr(self.language, "평균 기압", "Mean Pressure"),
                        &format!("{:.1} kPa", derived.mean_surface_pressure_pa / 1_000.0),
                        colors,
                    );
                    planet_metric(
                        &mut columns[3],
                        tr(self.language, "해양 비율", "Ocean Coverage"),
                        &format!("{:.0}%", planet.surface.ocean_coverage() * 100.0),
                        colors,
                    );
                    planet_metric(
                        &mut columns[4],
                        tr(self.language, "지역 지도", "Regional Maps"),
                        &regions.len().to_string(),
                        colors,
                    );
                });
                ui.add_space(12.0);
                let footer_height = if self.planet_region_draft.is_some() {
                    78.0
                } else {
                    0.0
                };
                let available = ui.available_rect_before_wrap();
                let canvas = Rect::from_min_max(
                    available.min,
                    Pos2::new(available.right(), available.bottom() - footer_height),
                );
                let response = ui.allocate_rect(canvas, Sense::click_and_drag());
                ui.painter().rect_filled(canvas, 4.0, colors.panel_alt);
                let map_rect = planet_map_rect(canvas, self.planet_map_zoom, self.planet_map_pan);
                let pointer_position = response.interact_pointer_pos();
                let hovered_planet_position = pointer_position.and_then(|pointer| {
                    if self.planet_globe_view {
                        planet_position_from_globe(
                            pointer,
                            canvas,
                            self.planet_globe_yaw,
                            self.planet_globe_pitch,
                            self.planet_globe_zoom,
                        )
                    } else {
                        planet_position_from_map(pointer, map_rect)
                    }
                });
                if self.planet_region_selecting {
                    if response.drag_started() {
                        self.planet_region_drag_start = hovered_planet_position;
                    }
                    if response.dragged()
                        && let (Some(start), Some(end)) =
                            (self.planet_region_drag_start, hovered_planet_position)
                    {
                        self.planet_region_draft = Some(build_planet_region_draft(
                            start,
                            end,
                            planet.physical.radius_m,
                        ));
                    }
                    if response.drag_stopped() {
                        self.planet_region_drag_start = None;
                    }
                } else if response.dragged() {
                    let delta = ui.input(|input| input.pointer.delta());
                    if self.planet_globe_view {
                        self.planet_globe_yaw -= delta.x * 0.006;
                        self.planet_globe_pitch =
                            (self.planet_globe_pitch + delta.y * 0.006).clamp(-1.35, 1.35);
                    } else {
                        self.planet_map_pan = clamp_planet_map_pan(
                            canvas,
                            self.planet_map_zoom,
                            self.planet_map_pan + delta,
                        );
                    }
                }
                if response.hovered() {
                    let scroll = ui.input(|input| input.smooth_scroll_delta.y);
                    if scroll != 0.0 {
                        if self.planet_globe_view {
                            self.planet_globe_zoom = (self.planet_globe_zoom
                                * (scroll * 0.0025).exp())
                            .clamp(0.65, 2.75);
                        } else if let Some(pointer) = pointer_position {
                            zoom_planet_map_at_pointer(
                                canvas,
                                pointer,
                                scroll,
                                &mut self.planet_map_zoom,
                                &mut self.planet_map_pan,
                            );
                        }
                        ui.ctx().request_repaint();
                    }
                }
                let planet_painter = ui.painter().with_clip_rect(canvas);
                if self.planet_globe_view {
                    paint_planet_surface_globe(
                        &planet_painter,
                        canvas,
                        &planet.surface,
                        planet.physical.radius_m,
                        self.planet_globe_yaw,
                        self.planet_globe_pitch,
                        self.planet_globe_zoom,
                        &regions,
                        self.planet_region_draft.as_ref(),
                        colors,
                    );
                    paint_planet_rotation_axis(
                        &planet_painter,
                        canvas,
                        self.planet_globe_yaw,
                        self.planet_globe_pitch,
                        self.planet_globe_zoom,
                        PlanetReferenceFrame::from_physical(&planet.physical),
                        colors,
                    );
                } else {
                    paint_planet_surface_map(
                        &planet_painter,
                        map_rect,
                        &planet.surface,
                        None,
                        planet.physical.radius_m,
                        &regions,
                        self.planet_region_draft.as_ref(),
                        colors,
                    );
                }
                if self.planet_region_selecting && self.planet_region_draft.is_none() {
                    ui.painter().text(
                        canvas.left_top() + Vec2::new(14.0, 14.0),
                        Align2::LEFT_TOP,
                        tr(
                            self.language,
                            "드래그하여 지도에 담을 영역을 선택하세요.",
                            "Drag to select the surface area for a map.",
                        ),
                        FontId::proportional(12.0),
                        colors.title,
                    );
                }
                if let Some(draft) = &mut self.planet_region_draft {
                    let footer = Rect::from_min_max(
                        Pos2::new(available.left(), canvas.bottom() + 8.0),
                        available.max,
                    );
                    ui.scope_builder(egui::UiBuilder::new().max_rect(footer), |ui| {
                        egui::Frame::new()
                            .fill(colors.surface)
                            .stroke(Stroke::new(1.0, colors.border))
                            .inner_margin(Margin::symmetric(12, 8))
                            .show(ui, |ui| {
                                ui.horizontal(|ui| {
                                    ui.label(
                                        RichText::new(format!(
                                            "{:.0} × {:.0} km",
                                            draft.width_km, draft.height_km
                                        ))
                                        .size(11.0)
                                        .color(colors.muted),
                                    );
                                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                        if ui
                                            .add_sized(
                                                [118.0, 32.0],
                                                egui::Button::new(tr(
                                                    self.language,
                                                    "지역 지도 생성",
                                                    "Create Region Map",
                                                )),
                                            )
                                            .clicked()
                                        {
                                            create_region = Some(draft.clone());
                                        }
                                    });
                                });
                            });
                    });
                }
            });
        if let Some(draft) = create_region {
            self.begin_region_map_creation(draft);
        }
    }

    #[allow(dead_code)]
    fn planet_workspace_legacy(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let config = self.world.planet.generation_config.clone();
        let derived = config.derived_summary();
        let geology = self.world.planet.geology.clone();
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.map_background)
                    .inner_margin(Margin::same(18)),
            )
            .show(root, |ui| {
                ui.horizontal(|ui| {
                    ui.label(
                        RichText::new(format!(
                            "{} · {}",
                            self.world.title,
                            tr(self.language, "행성", "Planet")
                        ))
                        .size(19.0)
                        .strong()
                        .color(colors.title),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if ui
                            .add_sized(
                                [104.0, 30.0],
                                egui::Button::selectable(
                                    !self.planet_globe_view,
                                    tr(self.language, "행성 지도", "Planet Map"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_globe_view = false;
                        }
                        if ui
                            .add_sized(
                                [104.0, 30.0],
                                egui::Button::selectable(
                                    self.planet_globe_view,
                                    tr(self.language, "구체 보기", "Globe"),
                                ),
                            )
                            .clicked()
                        {
                            self.planet_globe_view = true;
                        }
                    });
                });
                ui.add_space(8.0);
                ui.columns(5, |columns| {
                    planet_metric(
                        &mut columns[0],
                        tr(self.language, "반지름", "Radius"),
                        &format!("{:.0} km", config.physical.radius_m / 1_000.0),
                        colors,
                    );
                    planet_metric(
                        &mut columns[1],
                        tr(self.language, "중력", "Gravity"),
                        &format!("{:.2} m/s2", derived.surface_gravity_ms2),
                        colors,
                    );
                    planet_metric(
                        &mut columns[2],
                        tr(self.language, "평균 기압", "Mean Pressure"),
                        &format!("{:.1} kPa", derived.mean_surface_pressure_pa / 1_000.0),
                        colors,
                    );
                    planet_metric(
                        &mut columns[3],
                        tr(self.language, "예상 해양", "Estimated Ocean"),
                        &format!("{:.0}%", derived.estimated_ocean_coverage * 100.0),
                        colors,
                    );
                    planet_metric(
                        &mut columns[4],
                        tr(self.language, "주요 판", "Major Plates"),
                        &geology.plates.len().to_string(),
                        colors,
                    );
                });
                ui.add_space(12.0);
                let canvas = ui.available_rect_before_wrap();
                ui.allocate_rect(canvas, Sense::hover());
                ui.painter().rect_filled(canvas, 4.0, colors.panel_alt);
                ui.painter().rect_stroke(
                    canvas,
                    CornerRadius::same(4),
                    Stroke::new(1.0, colors.border),
                    egui::StrokeKind::Inside,
                );
                if self.planet_globe_view {
                    paint_planet_globe(ui.painter(), canvas, &geology, colors);
                } else {
                    paint_planet_map(ui.painter(), canvas, &geology, colors);
                }
            });
    }

    fn fallback_map_mode_controls(&mut self, context: &egui::Context) {
        if self.runtime_ready && self.runtime_embedded {
            return;
        }
        if !self.map_viewport_rect.is_positive() {
            return;
        }
        let colors = self.colors();
        let position =
            self.map_viewport_rect.left_top() + Vec2::splat(theme::Metrics::MAP_EDGE_INSET);
        egui::Area::new("map_mode_controls".into())
            .fixed_pos(position)
            .constrain_to(self.map_viewport_rect)
            .order(egui::Order::Foreground)
            .show(context, |ui| {
                overlay_frame(colors).show(ui, |ui| {
                    let mut changed = false;
                    let previous_tool = self.tool;
                    let mode_label = match self.map_edit_mode {
                        MapEditMode::View => tr(self.language, "열람 모드", "View Mode"),
                        MapEditMode::Civilization => {
                            tr(self.language, "문명 편집", "Civilization Edit")
                        }
                        MapEditMode::Terrain => tr(self.language, "환경 편집", "Environment Edit"),
                    };
                    if ui
                        .add_sized([158.0, 30.0], egui::Button::new(format!("{mode_label}  ›")))
                        .on_hover_text(tr(self.language, "모드 순환", "Cycle edit mode"))
                        .clicked()
                    {
                        self.map_edit_mode = match self.map_edit_mode {
                            MapEditMode::View => MapEditMode::Civilization,
                            MapEditMode::Civilization => MapEditMode::Terrain,
                            MapEditMode::Terrain => MapEditMode::View,
                        };
                        self.tool = Tool::Pan;
                        changed = true;
                    }
                    if self.map_edit_mode != MapEditMode::View {
                        ui.separator();
                        ui.set_width(158.0);
                        ui.horizontal(|ui| {
                            let undo = ui
                                .add_enabled_ui(!self.civilization_undo.is_empty(), |ui| {
                                    vector_icon_button(
                                        ui,
                                        UiIcon::Undo,
                                        tr(self.language, "실행 취소", "Undo"),
                                        30.0,
                                    )
                                })
                                .inner;
                            if undo.clicked() {
                                self.undo_civilization_transaction();
                            }
                            let redo = ui
                                .add_enabled_ui(!self.civilization_redo.is_empty(), |ui| {
                                    vector_icon_button(
                                        ui,
                                        UiIcon::Redo,
                                        tr(self.language, "다시 실행", "Redo"),
                                        30.0,
                                    )
                                })
                                .inner;
                            if redo.clicked() {
                                self.redo_civilization_transaction();
                            }
                        });
                        ui.vertical(|ui| {
                            changed |= compact_tool_button(
                                ui,
                                &mut self.tool,
                                Tool::Pan,
                                "↔",
                                tr(self.language, "이동", "Pan"),
                            );
                            if self.map_edit_mode == MapEditMode::Civilization {
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::Road,
                                    "╱",
                                    tr(self.language, "길", "Road"),
                                );
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::Territory,
                                    "◫",
                                    tr(self.language, "영토", "Territory"),
                                );
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::Place,
                                    "●",
                                    tr(self.language, "장소", "Place"),
                                );
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::Event,
                                    "◆",
                                    tr(self.language, "사건", "Event"),
                                );
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::PlaceName,
                                    "Aa",
                                    tr(self.language, "지명", "Place Name"),
                                );
                            } else {
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::Elevation,
                                    "△",
                                    tr(self.language, "고도", "Elevation"),
                                );
                                changed |= compact_tool_button(
                                    ui,
                                    &mut self.tool,
                                    Tool::Terrain,
                                    "▦",
                                    tr(self.language, "지형", "Terrain"),
                                );
                            }
                        });
                    }
                    if changed {
                        if previous_tool == Tool::Territory && self.tool != Tool::Territory {
                            if let Some(restore) = self.territory_visibility_restore.take() {
                                self.show_territories = restore;
                            }
                        } else if previous_tool != Tool::Territory && self.tool == Tool::Territory {
                            self.territory_visibility_restore = Some(self.show_territories);
                        }
                        match self.tool {
                            Tool::Terrain => self.terrain_layer_visible = true,
                            Tool::Elevation => {
                                self.terrain_layer_visible = true;
                                self.show_contours = true;
                                self.show_coastline = true;
                            }
                            Tool::Territory => self.show_territories = true,
                            Tool::Road => self.show_roads = true,
                            Tool::Place => self.show_locations = true,
                            Tool::Event => self.show_event_icons = true,
                            Tool::PlaceName => self.show_place_names = true,
                            Tool::Pan => {}
                        }
                        self.send_runtime_tool();
                    }
                });
            });
    }

    fn fallback_tool_context_panel(&mut self, context: &egui::Context) {
        if !self.map_viewport_rect.is_positive()
            || self.map_edit_mode == MapEditMode::View
            || !matches!(
                self.tool,
                Tool::Terrain | Tool::Elevation | Tool::Territory | Tool::PlaceName
            )
        {
            return;
        }
        let colors = self.colors();
        let mut finalize_place_name = false;
        let mut cancel_place_name = false;
        let tool_panel_height = match self.map_edit_mode {
            MapEditMode::Civilization => 326.0,
            MapEditMode::Terrain => 196.0,
            MapEditMode::View => 0.0,
        };
        let position = self.map_viewport_rect.left_top()
            + Vec2::new(
                theme::Metrics::MAP_EDGE_INSET,
                theme::Metrics::MAP_EDGE_INSET + tool_panel_height,
            );
        egui::Area::new("map_tool_context".into())
            .fixed_pos(position)
            .constrain_to(self.map_viewport_rect)
            .order(egui::Order::Foreground)
            .show(context, |ui| {
                ui.set_width(242.0);
                overlay_frame(colors).show(ui, |ui| {
                    let mut changed = false;
                    ui.label(
                        RichText::new(match self.tool {
                            Tool::Terrain => tr(self.language, "지형 편집", "Terrain Settings"),
                            Tool::Elevation => tr(self.language, "고도 편집", "Elevation Settings"),
                            Tool::Territory => tr(self.language, "영토 편집", "Territory Settings"),
                            Tool::PlaceName => {
                                tr(self.language, "지명 편집", "Place Name Settings")
                            }
                            _ => "",
                        })
                        .size(11.0)
                        .strong()
                        .color(colors.title),
                    );
                    ui.separator();
                    match self.tool {
                        Tool::Terrain => {
                            egui::ComboBox::from_id_salt("context-terrain")
                                .selected_text(terrain_label(self.language, self.selected_terrain))
                                .width(224.0)
                                .show_ui(ui, |ui| {
                                    for terrain in [
                                        "forest",
                                        "farmland",
                                        "plain",
                                        "grassland",
                                        "mountain",
                                        "desert",
                                    ] {
                                        changed |= ui
                                            .selectable_value(
                                                &mut self.selected_terrain,
                                                terrain,
                                                terrain_label(self.language, terrain),
                                            )
                                            .changed();
                                    }
                                });
                            changed |= ui
                                .add(
                                    egui::Slider::new(&mut self.terrain_brush_noise, 0.0..=1.0)
                                        .text(tr(self.language, "모양 노이즈", "Shape noise")),
                                )
                                .changed();
                        }
                        Tool::Elevation => {
                            ui.horizontal_wrapped(|ui| {
                                changed |= ui
                                    .selectable_value(
                                        &mut self.elevation_mode,
                                        ElevationBrushMode::Target,
                                        tr(self.language, "목표값", "Target"),
                                    )
                                    .changed();
                                changed |= ui
                                    .selectable_value(
                                        &mut self.elevation_mode,
                                        ElevationBrushMode::Raise,
                                        tr(self.language, "올리기", "Raise"),
                                    )
                                    .changed();
                                changed |= ui
                                    .selectable_value(
                                        &mut self.elevation_mode,
                                        ElevationBrushMode::Lower,
                                        tr(self.language, "내리기", "Lower"),
                                    )
                                    .changed();
                            });
                            let range = if self.elevation_mode == ElevationBrushMode::Target {
                                -1_000.0..=12_000.0
                            } else {
                                25.0..=2_000.0
                            };
                            changed |= ui
                                .add(egui::Slider::new(&mut self.elevation_delta, range).text(tr(
                                    self.language,
                                    "고도·변화량",
                                    "Elevation / Amount",
                                )))
                                .changed();
                            changed |= ui
                                .add(
                                    egui::Slider::new(&mut self.brush_strength, 0.05..=1.0)
                                        .text(tr(self.language, "강도", "Strength")),
                                )
                                .changed();
                            changed |= ui
                                .add(
                                    egui::Slider::new(&mut self.brush_falloff, 0.0..=1.0).text(tr(
                                        self.language,
                                        "경계 감쇠",
                                        "Falloff",
                                    )),
                                )
                                .changed();
                        }
                        Tool::Territory => {
                            let selected = self
                                .world
                                .map
                                .factions
                                .get(self.selected_faction_index)
                                .map(|faction| faction.name.as_str())
                                .unwrap_or(tr(self.language, "국가 미지정", "No country"));
                            egui::ComboBox::from_id_salt("context-territory-owner")
                                .selected_text(selected)
                                .width(224.0)
                                .show_ui(ui, |ui| {
                                    for (index, faction) in
                                        self.world.map.factions.iter().enumerate()
                                    {
                                        if faction.kind == "country" || faction.has_territory {
                                            changed |= ui
                                                .selectable_value(
                                                    &mut self.selected_faction_index,
                                                    index,
                                                    &faction.name,
                                                )
                                                .changed();
                                        }
                                    }
                                });
                        }
                        Tool::PlaceName => {
                            if let Some(draft) = &mut self.pending_place_name {
                                ui.add_sized(
                                    [224.0, 28.0],
                                    egui::TextEdit::singleline(&mut draft.text).hint_text(tr(
                                        self.language,
                                        "지명",
                                        "Place name",
                                    )),
                                );
                                ui.add(
                                    egui::Slider::new(&mut draft.font_size, 7.0..=42.0).text(tr(
                                        self.language,
                                        "글자 크기",
                                        "Font size",
                                    )),
                                );
                                ui.add(
                                    egui::Slider::new(&mut draft.letter_spacing, -2.0..=24.0)
                                        .text(tr(self.language, "글자 간격", "Letter spacing")),
                                );
                                ui.horizontal(|ui| {
                                    ui.checkbox(&mut draft.bold, tr(self.language, "굵게", "Bold"));
                                    ui.checkbox(
                                        &mut draft.italic,
                                        tr(self.language, "기울임", "Italic"),
                                    );
                                });
                                ui.horizontal(|ui| {
                                    finalize_place_name = ui
                                        .add_enabled(
                                            !draft.text.trim().is_empty(),
                                            egui::Button::new(tr(self.language, "확정", "Confirm")),
                                        )
                                        .clicked();
                                    cancel_place_name =
                                        ui.button(tr(self.language, "취소", "Cancel")).clicked();
                                });
                            } else {
                                ui.label(
                                    RichText::new(tr(
                                        self.language,
                                        "지도 위에서 지명 기준선을 드래그하세요.",
                                        "Drag a baseline on the map for the place name.",
                                    ))
                                    .size(9.0)
                                    .color(colors.muted),
                                );
                            }
                        }
                        _ => {}
                    }
                    if matches!(self.tool, Tool::Terrain | Tool::Elevation | Tool::Territory) {
                        changed |= ui
                            .add(
                                egui::Slider::new(&mut self.brush_radius, 0.5..=18.0).text(tr(
                                    self.language,
                                    "브러시 반경",
                                    "Brush radius",
                                )),
                            )
                            .changed();
                    }
                    if changed {
                        self.send_runtime_tool();
                    }
                });
            });
        if cancel_place_name {
            self.pending_place_name = None;
        }
        if finalize_place_name {
            if let Some(draft) = self.pending_place_name.take() {
                let Some(path) = longest_land_interval(&self.world.map, &draft.path) else {
                    self.notify(tr(
                        self.language,
                        "지명은 육지 위에만 배치할 수 있습니다.",
                        "Place names can only be placed on land.",
                    ));
                    return;
                };
                let index = self.world.map.place_names.len() + 1;
                let position = path[path.len() / 2];
                self.begin_civilization_transaction();
                self.world.map.place_names.push(crate::model::PlaceName {
                    id: format!("native-place-name-{index}-{}", self.year),
                    article_id: None,
                    name: draft.text,
                    position,
                    path,
                    start_year: self.year,
                    end_year: None,
                    font_size: draft.font_size,
                    letter_spacing: draft.letter_spacing,
                    bold: draft.bold,
                    italic: draft.italic,
                });
                self.finish_civilization_transaction();
                self.tool = Tool::Pan;
                self.send_runtime_tool();
            }
        }
    }

    fn fallback_map_entity_summary(&mut self, context: &egui::Context) {
        let Some(selected) = self.selected_map_entity.clone() else {
            return;
        };
        let (title, kind_label, article_id, warning) = match &selected {
            SelectedMapEntity::Place(id) => {
                let Some(location) = self
                    .world
                    .map
                    .locations
                    .iter()
                    .find(|location| &location.id == id)
                else {
                    self.selected_map_entity = None;
                    return;
                };
                let Some(state) = location.state_at(self.year) else {
                    self.selected_map_entity = None;
                    return;
                };
                (
                    state.name.clone(),
                    tr(self.language, "장소", "Place"),
                    location.article_id.clone(),
                    location.water_position_warning,
                )
            }
            SelectedMapEntity::Event(id) => {
                let Some(event) = self.world.map.events.iter().find(|event| &event.id == id) else {
                    self.selected_map_entity = None;
                    return;
                };
                (
                    event.title.clone(),
                    tr(self.language, "사건", "Event"),
                    event.article_id.clone(),
                    event.water_position_warning,
                )
            }
        };
        let colors = self.colors();
        let position = self.map_viewport_rect.left_bottom()
            + Vec2::new(theme::Metrics::MAP_EDGE_INSET, -154.0);
        let mut close = false;
        let mut open_document = false;
        let mut save_name = false;
        let mut delete_marker = false;
        let mut delete_document = false;
        egui::Area::new("map_entity_summary".into())
            .fixed_pos(position)
            .constrain_to(self.map_viewport_rect)
            .order(egui::Order::Foreground)
            .show(context, |ui| {
                ui.set_width(252.0);
                overlay_frame(colors).show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.label(RichText::new(kind_label).size(8.5).color(colors.muted));
                        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                            close = ui.small_button("×").clicked();
                        });
                    });
                    ui.label(
                        RichText::new(&title)
                            .size(13.0)
                            .strong()
                            .color(colors.title),
                    );
                    if warning {
                        ui.label(
                            RichText::new(tr(
                                self.language,
                                "현재 위치가 물 영역입니다.",
                                "The current position is over water.",
                            ))
                            .size(8.5)
                            .color(colors.danger),
                        );
                    }
                    ui.horizontal(|ui| {
                        if ui.button(tr(self.language, "편집", "Edit")).clicked() {
                            self.map_entity_editing = !self.map_entity_editing;
                            self.map_entity_name = title.clone();
                        }
                        open_document = ui
                            .add_enabled(
                                article_id.is_some(),
                                egui::Button::new(tr(self.language, "문서", "Document")),
                            )
                            .clicked();
                    });
                    if self.map_entity_editing {
                        ui.add_sized(
                            [ui.available_width(), 27.0],
                            egui::TextEdit::singleline(&mut self.map_entity_name),
                        );
                        ui.horizontal(|ui| {
                            save_name = ui
                                .add_enabled(
                                    !self.map_entity_name.trim().is_empty(),
                                    egui::Button::new(tr(self.language, "이름 저장", "Save name")),
                                )
                                .clicked();
                            delete_marker = ui
                                .button(tr(self.language, "표식 삭제", "Delete marker"))
                                .clicked();
                            delete_document = ui
                                .add_enabled(
                                    article_id.is_some(),
                                    egui::Button::new(tr(
                                        self.language,
                                        "문서도 삭제",
                                        "Delete both",
                                    )),
                                )
                                .clicked();
                        });
                    }
                });
            });
        if close {
            self.selected_map_entity = None;
            self.map_entity_editing = false;
        }
        if open_document
            && let Some(article_id) = article_id.as_deref()
            && let Some(index) = self
                .world
                .articles
                .iter()
                .position(|article| article.id == article_id)
        {
            self.selected_article = index;
            self.selected_category = self.world.articles[index]
                .category_id
                .clone()
                .or_else(|| Some(self.world.articles[index].category.clone()));
            self.section = Section::World;
            self.utility_page = None;
        }
        if save_name {
            let name = self.map_entity_name.trim().to_owned();
            match &selected {
                SelectedMapEntity::Place(id) => {
                    if let Some(location) = self
                        .world
                        .map
                        .locations
                        .iter_mut()
                        .find(|location| &location.id == id)
                    {
                        if let Some(state) = location
                            .states
                            .iter_mut()
                            .rev()
                            .find(|state| state.start_year <= self.year)
                        {
                            state.name = name.clone();
                        }
                    }
                }
                SelectedMapEntity::Event(id) => {
                    if let Some(event) = self
                        .world
                        .map
                        .events
                        .iter_mut()
                        .find(|event| &event.id == id)
                    {
                        event.title = name.clone();
                    }
                }
            }
            if let Some(article_id) = article_id.as_deref()
                && let Some(article) = self
                    .world
                    .articles
                    .iter_mut()
                    .find(|article| article.id == article_id)
            {
                article.title = name;
            }
            self.map_entity_editing = false;
            self.sync_active_map_snapshot();
        }
        if delete_marker || delete_document {
            self.begin_civilization_transaction();
            match &selected {
                SelectedMapEntity::Place(id) => self
                    .world
                    .map
                    .locations
                    .retain(|location| &location.id != id),
                SelectedMapEntity::Event(id) => {
                    self.world.map.events.retain(|event| &event.id != id)
                }
            }
            if delete_document && let Some(article_id) = article_id.as_deref() {
                self.world
                    .articles
                    .retain(|article| article.id != article_id);
            }
            self.selected_map_entity = None;
            self.map_entity_editing = false;
            self.finish_civilization_transaction();
        }
    }

    fn fallback_map_overlays(&mut self, context: &egui::Context) {
        if !self.map_viewport_rect.is_positive() {
            return;
        }
        let colors = self.colors();
        let panel_width = theme::Metrics::MAP_OVERLAY_WIDTH;
        let (mut panel_position, button_position, panel_content_position, overlay_right) =
            map_overlay_fixed_geometry(self.map_viewport_rect, panel_width);
        let pointer_width = 282.0_f32.min(panel_width);
        panel_position.x = overlay_right - pointer_width;
        egui::Area::new("fallback_pointer_panel".into())
            .fixed_pos(panel_position)
            .constrain_to(self.map_viewport_rect)
            .order(egui::Order::Foreground)
            .show(context, |ui| {
                ui.set_width(pointer_width);
                ui.set_max_width(overlay_right - panel_position.x);
                overlay_frame(colors).show(ui, |ui| {
                    ui.set_min_width(pointer_width - 18.0);
                    if let Some((point, elevation, zoom, surface)) = self.pointer_sample {
                        ui.label(
                            RichText::new(format!(
                                "X {:.2}   Y {:.2}   {:.0} m   {}",
                                point.x,
                                point.y,
                                elevation,
                                pointer_surface_label(self.language, surface)
                            ))
                            .size(10.0)
                            .color(colors.title),
                        );
                        ui.label(
                            RichText::new(format!("Zoom {:.2}×", zoom.max(0.01)))
                                .size(9.0)
                                .color(colors.muted),
                        );
                        if let Ok(position) = self.world.active_point_to_planet(point) {
                            let (latitude, longitude) = position.latitude_longitude_deg();
                            ui.label(
                                RichText::new(format!("Lat {latitude:.4}°   Lon {longitude:.4}°"))
                                    .size(9.0)
                                    .color(colors.muted),
                            );
                        }
                    } else {
                        ui.label(
                            RichText::new(tr(
                                self.language,
                                "지도 위에 포인터를 올리세요",
                                "Move the pointer over the map",
                            ))
                            .size(10.0)
                            .color(colors.muted),
                        );
                    }
                });
            });
        egui::Area::new("fallback_map_overlay_buttons".into())
            .fixed_pos(button_position)
            .constrain_to(self.map_viewport_rect)
            .order(egui::Order::Foreground)
            .show(context, |ui| {
                ui.set_width(74.0);
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if filled_vector_icon_button(
                        ui,
                        UiIcon::Information,
                        tr(self.language, "지도 정보", "Map Information"),
                        theme::Metrics::MAP_OVERLAY_ICON_SIZE,
                    )
                    .clicked()
                    {
                        self.map_info_open = !self.map_info_open;
                        self.layer_panel_open = false;
                    }
                    if filled_vector_icon_button(
                        ui,
                        UiIcon::Layers,
                        tr(self.language, "레이어 표시", "Layer Display"),
                        theme::Metrics::MAP_OVERLAY_ICON_SIZE,
                    )
                    .clicked()
                    {
                        self.layer_panel_open = !self.layer_panel_open;
                        self.map_info_open = false;
                    }
                });
            });
        if self.layer_panel_open {
            egui::Area::new("fallback_layer_panel".into())
                .fixed_pos(panel_content_position)
                .constrain_to(self.map_viewport_rect)
                .order(egui::Order::Foreground)
                .show(context, |ui| {
                    ui.set_width(panel_width);
                    overlay_frame(colors).show(ui, |ui| {
                        ui.set_min_width(panel_width - 18.0);
                        let mut changed = false;
                        changed |= ui
                            .checkbox(
                                &mut self.terrain_layer_visible,
                                tr(self.language, "지형 표시", "Terrain"),
                            )
                            .changed();
                        ui.horizontal(|ui| {
                            ui.label(
                                RichText::new(tr(
                                    self.language,
                                    "레이어 불투명도",
                                    "Layer Opacity",
                                ))
                                .size(9.0)
                                .color(colors.muted),
                            );
                            let opacity_changed = ui
                                .add(
                                    egui::Slider::new(&mut self.layer_opacity, 0.0..=1.0)
                                        .show_value(false),
                                )
                                .changed();
                            ui.label(
                                RichText::new(format!("{:.0}%", self.layer_opacity * 100.0))
                                    .size(9.0)
                                    .color(colors.title),
                            );
                            if opacity_changed {
                                self.map_render
                                    .rebuild_territory(&self.world.map, self.layer_opacity);
                                self.map_render.invalidate_environment();
                                changed = true;
                            }
                        });
                        ui.separator();
                        ui.label(
                            RichText::new(tr(self.language, "기상·기후", "Weather & Climate"))
                                .size(9.0)
                                .strong()
                                .color(colors.muted),
                        );
                        egui::Grid::new("weather-climate-layer-grid")
                            .num_columns(2)
                            .min_col_width((panel_width - 44.0) * 0.5)
                            .show(ui, |ui| {
                                for (index, layer) in EnvironmentLayer::ALL.into_iter().enumerate()
                                {
                                    let selected = self.environment_layer == Some(layer);
                                    let label = environment_layer_period_label(
                                        self.language,
                                        &self.world.display_calendar(self.language),
                                        self.timeline_precision,
                                        layer,
                                    );
                                    if left_selectable_button(
                                        ui,
                                        [(panel_width - 44.0) * 0.5, 28.0],
                                        &label,
                                        selected,
                                        colors,
                                    )
                                    .clicked()
                                    {
                                        self.environment_layer =
                                            if selected { None } else { Some(layer) };
                                        self.show_environment_layer =
                                            self.environment_layer.is_some();
                                        self.map_render.invalidate_environment();
                                        changed = true;
                                    }
                                    if index % 2 == 1 {
                                        ui.end_row();
                                    }
                                }
                                if EnvironmentLayer::ALL.len() % 2 == 1 {
                                    ui.end_row();
                                }
                            });
                        ui.separator();
                        ui.label(
                            RichText::new(tr(self.language, "정치·인문", "Political & Human"))
                                .size(9.0)
                                .strong()
                                .color(colors.muted),
                        );
                        egui::Grid::new("political-human-layer-grid")
                            .num_columns(2)
                            .show(ui, |ui| {
                                let territory_changed = ui
                                    .checkbox(
                                        &mut self.show_territories,
                                        tr(self.language, "국가 영토", "Territories"),
                                    )
                                    .changed();
                                changed |= territory_changed;
                                if territory_changed && self.tool == Tool::Territory {
                                    self.territory_visibility_restore = Some(self.show_territories);
                                }
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_country_names,
                                        tr(self.language, "국명", "Country Names"),
                                    )
                                    .changed();
                                ui.end_row();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_roads,
                                        tr(self.language, "길", "Roads"),
                                    )
                                    .changed();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_locations,
                                        tr(self.language, "장소", "Places"),
                                    )
                                    .changed();
                                ui.end_row();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_place_names,
                                        tr(self.language, "지명 라벨", "Place Labels"),
                                    )
                                    .changed();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_event_icons,
                                        tr(self.language, "사건 아이콘", "Event Icons"),
                                    )
                                    .changed();
                                ui.end_row();
                            });
                        ui.separator();
                        ui.label(
                            RichText::new(tr(self.language, "오버레이", "Overlay"))
                                .size(9.0)
                                .strong()
                                .color(colors.muted),
                        );
                        egui::Grid::new("overlay-layer-grid")
                            .num_columns(2)
                            .show(ui, |ui| {
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_contours,
                                        tr(self.language, "등고선", "Contours"),
                                    )
                                    .changed();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_coastline,
                                        tr(self.language, "해안선", "Coastline"),
                                    )
                                    .changed();
                                ui.end_row();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_rivers,
                                        tr(self.language, "강", "Rivers"),
                                    )
                                    .changed();
                                changed |= ui
                                    .checkbox(
                                        &mut self.show_wind_direction,
                                        tr(self.language, "풍향", "Wind Direction"),
                                    )
                                    .changed();
                                ui.end_row();
                            });
                        if changed {
                            if let Some(runtime) = &self.runtime {
                                runtime.send_layers(
                                    self.show_rivers,
                                    self.show_roads,
                                    self.show_locations,
                                    self.show_environment_layer,
                                    self.show_territories,
                                    self.language == Language::English,
                                );
                            }
                        }
                    });
                });
        } else if self.map_info_open {
            egui::Area::new("fallback_map_info_panel".into())
                .fixed_pos(panel_content_position)
                .constrain_to(self.map_viewport_rect)
                .order(egui::Order::Foreground)
                .show(context, |ui| {
                    ui.set_width(panel_width);
                    overlay_frame(colors).show(ui, |ui| {
                        ui.set_min_width(panel_width - 18.0);
                        self.map_name_info_row(ui);
                        info_row(
                            ui,
                            tr(self.language, "지도 크기", "Map Size"),
                            format!(
                                "{:.0} × {:.0} km",
                                self.world.map.width, self.world.map.height
                            ),
                            false,
                        );
                        let (pixel_width, pixel_height) = self.world.map.logical_pixel_dimensions();
                        info_row(
                            ui,
                            tr(self.language, "논리 해상도", "Logical Resolution"),
                            format!("{pixel_width} × {pixel_height} px"),
                            false,
                        );
                        info_row(
                            ui,
                            tr(self.language, "현재 연도", "Current Year"),
                            self.year.to_string(),
                            false,
                        );
                        info_row(
                            ui,
                            tr(self.language, "생성 시드", "Generation Seed"),
                            self.world.map.environment_seed.to_string(),
                            false,
                        );
                    });
                });
        }
        let scale_anchor =
            self.map_viewport_rect.right_bottom() - Vec2::splat(theme::Metrics::MAP_EDGE_INSET);
        if let Some(layer) = self.environment_layer {
            egui::Area::new("fallback_climate_legend".into())
                .pivot(Align2::RIGHT_BOTTOM)
                .fixed_pos(scale_anchor - Vec2::new(0.0, 62.0))
                .constrain_to(self.map_viewport_rect)
                .order(egui::Order::Foreground)
                .show(context, |ui| {
                    egui::Frame::new()
                        .fill(Color32::from_rgba_premultiplied(
                            colors.panel.r(),
                            colors.panel.g(),
                            colors.panel.b(),
                            238,
                        ))
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(CornerRadius::same(5))
                        .inner_margin(Margin::same(8))
                        .show(ui, |ui| {
                            ui.set_width(theme::Metrics::MAP_SCALE_WIDTH - 24.0);
                            ui.label(
                                RichText::new(environment_layer_label(self.language, layer))
                                    .size(9.0)
                                    .color(colors.muted),
                            );
                            environment_gradient_legend(ui, layer, colors);
                        });
                });
        }
        egui::Area::new("fallback_map_scale".into())
            .pivot(Align2::RIGHT_BOTTOM)
            .fixed_pos(scale_anchor)
            .constrain_to(self.map_viewport_rect)
            .order(egui::Order::Foreground)
            .show(context, |ui| {
                egui::Frame::new()
                    .fill(Color32::from_rgba_premultiplied(
                        colors.panel.r(),
                        colors.panel.g(),
                        colors.panel.b(),
                        238,
                    ))
                    .stroke(Stroke::new(1.0, colors.border))
                    .corner_radius(CornerRadius::same(5))
                    .inner_margin(Margin::same(8))
                    .show(ui, |ui| {
                        ui.set_min_height(theme::Metrics::MAP_SCALE_HEIGHT - 16.0);
                        let scale = visible_scale_bar(
                            self.scene_rect.width(),
                            fitted_scene_content_rect(self.map_viewport_rect, self.scene_rect)
                                .width(),
                            theme::Metrics::MAP_SCALE_WIDTH - 24.0,
                        );
                        let (line_rect, _) = ui.allocate_exact_size(
                            Vec2::new(theme::Metrics::MAP_SCALE_WIDTH - 24.0, 8.0),
                            Sense::hover(),
                        );
                        let line_right = line_rect.left() + scale.pixel_width;
                        ui.painter().line_segment(
                            [
                                Pos2::new(line_rect.left(), line_rect.center().y),
                                Pos2::new(line_right, line_rect.center().y),
                            ],
                            Stroke::new(2.0, colors.title),
                        );
                        for x in [line_rect.left(), line_right] {
                            ui.painter().line_segment(
                                [
                                    Pos2::new(x, line_rect.top()),
                                    Pos2::new(x, line_rect.bottom()),
                                ],
                                Stroke::new(2.0, colors.title),
                            );
                        }
                        ui.vertical_centered(|ui| {
                            let label = if scale.distance_km < 1.0 {
                                format!("{:.0} m", scale.distance_km * 1_000.0)
                            } else if scale.distance_km < 10.0 {
                                format!("{:.1} km", scale.distance_km)
                            } else {
                                format!("{:.0} km", scale.distance_km)
                            };
                            ui.label(RichText::new(label).size(10.0).strong().color(colors.title));
                        });
                    });
            });
    }

    fn fallback_pipeline_debug_overlay(&self, context: &egui::Context, screen_scale: f32) {
        if !self.pipeline_debug_overlay || !self.map_viewport_rect.is_positive() {
            return;
        }
        let colors = self.colors();
        let map = &self.world.map;
        let texture_stats = self.terrain_textures.stats();
        let render_stats = self.map_render.stats();
        let canonical = map
            .canonical_surface
            .as_ref()
            .map(|surface| format!("{}x{}", surface.width, surface.height))
            .unwrap_or_else(|| "none".to_owned());
        let target_resolution_m = map
            .generation_settings
            .as_ref()
            .map_or(f64::from(map.surface_cell_m), |settings| {
                settings.target_resolution_m
            });
        let region = map.region_id.as_ref().and_then(|region_id| {
            self.world
                .regions
                .iter()
                .find(|region| &region.id == region_id)
        });
        let detail = map.region_id.as_ref().and_then(|region_id| {
            self.world
                .detailed_regions
                .iter()
                .find(|detail| &detail.region_id == region_id)
        });
        let preflight = region.and_then(|region| {
            region
                .selection
                .metric_bounds()
                .and_then(|(_, width_m, height_m, _)| {
                    region_preflight(width_m, height_m, &region.generation_config).ok()
                })
        });
        let position = Pos2::new(
            self.map_viewport_rect.left() + 12.0,
            self.map_viewport_rect.top() + 72.0,
        );
        egui::Area::new("map_pipeline_debug_overlay".into())
            .fixed_pos(position)
            .order(egui::Order::Foreground)
            .constrain_to(self.map_viewport_rect)
            .show(context, |ui| {
                egui::Frame::new()
                    .fill(Color32::from_rgba_premultiplied(
                        colors.panel.r(),
                        colors.panel.g(),
                        colors.panel.b(),
                        244,
                    ))
                    .stroke(Stroke::new(1.0, colors.accent))
                    .corner_radius(CornerRadius::same(5))
                    .inner_margin(Margin::same(9))
                    .show(ui, |ui| {
                        ui.set_width(390.0);
                        ui.label(
                            RichText::new("MAP PIPELINE DEBUG")
                                .size(10.5)
                                .strong()
                                .color(colors.title),
                        );
                        ui.separator();
                        ui.label(
                            RichText::new(format!(
                                "Zoom -> render LOD: scale {screen_scale:.4}, LOD {}, {} visible, {} uploads",
                                texture_stats.active_lod,
                                texture_stats.visible_tile_count,
                                texture_stats.last_upload_count,
                            ))
                            .size(9.0)
                            .color(colors.text),
                        );
                        ui.label(
                            RichText::new(format!(
                                "target_resolution -> DetailedRegion: {target_resolution_m:.1} m, output {}",
                                detail
                                    .map(|value| format!(
                                        "{}x{} / {} patches",
                                        value.output_width_cells,
                                        value.output_height_cells,
                                        value.patch_refs.len()
                                    ))
                                    .unwrap_or_else(|| "none".to_owned()),
                            ))
                            .size(9.0)
                            .color(colors.text),
                        );
                        if let Some(preflight) = &preflight {
                            ui.label(
                                RichText::new(format!(
                                    "regional_preflight: requested {}, analysis {}, CPU est. {:.2} MiB",
                                    preflight.requested_cells,
                                    preflight.analysis_cells,
                                    preflight.estimated_cpu_peak_bytes as f64 / (1024.0 * 1024.0),
                                ))
                                .size(9.0)
                                .color(colors.text),
                            );
                        }
                        ui.label(
                            RichText::new(format!(
                                "analysis -> CanonicalSurface: {}x{} -> {canonical}",
                                map.grid_width, map.grid_height,
                            ))
                            .size(9.0)
                            .color(colors.text),
                        );
                        ui.label(
                            RichText::new(format!(
                                "Plate -> elevation: {} plates, planet {}x{}; Triangle = render-only 240x120",
                                self.world.planet.geology.plates.len(),
                                self.world.planet.surface.width,
                                self.world.planet.surface.height,
                            ))
                            .size(9.0)
                            .color(colors.text),
                        );
                        ui.separator();
                        ui.label(
                            RichText::new(format!(
                                "render: texture {:.3} ms (tile {:.3}, overview {:.3}); river {:.3}, shore {:.3}, contour {:.3} ms",
                                texture_stats.last_ensure_micros as f64 / 1_000.0,
                                texture_stats.last_tile_build_micros as f64 / 1_000.0,
                                texture_stats.last_overview_build_micros as f64 / 1_000.0,
                                render_stats.last_river_build_micros as f64 / 1_000.0,
                                render_stats.last_shoreline_build_micros as f64 / 1_000.0,
                                render_stats.last_contour_build_micros as f64 / 1_000.0,
                            ))
                            .size(9.0)
                            .color(colors.accent),
                        );
                        ui.label(
                            RichText::new(format!(
                                "cache: {} requested / {} hits / {} misses / {} built; {} virtual canonical samples",
                                texture_stats.last_tiles_requested,
                                texture_stats.last_tile_cache_hits,
                                texture_stats.last_tile_cache_misses,
                                texture_stats.last_tiles_built,
                                texture_stats.last_canonical_cells_virtual,
                            ))
                            .size(9.0)
                            .color(colors.accent),
                        );
                        ui.label(
                            RichText::new(format!(
                                "texture phases: LOD {:.3}, visible {:.3}, lookup {:.3}, CPU {:.3}, encode {:.3}, submit {:.3} ms",
                                texture_stats.last_lod_selection_micros as f64 / 1_000.0,
                                texture_stats.last_visible_chunk_query_micros as f64 / 1_000.0,
                                texture_stats.last_cache_lookup_micros as f64 / 1_000.0,
                                texture_stats.last_tile_cpu_synthesis_micros as f64 / 1_000.0,
                                texture_stats.last_texture_encode_micros as f64 / 1_000.0,
                                texture_stats.last_texture_submission_micros as f64 / 1_000.0,
                            ))
                            .size(9.0)
                            .color(colors.muted),
                        );
                        for stage in &map.generation_diagnostics.stages {
                            ui.label(
                                RichText::new(format!(
                                    "{}: {:.3} ms",
                                    stage.name,
                                    stage.elapsed_micros as f64 / 1_000.0,
                                ))
                                .size(8.5)
                                .color(colors.muted),
                            );
                        }
                    });
            });
    }

    fn fallback_map(&mut self, ui: &mut egui::Ui) {
        let frame_started = Instant::now();
        let pipeline_calls_before = crate::diagnostics::pipeline_call_counters();
        let map_size = Vec2::new(self.world.map.width, self.world.map.height);
        let viewport_rect = ui.available_rect_before_wrap();
        let input_started = Instant::now();
        let screen_scale_before_zoom = world_to_screen_scale(
            viewport_rect,
            viewport_aligned_scene_rect(self.scene_rect, viewport_rect.size()),
        );
        let zoom_range = map_relative_zoom_range(map_size, viewport_rect.size());
        let pointer_position = ui.ctx().pointer_hover_pos();
        let wheel_delta = ui.input_mut(|input| {
            if pointer_position.is_some_and(|pointer| viewport_rect.contains(pointer)) {
                let delta = input.smooth_scroll_delta.y;
                input.smooth_scroll_delta = Vec2::ZERO;
                delta
            } else {
                0.0
            }
        });
        let input_us = input_started.elapsed().as_micros() as u64;
        let zoom_event_id = (wheel_delta.abs() > f32::EPSILON).then(|| {
            self.zoom_event_sequence = self.zoom_event_sequence.wrapping_add(1).max(1);
            self.zoom_event_sequence
        });
        let camera_started = Instant::now();
        if wheel_delta.abs() > f32::EPSILON {
            if let Some(pointer) = pointer_position {
                self.scene_rect = cursor_centered_scene_zoom(
                    self.scene_rect,
                    viewport_rect,
                    pointer,
                    wheel_delta,
                    zoom_range.clone(),
                );
            }
        }
        let scene_rect_before_interaction = self.scene_rect;
        let aligned_scene = viewport_aligned_scene_rect(self.scene_rect, viewport_rect.size());
        let screen_scale = world_to_screen_scale(viewport_rect, aligned_scene);
        let camera_us = camera_started.elapsed().as_micros() as u64;
        let texture_lod_before = self.terrain_textures.stats().active_lod;
        let surface_stroke_active = matches!(self.tool, Tool::Terrain | Tool::Elevation)
            && ui.input(|input| input.pointer.primary_down());
        self.map_render
            .ensure_river_mesh_traced(&self.world.map, screen_scale, zoom_event_id);
        if self.show_contours && !surface_stroke_active {
            self.map_render.ensure_contour_mesh_traced(
                &self.world.map,
                screen_scale,
                aligned_scene.expand(1.0),
                zoom_event_id,
            );
        }
        let environment_mesh = self.environment_layer.map(|layer| {
            self.map_render
                .environment_mesh(&self.world.map, layer, self.layer_opacity)
        });
        self.terrain_textures.ensure_traced(
            ui.ctx(),
            &self.world.map,
            screen_scale,
            aligned_scene.expand(1.0),
            self.terrain_layer_visible,
            zoom_event_id,
        );
        let surface_tiles = self
            .terrain_textures
            .draw_commands(aligned_scene.expand(1.0));
        let map_debug_draw = self.map_debug_render.draw_for_view(
            &self.world.map,
            aligned_scene.expand(1.0),
            screen_scale,
            self.map_debug_layers,
        );
        let territory_mesh = Arc::clone(&self.map_render.territory_mesh);
        let shoreline_mesh = if self.show_coastline && !surface_stroke_active {
            self.map_render.shoreline_mesh_for_view_traced(
                &self.world.map,
                aligned_scene.expand(1.0),
                screen_scale,
                zoom_event_id,
            )
        } else {
            Arc::clone(&self.map_render.shoreline_mesh)
        };
        let river_mesh = Arc::clone(&self.map_render.river_mesh);
        let road_mesh = Arc::clone(&self.map_render.road_mesh);
        let contour_mesh = Arc::clone(&self.map_render.contour_mesh);
        let country_anchors = Arc::clone(&self.map_render.country_anchors);
        let location_zoom = self.world.map.width / self.scene_rect.width().max(0.01);
        if self.place_labels_zoom_visible && location_zoom < 0.72 {
            self.place_labels_zoom_visible = false;
        } else if !self.place_labels_zoom_visible && location_zoom > 0.82 {
            self.place_labels_zoom_visible = true;
        }
        let detail_overlays_visible = self.place_labels_zoom_visible;
        let pan_buttons = if self.map_edit_mode == MapEditMode::View || self.tool == Tool::Pan {
            DragPanButtons::PRIMARY | DragPanButtons::MIDDLE
        } else {
            DragPanButtons::MIDDLE
        };
        let scene = Scene::new()
            .zoom_range(zoom_range)
            .max_inner_size(map_size)
            .drag_pan_buttons(pan_buttons);
        let tool = self.tool;
        let brush_radius = self.brush_radius;
        let mut brush_sample = None;
        let mut click_sample = None;
        let mut selection_sample = None;
        let mut hover_sample = None;
        let mut stroke_started = false;
        let mut stroke_ended = false;
        let mut interior_pan_delta = None;
        let paint_started = Instant::now();
        scene.show(ui, &mut self.scene_rect, |ui| {
            let map_rect = Rect::from_min_size(Pos2::ZERO, map_size);
            let response = ui.allocate_rect(map_rect, Sense::click_and_drag());
            paint_surface_textures(
                ui.painter(),
                &self.world.map,
                &surface_tiles,
                self.terrain_layer_visible,
            );
            if let Some(mesh) = &environment_mesh {
                ui.painter().add(egui::Shape::Mesh(Arc::clone(mesh)));
            }
            for mesh in &map_debug_draw.fill_meshes {
                ui.painter().add(egui::Shape::Mesh(Arc::clone(mesh)));
            }
            paint_map_overlays(
                ui,
                &self.world.map,
                self.year,
                Arc::clone(&self.overlay_mesh),
                Arc::clone(&territory_mesh),
                Arc::clone(&shoreline_mesh),
                Arc::clone(&river_mesh),
                Arc::clone(&road_mesh),
                self.show_territories,
                self.show_coastline,
                self.show_rivers,
                self.show_roads,
                false,
                false,
                false,
                self.show_event_icons && detail_overlays_visible,
            );
            paint_grid_overlays(
                ui,
                &self.world.map,
                Arc::clone(&contour_mesh),
                self.show_contours,
                self.show_wind_direction,
            );
            let debug_line_scale = screen_scale.max(0.001);
            let canonical_grid_stroke = Stroke::new(
                0.8 / debug_line_scale,
                Color32::from_rgba_unmultiplied(255, 208, 72, 190),
            );
            for [start, end] in map_debug_draw.canonical_grid.iter() {
                ui.painter().line_segment(
                    [Pos2::new(start.x, start.y), Pos2::new(end.x, end.y)],
                    canonical_grid_stroke,
                );
            }
            let refined_shoreline_stroke = Stroke::new(
                1.6 / debug_line_scale,
                Color32::from_rgba_unmultiplied(255, 64, 196, 240),
            );
            for [start, end] in map_debug_draw.refined_shoreline.iter() {
                ui.painter().line_segment(
                    [Pos2::new(start.x, start.y), Pos2::new(end.x, end.y)],
                    refined_shoreline_stroke,
                );
            }
            hover_sample = response
                .hover_pos()
                .filter(|position| map_rect.contains(*position))
                .map(|position| Point {
                    x: position.x,
                    y: position.y,
                });
            if (self.map_edit_mode == MapEditMode::View || tool == Tool::Pan)
                && response.dragged_by(egui::PointerButton::Primary)
            {
                interior_pan_delta = Some(ui.input(|input| input.pointer.delta()));
            }
            if matches!(tool, Tool::Terrain | Tool::Elevation | Tool::Territory) {
                if let Some(position) = response
                    .hover_pos()
                    .filter(|position| map_rect.contains(*position))
                {
                    ui.painter().circle_stroke(
                        position,
                        brush_radius,
                        Stroke::new(0.22, Color32::WHITE),
                    );
                    stroke_started = response.drag_started_by(egui::PointerButton::Primary)
                        || response.clicked_by(egui::PointerButton::Primary);
                    if response.dragged_by(egui::PointerButton::Primary)
                        || response.clicked_by(egui::PointerButton::Primary)
                    {
                        brush_sample = Some(Point {
                            x: position.x,
                            y: position.y,
                        });
                    }
                }
                stroke_ended = response.drag_stopped_by(egui::PointerButton::Primary)
                    || response.clicked_by(egui::PointerButton::Primary);
            } else if matches!(tool, Tool::Road | Tool::PlaceName) {
                if let Some(position) = response
                    .hover_pos()
                    .filter(|position| map_rect.contains(*position))
                {
                    stroke_started = response.drag_started_by(egui::PointerButton::Primary);
                    if response.dragged_by(egui::PointerButton::Primary) {
                        brush_sample = Some(Point {
                            x: position.x,
                            y: position.y,
                        });
                    }
                    let mut preview = self.stroke_points.clone();
                    preview.push(Point {
                        x: position.x,
                        y: position.y,
                    });
                    for segment in preview.windows(2) {
                        ui.painter().line_segment(
                            [
                                Pos2::new(segment[0].x, segment[0].y),
                                Pos2::new(segment[1].x, segment[1].y),
                            ],
                            Stroke::new(0.22, Color32::from_rgb(139, 211, 247)),
                        );
                    }
                }
                stroke_ended = response.drag_stopped_by(egui::PointerButton::Primary);
            } else if matches!(tool, Tool::Place | Tool::Event)
                && response.clicked_by(egui::PointerButton::Primary)
            {
                click_sample = response.hover_pos().map(|position| Point {
                    x: position.x,
                    y: position.y,
                });
            } else if tool == Tool::Pan && response.clicked_by(egui::PointerButton::Primary) {
                selection_sample = response.hover_pos().map(|position| Point {
                    x: position.x,
                    y: position.y,
                });
            }
        });
        if !ui.input(|input| input.pointer.primary_down()) && !self.stroke_points.is_empty() {
            stroke_ended = true;
        }
        let mut manual_pan_applied = false;
        if self.scene_rect == scene_rect_before_interaction
            && let Some(delta) = interior_pan_delta
            && delta.length_sq() > 0.0
        {
            let aligned = viewport_aligned_scene_rect(self.scene_rect, viewport_rect.size());
            let world_per_screen = Vec2::new(
                aligned.width() / viewport_rect.width().max(1.0),
                aligned.height() / viewport_rect.height().max(1.0),
            );
            self.scene_rect = aligned.translate(Vec2::new(
                -delta.x * world_per_screen.x,
                -delta.y * world_per_screen.y,
            ));
            manual_pan_applied = true;
            ui.ctx().request_repaint();
        }
        let label_painter = ui.ctx().layer_painter(egui::LayerId::new(
            egui::Order::Middle,
            egui::Id::new("crisp-map-labels"),
        ));
        let label_scene_rect = if manual_pan_applied {
            scene_rect_before_interaction
        } else {
            self.scene_rect
        };
        paint_map_labels_screen(
            &label_painter,
            viewport_rect,
            label_scene_rect,
            &self.world.map,
            self.year,
            self.show_locations && detail_overlays_visible,
            self.show_place_names && detail_overlays_visible,
            self.show_country_names && detail_overlays_visible,
            self.show_place_names && detail_overlays_visible,
            &country_anchors,
        );
        let egui_paint_us = paint_started.elapsed().as_micros() as u64;
        if self.scene_rect != scene_rect_before_interaction || wheel_delta.abs() > f32::EPSILON {
            if let Some(runtime) = &self.runtime {
                runtime.send_camera(runtime_camera_from_scene_rect(self.scene_rect));
            }
        }
        if let Some(point) = hover_sample {
            let sample = self.world.map.surface_sample_at_world(point);
            self.pointer_sample = Some((
                point,
                sample.elevation_m,
                self.scene_rect.width() / self.world.map.width.max(1.0),
                surface_id_for_pointer(sample.water, sample.terrain),
            ));
        }
        if stroke_started {
            self.stroke_points.clear();
            self.stroke_original_elevation.clear();
            self.stroke_influences.clear();
            if matches!(self.tool, Tool::Terrain | Tool::Elevation | Tool::Territory) {
                self.begin_civilization_transaction();
                if self.tool == Tool::Territory
                    && !self
                        .world
                        .map
                        .territory_history
                        .iter()
                        .any(|state| state.start_year <= self.year)
                {
                    self.world
                        .map
                        .record_territory_snapshot(self.year.saturating_sub(1));
                }
            }
        }
        if let Some(point) = brush_sample {
            if matches!(self.tool, Tool::Road | Tool::PlaceName) {
                self.append_continuous_stroke_point(point);
            } else {
                self.apply_fallback_brush_path(point);
            }
            ui.ctx().request_repaint();
        }
        if let Some(point) = click_sample {
            self.apply_civilization_stroke(self.tool.runtime(), vec![point]);
        }
        if let Some(point) = selection_sample {
            if self.map_entity_editing && self.selected_map_entity.is_some() {
                self.move_selected_map_entity(point);
            } else {
                self.select_map_entity_near(point, viewport_rect);
            }
        }
        if stroke_ended {
            if matches!(self.tool, Tool::Road | Tool::PlaceName) {
                let points = std::mem::take(&mut self.stroke_points);
                self.apply_civilization_stroke(self.tool.runtime(), points);
            } else if matches!(self.tool, Tool::Terrain | Tool::Elevation) {
                let changed_cells = self.edited_cells.keys().copied().collect::<Vec<_>>();
                if self.tool == Tool::Elevation {
                    self.commit_elevation_water_connectivity(&changed_cells);
                    self.map_render.rebuild_derived(&self.world.map);
                } else {
                    self.world
                        .map
                        .refresh_analysis_from_canonical(&changed_cells);
                }
                self.edited_cells.clear();
                self.overlay_mesh = Arc::new(Mesh::default());
                if let Some(center) = self.stroke_points.last().copied() {
                    self.record_active_regional_override(self.tool, center);
                }
                self.finish_civilization_transaction();
            } else if self.tool == Tool::Territory {
                self.world.map.record_territory_snapshot(self.year);
                self.map_render
                    .rebuild_territory(&self.world.map, self.layer_opacity);
                self.edited_cells.clear();
                self.overlay_mesh = Arc::new(Mesh::default());
                self.finish_civilization_transaction();
            }
            self.stroke_points.clear();
            self.stroke_original_elevation.clear();
            self.stroke_influences.clear();
            self.notify(tr(
                self.language,
                "브러시 스트로크를 반영했습니다.",
                "Brush stroke applied.",
            ));
        }
        self.fallback_pipeline_debug_overlay(ui.ctx(), screen_scale);
        if let Some(zoom_event_id) = zoom_event_id {
            let texture_stats = self.terrain_textures.stats();
            let render_stats = self.map_render.stats();
            let pipeline_calls_after = crate::diagnostics::pipeline_call_counters();
            let regional_refinement_calls = pipeline_calls_after
                .regional_refinement_calls
                .saturating_sub(pipeline_calls_before.regional_refinement_calls);
            let map_generation_calls = pipeline_calls_after
                .map_generation_calls
                .saturating_sub(pipeline_calls_before.map_generation_calls);
            let screen_pixels_per_km_x = viewport_rect.width() / aligned_scene.width().max(0.000_1);
            let screen_pixels_per_km_y =
                viewport_rect.height() / aligned_scene.height().max(0.000_1);
            let derived_mesh_us = render_stats
                .last_river_build_micros
                .saturating_add(render_stats.last_contour_build_micros)
                .saturating_add(render_stats.last_shoreline_build_micros);
            let frame_cpu_total_us = frame_started.elapsed().as_micros() as u64;
            let stages = [
                ("input", input_us),
                ("camera", camera_us),
                ("terrain", texture_stats.last_ensure_micros),
                ("derived_mesh", derived_mesh_us),
                ("egui_paint", egui_paint_us),
                (
                    "texture_delta_submission",
                    texture_stats.last_texture_submission_micros,
                ),
            ];
            let (largest_stage, largest_stage_us) = stages
                .into_iter()
                .max_by_key(|(_, micros)| *micros)
                .unwrap_or(("none", 0));
            let cache_state = if texture_stats.last_tile_cache_misses > 0
                || texture_stats.last_overview_build_micros > 0
                || !render_stats.last_river_cache_hit
                || !render_stats.last_contour_cache_hit
                || !render_stats.last_shoreline_cache_hit
            {
                "cold"
            } else {
                "warm"
            };
            crate::diagnostics::event(
                "map_zoom",
                "wheel",
                "completed",
                &[
                    ("zoom_event_id", zoom_event_id.to_string()),
                    ("map_id", self.world.map.source_id.clone()),
                    ("wheel_delta", format!("{wheel_delta:.6}")),
                    (
                        "scene_scale_before",
                        format!("{screen_scale_before_zoom:.9}"),
                    ),
                    ("scene_scale_after", format!("{screen_scale:.9}")),
                    ("viewport_width_px", format!("{:.3}", viewport_rect.width())),
                    (
                        "viewport_height_px",
                        format!("{:.3}", viewport_rect.height()),
                    ),
                    (
                        "visible_world_width_km",
                        format!("{:.6}", aligned_scene.width()),
                    ),
                    (
                        "visible_world_height_km",
                        format!("{:.6}", aligned_scene.height()),
                    ),
                    (
                        "screen_pixels_per_km_x",
                        format!("{screen_pixels_per_km_x:.9}"),
                    ),
                    (
                        "screen_pixels_per_km_y",
                        format!("{screen_pixels_per_km_y:.9}"),
                    ),
                    (
                        "surface_cell_m",
                        format!("{:.3}", self.world.map.surface_cell_m),
                    ),
                    ("lod_before", texture_lod_before.to_string()),
                    ("lod_after", texture_stats.active_lod.to_string()),
                    ("scene_transform_us", camera_us.to_string()),
                    (
                        "regional_refinement_calls",
                        regional_refinement_calls.to_string(),
                    ),
                    ("map_generation_calls", map_generation_calls.to_string()),
                    ("cache_state", cache_state.to_owned()),
                    ("input_us", input_us.to_string()),
                    ("camera_us", camera_us.to_string()),
                    ("terrain_us", texture_stats.last_ensure_micros.to_string()),
                    ("derived_mesh_us", derived_mesh_us.to_string()),
                    ("egui_paint_us", egui_paint_us.to_string()),
                    (
                        "texture_delta_submission_us",
                        texture_stats.last_texture_submission_micros.to_string(),
                    ),
                    ("wgpu_submit_us", "unavailable_at_egui_layer".to_owned()),
                    ("frame_cpu_total_us", frame_cpu_total_us.to_string()),
                    ("largest_stage", largest_stage.to_owned()),
                    ("largest_stage_us", largest_stage_us.to_string()),
                ],
            );
            if frame_cpu_total_us > 16_667 {
                crate::diagnostics::warning(
                    "map_zoom",
                    "frame_budget",
                    "exceeded",
                    &[
                        ("zoom_event_id", zoom_event_id.to_string()),
                        ("frame_cpu_total_us", frame_cpu_total_us.to_string()),
                        ("largest_stage", largest_stage.to_owned()),
                        ("largest_stage_us", largest_stage_us.to_string()),
                        ("budget_us", "16667".to_owned()),
                    ],
                );
            }
        }
    }

    fn append_continuous_stroke_point(&mut self, point: Point) {
        if self.stroke_points.is_empty() {
            self.stroke_points.push(point);
            return;
        }
        let previous = *self.stroke_points.last().unwrap_or(&point);
        let sampled = resample_world_stroke(&[previous, point], 0.35);
        self.stroke_points.extend(sampled.into_iter().skip(1));
    }

    fn record_active_regional_override(&mut self, tool: Tool, center: Point) {
        let Some(region_id) = self.world.map.region_id.clone() else {
            return;
        };
        let Ok(center) = self.world.active_point_to_planet(center) else {
            return;
        };
        let kind = match tool {
            Tool::Terrain => RegionalOverrideKind::TerrainEdit {
                terrain: self.selected_terrain.to_owned(),
            },
            Tool::Elevation if self.elevation_mode == ElevationBrushMode::Target => {
                RegionalOverrideKind::ElevationSetM(self.elevation_delta)
            }
            Tool::Elevation => RegionalOverrideKind::ElevationOffsetM(self.elevation_delta),
            _ => return,
        };
        let Some(region) = self
            .world
            .regions
            .iter_mut()
            .find(|region| region.id == region_id)
        else {
            return;
        };
        let serial = region.regional_overrides.len() + 1;
        region.regional_overrides.push(RegionalOverride {
            id: format!(
                "{}-override-{}-{}",
                region.id, self.world.map.surface_revision, serial
            ),
            scope: RegionalOverrideScope::RegionOnly,
            center,
            radius_m: f64::from(self.brush_radius.max(0.01)) * 1_000.0,
            revision: self.world.map.surface_revision,
            kind,
        });
    }

    fn apply_fallback_brush_path(&mut self, point: Point) {
        let previous = self.stroke_points.last().copied().unwrap_or(point);
        let distance = ((point.x - previous.x).powi(2) + (point.y - previous.y).powi(2)).sqrt();
        let spacing = (self.brush_radius * 0.35).max(0.08);
        let steps = (distance / spacing).ceil().max(1.0) as usize;
        for step in 1..=steps {
            let ratio = step as f32 / steps as f32;
            self.apply_fallback_brush(Point {
                x: previous.x + (point.x - previous.x) * ratio,
                y: previous.y + (point.y - previous.y) * ratio,
            });
        }
        self.overlay_mesh = build_cell_overlay_mesh(
            &self.world.map,
            &self.edited_cells,
            matches!(self.tool, Tool::Terrain | Tool::Elevation),
        );
        self.stroke_points.push(point);
    }

    fn select_map_entity_near(&mut self, point: Point, viewport: Rect) {
        let threshold = (self.scene_rect.width() / viewport.width().max(1.0) * 12.0).max(0.35);
        let distance = |candidate: Point| {
            ((candidate.x - point.x).powi(2) + (candidate.y - point.y).powi(2)).sqrt()
        };
        let place = self
            .world
            .map
            .locations
            .iter()
            .filter_map(|location| {
                location
                    .state_at(self.year)
                    .map(|state| (location, state, distance(state.position)))
            })
            .filter(|(_, _, distance)| *distance <= threshold)
            .min_by(|left, right| left.2.total_cmp(&right.2));
        let event = self
            .world
            .map
            .events
            .iter()
            .filter(|event| {
                event.start_year <= self.year && event.end_year.is_none_or(|end| self.year <= end)
            })
            .filter_map(|event| {
                event
                    .position_at(self.year)
                    .map(|location| (event, distance(location)))
            })
            .filter(|(_, distance)| *distance <= threshold)
            .min_by(|left, right| left.1.total_cmp(&right.1));
        self.selected_map_entity = match (place, event) {
            (Some((_location, _state, place_distance)), Some((event, event_distance)))
                if event_distance < place_distance =>
            {
                self.map_entity_name = event.title.clone();
                Some(SelectedMapEntity::Event(event.id.clone()))
            }
            (Some((location, state, _)), _) => {
                self.map_entity_name = state.name.clone();
                Some(SelectedMapEntity::Place(location.id.clone()))
            }
            (_, Some((event, _))) => {
                self.map_entity_name = event.title.clone();
                Some(SelectedMapEntity::Event(event.id.clone()))
            }
            _ => None,
        };
        self.map_entity_editing = false;
    }

    fn move_selected_map_entity(&mut self, point: Point) {
        let Some(selected) = self.selected_map_entity.clone() else {
            return;
        };
        let target = nearest_land_point(&self.world.map, point).unwrap_or(point);
        self.begin_civilization_transaction();
        match selected {
            SelectedMapEntity::Place(id) => {
                if let Some(location) = self
                    .world
                    .map
                    .locations
                    .iter_mut()
                    .find(|location| location.id == id)
                {
                    let active = location
                        .state_at(self.year)
                        .cloned()
                        .or_else(|| location.states.last().cloned());
                    if let Some(mut state) = active {
                        if let Some(existing) = location
                            .states
                            .iter_mut()
                            .find(|candidate| candidate.start_year == self.year)
                        {
                            existing.position = target;
                        } else {
                            let previous_end = state.end_year;
                            if let Some(previous) =
                                location.states.iter_mut().rev().find(|candidate| {
                                    candidate.start_year < self.year
                                        && candidate.end_year.is_none_or(|end| self.year <= end)
                                })
                            {
                                previous.end_year = Some(self.year.saturating_sub(1));
                            }
                            state.start_year = self.year;
                            state.end_year = previous_end;
                            state.position = target;
                            location.states.push(state);
                            location.states.sort_by_key(|state| state.start_year);
                        }
                    }
                }
            }
            SelectedMapEntity::Event(id) => {
                if let Some(event) = self
                    .world
                    .map
                    .events
                    .iter_mut()
                    .find(|event| event.id == id)
                {
                    let previous = event.position_at(self.year).or(event.location);
                    if event.location_history.is_empty()
                        && let Some(position) = previous
                    {
                        event.location_history.push(crate::model::TemporalMapPoint {
                            start_year: event.start_year,
                            end_year: Some(self.year.saturating_sub(1)),
                            position,
                        });
                    }
                    if let Some(existing) = event
                        .location_history
                        .iter_mut()
                        .find(|state| state.start_year == self.year)
                    {
                        existing.position = target;
                    } else {
                        if let Some(previous) =
                            event.location_history.iter_mut().rev().find(|state| {
                                state.start_year < self.year
                                    && state.end_year.is_none_or(|end| self.year <= end)
                            })
                        {
                            previous.end_year = Some(self.year.saturating_sub(1));
                        }
                        event.location_history.push(crate::model::TemporalMapPoint {
                            start_year: self.year,
                            end_year: event.end_year,
                            position: target,
                        });
                        event.location_history.sort_by_key(|state| state.start_year);
                    }
                    event.location = Some(target);
                }
            }
        }
        self.finish_civilization_transaction();
    }

    fn civilization_snapshot(&self) -> CivilizationEditSnapshot {
        CivilizationEditSnapshot {
            roads: self.world.map.roads.clone(),
            rivers: self.world.map.rivers.clone(),
            place_names: self.world.map.place_names.clone(),
            locations: self.world.map.locations.clone(),
            events: self.world.map.events.clone(),
            territory_owners: self.world.map.territory_owners.clone(),
            territory_history: self.world.map.territory_history.clone(),
            terrain: CompactStrings::pack(&self.world.map.terrain),
            elevation: self.world.map.elevation.clone(),
            water: CompactStrings::pack(&self.world.map.water),
            canonical_surface: self.world.map.canonical_surface.clone(),
        }
    }

    fn begin_civilization_transaction(&mut self) {
        self.civilization_undo.push(self.civilization_snapshot());
        if self.civilization_undo.len() > 24 {
            self.civilization_undo.remove(0);
        }
        self.civilization_redo.clear();
    }

    fn restore_civilization_snapshot(&mut self, snapshot: CivilizationEditSnapshot) {
        self.world.map.roads = snapshot.roads;
        self.world.map.rivers = snapshot.rivers;
        self.world.map.place_names = snapshot.place_names;
        self.world.map.locations = snapshot.locations;
        self.world.map.events = snapshot.events;
        self.world.map.territory_owners = snapshot.territory_owners;
        self.world.map.territory_history = snapshot.territory_history;
        self.world.map.terrain = snapshot.terrain.unpack();
        self.world.map.elevation = snapshot.elevation;
        self.world.map.water = snapshot.water.unpack();
        self.world.map.canonical_surface = snapshot.canonical_surface;
        self.world.events = self.world.map.events.clone();
        self.map_render
            .rebuild_all(&self.world.map, self.layer_opacity);
        self.edited_cells.clear();
        self.overlay_mesh = Arc::new(Mesh::default());
        self.sync_active_map_snapshot();
        if let Some(runtime) = &self.runtime {
            runtime.send_snapshot(&self.world.map);
        }
    }

    fn undo_civilization_transaction(&mut self) {
        let Some(snapshot) = self.civilization_undo.pop() else {
            return;
        };
        self.civilization_redo.push(self.civilization_snapshot());
        self.restore_civilization_snapshot(snapshot);
        self.notify(tr(
            self.language,
            "지도 편집을 실행 취소했습니다.",
            "Map edit undone.",
        ));
    }

    fn redo_civilization_transaction(&mut self) {
        let Some(snapshot) = self.civilization_redo.pop() else {
            return;
        };
        self.civilization_undo.push(self.civilization_snapshot());
        self.restore_civilization_snapshot(snapshot);
        self.notify(tr(
            self.language,
            "지도 편집을 다시 실행했습니다.",
            "Map edit redone.",
        ));
    }

    fn finish_civilization_transaction(&mut self) {
        self.world.events = self.world.map.events.clone();
        self.sync_active_map_snapshot();
        if let Some(runtime) = &self.runtime {
            runtime.send_snapshot(&self.world.map);
        }
    }

    fn apply_civilization_stroke(&mut self, tool: RuntimeTool, points: Vec<Point>) {
        let points = resample_world_stroke(&points, 0.35);
        if points.is_empty() {
            return;
        }
        match tool {
            RuntimeTool::Road if points.len() >= 2 => {
                let paths = split_land_intervals(&self.world.map, &smooth_world_path(&points));
                if paths.is_empty() {
                    return;
                }
                self.begin_civilization_transaction();
                self.world.map.roads.extend(
                    paths
                        .into_iter()
                        .filter(|path| path.len() >= 2)
                        .map(|nodes| crate::model::PathLine { nodes }),
                );
                self.show_roads = true;
            }
            RuntimeTool::Place => {
                let Some(point) = nearest_land_point(&self.world.map, points[0]) else {
                    self.notify(tr(
                        self.language,
                        "장소는 육지 위에만 배치할 수 있습니다.",
                        "Places can only be placed on land.",
                    ));
                    return;
                };
                self.begin_civilization_transaction();
                let index = self.world.map.locations.len() + 1;
                let entity_id = format!("native-place-{index}-{}", self.year);
                let name = format!("{} {index}", tr(self.language, "새 장소", "New Place"));
                let article_id = create_linked_map_article(
                    &mut self.world,
                    &entity_id,
                    &name,
                    MapEntityKind::Place,
                    point,
                    self.year,
                );
                self.world.map.locations.push(crate::model::Location {
                    id: entity_id.clone(),
                    article_id: Some(article_id),
                    water_position_warning: false,
                    states: vec![crate::model::LocationTemporalState {
                        start_year: self.year,
                        end_year: None,
                        name,
                        position: point,
                        population: Some(0.0),
                        economy: Some(0.0),
                        location_type: "city".to_owned(),
                        description: String::new(),
                    }],
                });
                self.selected_map_entity = Some(SelectedMapEntity::Place(entity_id));
                self.map_entity_name =
                    format!("{} {index}", tr(self.language, "새 장소", "New Place"));
                self.map_entity_editing = true;
                self.show_locations = true;
            }
            RuntimeTool::Event => {
                self.begin_civilization_transaction();
                let index = self.world.map.events.len() + 1;
                let entity_id = format!("native-event-{index}-{}", self.year);
                let name = format!("{} {index}", tr(self.language, "새 사건", "New Event"));
                let article_id = create_linked_map_article(
                    &mut self.world,
                    &entity_id,
                    &name,
                    MapEntityKind::Event,
                    points[0],
                    self.year,
                );
                self.world.map.events.push(crate::model::Event {
                    id: entity_id.clone(),
                    title: name,
                    start_year: self.year,
                    end_year: Some(self.year),
                    location: Some(points[0]),
                    location_history: vec![crate::model::TemporalMapPoint {
                        start_year: self.year,
                        end_year: Some(self.year),
                        position: points[0],
                    }],
                    article_id: Some(article_id),
                    water_position_warning: false,
                });
                self.selected_map_entity = Some(SelectedMapEntity::Event(entity_id));
                self.map_entity_name =
                    format!("{} {index}", tr(self.language, "새 사건", "New Event"));
                self.map_entity_editing = true;
                self.show_event_icons = true;
            }
            RuntimeTool::PlaceName if points.len() >= 2 => {
                let Some(path) =
                    longest_land_interval(&self.world.map, &smooth_world_path(&points))
                else {
                    self.notify(tr(
                        self.language,
                        "지명은 육지 위에만 배치할 수 있습니다.",
                        "Place names can only be placed on land.",
                    ));
                    return;
                };
                let index = self.world.map.place_names.len() + 1;
                self.pending_place_name = Some(PlaceNameDraft {
                    path,
                    text: format!("{} {index}", tr(self.language, "새 지명", "New Place Name")),
                    font_size: 13.0,
                    letter_spacing: 0.0,
                    bold: false,
                    italic: false,
                });
                self.show_place_names = true;
                return;
            }
            _ => return,
        }
        if tool == RuntimeTool::Road {
            self.map_render.rebuild_transport(&self.world.map);
        }
        self.finish_civilization_transaction();
        self.tool = Tool::Pan;
        self.send_runtime_tool();
    }

    fn apply_fallback_brush(&mut self, point: Point) {
        let tool = self.tool;
        let brush_radius = self.brush_radius.max(0.01);
        let selected_terrain = self.selected_terrain;
        let elevation_mode = self.elevation_mode;
        let elevation_value = self.elevation_delta.abs();
        let elevation_target = self.elevation_delta;
        let strength = self.brush_strength.clamp(0.01, 1.0);
        let falloff = self.brush_falloff.clamp(0.0, 1.0);
        let terrain_noise = self.terrain_brush_noise.clamp(0.0, 1.0);
        let layer_opacity = self.layer_opacity;
        let original_elevation = &mut self.stroke_original_elevation;
        let stroke_influences = &mut self.stroke_influences;
        let map = &mut self.world.map;
        let canonical = matches!(tool, Tool::Terrain | Tool::Elevation);
        let (grid_width, grid_height) = if canonical {
            map.canonical_cell_dimensions()
        } else {
            (map.grid_width, map.grid_height)
        };
        let cell_width = map.width / grid_width.max(1) as f32;
        let cell_height = map.height / grid_height.max(1) as f32;
        let radius_x = (brush_radius / cell_width).ceil() as isize;
        let radius_y = (brush_radius / cell_height).ceil() as isize;
        let center_x = (point.x / map.width * grid_width as f32).floor() as isize;
        let center_y = (point.y / map.height * grid_height as f32).floor() as isize;
        for y in (center_y - radius_y).max(0)..=(center_y + radius_y).min(grid_height as isize - 1)
        {
            for x in
                (center_x - radius_x).max(0)..=(center_x + radius_x).min(grid_width as isize - 1)
            {
                let dx = (x as f32 + 0.5) * cell_width - point.x;
                let dy = (y as f32 + 0.5) * cell_height - point.y;
                let distance = (dx * dx + dy * dy).sqrt() / brush_radius;
                let boundary = if tool == Tool::Terrain {
                    1.0 + (brush_cell_noise(x as usize, y as usize) - 0.5) * terrain_noise * 0.72
                } else {
                    1.0
                };
                if distance > boundary {
                    continue;
                }
                let index = y as usize * grid_width + x as usize;
                let canonical_sample =
                    canonical.then(|| map.canonical_sample(x as usize, y as usize));
                let color = match tool {
                    Tool::Terrain => {
                        if canonical_sample.is_some_and(|sample| sample.water != "land") {
                            continue;
                        }
                        map.edit_canonical_cell(
                            x as usize,
                            y as usize,
                            None,
                            Some(selected_terrain),
                            None,
                        );
                        surface_color(selected_terrain)
                    }
                    Tool::Elevation => {
                        let normalized_distance = (distance / boundary.max(0.35)).clamp(0.0, 1.0);
                        let weight = if falloff <= 0.001 {
                            1.0
                        } else {
                            (1.0 - normalized_distance).powf(0.45 + falloff * 2.55)
                        };
                        let prior_weight = stroke_influences.get(&index).copied().unwrap_or(-1.0);
                        if weight <= prior_weight {
                            continue;
                        }
                        let original = *original_elevation.entry(index).or_insert(
                            canonical_sample
                                .map(|sample| sample.elevation_m)
                                .unwrap_or(map.sea_level),
                        );
                        let elevation = elevation_brush_value(
                            original,
                            elevation_mode,
                            elevation_target,
                            elevation_value,
                            strength,
                            weight,
                        );
                        map.edit_canonical_cell(
                            x as usize,
                            y as usize,
                            Some(elevation),
                            None,
                            None,
                        );
                        stroke_influences.insert(index, weight);
                        let intensity = ((elevation - map.sea_level) / 6_000.0).clamp(0.0, 1.0);
                        Color32::from_rgb(
                            (100.0 + 110.0 * intensity) as u8,
                            (118.0 + 95.0 * intensity) as u8,
                            (92.0 + 105.0 * intensity) as u8,
                        )
                    }
                    Tool::Territory => {
                        let world_point = Point {
                            x: (x as f32 + 0.5) * cell_width,
                            y: (y as f32 + 0.5) * cell_height,
                        };
                        if map.surface_sample_at_world(world_point).water != "land" {
                            continue;
                        }
                        if map.territory_owners.len()
                            != map.grid_width.saturating_mul(map.grid_height)
                        {
                            map.territory_owners =
                                vec![-1; map.grid_width.saturating_mul(map.grid_height)];
                        }
                        map.territory_owners[index] = self.selected_faction_index as i32;
                        let base = map
                            .factions
                            .get(self.selected_faction_index)
                            .map(|faction| parse_hex_color(&faction.color))
                            .unwrap_or(Color32::from_rgb(205, 78, 92));
                        Color32::from_rgba_unmultiplied(
                            base.r(),
                            base.g(),
                            base.b(),
                            (128.0 * layer_opacity.clamp(0.0, 1.0)).round() as u8,
                        )
                    }
                    Tool::Pan | Tool::Road | Tool::Place | Tool::Event | Tool::PlaceName => {
                        continue;
                    }
                };
                self.edited_cells.insert(index, color);
            }
        }
    }

    fn commit_elevation_water_connectivity(&mut self, changed_cells: &[usize]) {
        let dirty_cells =
            reconcile_canonical_ocean_connectivity(&mut self.world.map, changed_cells);
        if dirty_cells.is_empty() {
            return;
        }
        self.world.map.refresh_analysis_from_canonical(&dirty_cells);
        refresh_water_affected_entities(&mut self.world.map);
        let mut affected = self
            .world
            .map
            .locations
            .iter()
            .filter(|location| location.water_position_warning)
            .map(|location| WaterAffectedRecord {
                kind: MapEntityKind::Place,
                id: location.id.clone(),
                name: location
                    .state_at(self.year)
                    .map(|state| state.name.clone())
                    .unwrap_or_else(|| location.id.clone()),
                preserve: true,
            })
            .collect::<Vec<_>>();
        affected.extend(
            self.world
                .map
                .events
                .iter()
                .filter(|event| event.water_position_warning)
                .map(|event| WaterAffectedRecord {
                    kind: MapEntityKind::Event,
                    id: event.id.clone(),
                    name: event.title.clone(),
                    preserve: true,
                }),
        );
        if !affected.is_empty()
            && let Some(rollback) = self.civilization_undo.last().cloned()
        {
            self.water_decision = Some(WaterDecision {
                rollback,
                records: affected,
            });
        }
        self.schedule_hydrology_rebuild();
    }

