    fn place_metric_panel(
        &mut self,
        ui: &mut egui::Ui,
        article: &Article,
        display_calendar: &CalendarProfile,
    ) {
        let colors = self.colors();
        let editing = self.editing_article;
        let calendar_options = self
            .world
            .articles
            .iter()
            .filter_map(|article| {
                article
                    .calendar_profile
                    .clone()
                    .map(|profile| (article.id.clone(), profile))
            })
            .collect::<Vec<_>>();
        let profile = if editing {
            self.article_edit_profiles.place.as_ref()
        } else {
            article.profiles.place.as_ref()
        };
        let mut records = place_metric_records(profile);
        if records.is_empty() {
            records = place_metric_records_from_location(&self.world, article);
        }
        records.sort_by_key(|record| record.world_year);
        let mut expanded = self.place_metric_expanded;
        theme::surface_frame(self.dark_mode).show(ui, |ui| {
            ui.set_min_width(ui.available_width());
            ui.horizontal(|ui| {
                section_title(
                    ui,
                    tr(
                        self.language,
                        "인구·경제력 기록",
                        "Population & Economy Records",
                    ),
                    colors,
                );
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if ui
                        .add_sized(
                            [58.0, 26.0],
                            egui::Button::new(if expanded {
                                tr(self.language, "접기", "Collapse")
                            } else {
                                tr(self.language, "펼치기", "Expand")
                            }),
                        )
                        .clicked()
                    {
                        expanded = !expanded;
                    }
                });
            });
            if !expanded {
                return;
            }
            if editing {
                let mut remove = None;
                for (index, record) in records.iter_mut().enumerate() {
                    ui.vertical(|ui| {
                        place_metric_date_editor(
                            ui,
                            self.language,
                            display_calendar,
                            self.world.orbital_period_days as f64,
                            &calendar_options,
                            index,
                            record,
                        );
                        ui.horizontal(|ui| {
                            optional_f64_editor(
                                ui,
                                &mut record.population,
                                tr(self.language, "인구", "Population"),
                            );
                            optional_f64_editor(
                                ui,
                                &mut record.economy,
                                tr(self.language, "경제력", "Economy"),
                            );
                            if ui
                                .small_button("×")
                                .on_hover_text(tr(self.language, "삭제", "Delete"))
                                .clicked()
                            {
                                remove = Some(index);
                            }
                        });
                    });
                }
                if let Some(index) = remove {
                    records.remove(index);
                }
                if ui
                    .button(tr(self.language, "+ 기록 추가", "+ Add Record"))
                    .clicked()
                {
                    records.push(PlaceMetricRecord {
                        world_year: 0,
                        date_specified: false,
                        absolute_day: None,
                        calendar_id: None,
                        show_time: false,
                        population: None,
                        economy: None,
                    });
                }
                let profile = json_object_mut(&mut self.article_edit_profiles.place);
                profile.insert(
                    "metricRecords".to_owned(),
                    serde_json::to_value(&records)
                        .unwrap_or_else(|_| serde_json::Value::Array(Vec::new())),
                );
            } else {
                let (left, right, _) = metric_neighbors(&records, self.year);
                let cell_width = ((ui.available_width() - 8.0) * 0.5).max(72.0);
                egui::Grid::new(("place-metric-records", &article.id))
                    .num_columns(2)
                    .min_col_width(cell_width)
                    .spacing(Vec2::new(8.0, 6.0))
                    .show(ui, |ui| {
                        metric_value_cell(
                            ui,
                            self.language,
                            colors,
                            display_calendar,
                            left,
                            self.world.orbital_period_days as f64,
                            PlaceMetricKind::Population,
                        );
                        metric_value_cell(
                            ui,
                            self.language,
                            colors,
                            display_calendar,
                            right,
                            self.world.orbital_period_days as f64,
                            PlaceMetricKind::Population,
                        );
                        ui.end_row();
                        metric_value_cell(
                            ui,
                            self.language,
                            colors,
                            display_calendar,
                            left,
                            self.world.orbital_period_days as f64,
                            PlaceMetricKind::Economy,
                        );
                        metric_value_cell(
                            ui,
                            self.language,
                            colors,
                            display_calendar,
                            right,
                            self.world.orbital_period_days as f64,
                            PlaceMetricKind::Economy,
                        );
                        ui.end_row();
                    });
            }
        });
        self.place_metric_expanded = expanded;
    }

    fn place_chronology_panel(&mut self, ui: &mut egui::Ui, article: &Article) {
        let language = self.language;
        let colors = self.colors();
        let calendar = self.world.display_calendar(language);
        let calendar_options = self
            .world
            .articles
            .iter()
            .filter_map(|article| {
                article
                    .calendar_profile
                    .clone()
                    .map(|profile| (article.id.clone(), profile))
            })
            .collect::<Vec<_>>();
        let editing = self.editing_article;
        let mut entries = if editing {
            place_chronology_entries(self.article_edit_profiles.place.as_ref())
        } else {
            let saved = place_chronology_entries(article.profiles.place.as_ref());
            if saved.is_empty() {
                place_chronology_from_location(&self.world, article)
            } else {
                saved
            }
        };
        let mut expanded = self.chronology_expanded;
        let mut action: Option<(usize, i32)> = None;
        let mut add_entry = false;
        theme::surface_frame(self.dark_mode).show(ui, |ui| {
            ui.set_min_width(ui.available_width());
            ui.horizontal(|ui| {
                section_title(ui, tr(language, "연표", "Chronology"), colors);
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if ui
                        .add_sized(
                            [58.0, 26.0],
                            egui::Button::new(if expanded {
                                tr(language, "접기", "Collapse")
                            } else {
                                tr(language, "펼치기", "Expand")
                            }),
                        )
                        .clicked()
                    {
                        expanded = !expanded;
                    }
                });
            });
            if !expanded {
                return;
            }
            if entries.is_empty() && !editing {
                ui.label(
                    RichText::new(tr(
                        language,
                        "기록된 연표가 없습니다.",
                        "No chronology recorded.",
                    ))
                    .size(9.5)
                    .color(colors.muted),
                );
            } else if editing {
                for index in 0..entries.len() {
                    let entry_count = entries.len();
                    egui::Frame::new()
                        .fill(colors.panel_alt)
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(4.0)
                        .inner_margin(Margin::same(7))
                        .show(ui, |ui| {
                            let entry = &mut entries[index];
                            ui.horizontal(|ui| {
                                ui.label(
                                    RichText::new(format!(
                                        "{} {}",
                                        index + 1,
                                        tr(language, "번째", "")
                                    ))
                                    .size(8.5)
                                    .color(colors.muted),
                                );
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    if ui
                                        .small_button("×")
                                        .on_hover_text(tr(language, "삭제", "Delete"))
                                        .clicked()
                                    {
                                        action = Some((index, 0));
                                    }
                                    if ui
                                        .add_enabled(
                                            index + 1 < entry_count,
                                            egui::Button::new("↓"),
                                        )
                                        .clicked()
                                    {
                                        action = Some((index, 1));
                                    }
                                    if ui.add_enabled(index > 0, egui::Button::new("↑")).clicked()
                                    {
                                        action = Some((index, -1));
                                    }
                                });
                            });
                            chronology_moment_editor(
                                ui,
                                language,
                                &calendar,
                                self.world.orbital_period_days as f64,
                                &calendar_options,
                                entry,
                            );
                            ui.add_sized(
                                [ui.available_width(), 26.0],
                                egui::TextEdit::singleline(&mut entry.title).hint_text(tr(
                                    language,
                                    "연표 제목",
                                    "Chronology title",
                                )),
                            );
                            ui.add_sized(
                                [ui.available_width(), 52.0],
                                egui::TextEdit::multiline(&mut entry.description).hint_text(tr(
                                    language,
                                    "연표 내용",
                                    "Chronology description",
                                )),
                            );
                        });
                }
                if ui
                    .button(tr(language, "+ 연표 항목 추가", "+ Add Chronology Entry"))
                    .clicked()
                {
                    add_entry = true;
                }
            } else {
                place_chronology_table(
                    ui,
                    language,
                    colors,
                    &calendar,
                    self.world.orbital_period_days as f64,
                    &entries,
                    &article.id,
                );
            }
        });
        self.chronology_expanded = expanded;
        if let Some((index, direction)) = action {
            match direction {
                -1 if index > 0 => entries.swap(index, index - 1),
                1 if index + 1 < entries.len() => entries.swap(index, index + 1),
                0 if index < entries.len() => {
                    entries.remove(index);
                }
                _ => {}
            }
        }
        if add_entry {
            entries.push(PlaceChronologyEntry::empty(next_place_chronology_id(
                &entries,
            )));
        }
        if editing {
            let profile = json_object_mut(&mut self.article_edit_profiles.place);
            profile.insert(
                "chronology".to_owned(),
                serde_json::Value::Array(
                    entries
                        .into_iter()
                        .filter_map(|entry| serde_json::to_value(entry).ok())
                        .collect(),
                ),
            );
        }
    }

    fn item_ownership_panel(&mut self, ui: &mut egui::Ui, article: &Article) {
        let language = self.language;
        let colors = self.colors();
        let editing = self.editing_article;
        let profile = if editing {
            self.article_edit_profiles.item.as_ref()
        } else {
            article.profiles.item.as_ref()
        };
        let selected_descriptor = if editing {
            self.article_edit_category_id
                .as_deref()
                .and_then(|id| {
                    self.world
                        .categories
                        .iter()
                        .find(|category| category.id == id)
                })
                .and_then(category_system_key)
                .unwrap_or_else(|| article_category_descriptor(article))
        } else {
            article_category_descriptor(article)
        };
        let is_unique = contains_any(
            &selected_descriptor,
            &[
                "weapon_unique",
                "armor_unique",
                "accessory_unique",
                "item_unique",
                "(고유)",
                "Unique",
            ],
        );
        if !is_unique {
            return;
        }
        let mut periods = item_ownership_periods(profile);
        let references = u_fields::reference_options(&self.world.articles);
        let calendar = self.world.display_calendar(language);
        let calendar_options = self
            .world
            .articles
            .iter()
            .filter_map(|article| {
                article
                    .calendar_profile
                    .clone()
                    .map(|profile| (article.id.clone(), profile))
            })
            .collect::<Vec<_>>();
        let orbital_period_days = self.world.orbital_period_days as f64;
        let invalid_ids = ownership_validation_errors(&periods);
        let mut expanded = self.ownership_expanded;
        let mut action: Option<(usize, i32)> = None;
        let mut add_period = false;
        theme::surface_frame(self.dark_mode).show(ui, |ui| {
            ui.horizontal(|ui| {
                section_title(ui, tr(language, "소유권 기록", "Ownership History"), colors);
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if ui
                        .add_sized(
                            [58.0, 26.0],
                            egui::Button::new(if expanded {
                                tr(language, "접기", "Collapse")
                            } else {
                                tr(language, "펼치기", "Expand")
                            }),
                        )
                        .clicked()
                    {
                        expanded = !expanded;
                    }
                });
            });
            if !expanded {
                return;
            }
            if editing {
                for index in 0..periods.len() {
                    let period_count = periods.len();
                    let invalid = invalid_ids.contains(&periods[index].id);
                    egui::Frame::new()
                        .fill(colors.panel_alt)
                        .stroke(Stroke::new(1.0, if invalid { colors.danger } else { colors.border }))
                        .corner_radius(4.0)
                        .inner_margin(Margin::same(7))
                        .show(ui, |ui| {
                            let period = &mut periods[index];
                            ui.horizontal(|ui| {
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    if ui.small_button("×").on_hover_text(tr(language, "삭제", "Delete")).clicked() {
                                        action = Some((index, 0));
                                    }
                                    if ui.add_enabled(index + 1 < period_count, egui::Button::new("↓")).clicked() {
                                        action = Some((index, 1));
                                    }
                                    if ui.add_enabled(index > 0, egui::Button::new("↑")).clicked() {
                                        action = Some((index, -1));
                                    }
                                });
                            });
                            let mut owner = serde_json::Map::new();
                            if references.iter().any(|option| option.id == period.owner_id) {
                                owner.insert("ownerArticleId".to_owned(), serde_json::Value::String(period.owner_id.clone()));
                            } else if !period.owner_id.trim().is_empty() {
                                owner.insert("ownerName".to_owned(), serde_json::Value::String(period.owner_id.clone()));
                            }
                            u_fields::u_input_single(
                                ui,
                                language,
                                ("ownership-owner", &period.id),
                                tr(language, "소유자", "Owner"),
                                &mut owner,
                                "ownerArticleId",
                                Some("ownerName"),
                                &references,
                                &["person", "family", "country", "faction", "organization", "order", "guild", "company"],
                            );
                            if let Some(id) = owner.get("ownerArticleId").and_then(serde_json::Value::as_str) {
                                period.owner_id = id.to_owned();
                                period.owner_type = references.iter().find(|option| option.id == id)
                                    .map(|option| option.category.clone())
                                    .unwrap_or_else(|| "reference".to_owned());
                            } else {
                                period.owner_id = owner.get("ownerName").and_then(serde_json::Value::as_str).unwrap_or_default().trim_matches(['[', ']']).to_owned();
                                period.owner_type = "custom".to_owned();
                            }
                            ownership_date_editor(ui, language, &calendar, orbital_period_days, &calendar_options, period, true);
                            ownership_date_editor(ui, language, &calendar, orbital_period_days, &calendar_options, period, false);
                            ui.add_sized(
                                [ui.available_width(), 26.0],
                                egui::TextEdit::singleline(&mut period.note)
                                    .hint_text(tr(language, "비고", "Note")),
                            );
                            if invalid {
                                ui.label(
                                    RichText::new(tr(
                                        language,
                                        "기간이 역전되었거나 다른 소유권 기록과 겹칩니다.",
                                        "This period is reversed or overlaps another ownership record.",
                                    ))
                                    .size(8.5)
                                    .color(colors.danger),
                                );
                            }
                        });
                }
                if ui.button(tr(language, "+ 소유권 기록", "+ Ownership Record")).clicked()
                {
                    add_period = true;
                }
            } else if periods.is_empty() {
                ui.label(RichText::new(tr(language, "소유권 기록이 없습니다.", "No ownership records.")).size(9.5).color(colors.muted));
            } else {
                for period in &periods {
                    let start = if period.start_specified {
                        calendar::format_absolute_moment_precision(
                            &calendar,
                            language,
                            TimelineMoment::new(period.start_year, 0.0),
                            orbital_period_days,
                            0,
                        )
                    } else {
                        "-".to_owned()
                    };
                    let end = period.end_year.map(|year| {
                        calendar::format_absolute_moment_precision(
                            &calendar,
                            language,
                            TimelineMoment::new(year, 0.0),
                            orbital_period_days,
                            0,
                        )
                    }).unwrap_or_else(|| tr(language, "현재", "Present").to_owned());
                    ui.horizontal_wrapped(|ui| {
                        ui.label(
                            RichText::new(format!("{start} - {end}"))
                                .size(9.0)
                                .strong()
                                .color(colors.title),
                        );
                        ui.label(
                            RichText::new(ownership_label(&self.world, period))
                                .size(9.0)
                                .color(colors.text),
                        );
                        if !period.note.trim().is_empty() {
                            ui.label(
                                RichText::new(&period.note)
                                    .size(9.0)
                                    .color(colors.muted),
                            );
                        }
                    });
                    ui.separator();
                }
            }
        });
        self.ownership_expanded = expanded;
        if let Some((index, direction)) = action {
            match direction {
                -1 if index > 0 => periods.swap(index, index - 1),
                1 if index + 1 < periods.len() => periods.swap(index, index + 1),
                0 if index < periods.len() => {
                    periods.remove(index);
                }
                _ => {}
            }
        }
        if add_period {
            periods.push(ItemOwnershipPeriod {
                id: next_ownership_id(&periods),
                owner_type: "custom".to_owned(),
                owner_id: String::new(),
                start_year: 0,
                start_specified: false,
                start_absolute_day: None,
                start_calendar_id: None,
                start_show_time: false,
                end_year: None,
                end_absolute_day: None,
                end_calendar_id: None,
                end_show_time: false,
                note: String::new(),
            });
        }
        if editing {
            let profile = json_object_mut(&mut self.article_edit_profiles.item);
            profile.insert(
                "ownershipHistory".to_owned(),
                serde_json::Value::Array(
                    periods
                        .into_iter()
                        .filter_map(|period| serde_json::to_value(period).ok())
                        .collect(),
                ),
            );
        }
    }

    fn document_symbol_panel(&mut self, ui: &mut egui::Ui, article: &Article, category: &str) {
        if !article_supports_heraldry(category) {
            return;
        }
        let colors = self.colors();
        let has_territory = article_has_territory(&self.world, article, category);
        let (flag_id, emblem_id) = if self.editing_article {
            profile_symbol_ids(&self.article_edit_profiles, category)
        } else {
            article_symbol_ids(&self.world, article, category)
        };
        let flag_asset = flag_id.as_deref().and_then(|id| {
            self.world
                .heraldic_assets
                .iter()
                .find(|asset| asset.id == id)
                .cloned()
        });
        let emblem_asset = emblem_id.as_deref().and_then(|id| {
            self.world
                .heraldic_assets
                .iter()
                .find(|asset| asset.id == id)
                .cloned()
        });
        let mut picker = self.article_symbol_picker;
        let mut picked = None;
        theme::surface_frame(self.dark_mode).show(ui, |ui| {
            section_title(
                ui,
                if has_territory {
                    tr(self.language, "영토/상징", "Territory & Symbols")
                } else {
                    tr(self.language, "상징", "Symbols")
                },
                colors,
            );
            if has_territory {
                territory_inset(ui, &self.world, article, colors, self.year);
                ui.add_space(7.0);
            }
            ui.columns(2, |columns| {
                let flag_response = heraldry_document_tile(
                    &mut columns[0],
                    tr(self.language, "깃발", "Flag"),
                    flag_asset.as_ref(),
                    self.editing_article,
                    colors,
                );
                let emblem_response = heraldry_document_tile(
                    &mut columns[1],
                    tr(self.language, "문장", "Emblem"),
                    emblem_asset.as_ref(),
                    self.editing_article,
                    colors,
                );
                if self.editing_article && flag_response.clicked() {
                    picker = if picker == Some(HeraldryKind::Flag) {
                        None
                    } else {
                        Some(HeraldryKind::Flag)
                    };
                }
                if self.editing_article && emblem_response.clicked() {
                    picker = if picker == Some(HeraldryKind::Emblem) {
                        None
                    } else {
                        Some(HeraldryKind::Emblem)
                    };
                }
            });
            if let Some(kind) = picker {
                ui.add_space(6.0);
                egui::Frame::new()
                    .fill(colors.panel_alt)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::same(6))
                    .show(ui, |ui| {
                        ui.label(
                            RichText::new(match kind {
                                HeraldryKind::Flag => tr(self.language, "깃발 선택", "Select Flag"),
                                HeraldryKind::Emblem => {
                                    tr(self.language, "문장 선택", "Select Emblem")
                                }
                            })
                            .size(9.5)
                            .strong()
                            .color(colors.muted),
                        );
                        egui::ScrollArea::vertical()
                            .max_height(210.0)
                            .scroll_bar_visibility(
                                egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded,
                            )
                            .show(ui, |ui| {
                                for asset in self.world.heraldic_assets.iter().filter(|asset| {
                                    asset.is_emblem() == (kind == HeraldryKind::Emblem)
                                }) {
                                    if heraldry_asset_library_row(ui, asset, false, colors)
                                        .clicked()
                                    {
                                        picked = Some((kind, asset.id.clone()));
                                    }
                                }
                            });
                    });
            }
        });
        self.article_symbol_picker = picker;
        if let Some((kind, id)) = picked {
            set_profile_symbol_id(&mut self.article_edit_profiles, category, kind, Some(id));
            self.article_symbol_picker = None;
        }
    }

    fn document_genealogy_panel(&mut self, ui: &mut egui::Ui, article: &Article, category: &str) {
        let graph = if contains_any(category, &["인물", "Person", "person"]) {
            build_person_genealogy_graph(&self.world, article)
        } else if category_is_family(category) {
            build_family_genealogy_graph(&self.world, article)
        } else {
            None
        };
        let Some(_graph) = graph else { return };
        if ui
            .add_sized(
                [ui.available_width(), 30.0],
                egui::Button::new(tr(self.language, "가계도 보기", "View Genealogy")),
            )
            .clicked()
        {
            self.genealogy_popup_article_id = Some(article.id.clone());
        }
    }

    fn genealogy_popup(&mut self, context: &egui::Context) {
        let Some(article_id) = self.genealogy_popup_article_id.clone() else {
            return;
        };
        let Some(mut article) = self
            .world
            .articles
            .iter()
            .find(|article| article.id == article_id)
            .cloned()
        else {
            self.genealogy_popup_article_id = None;
            return;
        };
        if self.editing_article
            && self
                .world
                .articles
                .get(self.selected_article)
                .is_some_and(|selected| selected.id == article.id)
        {
            article.title = self.article_edit_title.clone();
            article.profiles = self.article_edit_profiles.clone();
        }
        let category = article_category_descriptor(&article);
        let graph = if category_is_family(&category) {
            build_family_genealogy_graph(&self.world, &article)
        } else {
            build_person_genealogy_graph(&self.world, &article)
        };
        let Some(graph) = graph else {
            self.genealogy_popup_article_id = None;
            return;
        };
        let mut open = true;
        let colors = self.colors();
        let mut selected = None;
        egui::Window::new(tr(self.language, "가계도", "Genealogy"))
            .id(egui::Id::new("genealogy-popup"))
            .open(&mut open)
            .collapsible(false)
            .resizable(true)
            .default_size(Vec2::new(920.0, 640.0))
            .anchor(Align2::CENTER_CENTER, Vec2::ZERO)
            .show(context, |ui| {
                ui.label(
                    RichText::new(&article.title)
                        .size(16.0)
                        .strong()
                        .color(colors.title),
                );
                ui.separator();
                selected = genealogy_graph_ui(
                    ui,
                    self.language,
                    colors,
                    &graph,
                    &mut self.genealogy_collapsed_ids,
                );
            });
        if !open {
            self.genealogy_popup_article_id = None;
        }
        if let Some(target) = selected
            && let Some(index) = self
                .world
                .articles
                .iter()
                .position(|candidate| candidate.title == target)
        {
            self.selected_article = index;
            self.selected_category = self.world.articles[index]
                .category_id
                .clone()
                .or_else(|| Some(self.world.articles[index].category.clone()));
            self.genealogy_popup_article_id = Some(self.world.articles[index].id.clone());
        }
    }

    fn planet_environment_workspace(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let planet_texture = self.planet_surface_texture_id(root.ctx());
        let revision = self
            .world
            .planet
            .revisions
            .climate
            .max(self.world.planet.revisions.surface);
        if self
            .planet_environment_summary
            .as_ref()
            .is_none_or(|(cached_revision, _)| *cached_revision != revision)
        {
            self.planet_environment_summary =
                Some((revision, environment::analyze_planet(&self.world.planet)));
        }
        let summary = self
            .planet_environment_summary
            .as_ref()
            .map(|(_, summary)| *summary)
            .unwrap_or_default();
        let analysis = environment::analyze_planet_point(
            &self.world.planet,
            self.planet_environment_point,
            self.year,
        );
        let planet = self.world.planet.clone();
        let mut select_pin = None;
        let mut save_pin = false;
        egui::Panel::left("planet_environment_controls")
            .exact_size(theme::Metrics::ENVIRONMENT_CONTROLS_WIDTH)
            .resizable(false)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel_alt)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::same(14)),
            )
            .show(root, |ui| {
                ui.label(
                    RichText::new(tr(
                        self.language,
                        "행성 기상·기후",
                        "Planet Weather & Climate",
                    ))
                    .size(17.0)
                    .strong()
                    .color(colors.title),
                );
                ui.add_space(10.0);
                theme::inset_frame(self.dark_mode, 8).show(ui, |ui| {
                    generator_section_title(
                        ui,
                        tr(self.language, "현재 선택 지점", "Selected Point"),
                        colors,
                    );
                    info_row(
                        ui,
                        tr(self.language, "위도", "Latitude"),
                        format!("{:.2}°", analysis.latitude_deg),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "경도", "Longitude"),
                        format!("{:.2}°", analysis.longitude_deg),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "고도", "Elevation"),
                        format!("{:.0} m", analysis.elevation_m),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "기온", "Temperature"),
                        format!("{:.1} °C", analysis.temperature_c),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "습도", "Moisture"),
                        format!("{:.0}%", analysis.moisture_percent),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "기후", "Climate"),
                        analysis.climate.code().to_owned(),
                        false,
                    );
                });
                ui.separator();
                generator_section_title(ui, tr(self.language, "행성 핀", "Planet Pins"), colors);
                if ui
                    .add_sized(
                        [ui.available_width(), 30.0],
                        egui::Button::new(tr(
                            self.language,
                            "현재 지점 저장",
                            "Save Current Point",
                        )),
                    )
                    .clicked()
                {
                    save_pin = true;
                }
                for pin in &planet.environment_pins {
                    if tree_button(
                        ui,
                        "•",
                        &pin.name,
                        "",
                        pin.position
                            .angular_distance_rad(self.planet_environment_point)
                            < 1.0e-8,
                        colors,
                    )
                    .clicked()
                    {
                        select_pin = Some(pin.position);
                    }
                }
            });
        if save_pin {
            let serial = self.world.planet.environment_pins.len() + 1;
            self.world
                .planet
                .environment_pins
                .push(crate::spatial::PlanetEnvironmentPin {
                    id: format!("planet-environment-pin-{serial}"),
                    name: format!("{} {serial}", tr(self.language, "지점", "Point")),
                    position: self.planet_environment_point,
                });
        }
        if let Some(position) = select_pin {
            self.planet_environment_point = position;
        }

        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.background)
                    .inner_margin(Margin::same(22)),
            )
            .show(root, |ui| {
                ui.horizontal(|ui| {
                    ui.label(
                        RichText::new(tr(
                            self.language,
                            "행성 환경 분석",
                            "Planet Environment Analysis",
                        ))
                        .size(20.0)
                        .strong()
                        .color(colors.title),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        ui.selectable_value(
                            &mut self.planet_globe_view,
                            false,
                            tr(self.language, "지도", "Map"),
                        );
                        ui.selectable_value(
                            &mut self.planet_globe_view,
                            true,
                            tr(self.language, "구체", "Sphere"),
                        );
                    });
                });
                ui.add_space(10.0);
                let canvas_height = ui.available_height().max(320.0);
                let (canvas, response) = ui.allocate_exact_size(
                    Vec2::new(ui.available_width(), canvas_height),
                    Sense::click_and_drag(),
                );
                let planet_painter = ui.painter().with_clip_rect(canvas);
                planet_painter.rect_filled(canvas, 4.0, colors.panel_alt);
                let map_rect = planet_map_rect(canvas, self.planet_map_zoom, self.planet_map_pan);
                if self.planet_globe_view {
                    paint_planet_surface_globe(
                        &planet_painter,
                        canvas,
                        &planet.surface,
                        planet.physical.radius_m,
                        self.planet_globe_yaw,
                        self.planet_globe_pitch,
                        self.planet_globe_zoom,
                        &[],
                        None,
                        colors,
                    );
                    paint_planet_rotation_axis(
                        &planet_painter,
                        canvas,
                        self.planet_globe_yaw,
                        self.planet_globe_pitch,
                        self.planet_globe_zoom,
                        PlanetReferenceFrame::from_physical(&planet.physical),
                        colors,
                    );
                } else {
                    paint_planet_surface_map(
                        &planet_painter,
                        map_rect,
                        &planet.surface,
                        planet_texture,
                        planet.physical.radius_m,
                        &[],
                        None,
                        colors,
                    );
                }
                paint_planet_environment_marker(
                    &planet_painter,
                    canvas,
                    map_rect,
                    self.planet_environment_point,
                    self.planet_globe_view,
                    self.planet_globe_yaw,
                    self.planet_globe_pitch,
                    self.planet_globe_zoom,
                    colors,
                );
                if response.dragged() {
                    let delta = ui.input(|input| input.pointer.delta());
                    if self.planet_globe_view {
                        self.planet_globe_yaw -= delta.x * 0.006;
                        self.planet_globe_pitch =
                            (self.planet_globe_pitch + delta.y * 0.006).clamp(-1.35, 1.35);
                    } else {
                        self.planet_map_pan = clamp_planet_map_pan(
                            canvas,
                            self.planet_map_zoom,
                            self.planet_map_pan + delta,
                        );
                    }
                } else if response.clicked()
                    && let Some(pointer) = response.interact_pointer_pos()
                {
                    let position = if self.planet_globe_view {
                        planet_position_from_globe(
                            pointer,
                            canvas,
                            self.planet_globe_yaw,
                            self.planet_globe_pitch,
                            self.planet_globe_zoom,
                        )
                    } else {
                        planet_position_from_map(pointer, map_rect)
                    };
                    if let Some(position) = position {
                        self.planet_environment_point = position;
                    }
                }
                if response.hovered() {
                    let scroll = ui.input(|input| input.smooth_scroll_delta.y);
                    if scroll != 0.0 {
                        if self.planet_globe_view {
                            self.planet_globe_zoom = (self.planet_globe_zoom
                                * (scroll * 0.0025).exp())
                            .clamp(0.65, 2.75);
                        } else if let Some(pointer) = response.hover_pos() {
                            zoom_planet_map_at_pointer(
                                canvas,
                                pointer,
                                scroll,
                                &mut self.planet_map_zoom,
                                &mut self.planet_map_pan,
                            );
                        }
                        ui.ctx().request_repaint();
                    }
                }
                let summary_rect = Rect::from_min_size(
                    Pos2::new(canvas.right() - 226.0, canvas.top() + 12.0),
                    Vec2::new(214.0, 164.0),
                );
                ui.scope_builder(egui::UiBuilder::new().max_rect(summary_rect), |ui| {
                    egui::Frame::new()
                        .fill(colors.panel.gamma_multiply(0.96))
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(5.0)
                        .inner_margin(Margin::same(9))
                        .show(ui, |ui| {
                            generator_section_title(
                                ui,
                                tr(self.language, "행성 평균 기후", "Planet Mean Climate"),
                                colors,
                            );
                            info_row(
                                ui,
                                tr(self.language, "평균 기온", "Mean"),
                                format!("{:.1} °C", summary.mean_temperature_c),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "기온 범위", "Range"),
                                format!(
                                    "{:.1}–{:.1} °C",
                                    summary.minimum_temperature_c, summary.maximum_temperature_c
                                ),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "평균 수분", "Moisture"),
                                format!("{:.1}%", summary.mean_moisture_percent),
                                false,
                            );
                            info_row(
                                ui,
                                tr(self.language, "해양/육지", "Ocean/Land"),
                                format!(
                                    "{:.1}% / {:.1}%",
                                    summary.ocean_area_percent, summary.land_area_percent
                                ),
                                false,
                            );
                        });
                });
            });
    }

    fn environment_workspace(&mut self, root: &mut egui::Ui) {
        if self.environment_planet_selected {
            self.planet_environment_workspace(root);
            return;
        }
        let colors = self.colors();
        let display_calendar = self.world.display_calendar(self.language);
        let calendar_coordinates = calendar::calendar_coordinates(
            &display_calendar,
            TimelineMoment::new(self.year, self.timeline_fraction),
            self.world.orbital_period_days as f64,
        );
        self.environment_month =
            calendar::climate_month(&display_calendar, calendar_coordinates.year_fraction);
        self.environment_day =
            calendar::day_units(&display_calendar, calendar_coordinates.year_fraction)
                .last()
                .copied()
                .unwrap_or(1);
        self.environment_hour =
            calendar::time_units(&display_calendar, calendar_coordinates.year_fraction)
                .first()
                .copied()
                .unwrap_or(0);
        let analysis = environment::analyze_point(
            &self.world.map,
            self.environment_point,
            self.year,
            climate_from_id(self.world.map.climate_model),
            self.world.map.environment_seed,
        );
        let mut pins_changed = false;
        egui::Panel::left("environment_controls")
            .exact_size(theme::Metrics::ENVIRONMENT_CONTROLS_WIDTH)
            .resizable(false)
            .frame(
                egui::Frame::new()
                    .fill(colors.panel_alt)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::same(14)),
            )
            .show(root, |ui| {
                ui.label(
                    RichText::new(tr(
                        self.language,
                        "지점 기상·기후",
                        "Point Weather & Climate",
                    ))
                    .size(17.0)
                    .strong()
                    .color(colors.title),
                );
                ui.add_space(10.0);
                theme::inset_frame(self.dark_mode, 8).show(ui, |ui| {
                    info_row(
                        ui,
                        tr(self.language, "활성 지도", "Active Map"),
                        self.world.map.title.clone(),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "생성 기후", "Generated Climate"),
                        format!(
                            "{} · {}",
                            climate_from_id(self.world.map.climate_model).code(),
                            climate_name(
                                self.language,
                                climate_from_id(self.world.map.climate_model)
                            )
                        ),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "분석 시점", "Analysis Date"),
                        calendar::format_absolute_moment(
                            &display_calendar,
                            self.language,
                            TimelineMoment::new(self.year, self.timeline_fraction),
                            self.world.orbital_period_days as f64,
                        ),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "분석 지점", "Analysis Point"),
                        format!(
                            "X {:.2} · Y {:.2}",
                            self.environment_point.x, self.environment_point.y
                        ),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "고도", "Elevation"),
                        format!("{:.0} m", analysis.elevation),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "지형", "Terrain"),
                        terrain_label(self.language, &analysis.terrain).to_owned(),
                        false,
                    );
                    info_row(
                        ui,
                        tr(self.language, "기후", "Climate"),
                        format!(
                            "{} · {}",
                            analysis.climate.code(),
                            climate_name(self.language, analysis.climate)
                        ),
                        false,
                    );
                });
                ui.separator();
                generator_section_title(ui, tr(self.language, "지도 핀", "Map Pins"), colors);
                if ui
                    .add_sized(
                        [ui.available_width(), 30.0],
                        egui::Button::new(tr(
                            self.language,
                            "현재 지점 핀 저장",
                            "Save Current Point",
                        )),
                    )
                    .clicked()
                {
                    let name = format!(
                        "{} {}",
                        tr(self.language, "지점", "Point"),
                        self.environment_pins.len() + 1
                    );
                    self.environment_pins.push(EnvironmentPin {
                        id: format!("environment-pin-{}", self.environment_pins.len() + 1),
                        name,
                        point: self.environment_point,
                    });
                    pins_changed = true;
                }
                for (index, pin) in self.environment_pins.clone().into_iter().enumerate() {
                    if self.environment_pin_rename.as_deref() == Some(pin.id.as_str()) {
                        let mut confirm = false;
                        let mut cancel = false;
                        let mut lost_focus = false;
                        ui.horizontal(|ui| {
                            let mut output =
                                egui::TextEdit::singleline(&mut self.environment_pin_rename_text)
                                    .desired_width((ui.available_width() - 54.0).max(60.0))
                                    .show(ui);
                            if self.environment_pin_rename_focus_pending {
                                output.response.request_focus();
                                output.state.cursor.set_char_range(Some(
                                    egui::text::CCursorRange::two(
                                        egui::text::CCursor::new(0),
                                        egui::text::CCursor::new(
                                            self.environment_pin_rename_text.chars().count(),
                                        ),
                                    ),
                                ));
                                output.state.store(ui.ctx(), output.response.id);
                                self.environment_pin_rename_focus_pending = false;
                            }
                            lost_focus = output.response.lost_focus();
                            confirm = ui
                                .small_button("OK")
                                .on_hover_text(tr(self.language, "이름 저장", "Save name"))
                                .clicked()
                                || (output.response.has_focus()
                                    && ui.input(|input| input.key_pressed(egui::Key::Enter)));
                            cancel = vector_icon_button(
                                ui,
                                UiIcon::Close,
                                tr(self.language, "취소", "Cancel"),
                                22.0,
                            )
                            .clicked()
                                || ui.input(|input| input.key_pressed(egui::Key::Escape));
                        });
                        if cancel {
                            self.environment_pin_rename = None;
                            self.environment_pin_rename_focus_pending = false;
                        } else if confirm || lost_focus {
                            let name = self.environment_pin_rename_text.trim();
                            if rename_environment_pin(&mut self.environment_pins, index, name) {
                                pins_changed = true;
                                self.environment_pin_rename = None;
                                self.environment_pin_rename_focus_pending = false;
                            }
                        }
                        ui.label(
                            RichText::new(format!("X {:.2} · Y {:.2}", pin.point.x, pin.point.y))
                                .size(8.5)
                                .color(colors.muted),
                        );
                    } else {
                        let response = tree_button(
                            ui,
                            "◆",
                            &pin.name,
                            &format!("{:.0},{:.0}", pin.point.x, pin.point.y),
                            distance(pin.point, self.environment_point) < 0.01,
                            colors,
                        )
                        .on_hover_text(tr(
                            self.language,
                            "더블클릭하여 이름 변경",
                            "Double-click to rename",
                        ));
                        if response.double_clicked() {
                            self.cancel_map_rename();
                            self.environment_pin_rename = Some(pin.id.clone());
                            self.environment_pin_rename_text = pin.name.clone();
                            self.environment_pin_rename_focus_pending = true;
                        } else if response.clicked() {
                            self.environment_point = pin.point;
                        }
                    }
                }
            });

        if pins_changed {
            self.sync_active_map_snapshot();
        }

        let weather = environment::weather_at(
            &analysis,
            self.environment_month,
            self.environment_day,
            self.environment_hour,
            self.year,
            self.world.map.environment_seed,
        );
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.background)
                    .inner_margin(Margin::same(22)),
            )
            .show(root, |ui| {
                egui::ScrollArea::vertical().show(ui, |ui| {
                    ui.label(
                        RichText::new(tr(
                            self.language,
                            "선택 지점 환경 분석",
                            "Selected Point Environment",
                        ))
                        .size(20.0)
                        .strong()
                        .color(colors.title),
                    );
                    ui.label(
                        RichText::new(format!(
                            "X {:.2} · Y {:.2} · {} {}",
                            analysis.point.x,
                            analysis.point.y,
                            self.year,
                            tr(self.language, "년", "year")
                        ))
                        .size(10.0)
                        .color(colors.muted),
                    );
                    ui.add_space(10.0);

                    theme::surface_frame(self.dark_mode).show(ui, |ui| {
                        section_title(
                            ui,
                            tr(
                                self.language,
                                "지도에서 분석 지점 선택",
                                "Select a Point on the Map",
                            ),
                            colors,
                        );
                        if let Some(point) = environment_selection_map(
                            ui,
                            &self.world.map,
                            self.environment_point,
                            &self.environment_pins,
                            colors,
                        ) {
                            self.environment_point = point;
                        }
                    });

                    ui.add_space(10.0);
                    theme::surface_frame(self.dark_mode).show(ui, |ui| {
                        section_title(
                            ui,
                            tr(self.language, "현재 기상", "Current Weather"),
                            colors,
                        );
                        ui.columns(6, |columns| {
                            metric_tile(
                                &mut columns[0],
                                tr(self.language, "기온", "Temperature"),
                                &format!("{:.1}°C", weather.temperature),
                                colors,
                            );
                            metric_tile(
                                &mut columns[1],
                                tr(self.language, "강수", "Precipitation"),
                                &format!("{:.1} mm", weather.precipitation),
                                colors,
                            );
                            metric_tile(
                                &mut columns[2],
                                tr(self.language, "습도", "Humidity"),
                                &format!("{:.0}%", weather.humidity),
                                colors,
                            );
                            metric_tile(
                                &mut columns[3],
                                tr(self.language, "풍향·풍속", "Wind"),
                                &format!(
                                    "{} {:.1} m/s",
                                    compass_direction(self.language, analysis.wind_direction),
                                    weather.wind
                                ),
                                colors,
                            );
                            metric_tile(
                                &mut columns[4],
                                tr(self.language, "일조시간", "Solar Hours"),
                                &format!("{:.1} h", weather.solar_hours),
                                colors,
                            );
                            metric_tile(
                                &mut columns[5],
                                tr(self.language, "일사량", "Irradiance"),
                                &format!("{:.0} W/m²", weather.solar_irradiance),
                                colors,
                            );
                        });
                        ui.separator();
                        ui.columns(6, |columns| {
                            metric_tile(
                                &mut columns[0],
                                tr(self.language, "강설량", "Snowfall"),
                                &format!("{:.1} mm", weather.snowfall),
                                colors,
                            );
                            metric_tile(
                                &mut columns[1],
                                tr(self.language, "적설", "Snow Cover"),
                                &format!("{:.1} mm", weather.snow_cover),
                                colors,
                            );
                            metric_tile(
                                &mut columns[2],
                                tr(self.language, "증발산량", "Evapotranspiration"),
                                &format!("{:.1} mm", weather.evapotranspiration),
                                colors,
                            );
                            metric_tile(
                                &mut columns[3],
                                tr(self.language, "토양수분", "Soil Moisture"),
                                &format!(
                                    "{:.0}%",
                                    weather.soil_moisture.max(analysis.soil_moisture)
                                ),
                                colors,
                            );
                            metric_tile(
                                &mut columns[4],
                                tr(self.language, "지표 유출량", "Surface Runoff"),
                                &format!("{:.1} mm", weather.runoff),
                                colors,
                            );
                            metric_tile(
                                &mut columns[5],
                                tr(self.language, "수자원 접근성", "Water Access"),
                                &format!("{:.0}", analysis.water_access),
                                colors,
                            );
                        });
                    });

                    ui.add_space(10.0);
                    environment_summary_pair(
                        ui,
                        self.dark_mode,
                        self.language,
                        &self.world.map,
                        self.year,
                        self.environment_month,
                        &self.environment_pins,
                        &analysis,
                        colors,
                    );
                    ui.add_space(10.0);
                    environment_analysis_pair(
                        ui,
                        self.dark_mode,
                        self.language,
                        &self.world,
                        self.environment_month,
                        &analysis,
                        colors,
                        &mut self.environment_suitability_local,
                    );
                });
            });
    }

    fn project_home_workspace(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.background)
                    .inner_margin(Margin::same(24)),
            )
            .show(root, |ui| {
                egui::ScrollArea::vertical()
                    .scroll_bar_visibility(
                        egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded,
                    )
                    .show(ui, |ui| {
                        ui.label(
                            RichText::new(tr(self.language, "프로젝트 홈", "Project Home"))
                                .size(22.0)
                                .strong()
                                .color(colors.title),
                        );
                        ui.label(
                            RichText::new(&self.world.title)
                                .size(12.0)
                                .color(colors.muted),
                        );
                        ui.add_space(14.0);
                        document_columns(ui, |columns| {
                            theme::surface_frame(self.dark_mode).show(&mut columns[0], |ui| {
                                ui.horizontal(|ui| {
                                    section_title(
                                        ui,
                                        tr(self.language, "목차와 본문", "Contents and Body"),
                                        colors,
                                    );
                                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                        if self.project_home_editing {
                                            if ui
                                                .button(tr(self.language, "완료", "Done"))
                                                .clicked()
                                            {
                                                self.project_home_editing = false;
                                                self.project_home_snapshot = None;
                                                self.world.description =
                                                    project_sections_to_legacy_description(
                                                        &self.world.project_sections,
                                                    );
                                            }
                                            if ui
                                                .button(tr(self.language, "취소", "Cancel"))
                                                .clicked()
                                            {
                                                if let Some(snapshot) =
                                                    self.project_home_snapshot.take()
                                                {
                                                    self.world.project_sections = snapshot;
                                                }
                                                self.project_home_editing = false;
                                            }
                                        } else if vector_icon_button(
                                            ui,
                                            UiIcon::Edit,
                                            tr(
                                                self.language,
                                                "목차와 본문 편집",
                                                "Edit contents and body",
                                            ),
                                            28.0,
                                        )
                                        .clicked()
                                        {
                                            self.project_home_snapshot =
                                                Some(self.world.project_sections.clone());
                                            self.project_home_editing = true;
                                        }
                                    });
                                });
                                ui.separator();
                                if self.project_home_editing {
                                    toc_editor_panel(
                                        ui,
                                        self.language,
                                        colors,
                                        &mut self.world.project_sections,
                                    );
                                    ui.add_space(8.0);
                                    for section in &mut self.world.project_sections {
                                        theme::inset_frame(self.dark_mode, 8).show(ui, |ui| {
                                            ui.label(
                                                RichText::new(&section.title)
                                                    .size(
                                                        (16.0 - section.level as f32).max(12.0)
                                                            * self.ui_scale,
                                                    )
                                                    .strong()
                                                    .color(colors.title),
                                            );
                                            wiki_multiline_editor(
                                                ui,
                                                &mut section.content,
                                                5,
                                                &self.world.articles,
                                                colors,
                                            );
                                        });
                                        ui.add_space(6.0);
                                    }
                                } else {
                                    toc_sections_panel(
                                        ui,
                                        self.language,
                                        colors,
                                        &self.world.project_sections,
                                    );
                                    if self.world.project_sections.is_empty() {
                                        ui.label(RichText::new("-").color(colors.muted));
                                    } else {
                                        for section in &self.world.project_sections {
                                            theme::inset_frame(self.dark_mode, 8).show(ui, |ui| {
                                                ui.label(
                                                    RichText::new(&section.title)
                                                        .size(
                                                            (16.0 - section.level as f32).max(12.0),
                                                        )
                                                        .strong()
                                                        .color(colors.title),
                                                );
                                                let _ = linked_document_text(
                                                    ui,
                                                    &section.content,
                                                    self.language,
                                                    colors,
                                                    &self.world.articles,
                                                    12.5,
                                                    false,
                                                    false,
                                                );
                                            });
                                            ui.add_space(6.0);
                                        }
                                    }
                                }
                            });
                            columns[1].vertical(|ui| {
                                theme::surface_frame(self.dark_mode).show(ui, |ui| {
                                    section_title(
                                        ui,
                                        tr(self.language, "세계 정보", "World Information"),
                                        colors,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "세계 이름", "World Name"),
                                        self.world.title.clone(),
                                        false,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "활성 지도", "Active Map"),
                                        self.world.map.title.clone(),
                                        false,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "문서", "Documents"),
                                        self.world.articles.len().to_string(),
                                        false,
                                    );
                                });
                                ui.add_space(10.0);
                                theme::surface_frame(self.dark_mode).show(ui, |ui| {
                                    section_title(
                                        ui,
                                        tr(self.language, "세계 환경 기준", "World Environment"),
                                        colors,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "자전축 기울기", "Axial Tilt"),
                                        format!("{:.2}°", self.world.axial_tilt_deg),
                                        false,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "하루 길이", "Day Length"),
                                        format!(
                                            "{:.1} {}",
                                            self.world.day_length_hours,
                                            tr(self.language, "시간", "hours"),
                                        ),
                                        false,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "공전 주기", "Orbital Period"),
                                        format!(
                                            "{:.0} {}",
                                            self.world.orbital_period_days,
                                            tr(self.language, "일", "days"),
                                        ),
                                        false,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "기준 위도", "Reference Latitude"),
                                        format!("{:.1}°", self.world.latitude_deg),
                                        false,
                                    );
                                    info_row(
                                        ui,
                                        tr(self.language, "중력", "Gravity"),
                                        format!("{:.2} m/s²", self.world.gravity_ms2),
                                        false,
                                    );
                                });
                                ui.add_space(10.0);
                                theme::surface_frame(self.dark_mode).show(ui, |ui| {
                                    section_title(
                                        ui,
                                        tr(self.language, "프로젝트 현황", "Project Overview"),
                                        colors,
                                    );
                                    ui.columns(2, |columns| {
                                        metric_tile(
                                            &mut columns[0],
                                            tr(self.language, "지도", "Maps"),
                                            &self.world.maps.len().max(1).to_string(),
                                            colors,
                                        );
                                        metric_tile(
                                            &mut columns[1],
                                            tr(self.language, "문서", "Documents"),
                                            &self.world.articles.len().to_string(),
                                            colors,
                                        );
                                    });
                                    ui.columns(2, |columns| {
                                        metric_tile(
                                            &mut columns[0],
                                            tr(self.language, "사건", "Events"),
                                            &self.world.events.len().to_string(),
                                            colors,
                                        );
                                        metric_tile(
                                            &mut columns[1],
                                            tr(self.language, "세력", "Factions"),
                                            &self.world.factions.len().to_string(),
                                            colors,
                                        );
                                    });
                                });
                            });
                        });
                    });
            });
    }

    fn rpg_rules_workspace(&mut self, root: &mut egui::Ui) {
        let colors = self.colors();
        let language = self.language;
        let mut add_category = false;
        let mut add_group = false;
        let mut definition_action: Option<(usize, i32)> = None;
        let mut blocked_definition = None;
        let mut active_group_index = None;
        let mut category_action: Option<i32> = None;
        let mut group_action: Option<i32> = None;
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.background)
                    .inner_margin(Margin::same(22)),
            )
            .show(root, |ui| {
                ui.horizontal(|ui| {
                    ui.label(
                        RichText::new(tr(language, "RPG 규칙", "RPG Rules"))
                            .size(20.0)
                            .strong()
                            .color(colors.title),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if self.rpg_rules_editing {
                            if ui
                                .add_sized(
                                    [58.0, 30.0],
                                    egui::Button::new(tr(language, "완료", "Done")),
                                )
                                .clicked()
                            {
                                self.rpg_rules_editing = false;
                                self.rpg_rules_snapshot = None;
                            }
                            if ui
                                .add_sized(
                                    [58.0, 30.0],
                                    egui::Button::new(tr(language, "취소", "Cancel")),
                                )
                                .clicked()
                            {
                                if let Some(snapshot) = self.rpg_rules_snapshot.take() {
                                    self.rpg_rule_set = snapshot;
                                }
                                self.rpg_rules_editing = false;
                            }
                        } else if vector_icon_button(
                            ui,
                            UiIcon::Edit,
                            tr(language, "RPG 규칙 편집", "Edit RPG Rules"),
                            32.0,
                        )
                        .clicked()
                        {
                            self.rpg_rules_snapshot = Some(self.rpg_rule_set.clone());
                            self.rpg_rules_editing = true;
                        }
                    });
                });
                ui.add_space(12.0);
                ui.horizontal_wrapped(|ui| {
                    for (index, category) in self.rpg_rule_set.categories.iter().enumerate() {
                        if ui
                            .add_sized(
                                [160.0, 37.0],
                                egui::Button::selectable(
                                    self.rpg_tab == index,
                                    RichText::new(category.label(language)).size(11.0).strong(),
                                ),
                            )
                            .clicked()
                        {
                            self.rpg_tab = index;
                            self.rpg_group_tab = 0;
                        }
                    }
                    if self.rpg_rules_editing
                        && vector_icon_button(
                            ui,
                            UiIcon::Plus,
                            tr(language, "상위 범주 추가", "Add top-level category"),
                            34.0,
                        )
                        .clicked()
                    {
                        add_category = true;
                    }
                });
                if self.rpg_rules_editing {
                    let category_count = self.rpg_rule_set.categories.len();
                    if let Some(category) = self.rpg_rule_set.categories.get_mut(self.rpg_tab) {
                        ui.horizontal(|ui| {
                            let width = ((ui.available_width() - 138.0) * 0.5).max(90.0);
                            ui.add_sized(
                                [width, 28.0],
                                egui::TextEdit::singleline(&mut category.korean),
                            );
                            ui.add_sized(
                                [width, 28.0],
                                egui::TextEdit::singleline(&mut category.english),
                            );
                            if ui
                                .add_enabled(self.rpg_tab > 0, egui::Button::new("↑"))
                                .clicked()
                            {
                                category_action = Some(-1);
                            }
                            if ui
                                .add_enabled(
                                    self.rpg_tab + 1 < category_count,
                                    egui::Button::new("↓"),
                                )
                                .clicked()
                            {
                                category_action = Some(1);
                            }
                            if !category.builtin
                                && ui
                                    .add_sized(
                                        [28.0, 28.0],
                                        egui::Button::new(RichText::new("×").color(colors.danger)),
                                    )
                                    .clicked()
                            {
                                category_action = Some(0);
                            }
                        });
                    }
                }
                ui.add_space(8.0);
                let selected_category_id = self
                    .rpg_rule_set
                    .categories
                    .get(self.rpg_tab)
                    .map(|category| category.id.clone());
                let group_indices = self
                    .rpg_rule_set
                    .groups
                    .iter()
                    .enumerate()
                    .filter(|(_, group)| {
                        selected_category_id.as_deref() == Some(group.parent_id.as_str())
                            && (!group.magic_only || self.world.magic_enabled)
                    })
                    .map(|(index, _)| index)
                    .collect::<Vec<_>>();
                if self.rpg_group_tab >= group_indices.len() {
                    self.rpg_group_tab = 0;
                }
                active_group_index = group_indices.get(self.rpg_group_tab).copied();
                egui::ScrollArea::vertical().show(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        for (local_index, group_index) in group_indices.iter().copied().enumerate()
                        {
                            let group = &self.rpg_rule_set.groups[group_index];
                            if ui
                                .add_sized(
                                    [124.0, 34.0],
                                    egui::Button::selectable(
                                        self.rpg_group_tab == local_index,
                                        RichText::new(group.label(language)).size(10.5),
                                    ),
                                )
                                .clicked()
                            {
                                self.rpg_group_tab = local_index;
                            }
                        }
                        if self.rpg_rules_editing
                            && selected_category_id.is_some()
                            && vector_icon_button(
                                ui,
                                UiIcon::Plus,
                                tr(language, "하위 범주 추가", "Add subcategory"),
                                32.0,
                            )
                            .clicked()
                        {
                            add_group = true;
                        }
                    });
                    ui.add_space(8.0);
                    theme::surface_frame(self.dark_mode).show(ui, |ui| {
                        if let Some(group_index) = group_indices.get(self.rpg_group_tab).copied() {
                            let title = self.rpg_rule_set.groups[group_index]
                                .label(language)
                                .to_owned();
                            section_title(ui, &title, colors);
                            let editing = self.rpg_rules_editing;
                            let group = &mut self.rpg_rule_set.groups[group_index];
                            if editing {
                                let local_group_index = self.rpg_group_tab;
                                let local_group_count = group_indices.len();
                                ui.horizontal(|ui| {
                                    let width = ((ui.available_width() - 138.0) * 0.5).max(76.0);
                                    ui.add_sized(
                                        [width, 28.0],
                                        egui::TextEdit::singleline(&mut group.korean)
                                            .hint_text("한국어"),
                                    );
                                    ui.add_sized(
                                        [width, 28.0],
                                        egui::TextEdit::singleline(&mut group.english)
                                            .hint_text("English"),
                                    );
                                    if ui
                                        .add_enabled(local_group_index > 0, egui::Button::new("↑"))
                                        .clicked()
                                    {
                                        group_action = Some(-1);
                                    }
                                    if ui
                                        .add_enabled(
                                            local_group_index + 1 < local_group_count,
                                            egui::Button::new("↓"),
                                        )
                                        .clicked()
                                    {
                                        group_action = Some(1);
                                    }
                                    if !group.builtin
                                        && ui
                                            .add_sized(
                                                [28.0, 28.0],
                                                egui::Button::new(
                                                    RichText::new("×").color(colors.danger),
                                                ),
                                            )
                                            .clicked()
                                    {
                                        group_action = Some(0);
                                    }
                                });
                            }
                            ui.separator();
                            let definition_count = group.definitions.len();
                            for (entry_index, definition) in
                                group.definitions.iter_mut().enumerate()
                            {
                                if editing {
                                    if let Some(action) = rpg_definition_edit_row(
                                        ui,
                                        definition,
                                        entry_index,
                                        definition_count,
                                        language,
                                        colors,
                                    ) {
                                        if action == 0
                                            && rpg_definition_is_used(&self.world, &definition.id)
                                        {
                                            blocked_definition =
                                                Some(definition.label(language).to_owned());
                                        } else {
                                            definition_action = Some((entry_index, action));
                                        }
                                    }
                                } else {
                                    rpg_definition_read_row(ui, definition, language, colors);
                                }
                            }
                            if editing {
                                ui.separator();
                                ui.horizontal(|ui| {
                                    let width = ((ui.available_width() - 96.0) * 0.5).max(90.0);
                                    ui.add_sized(
                                        [width, 30.0],
                                        egui::TextEdit::singleline(&mut self.rpg_new_name)
                                            .hint_text(tr(language, "새 수치명", "New definition")),
                                    );
                                    ui.add_sized(
                                        [width, 30.0],
                                        egui::TextEdit::singleline(&mut self.rpg_new_name_english)
                                            .hint_text("English"),
                                    );
                                    if ui
                                        .add_sized(
                                            [80.0, 30.0],
                                            egui::Button::new(tr(language, "추가", "Add")),
                                        )
                                        .clicked()
                                        && !self.rpg_new_name.trim().is_empty()
                                    {
                                        let serial = group.definitions.len() + 1;
                                        group.definitions.push(RpgRuleDefinition {
                                            id: format!("{}-custom-{serial}", group.id),
                                            korean: self.rpg_new_name.trim().to_owned(),
                                            english: if self.rpg_new_name_english.trim().is_empty()
                                            {
                                                self.rpg_new_name.trim().to_owned()
                                            } else {
                                                self.rpg_new_name_english.trim().to_owned()
                                            },
                                            value_kind: RpgValueKind::Integer,
                                            builtin: false,
                                        });
                                        self.rpg_new_name.clear();
                                        self.rpg_new_name_english.clear();
                                    }
                                });
                            }
                        }
                    });
                });
            });

        if add_category {
            let serial = self.rpg_rule_set.categories.len() + 1;
            self.rpg_rule_set
                .categories
                .push(crate::reference_data::RpgRuleCategory {
                    id: format!("custom-category-{serial}"),
                    korean: format!("새 범주 {serial}"),
                    english: format!("Custom Category {serial}"),
                    builtin: false,
                });
            self.rpg_tab = self.rpg_rule_set.categories.len() - 1;
            self.rpg_group_tab = 0;
        }
        if add_group {
            if let Some(parent_id) = self
                .rpg_rule_set
                .categories
                .get(self.rpg_tab)
                .map(|category| category.id.clone())
            {
                let serial = self.rpg_rule_set.groups.len() + 1;
                self.rpg_rule_set.groups.push(RpgRuleGroup {
                    id: format!("custom-group-{serial}"),
                    parent_id,
                    korean: format!("새 하위 범주 {serial}"),
                    english: format!("Custom Group {serial}"),
                    magic_only: false,
                    builtin: false,
                    definitions: Vec::new(),
                });
                let group_count = self
                    .rpg_rule_set
                    .groups
                    .iter()
                    .enumerate()
                    .filter(|(_, group)| {
                        self.rpg_rule_set
                            .categories
                            .get(self.rpg_tab)
                            .is_some_and(|category| group.parent_id == category.id)
                    })
                    .count();
                self.rpg_group_tab = group_count.saturating_sub(1);
            }
        }
        if let Some((index, direction)) = definition_action {
            if let Some(group_index) = active_group_index {
                let definitions = &mut self.rpg_rule_set.groups[group_index].definitions;
                match direction {
                    -1 if index > 0 => definitions.swap(index, index - 1),
                    1 if index + 1 < definitions.len() => definitions.swap(index, index + 1),
                    0 if index < definitions.len() => {
                        definitions.remove(index);
                    }
                    _ => {}
                }
            }
        }
        if let Some(direction) = group_action {
            if let Some(group_index) = active_group_index {
                let group_id = self.rpg_rule_set.groups[group_index].id.clone();
                let parent_id = self.rpg_rule_set.groups[group_index].parent_id.clone();
                let siblings = self
                    .rpg_rule_set
                    .groups
                    .iter()
                    .enumerate()
                    .filter(|(_, group)| group.parent_id == parent_id)
                    .map(|(index, _)| index)
                    .collect::<Vec<_>>();
                if let Some(local_index) = siblings.iter().position(|index| *index == group_index) {
                    match direction {
                        -1 if local_index > 0 => {
                            self.rpg_rule_set
                                .groups
                                .swap(group_index, siblings[local_index - 1]);
                            self.rpg_group_tab = self.rpg_group_tab.saturating_sub(1);
                        }
                        1 if local_index + 1 < siblings.len() => {
                            self.rpg_rule_set
                                .groups
                                .swap(group_index, siblings[local_index + 1]);
                            self.rpg_group_tab += 1;
                        }
                        0 => {
                            let in_use = self.rpg_rule_set.groups[group_index]
                                .definitions
                                .iter()
                                .any(|definition| {
                                    rpg_definition_is_used(&self.world, &definition.id)
                                });
                            if in_use {
                                blocked_definition = Some(group_id);
                            } else {
                                self.rpg_rule_set.groups.remove(group_index);
                                self.rpg_group_tab = self.rpg_group_tab.saturating_sub(1);
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
        if let Some(direction) = category_action {
            let index = self.rpg_tab;
            match direction {
                -1 if index > 0 => {
                    self.rpg_rule_set.categories.swap(index, index - 1);
                    self.rpg_tab -= 1;
                }
                1 if index + 1 < self.rpg_rule_set.categories.len() => {
                    self.rpg_rule_set.categories.swap(index, index + 1);
                    self.rpg_tab += 1;
                }
                0 if index < self.rpg_rule_set.categories.len() => {
                    let category_id = self.rpg_rule_set.categories[index].id.clone();
                    let in_use = self
                        .rpg_rule_set
                        .groups
                        .iter()
                        .filter(|group| group.parent_id == category_id)
                        .flat_map(|group| &group.definitions)
                        .any(|definition| rpg_definition_is_used(&self.world, &definition.id));
                    if in_use {
                        blocked_definition = Some(category_id);
                    } else {
                        self.rpg_rule_set
                            .groups
                            .retain(|group| group.parent_id != category_id);
                        self.rpg_rule_set.categories.remove(index);
                        self.rpg_tab = self
                            .rpg_tab
                            .min(self.rpg_rule_set.categories.len().saturating_sub(1));
                        self.rpg_group_tab = 0;
                    }
                }
                _ => {}
            }
        }
        if let Some(name) = blocked_definition {
            self.notify(&format!(
                "{}: {name}",
                tr(
                    language,
                    "문서에서 사용 중인 수치는 삭제할 수 없습니다",
                    "A definition used by a document cannot be deleted"
                )
            ));
        }
    }

    fn heraldry_workspace(&mut self, root: &mut egui::Ui, emblem: bool) {
        let colors = self.colors();
        let mut design = if emblem {
            self.emblem_design.clone()
        } else {
            self.flag_design.clone()
        };
        let mut selected = self
            .heraldry_selected_layer_id
            .as_deref()
            .and_then(|id| design.layers.iter().position(|layer| layer.id == id))
            .unwrap_or(self.heraldry_selected_layer)
            .min(design.layers.len().saturating_sub(1));
        let mut layer_selected = self.heraldry_layer_selected && !design.layers.is_empty();
        let mut browser_tab = self.heraldry_browser_tab;
        let mut charge_category = self.heraldry_charge_category;
        let mut add_mode = self.heraldry_add_mode;
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(colors.background)
                    .inner_margin(Margin::ZERO),
            )
            .show(root, |ui| {
                let heading = if emblem {
                    tr(self.language, "문장", "Emblems")
                } else {
                    tr(self.language, "깃발", "Flags")
                };
                egui::Frame::new()
                    .fill(colors.panel)
                    .stroke(Stroke::new(1.0, colors.border))
                    .inner_margin(Margin::symmetric(14, 10))
                    .show(ui, |ui| {
                        ui.horizontal(|ui| {
                            ui.label(
                                RichText::new(heading)
                                    .size(17.0)
                                    .strong()
                                    .color(colors.title),
                            );
                            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                let _ = ui.add_sized(
                                    [82.0, 30.0],
                                    egui::Button::new(tr(self.language, "저장", "Save")),
                                );
                            });
                        });
                    });

                let workspace_height = ui.available_height();
                ui.horizontal(|ui| {
                    ui.allocate_ui_with_layout(
                        Vec2::new(216.0, workspace_height),
                        Layout::top_down(Align::Min),
                        |ui| {
                            egui::Frame::new()
                                .fill(colors.panel_alt)
                                .stroke(Stroke::new(1.0, colors.border))
                                .inner_margin(Margin::same(10))
                                .show(ui, |ui| {
                                    ui.set_min_height((workspace_height - 22.0).max(220.0));
                                    section_title(
                                        ui,
                                        tr(self.language, "레이어", "Layers"),
                                        colors,
                                    );
                                    ui.horizontal(|ui| {
                                        if ui
                                            .add_sized(
                                                [ui.available_width() * 0.5 - 3.0, 28.0],
                                                egui::Button::new(tr(
                                                    self.language,
                                                    "무늬 추가",
                                                    "Add Pattern",
                                                )),
                                            )
                                            .clicked()
                                        {
                                            browser_tab = HeraldryBrowserTab::Pattern;
                                            add_mode =
                                                if add_mode == Some(HeraldryBrowserTab::Pattern) {
                                                    None
                                                } else {
                                                    Some(HeraldryBrowserTab::Pattern)
                                                };
                                        }
                                        if ui
                                            .add_sized(
                                                [ui.available_width(), 28.0],
                                                egui::Button::new(tr(
                                                    self.language,
                                                    "문양 추가",
                                                    "Add Charge",
                                                )),
                                            )
                                            .clicked()
                                        {
                                            browser_tab = HeraldryBrowserTab::Charge;
                                            add_mode =
                                                if add_mode == Some(HeraldryBrowserTab::Charge) {
                                                    None
                                                } else {
                                                    Some(HeraldryBrowserTab::Charge)
                                                };
                                        }
                                    });
                                    ui.add_space(6.0);
                                    let list_height = ui.available_height();
                                    egui::ScrollArea::vertical()
                                        .scroll_bar_visibility(
                                            egui::scroll_area::ScrollBarVisibility::AlwaysHidden,
                                        )
                                        .max_height(list_height)
                                        .auto_shrink([false, false])
                                        .show(ui, |ui| {
                                            for (layer_index, layer) in
                                                design.layers.iter().enumerate()
                                            {
                                                if heraldry_layer_thumbnail_data(
                                                    ui,
                                                    layer,
                                                    layer_selected && layer_index == selected,
                                                    design.shape,
                                                    colors,
                                                )
                                                .clicked()
                                                {
                                                    if layer_selected && selected == layer_index {
                                                        layer_selected = false;
                                                    } else {
                                                        selected = layer_index;
                                                        layer_selected = true;
                                                        add_mode = None;
                                                    }
                                                }
                                            }
                                        });
                                });
                        },
                    );

                    let center_width = (ui.available_width() - 250.0).max(330.0);
                    ui.allocate_ui_with_layout(
                        Vec2::new(center_width, workspace_height),
                        Layout::top_down(Align::Min),
                        |ui| {
                            let preview_height = (workspace_height * 0.40).clamp(220.0, 350.0);
                            let preview_response = heraldry_preview_design(
                                ui,
                                &design,
                                Vec2::new(ui.available_width(), preview_height),
                                self.language,
                                colors,
                            );
                            let preview_content = heraldry_content_rect(
                                preview_response.rect.shrink(28.0),
                                design.shape,
                            );
                            if preview_response.drag_started()
                                && let Some(pointer) = preview_response.interact_pointer_pos()
                            {
                                if let Some(hit_index) = design
                                    .layers
                                    .iter()
                                    .enumerate()
                                    .rev()
                                    .find(|(_, layer)| {
                                        layer.visible
                                            && !layer.locked
                                            && heraldry_layer_hit_test(
                                                layer,
                                                preview_content,
                                                design.shape,
                                                pointer,
                                            )
                                    })
                                    .map(|(index, _)| index)
                                {
                                    selected = hit_index;
                                    layer_selected = true;
                                    add_mode = None;
                                }
                                if layer_selected
                                    && let Some(layer) = design.layers.get(selected)
                                    && !layer.locked
                                    && !matches!(layer.artwork, LayerArtwork::Solid)
                                {
                                    self.heraldry_drag_origin = Some((selected, layer.x, layer.y));
                                }
                            }
                            if preview_response.dragged()
                                && let Some((layer_index, origin_x, origin_y)) =
                                    self.heraldry_drag_origin
                                && layer_index == selected
                            {
                                if let Some(layer) = design.layers.get_mut(selected)
                                    && !layer.locked
                                {
                                    let delta = preview_response.drag_delta();
                                    layer.x = (origin_x
                                        + delta.x / preview_content.width().max(1.0) * 200.0)
                                        .clamp(-200.0, 200.0);
                                    layer.y = (origin_y
                                        + delta.y / preview_content.height().max(1.0) * 200.0)
                                        .clamp(-200.0, 200.0);
                                }
                            }
                            if preview_response.drag_stopped() {
                                self.heraldry_drag_origin = None;
                            }
                            ui.add_space(8.0);
                            ui.horizontal(|ui| {
                                for (tab, label) in [
                                    (
                                        HeraldryBrowserTab::Shape,
                                        tr(self.language, "모양", "Shapes"),
                                    ),
                                    (
                                        HeraldryBrowserTab::Pattern,
                                        tr(self.language, "무늬", "Patterns"),
                                    ),
                                    (
                                        HeraldryBrowserTab::Charge,
                                        tr(self.language, "문양", "Charges"),
                                    ),
                                ] {
                                    if ui
                                        .add_sized(
                                            [96.0, 34.0],
                                            egui::Button::selectable(browser_tab == tab, label),
                                        )
                                        .clicked()
                                    {
                                        browser_tab = tab;
                                    }
                                }
                            });
                            if browser_tab == HeraldryBrowserTab::Charge {
                                ui.horizontal(|ui| {
                                    let width = (ui.available_width()
                                        - ui.spacing().item_spacing.x * 6.0)
                                        / 7.0;
                                    for category in ChargeCategory::ALL {
                                        if ui
                                            .add_sized(
                                                [width.max(34.0), 27.0],
                                                egui::Button::selectable(
                                                    charge_category == category,
                                                    charge_category_label(self.language, category),
                                                ),
                                            )
                                            .clicked()
                                        {
                                            charge_category = category;
                                        }
                                    }
                                });
                            }
                            ui.separator();
                            let browser_height = ui.available_height();
                            egui::ScrollArea::vertical()
                                .scroll_bar_visibility(
                                    egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded,
                                )
                                .max_height(browser_height)
                                .auto_shrink([false, false])
                                .show(ui, |ui| {
                                    ui.horizontal_wrapped(|ui| match browser_tab {
                                        HeraldryBrowserTab::Shape => {
                                            let shapes: &[HeraldryShape] = if emblem {
                                                &HeraldryShape::EMBLEM_SHAPES
                                            } else {
                                                &HeraldryShape::FLAG_SHAPES
                                            };
                                            for shape in shapes {
                                                if heraldry_shape_choice(
                                                    ui,
                                                    *shape,
                                                    design.shape == *shape,
                                                    colors,
                                                )
                                                .clicked()
                                                {
                                                    design.shape = *shape;
                                                }
                                            }
                                        }
                                        HeraldryBrowserTab::Pattern => {
                                            for artwork in LayerArtwork::PATTERNS {
                                                if heraldry_artwork_choice(ui, artwork, colors)
                                                    .clicked()
                                                {
                                                    if add_mode == Some(HeraldryBrowserTab::Pattern)
                                                        || !layer_selected
                                                    {
                                                        design.layers.push(HeraldryLayer::new(
                                                            artwork,
                                                            [226, 201, 88, 255],
                                                        ));
                                                        selected = design.layers.len() - 1;
                                                        layer_selected = true;
                                                        add_mode = None;
                                                    } else if let Some(layer) =
                                                        design.layers.get_mut(selected)
                                                    {
                                                        layer.artwork = artwork;
                                                    }
                                                }
                                            }
                                        }
                                        HeraldryBrowserTab::Charge => {
                                            for artwork in LayerArtwork::CHARGES.into_iter().filter(
                                                |artwork| {
                                                    charge_category == ChargeCategory::All
                                                        || artwork.charge_category()
                                                            == charge_category
                                                },
                                            ) {
                                                if heraldry_artwork_choice(ui, artwork, colors)
                                                    .clicked()
                                                {
                                                    if add_mode == Some(HeraldryBrowserTab::Charge)
                                                        || !layer_selected
                                                    {
                                                        design.layers.push(HeraldryLayer::new(
                                                            artwork,
                                                            [245, 248, 251, 255],
                                                        ));
                                                        selected = design.layers.len() - 1;
                                                        layer_selected = true;
                                                        add_mode = None;
                                                    } else if let Some(layer) =
                                                        design.layers.get_mut(selected)
                                                    {
                                                        layer.artwork = artwork;
                                                    }
                                                }
                                            }
                                        }
                                    });
                                });
                        },
                    );

                    ui.allocate_ui_with_layout(
                        Vec2::new(250.0, workspace_height),
                        Layout::top_down(Align::Min),
                        |ui| {
                            egui::Frame::new()
                                .fill(colors.panel_alt)
                                .stroke(Stroke::new(1.0, colors.border))
                                .inner_margin(Margin::same(10))
                                .show(ui, |ui| {
                                    ui.set_min_height((workspace_height - 22.0).max(220.0));
                                    section_title(
                                        ui,
                                        tr(self.language, "레이어 편집", "Layer Inspector"),
                                        colors,
                                    );
                                    let mut delete = false;
                                    let mut move_up = false;
                                    let mut move_down = false;
                                    let mut duplicate = false;
                                    let mut toggle_visibility = false;
                                    let mut toggle_lock = false;
                                    if layer_selected
                                        && let Some(layer) = design.layers.get(selected)
                                    {
                                        ui.horizontal(|ui| {
                                            let visibility_icon = if layer.visible {
                                                UiIcon::Eye
                                            } else {
                                                UiIcon::EyeOff
                                            };
                                            if vector_icon_button(
                                                ui,
                                                visibility_icon,
                                                tr(self.language, "숨기기/표시", "Hide/Show"),
                                                30.0,
                                            )
                                            .clicked()
                                            {
                                                toggle_visibility = true;
                                            }
                                            let lock_icon = if layer.locked {
                                                UiIcon::Lock
                                            } else {
                                                UiIcon::Unlock
                                            };
                                            if vector_icon_button(
                                                ui,
                                                lock_icon,
                                                tr(self.language, "잠금/해제", "Lock/Unlock"),
                                                30.0,
                                            )
                                            .clicked()
                                            {
                                                toggle_lock = true;
                                            }
                                            if vector_icon_button(
                                                ui,
                                                UiIcon::ArrowUp,
                                                tr(self.language, "위로", "Move Up"),
                                                30.0,
                                            )
                                            .on_hover_text(tr(self.language, "위로", "Move Up"))
                                            .clicked()
                                            {
                                                move_up = true;
                                            }
                                            if vector_icon_button(
                                                ui,
                                                UiIcon::ArrowDown,
                                                tr(self.language, "아래로", "Move Down"),
                                                30.0,
                                            )
                                            .on_hover_text(tr(self.language, "아래로", "Move Down"))
                                            .clicked()
                                            {
                                                move_down = true;
                                            }
                                            if vector_icon_button(
                                                ui,
                                                UiIcon::Duplicate,
                                                tr(self.language, "복제", "Duplicate"),
                                                30.0,
                                            )
                                            .clicked()
                                            {
                                                duplicate = true;
                                            }
                                            if vector_icon_button(
                                                ui,
                                                UiIcon::Close,
                                                tr(self.language, "삭제", "Delete"),
                                                30.0,
                                            )
                                            .on_hover_text(tr(self.language, "삭제", "Delete"))
                                            .clicked()
                                            {
                                                delete = true;
                                            }
                                        });
                                    }
                                    if toggle_visibility {
                                        if let Some(layer) = design.layers.get_mut(selected) {
                                            layer.visible = !layer.visible;
                                        }
                                    }
                                    if toggle_lock {
                                        if let Some(layer) = design.layers.get_mut(selected) {
                                            layer.locked = !layer.locked;
                                        }
                                    }
                                    if move_up && selected + 1 < design.layers.len() {
                                        design.layers.swap(selected, selected + 1);
                                        selected += 1;
                                    }
                                    if move_down && selected > 0 {
                                        design.layers.swap(selected, selected - 1);
                                        selected -= 1;
                                    }
                                    if duplicate {
                                        if let Some(layer) = design
                                            .layers
                                            .get(selected)
                                            .map(HeraldryLayer::duplicate)
                                        {
                                            design.layers.insert(selected + 1, layer);
                                            selected += 1;
                                        }
                                    }
                                    if layer_selected
                                        && let Some(layer) = design.layers.get_mut(selected)
                                    {
                                        ui.separator();
                                        ui.add_enabled_ui(!layer.locked, |ui| {
                                            let mut color = Color32::from_rgba_unmultiplied(
                                                layer.color[0],
                                                layer.color[1],
                                                layer.color[2],
                                                layer.color[3],
                                            );
                                            ui.horizontal(|ui| {
                                                ui.label(tr(self.language, "색상", "Color"));
                                                if ui.color_edit_button_srgba(&mut color).changed()
                                                {
                                                    layer.color = color.to_array();
                                                }
                                            });
                                            ui.label(
                                                RichText::new(tr(self.language, "크기", "Scale"))
                                                    .size(9.0)
                                                    .color(colors.muted),
                                            );
                                            ui.add(
                                                egui::Slider::new(&mut layer.scale, 10.0..=220.0)
                                                    .suffix("%"),
                                            );
                                            ui.label(
                                                RichText::new(tr(
                                                    self.language,
                                                    "불투명도",
                                                    "Opacity",
                                                ))
                                                .size(9.0)
                                                .color(colors.muted),
                                            );
                                            ui.add(
                                                egui::Slider::new(&mut layer.opacity, 0.0..=100.0)
                                                    .suffix("%"),
                                            );
                                            for (label, value) in [
                                                (tr(self.language, "X 위치", "X"), &mut layer.x),
                                                (tr(self.language, "Y 위치", "Y"), &mut layer.y),
                                            ] {
                                                ui.horizontal(|ui| {
                                                    ui.label(label);
                                                    ui.add(
                                                        egui::DragValue::new(value)
                                                            .range(-200.0..=200.0),
                                                    );
                                                });
                                            }
                                            ui.horizontal(|ui| {
                                                ui.label(tr(self.language, "각도", "Angle"));
                                                let angle = ui.add(
                                                    egui::DragValue::new(&mut layer.angle)
                                                        .range(-180.0..=180.0)
                                                        .speed(0.20)
                                                        .suffix("°"),
                                                );
                                                if self.heraldry_angle_snap
                                                    && (angle.drag_stopped() || angle.lost_focus())
                                                {
                                                    layer.angle =
                                                        (layer.angle / 15.0).round() * 15.0;
                                                }
                                            });
                                            ui.checkbox(
                                                &mut self.heraldry_angle_snap,
                                                tr(self.language, "15도 스냅", "15° Snap"),
                                            );
                                            ui.checkbox(
                                                &mut layer.flip_x,
                                                tr(self.language, "좌우 반전", "Flip Horizontal"),
                                            );
                                            ui.checkbox(
                                                &mut layer.flip_y,
                                                tr(self.language, "상하 반전", "Flip Vertical"),
                                            );
                                        });
                                    }
                                    if design.layers.is_empty() {
                                        ui.label(
                                            RichText::new(tr(
                                                self.language,
                                                "레이어가 없습니다.",
                                                "No layer selected.",
                                            ))
                                            .size(10.0)
                                            .color(colors.muted),
                                        );
                                    }
                                    if delete && !design.layers.is_empty() {
                                        design.layers.remove(selected);
                                        selected =
                                            selected.min(design.layers.len().saturating_sub(1));
                                        layer_selected = !design.layers.is_empty();
                                    }
                                });
                        },
                    );
                });
            });
        self.heraldry_selected_layer = selected;
        self.heraldry_selected_layer_id = design.layers.get(selected).map(|layer| layer.id.clone());
        self.heraldry_layer_selected = layer_selected;
        self.heraldry_browser_tab = browser_tab;
        self.heraldry_charge_category = charge_category;
        self.heraldry_add_mode = add_mode;
        if let Some(selected_id) = self.heraldry_selected_asset_id.as_deref()
            && let Some(asset) = self
                .world
                .heraldic_assets
                .iter_mut()
                .find(|asset| asset.id == selected_id && asset.is_emblem() == emblem)
        {
            asset.design = design.clone();
        }
        if emblem {
            self.emblem_design = design;
        } else {
            self.flag_design = design;
        }
    }

    fn new_world_dialog(&mut self, context: &egui::Context) {
        if !self.new_world_open {
            return;
        }
        if context.input(|input| input.key_pressed(egui::Key::Escape)) {
            if self.new_world_step == NewWorldStep::Planet {
                self.new_world_step = NewWorldStep::World;
            } else {
                self.new_world_open = false;
            }
            return;
        }
        let colors = self.colors();
        let screen = context.content_rect();
        let size = if self.new_world_step == NewWorldStep::World {
            Vec2::new(
                720.0_f32.min(screen.width() - 28.0),
                610.0_f32.min(screen.height() - 28.0),
            )
        } else {
            Vec2::new(
                1_280.0_f32.min(screen.width() - 24.0),
                760.0_f32.min(screen.height() - 24.0),
            )
        };
        let rect = Rect::from_center_size(screen.center(), size);
        let mut cancel = false;
        let mut previous = false;
        let mut next = false;
        let mut create = false;
        let mut planet_changed = false;
        egui::Area::new("new_world_modal_v39".into())
            .order(egui::Order::Foreground)
            .fixed_pos(screen.min)
            .show(context, |ui| {
                ui.set_min_size(screen.size());
                ui.painter().rect_filled(
                    Rect::from_min_size(Pos2::ZERO, screen.size()),
                    0.0,
                    Color32::from_rgba_premultiplied(3, 7, 13, 205),
                );
                ui.scope_builder(egui::UiBuilder::new().max_rect(rect), |ui| {
                    egui::Frame::new()
                        .fill(colors.panel_alt)
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(CornerRadius::same(8))
                        .inner_margin(Margin::same(20))
                        .show(ui, |ui| {
                            ui.set_min_size(size - Vec2::splat(40.0));
                            ui.horizontal(|ui| {
                                let title = match self.new_world_step {
                                    NewWorldStep::World => tr(
                                        self.language,
                                        "새 세계 생성",
                                        "Create a New World",
                                    ),
                                    NewWorldStep::Planet => tr(
                                        self.language,
                                        "행성 생성",
                                        "Generate Planet",
                                    ),
                                };
                                ui.label(
                                    RichText::new(title)
                                        .size(21.0)
                                        .strong()
                                        .color(colors.title),
                                );
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    if vector_icon_button(
                                        ui,
                                        UiIcon::Close,
                                        tr(self.language, "닫기", "Close"),
                                        34.0,
                                    )
                                    .clicked()
                                    {
                                        cancel = true;
                                    }
                                });
                            });
                            ui.add_space(12.0);
                            match self.new_world_step {
                                NewWorldStep::World => {
                                    ui.vertical_centered(|ui| {
                                        ui.set_max_width(650.0);
                                        theme::surface_frame(self.dark_mode).show(ui, |ui| {
                                            section_title(
                                                ui,
                                                tr(self.language, "세계 정보", "World"),
                                                colors,
                                            );
                                            ui.add_space(7.0);
                                            ui.label(
                                                RichText::new(tr(
                                                    self.language,
                                                    "세계 이름",
                                                    "World Name",
                                                ))
                                                .size(10.0)
                                                .color(colors.muted),
                                            );
                                            ui.add_sized(
                                                [ui.available_width(), 34.0],
                                                egui::TextEdit::singleline(
                                                    &mut self.new_world.title,
                                                ),
                                            );
                                            ui.add_space(8.0);
                                            ui.label(
                                                RichText::new(tr(
                                                    self.language,
                                                    "세계 설명",
                                                    "World Description",
                                                ))
                                                .size(10.0)
                                                .color(colors.muted),
                                            );
                                            ui.add_sized(
                                                [ui.available_width(), 96.0],
                                                egui::TextEdit::multiline(
                                                    &mut self.new_world.description,
                                                )
                                                .desired_rows(4),
                                            );
                                        });
                                        ui.add_space(10.0);
                                        ui.columns(2, |columns| {
                                            if columns[0]
                                                .add_sized(
                                                    [columns[0].available_width(), 44.0],
                                                    egui::Button::selectable(
                                                        self.new_world.rpg_enabled,
                                                        tr(
                                                            self.language,
                                                            "고유 수치 규칙 사용",
                                                            "Use Attribute Rules",
                                                        ),
                                                    ),
                                                )
                                                .clicked()
                                            {
                                                self.new_world.rpg_enabled =
                                                    !self.new_world.rpg_enabled;
                                                if !self.new_world.rpg_enabled {
                                                    self.new_world.magic_enabled = false;
                                                }
                                            }
                                            columns[1].add_enabled_ui(
                                                self.new_world.rpg_enabled,
                                                |ui| {
                                                    if ui
                                                        .add_sized(
                                                            [ui.available_width(), 44.0],
                                                            egui::Button::selectable(
                                                                self.new_world.magic_enabled,
                                                                tr(
                                                                    self.language,
                                                                    "마법력 존재",
                                                                    "Magic Exists",
                                                                ),
                                                            ),
                                                        )
                                                        .clicked()
                                                    {
                                                        self.new_world.magic_enabled =
                                                            !self.new_world.magic_enabled;
                                                    }
                                                },
                                            );
                                        });
                                        ui.add_space(18.0);
                                        ui.with_layout(
                                            Layout::right_to_left(Align::Center),
                                            |ui| {
                                                next = ui
                                                    .add_enabled(
                                                        !self.new_world.title.trim().is_empty(),
                                                        egui::Button::new(tr(
                                                            self.language,
                                                            "다음: 행성 생성",
                                                            "Next: Generate Planet",
                                                        ))
                                                        .min_size(Vec2::new(156.0, 38.0)),
                                                    )
                                                    .clicked();
                                            },
                                        );
                                    });
                                }
                                NewWorldStep::Planet => {
                                    let content_height = (ui.available_height() - 52.0).max(360.0);
                                    ui.horizontal(|ui| {
                                        ui.allocate_ui_with_layout(
                                            Vec2::new(355.0, content_height),
                                            Layout::top_down(Align::Min),
                                            |ui| {
                                                egui::ScrollArea::vertical()
                                                    .id_salt("planet_generation_controls_v39")
                                                    .scroll_bar_visibility(
                                                        egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded,
                                                    )
                                                    .show(ui, |ui| {
                                                        planet_changed |= planet_generation_controls(
                                                            ui,
                                                            self.language,
                                                            self.dark_mode,
                                                            &mut self.new_world.planet,
                                                        );
                                                    });
                                            },
                                        );
                                        ui.separator();
                                        ui.allocate_ui_with_layout(
                                            Vec2::new(ui.available_width(), content_height),
                                            Layout::top_down(Align::Center),
                                            |ui| {
                                                let canvas = ui.available_rect_before_wrap();
                                                let response = ui.allocate_rect(
                                                    canvas,
                                                    Sense::click_and_drag(),
                                                );
                                                ui.painter().rect_filled(
                                                    canvas,
                                                    4.0,
                                                    colors.map_background,
                                                );
                                                if response.dragged() {
                                                    let delta = ui.input(|input| input.pointer.delta());
                                                    self.planet_globe_yaw -= delta.x * 0.006;
                                                    self.planet_globe_pitch =
                                                        (self.planet_globe_pitch + delta.y * 0.006)
                                                            .clamp(-1.35, 1.35);
                                                }
                                                if response.hovered() {
                                                    let scroll = ui.input(|input| {
                                                        input.smooth_scroll_delta.y
                                                    });
                                                    if scroll != 0.0 {
                                                        self.planet_globe_zoom =
                                                            (self.planet_globe_zoom
                                                                * (scroll * 0.0025).exp())
                                                                .clamp(0.65, 2.75);
                                                    }
                                                }
                                                if let Some(planet) = &self.planet_preview {
                                                    paint_planet_surface_globe(
                                                        ui.painter(),
                                                        canvas,
                                                        &planet.surface,
                                                        planet.physical.radius_m,
                                                        self.planet_globe_yaw,
                                                        self.planet_globe_pitch,
                                                        self.planet_globe_zoom,
                                                        &[],
                                                        None,
                                                        colors,
                                                    );
                                                    paint_planet_rotation_axis(
                                                        ui.painter(),
                                                        canvas,
                                                        self.planet_globe_yaw,
                                                        self.planet_globe_pitch,
                                                        self.planet_globe_zoom,
                                                        PlanetReferenceFrame::from_physical(
                                                            &planet.physical,
                                                        ),
                                                        colors,
                                                    );
                                                } else {
                                                    ui.painter().text(
                                                        canvas.center(),
                                                        Align2::CENTER_CENTER,
                                                        tr(
                                                            self.language,
                                                            "행성 표면 생성 중",
                                                            "Generating planetary surface",
                                                        ),
                                                        FontId::proportional(15.0),
                                                        colors.muted,
                                                    );
                                                }
                                            },
                                        );
                                    });
                                    ui.add_space(9.0);
                                    ui.horizontal(|ui| {
                                        previous = ui
                                            .add_sized(
                                                [92.0, 38.0],
                                                egui::Button::new(tr(
                                                    self.language,
                                                    "이전",
                                                    "Back",
                                                )),
                                            )
                                            .clicked();
                                        ui.with_layout(
                                            Layout::right_to_left(Align::Center),
                                            |ui| {
                                                let preview_current = self.planet_preview.is_some()
                                                    && self.planet_preview_job.is_none()
                                                    && serde_json::to_string(
                                                        &self.new_world.planet,
                                                    )
                                                    .is_ok_and(|key| {
                                                        key == self.planet_preview_key
                                                    });
                                                create = ui
                                                    .add_enabled(
                                                        preview_current,
                                                        egui::Button::new(tr(
                                                            self.language,
                                                            "행성 확정",
                                                            "Finish Planet",
                                                        ))
                                                        .min_size(Vec2::new(126.0, 38.0)),
                                                    )
                                                    .clicked();
                                            },
                                        );
                                    });
                                }
                            }
                        });
                });
            });
        if planet_changed {
            self.schedule_planet_preview(false);
        }
        if cancel {
            self.new_world_open = false;
            self.planet_preview_job = None;
        } else if previous {
            self.new_world_step = NewWorldStep::World;
        } else if next {
            self.new_world_step = NewWorldStep::Planet;
            self.schedule_planet_preview(true);
        } else if create {
            self.create_world_from_draft();
        }
    }

