fn calendar_profile_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    profile: &mut CalendarProfile,
    references: &[UReferenceOption],
    display_calendar: &CalendarProfile,
    orbital_period_days: f64,
    calendar_options: &[(String, CalendarProfile)],
) {
    let colors = theme::palette(dark);
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(
            ui,
            tr(language, "역법 정보", "Calendar Information"),
            colors,
        );
        ui.separator();
        editable_text_row(
            ui,
            tr(language, "역법명", "Calendar"),
            &mut profile.calendar_name,
        );
        let mut metadata = serde_json::Map::new();
        if let Some(id) = &profile.creator_article_id {
            metadata.insert(
                "creatorArticleId".to_owned(),
                serde_json::Value::String(id.clone()),
            );
        } else if !profile.creator.trim().is_empty() && profile.creator != "-" {
            metadata.insert(
                "creator".to_owned(),
                serde_json::Value::String(profile.creator.clone()),
            );
        }
        u_fields::u_input_single(
            ui,
            language,
            "calendar-creator",
            tr(language, "제작자", "Creator"),
            &mut metadata,
            "creatorArticleId",
            Some("creator"),
            references,
            &["person", "organization", "country"],
        );
        profile.creator_article_id = metadata
            .get("creatorArticleId")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        profile.creator = profile
            .creator_article_id
            .as_deref()
            .and_then(|id| references.iter().find(|option| option.id == id))
            .map(|option| option.title.clone())
            .or_else(|| {
                metadata
                    .get("creator")
                    .and_then(serde_json::Value::as_str)
                    .map(str::to_owned)
            })
            .unwrap_or_default();

        if let Some(year) = profile.created_at_year {
            metadata.insert("createdAt".to_owned(), serde_json::json!(year));
            metadata.insert(
                "createdAtAbsoluteDay".to_owned(),
                serde_json::json!(profile.created_at_absolute_day.unwrap_or_else(|| {
                    calendar::absolute_day(TimelineMoment::new(year, 0.0), orbital_period_days)
                })),
            );
        }
        u_fields::u_date_json(
            ui,
            language,
            "calendar-created-at",
            tr(language, "제정 연도", "Enactment Date"),
            &mut metadata,
            "createdAt",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        profile.created_at_year = metadata
            .get("createdAt")
            .and_then(serde_json::Value::as_i64)
            .map(|year| year as i32);
        profile.created_at_absolute_day = metadata
            .get("createdAtAbsoluteDay")
            .and_then(serde_json::Value::as_f64);

        metadata.insert(
            "epoch".to_owned(),
            serde_json::json!(profile.epoch_world_year),
        );
        metadata.insert(
            "epochAbsoluteDay".to_owned(),
            serde_json::json!(profile.epoch_absolute_day.unwrap_or_else(
                || calendar::absolute_day(
                    TimelineMoment::new(profile.epoch_world_year, 0.0),
                    orbital_period_days
                )
            )),
        );
        u_fields::u_date_json(
            ui,
            language,
            "calendar-epoch",
            tr(language, "기준 연도", "Epoch Date"),
            &mut metadata,
            "epoch",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        if let Some(day) = metadata
            .get("epochAbsoluteDay")
            .and_then(serde_json::Value::as_f64)
        {
            let moment = calendar::timeline_moment_from_absolute_day(day, orbital_period_days);
            profile.epoch_world_year = moment.world_year;
            profile.epoch_absolute_day = Some(day);
        }
        ui.horizontal(|ui| {
            ui.label(
                RichText::new(tr(language, "연도 표기법", "Year Notation"))
                    .size(10.0)
                    .color(colors.muted),
            );
            egui::ComboBox::from_id_salt("calendar-display-mode")
                .selected_text(if profile.display_mode == "era" {
                    tr(language, "연호", "Era")
                } else {
                    tr(language, "숫자", "Number")
                })
                .show_ui(ui, |ui| {
                    ui.selectable_value(
                        &mut profile.display_mode,
                        "era".to_owned(),
                        tr(language, "연호", "Era"),
                    );
                    ui.selectable_value(
                        &mut profile.display_mode,
                        "number".to_owned(),
                        tr(language, "숫자", "Number"),
                    );
                });
        });
        if profile.display_mode == "era" {
            editable_text_row(
                ui,
                tr(language, "기준 이전 연호", "Before-Epoch Era"),
                &mut profile.before_era_name,
            );
            editable_text_row(
                ui,
                tr(language, "이전 약칭", "Before Abbreviation"),
                &mut profile.before_era_short_name,
            );
            editable_text_row(
                ui,
                tr(language, "기준 이후 연호", "After-Epoch Era"),
                &mut profile.after_era_name,
            );
            editable_text_row(
                ui,
                tr(language, "이후 약칭", "After Abbreviation"),
                &mut profile.after_era_short_name,
            );
        }
    });
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(
            ui,
            tr(language, "역법 작동법", "Calendar Operation"),
            colors,
        );
        ui.separator();
        calendar_units_editor(
            ui,
            language,
            colors,
            tr(language, "날짜법", "Date Units"),
            &mut profile.date_units,
            true,
        );
        ui.separator();
        calendar_units_editor(
            ui,
            language,
            colors,
            tr(language, "시간법", "Time Units"),
            &mut profile.time_units,
            false,
        );
    });
}

