fn calendar_units_editor(
    ui: &mut egui::Ui,
    language: Language,
    colors: theme::Palette,
    title: &str,
    units: &mut Vec<CalendarUnit>,
    date_units: bool,
) {
    let mut move_action: Option<(usize, isize)> = None;
    let mut remove_index = None;
    ui.horizontal(|ui| {
        ui.label(RichText::new(title).size(10.5).strong().color(colors.muted));
        ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
            if ui
                .add_sized([28.0, 25.0], egui::Button::new("＋"))
                .clicked()
            {
                let serial = units.len() + 1;
                units.push(CalendarUnit {
                    id: format!("{}-{serial}", if date_units { "date" } else { "time" }),
                    name: tr(language, "새 단위", "New Unit").to_owned(),
                    short_name: tr(language, "단위", "unit").to_owned(),
                    units_per_parent: if date_units && units.is_empty() {
                        1
                    } else {
                        10
                    },
                });
            }
        });
    });
    for index in 0..units.len() {
        ui.horizontal(|ui| {
            ui.label(
                RichText::new(format!("{}", index + 1))
                    .size(9.0)
                    .color(colors.muted),
            );
            ui.add_sized(
                [82.0, 25.0],
                egui::TextEdit::singleline(&mut units[index].name),
            );
            ui.add_sized(
                [58.0, 25.0],
                egui::TextEdit::singleline(&mut units[index].short_name),
            );
            if date_units && index == 0 {
                units[index].units_per_parent = 1;
                ui.label(RichText::new("1").size(10.0).color(colors.muted));
            } else {
                ui.add(
                    egui::DragValue::new(&mut units[index].units_per_parent)
                        .range(1..=100_000)
                        .prefix("1:")
                        .speed(1),
                );
            }
            if index > 0 && ui.small_button("↑").clicked() {
                move_action = Some((index, -1));
            }
            if index + 1 < units.len() && ui.small_button("↓").clicked() {
                move_action = Some((index, 1));
            }
            let minimum = if date_units { 1 } else { 1 };
            if units.len() > minimum && ui.small_button("×").clicked() {
                remove_index = Some(index);
            }
        });
    }
    if let Some((index, direction)) = move_action {
        let target =
            (index as isize + direction).clamp(0, units.len().saturating_sub(1) as isize) as usize;
        units.swap(index, target);
    }
    if let Some(index) = remove_index {
        units.remove(index);
    }
    if units.is_empty() {
        units.push(CalendarUnit {
            id: if date_units { "year" } else { "hour" }.to_owned(),
            name: tr(
                language,
                if date_units { "년" } else { "시" },
                if date_units { "Year" } else { "Hour" },
            )
            .to_owned(),
            short_name: tr(
                language,
                if date_units { "년" } else { "시" },
                if date_units { "yr" } else { "h" },
            )
            .to_owned(),
            units_per_parent: if date_units { 1 } else { 24 },
        });
    }
}

