fn rpg_definition_edit_row(
    ui: &mut egui::Ui,
    definition: &mut RpgRuleDefinition,
    index: usize,
    count: usize,
    language: Language,
    colors: theme::Palette,
) -> Option<i32> {
    let mut action = None;
    ui.horizontal(|ui| {
        let available = ui.available_width();
        let field_width = ((available - 196.0) * 0.5).clamp(82.0, 240.0);
        ui.add_sized(
            [field_width, 30.0],
            egui::TextEdit::singleline(&mut definition.korean).id_salt((&definition.id, "ko")),
        );
        ui.add_sized(
            [field_width, 30.0],
            egui::TextEdit::singleline(&mut definition.english).id_salt((&definition.id, "en")),
        );
        egui::ComboBox::from_id_salt((&definition.id, "type"))
            .selected_text(rpg_value_kind_label(language, definition.value_kind))
            .width(78.0)
            .show_ui(ui, |ui| {
                ui.selectable_value(
                    &mut definition.value_kind,
                    RpgValueKind::Integer,
                    tr(language, "정수", "Integer"),
                );
                ui.selectable_value(
                    &mut definition.value_kind,
                    RpgValueKind::Percent,
                    tr(language, "백분율", "Percent"),
                );
                ui.selectable_value(
                    &mut definition.value_kind,
                    RpgValueKind::Text,
                    tr(language, "텍스트", "Text"),
                );
            });
        if ui
            .add_enabled(index > 0, egui::Button::new("↑"))
            .on_hover_text(tr(language, "위로", "Move up"))
            .clicked()
        {
            action = Some(-1);
        }
        if ui
            .add_enabled(index + 1 < count, egui::Button::new("↓"))
            .on_hover_text(tr(language, "아래로", "Move down"))
            .clicked()
        {
            action = Some(1);
        }
        if ui
            .add_sized(
                [30.0, 30.0],
                egui::Button::new(RichText::new("×").color(colors.danger)),
            )
            .on_hover_text(tr(language, "삭제", "Delete"))
            .clicked()
        {
            action = Some(0);
        }
    });
    action
}

fn rpg_value_kind_label(language: Language, value_kind: RpgValueKind) -> &'static str {
    match value_kind {
        RpgValueKind::Integer => tr(language, "정수", "Integer"),
        RpgValueKind::Percent => tr(language, "백분율", "Percent"),
        RpgValueKind::Text => tr(language, "텍스트", "Text"),
    }
}

fn json_contains_string(value: &serde_json::Value, needle: &str) -> bool {
    match value {
        serde_json::Value::String(value) => value == needle,
        serde_json::Value::Array(values) => values
            .iter()
            .any(|value| json_contains_string(value, needle)),
        serde_json::Value::Object(values) => values
            .values()
            .any(|value| json_contains_string(value, needle)),
        _ => false,
    }
}

fn rpg_definition_is_used(world: &LoadedWorld, definition_id: &str) -> bool {
    world.articles.iter().any(|article| {
        serde_json::to_value(&article.profiles)
            .is_ok_and(|value| json_contains_string(&value, definition_id))
    })
}

