fn structured_information_panel(
    ui: &mut egui::Ui,
    dark: bool,
    title: &str,
    fields: Vec<(String, String)>,
    language: Language,
    articles: &[Article],
) -> Option<String> {
    let colors = theme::palette(dark);
    let mut open_link = None;
    egui::Frame::new()
        .fill(colors.surface_soft)
        .stroke(Stroke::new(1.0, colors.border))
        .corner_radius(CornerRadius::same(6))
        .inner_margin(Margin::same(7))
        .show(ui, |ui| {
            ui.spacing_mut().item_spacing.y = 3.0;
            section_title(ui, title, colors);
            ui.separator();
            for (index, (label, value)) in fields.into_iter().enumerate() {
                if index > 0 {
                    ui.separator();
                }
                if value.contains("[[") {
                    ui.horizontal(|ui| {
                        ui.add_sized(
                            [76.0, 26.0],
                            egui::Label::new(
                                RichText::new(&label)
                                    .size(scaled_text_size(ui, 10.0))
                                    .color(colors.muted),
                            )
                            .halign(Align::Center),
                        );
                        ui.allocate_ui_with_layout(
                            egui::vec2(ui.available_width(), 26.0),
                            Layout::left_to_right(Align::Center).with_main_align(Align::Center),
                            |ui| {
                                ui.spacing_mut().item_spacing.x = 0.0;
                                if let Some(target_id) = linked_document_text(
                                    ui, &value, language, colors, articles, 10.5, true, true,
                                ) {
                                    open_link = Some(target_id);
                                }
                            },
                        );
                    });
                } else {
                    info_row(ui, &label, value, false);
                }
            }
        });
    open_link
}

