fn heraldry_document_tile(
    ui: &mut egui::Ui,
    label: &str,
    asset: Option<&HeraldicAsset>,
    interactive: bool,
    colors: theme::Palette,
) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(
        Vec2::new(ui.available_width(), 104.0),
        if interactive {
            Sense::click()
        } else {
            Sense::hover()
        },
    );
    let fill = if response.hovered() && interactive {
        colors.hover
    } else {
        colors.surface_soft
    };
    ui.painter().rect(
        rect,
        CornerRadius::same(5),
        fill,
        Stroke::new(1.0, colors.border),
        egui::StrokeKind::Inside,
    );
    ui.painter().text(
        Pos2::new(rect.center().x, rect.top() + 13.0),
        Align2::CENTER_CENTER,
        label,
        FontId::proportional(9.5),
        colors.muted,
    );
    let preview_rect = Rect::from_min_max(
        Pos2::new(rect.left() + 8.0, rect.top() + 25.0),
        Pos2::new(rect.right() - 8.0, rect.bottom() - 19.0),
    );
    if let Some(asset) = asset {
        let content = heraldry_content_rect(preview_rect.shrink(2.0), asset.design.shape);
        paint_heraldry_composition(
            ui.painter(),
            content,
            asset.design.shape,
            &asset.design.layers,
            colors.panel_alt,
            fill,
            colors.border,
        );
        ui.painter().text(
            Pos2::new(rect.center().x, rect.bottom() - 9.5),
            Align2::CENTER_CENTER,
            &asset.name,
            FontId::proportional(8.5),
            colors.text,
        );
    } else {
        ui.painter().text(
            preview_rect.center(),
            Align2::CENTER_CENTER,
            "-",
            FontId::proportional(15.0),
            colors.muted,
        );
    }
    response
}

