fn generator_f64_slider(
    ui: &mut egui::Ui,
    value: &mut f64,
    range: std::ops::RangeInclusive<f64>,
    speed: f64,
    suffix: &str,
    label: &str,
    dirty: &mut Option<Instant>,
) {
    let mut changed = false;
    ui.horizontal(|ui| {
        ui.add_sized(
            [116.0, 28.0],
            egui::Label::new(RichText::new(label).size(9.3)).halign(Align::LEFT),
        );
        let slider = ui.add(
            egui::Slider::new(value, range.clone())
                .show_value(false)
                .trailing_fill(true),
        );
        changed |= slider.drag_stopped() || (slider.changed() && !slider.dragged());
        changed |= ui
            .add(
                egui::DragValue::new(value)
                    .range(range)
                    .speed(speed)
                    .suffix(suffix),
            )
            .changed();
    });
    if changed {
        *dirty = Some(Instant::now());
    }
}

fn generator_aspect_ratio_slider(
    ui: &mut egui::Ui,
    value: &mut f64,
    label: &str,
    dirty: &mut Option<Instant>,
) {
    *value = value.clamp(0.25, 4.0);
    let mut changed = false;
    ui.horizontal(|ui| {
        ui.add_sized(
            [116.0, 28.0],
            egui::Label::new(RichText::new(label).size(9.3)).halign(Align::LEFT),
        );
        let slider = ui.add(
            egui::Slider::new(value, 0.25..=4.0)
                .logarithmic(true)
                .show_value(false)
                .trailing_fill(true),
        );
        changed |= slider.drag_stopped() || (slider.changed() && !slider.dragged());
        changed |= ui
            .add(
                egui::DragValue::new(value)
                    .range(0.25..=4.0)
                    .speed(0.01)
                    .custom_formatter(|value, _| format_aspect_ratio(value))
                    .custom_parser(parse_aspect_ratio),
            )
            .changed();
    });
    if changed {
        *value = value.clamp(0.25, 4.0);
        *dirty = Some(Instant::now());
    }
}

fn format_aspect_ratio(value: f64) -> String {
    let value = value.clamp(0.25, 4.0);
    let component = if value >= 1.0 { value } else { value.recip() };
    let formatted = if (component - component.round()).abs() < 0.000_1 {
        format!("{:.0}", component)
    } else {
        format!("{component:.2}")
            .trim_end_matches('0')
            .trim_end_matches('.')
            .to_owned()
    };
    if value >= 1.0 {
        format!("{formatted}:1")
    } else {
        format!("1:{formatted}")
    }
}

fn parse_aspect_ratio(text: &str) -> Option<f64> {
    let text = text.trim();
    if let Some((left, right)) = text.split_once(':') {
        let left = left.trim().replace(',', ".").parse::<f64>().ok()?;
        let right = right.trim().replace(',', ".").parse::<f64>().ok()?;
        (right > 0.0).then_some((left / right).clamp(0.25, 4.0))
    } else {
        text.replace(',', ".")
            .parse::<f64>()
            .ok()
            .map(|value| value.clamp(0.25, 4.0))
    }
}

