#[cfg(any())]
fn coast_controls(
    ui: &mut egui::Ui,
    language: Language,
    edges: &mut [u8; 4],
    transitions: &mut [f32; 4],
    dirty: &mut Option<Instant>,
) {
    let colors = theme::palette(ui.visuals().dark_mode);
    let width = ui.available_width().min(300.0);
    let (rect, _) = ui.allocate_exact_size(Vec2::new(width, 210.0), Sense::hover());
    let center = Rect::from_min_max(
        Pos2::new(rect.left() + 62.0, rect.top() + 45.0),
        Pos2::new(rect.right() - 62.0, rect.bottom() - 45.0),
    );
    ui.painter().rect(
        center,
        CornerRadius::same(7),
        colors.surface,
        Stroke::new(1.0, colors.border),
        egui::StrokeKind::Inside,
    );
    let island = vec![
        Pos2::new(center.left() + center.width() * 0.15, center.center().y),
        Pos2::new(
            center.left() + center.width() * 0.33,
            center.top() + center.height() * 0.2,
        ),
        Pos2::new(
            center.left() + center.width() * 0.65,
            center.top() + center.height() * 0.12,
        ),
        Pos2::new(center.right() - center.width() * 0.08, center.center().y),
        Pos2::new(
            center.left() + center.width() * 0.65,
            center.bottom() - center.height() * 0.13,
        ),
        Pos2::new(
            center.left() + center.width() * 0.31,
            center.bottom() - center.height() * 0.22,
        ),
    ];
    ui.painter().add(egui::Shape::convex_polygon(
        island,
        Color32::from_rgb(82, 126, 74),
        Stroke::new(1.0, Color32::from_rgb(112, 159, 102)),
    ));
    ui.painter().text(
        center.center(),
        Align2::CENTER_CENTER,
        tr(language, "지역 지도", "Regional Map"),
        FontId::proportional(10.0),
        colors.muted,
    );

    let button_size = Vec2::new(86.0, 38.0);
    let button_rects = [
        Rect::from_center_size(Pos2::new(rect.center().x, rect.top() + 19.0), button_size),
        Rect::from_center_size(Pos2::new(rect.right() - 43.0, rect.center().y), button_size),
        Rect::from_center_size(
            Pos2::new(rect.center().x, rect.bottom() - 19.0),
            button_size,
        ),
        Rect::from_center_size(Pos2::new(rect.left() + 43.0, rect.center().y), button_size),
    ];
    let direction_labels = [
        tr(language, "북", "N"),
        tr(language, "동", "E"),
        tr(language, "남", "S"),
        tr(language, "서", "W"),
    ];
    for index in 0..4 {
        let label = format!(
            "{}  {}",
            direction_labels[index],
            coast_name(language, edges[index])
        );
        if ui
            .put(
                button_rects[index],
                egui::Button::new(RichText::new(label).size(10.0))
                    .fill(match edges[index] {
                        2 => Color32::from_rgb(18, 52, 74),
                        1 | 3 => Color32::from_rgb(32, 59, 53),
                        _ => colors.surface,
                    })
                    .stroke(Stroke::new(
                        1.0,
                        if edges[index] == 2 {
                            Color32::from_rgb(60, 135, 174)
                        } else if edges[index] == 1 || edges[index] == 3 {
                            Color32::from_rgb(111, 159, 117)
                        } else {
                            colors.border
                        },
                    )),
            )
            .clicked()
        {
            edges[index] = (edges[index] + 1) % 4;
            *dirty = Some(Instant::now());
        }
    }

    for (index, state) in edges.iter().copied().enumerate() {
        if state == 1 || state == 3 {
            ui.horizontal(|ui| {
                ui.label(
                    RichText::new(format!(
                        "{} · {}",
                        direction_labels[index],
                        coast_name(language, state),
                    ))
                    .size(9.0)
                    .color(colors.muted),
                );
                if ui
                    .add(
                        egui::DragValue::new(&mut transitions[index])
                            .range(0.0..=100.0)
                            .suffix("%"),
                    )
                    .changed()
                {
                    *dirty = Some(Instant::now());
                }
            });
        }
    }
}

