fn info_row(ui: &mut egui::Ui, label: &str, value: String, editing: bool) {
    ui.horizontal(|ui| {
        ui.add_sized(
            [76.0, 26.0],
            egui::Label::new(
                RichText::new(label)
                    .size(scaled_text_size(ui, 10.0))
                    .color(ui.visuals().weak_text_color()),
            )
            .halign(Align::Center),
        );
        if editing {
            let mut editable = value;
            ui.add_sized(
                [ui.available_width(), 26.0],
                egui::TextEdit::singleline(&mut editable),
            );
        } else {
            ui.add_sized(
                [ui.available_width(), 26.0],
                egui::Label::new(
                    RichText::new(if value.is_empty() {
                        "-".to_owned()
                    } else {
                        value
                    })
                    .size(scaled_text_size(ui, 10.5)),
                )
                .halign(Align::Center),
            );
        }
    });
}

fn information_title<'a>(language: Language, category: &str) -> &'a str {
    if contains_any(category, &["인물", "Person", "person"]) {
        tr(language, "인물 정보", "Person Information")
    } else if contains_any(
        category,
        &[
            "물건",
            "무기",
            "방어구",
            "Item",
            "Weapon",
            "Armor",
            "item",
            "weapon",
            "armor",
            "accessory",
        ],
    ) {
        tr(language, "물건 정보", "Item Information")
    } else if contains_any(category, &["전투", "Battle", "battle"]) {
        tr(language, "전투 정보", "Battle Information")
    } else if contains_any(category, &["전쟁", "War", "war"]) {
        tr(language, "전쟁 정보", "War Information")
    } else if contains_any(
        category,
        &["사건", "사고", "Event", "Incident", "event", "accident"],
    ) {
        tr(language, "사건 정보", "Event Information")
    } else {
        tr(language, "정보", "Information")
    }
}

