fn reference_or_text_list_editor(
    ui: &mut egui::Ui,
    language: Language,
    profile: &mut serde_json::Map<String, serde_json::Value>,
    reference_key: &str,
    custom_key: &str,
    label: &str,
    references: &[UReferenceOption],
    categories: &[&str],
) {
    u_fields::u_input_multi(
        ui,
        language,
        ("reference-or-text-list", reference_key),
        label,
        profile,
        reference_key,
        custom_key,
        references,
        categories,
    );
    let values_key = format!("{custom_key}Values");
    if let Some(values) = profile.get(&values_key).cloned() {
        profile.insert(custom_key.to_owned(), values);
    }
}

