fn country_capital_periods_editor(
    ui: &mut egui::Ui,
    language: Language,
    colors: theme::Palette,
    country: &mut serde_json::Map<String, serde_json::Value>,
    references: &[UReferenceOption],
    display_calendar: &CalendarProfile,
    orbital_period_days: f64,
    calendar_options: &[(String, CalendarProfile)],
) {
    let mut periods = country
        .get("capitalPeriods")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_else(|| {
            country
                .get("capitalLocationId")
                .and_then(serde_json::Value::as_str)
                .filter(|id| !id.is_empty())
                .map(|id| vec![serde_json::json!({ "id": "legacy-capital", "locationId": id })])
                .unwrap_or_default()
        });
    ui.separator();
    egui::CollapsingHeader::new(tr(language, "수도 연혁", "Capital History"))
        .default_open(false)
        .show(ui, |ui| {
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui
                    .button(tr(language, "+ 수도 기록", "+ Capital Record"))
                    .clicked()
                {
                    let mut serial = periods.len() + 1;
                    let mut id = format!("capital-period-{serial}");
                    while periods.iter().any(|entry| {
                        entry.get("id").and_then(serde_json::Value::as_str) == Some(id.as_str())
                    }) {
                        serial += 1;
                        id = format!("capital-period-{serial}");
                    }
                    periods.push(serde_json::json!({ "id": id }));
                }
            });
            let mut remove = None;
            for (index, entry) in periods.iter_mut().enumerate() {
                if !entry.is_object() {
                    *entry = serde_json::json!({ "id": format!("capital-period-{}", index + 1) });
                }
                let object = entry.as_object_mut().expect("capital period object");
                let record_id = object
                    .get("id")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("capital-period")
                    .to_owned();
                ui.push_id(("country-capital", &record_id), |ui| {
                    egui::Frame::new()
                        .fill(colors.surface_soft)
                        .stroke(Stroke::new(1.0, colors.border))
                        .corner_radius(4.0)
                        .inner_margin(7.0)
                        .show(ui, |ui| {
                            ui.horizontal(|ui| {
                                ui.label(
                                    RichText::new(format!(
                                        "{} {}",
                                        tr(language, "수도", "Capital"),
                                        index + 1
                                    ))
                                    .size(9.5),
                                );
                                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                    if ui
                                        .small_button("×")
                                        .on_hover_text(tr(
                                            language,
                                            "수도 기록 삭제",
                                            "Delete capital record",
                                        ))
                                        .clicked()
                                    {
                                        remove = Some(index);
                                    }
                                });
                            });
                            language_reference_editor(
                                ui,
                                language,
                                object,
                                "locationId",
                                tr(language, "장소", "Place"),
                                references,
                                &["city", "village", "fortress", "base", "location"],
                            );
                            editable_json_text(
                                ui,
                                tr(language, "직접 입력 명칭", "Custom Name"),
                                object,
                                "customName",
                            );
                            ui.columns(2, |columns| {
                                calendar_date_popup_editor(
                                    &mut columns[0],
                                    language,
                                    tr(language, "시작", "Start"),
                                    object,
                                    "startYear",
                                    display_calendar,
                                    orbital_period_days,
                                    calendar_options,
                                );
                                calendar_date_popup_editor(
                                    &mut columns[1],
                                    language,
                                    tr(language, "종료", "End"),
                                    object,
                                    "endYear",
                                    display_calendar,
                                    orbital_period_days,
                                    calendar_options,
                                );
                            });
                        });
                });
            }
            if let Some(index) = remove {
                periods.remove(index);
            }
        });
    country.insert(
        "capitalPeriods".to_owned(),
        serde_json::Value::Array(periods),
    );
}

fn country_transition_panel(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    colors: theme::Palette,
    article: &Article,
    world: &LoadedWorld,
) -> Option<String> {
    let country = article
        .profiles
        .faction
        .as_ref()
        .and_then(|profile| profile.get("countryProfile"));
    let predecessors =
        json_string_ids(country.and_then(|value| value.get("predecessorArticleIds")));
    let successors = json_string_ids(country.and_then(|value| value.get("successorArticleIds")));
    let predecessor_custom =
        json_string_ids(country.and_then(|value| value.get("predecessorCustomNames")));
    let successor_custom =
        json_string_ids(country.and_then(|value| value.get("successorCustomNames")));
    let mut open_link = None;
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(
            ui,
            tr(language, "성립 전후", "Predecessors and Successors"),
            colors,
        );
        ui.columns(2, |columns| {
            columns[0].label(
                RichText::new(tr(language, "성립 이전", "Predecessors"))
                    .size(9.0)
                    .color(colors.muted),
            );
            if predecessors.is_empty() && predecessor_custom.is_empty() {
                columns[0].label("-");
            }
            for id in &predecessors {
                let title = resolve_article_title(world, id);
                if country_transition_target(&mut columns[0], world, id, title, colors) {
                    open_link = Some(id.clone());
                }
            }
            for name in &predecessor_custom {
                columns[0].label(name);
            }
            columns[1].label(
                RichText::new(tr(language, "멸망 이후", "Successors"))
                    .size(9.0)
                    .color(colors.muted),
            );
            if successors.is_empty() && successor_custom.is_empty() {
                columns[1].label("-");
            }
            for id in &successors {
                let title = resolve_article_title(world, id);
                if country_transition_target(&mut columns[1], world, id, title, colors) {
                    open_link = Some(id.clone());
                }
            }
            for name in &successor_custom {
                columns[1].label(name);
            }
        });
    });
    open_link
}

fn country_transition_target(
    ui: &mut egui::Ui,
    world: &LoadedWorld,
    article_id: &str,
    title: &str,
    colors: theme::Palette,
) -> bool {
    ui.horizontal_centered(|ui| {
        if let Some(asset) = participant_flag_asset(world, article_id) {
            let (rect, _) = ui.allocate_exact_size(Vec2::new(20.0, 14.0), Sense::hover());
            let content = heraldry_content_rect(rect, asset.design.shape);
            paint_heraldry_composition(
                ui.painter(),
                content,
                asset.design.shape,
                &asset.design.layers,
                colors.panel_alt,
                colors.surface,
                colors.border,
            );
        }
        ui.link(title).clicked()
    })
    .inner
}

fn genealogy_reference_options<'a>(
    references: &'a [UReferenceOption],
    family: bool,
) -> Vec<&'a UReferenceOption> {
    references
        .iter()
        .filter(|option| {
            if family {
                contains_any(&option.category, &["가문", "Family", "House", "family"])
            } else {
                contains_any(&option.category, &["인물", "Person", "person"])
            }
        })
        .collect()
}

fn person_genealogy_profile_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    article_id: &str,
    article_title: &str,
    world: &LoadedWorld,
    profile: &mut Option<serde_json::Value>,
    references: &[UReferenceOption],
    display_calendar: &CalendarProfile,
    orbital_period_days: f64,
    calendar_options: &[(String, CalendarProfile)],
) {
    let colors = theme::palette(dark);
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(
            ui,
            tr(language, "인물 정보 편집", "Edit Person Information"),
            colors,
        );
        let profile = json_object_mut(profile);
        calendar_date_popup_editor(
            ui,
            language,
            tr(language, "출생 연도", "Birth Date"),
            profile,
            "birthYear",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        calendar_date_popup_editor(
            ui,
            language,
            tr(language, "사망 연도", "Death Date"),
            profile,
            "deathYear",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        language_multi_reference_editor(
            ui,
            language,
            profile,
            "nationalityArticleIds",
            tr(language, "국적", "Nationalities"),
            references,
            &["country"],
        );
        language_multi_reference_editor(
            ui,
            language,
            profile,
            "affiliationArticleIds",
            tr(language, "소속", "Affiliations"),
            references,
            &[
                "faction",
                "organization",
                "order",
                "merchant_guild",
                "mercenary_company",
                "assassin_guild",
                "knight_order",
            ],
        );
        language_multi_reference_editor(
            ui,
            language,
            profile,
            "religionArticleIds",
            tr(language, "종교", "Religions"),
            references,
            &["religion"],
        );
        language_multi_reference_editor(
            ui,
            language,
            profile,
            "languageArticleIds",
            tr(language, "언어", "Languages"),
            references,
            &["language", "dialect"],
        );
        language_multi_reference_editor(
            ui,
            language,
            profile,
            "ideologyArticleIds",
            tr(language, "사상", "Ideologies"),
            references,
            &["ideology"],
        );
        let current_family = profile
            .get("familyArticleId")
            .and_then(serde_json::Value::as_str)
            .and_then(|id| u_fields::canonical_reference_id(id, references))
            .map(str::to_owned);
        u_fields::u_input_single(
            ui,
            language,
            ("person-family", article_id),
            tr(language, "소속 가문", "Family"),
            profile,
            "familyArticleId",
            Some("familyCustom"),
            references,
            &["family"],
        );
        let selected_family = profile
            .get("familyArticleId")
            .and_then(serde_json::Value::as_str)
            .and_then(|id| u_fields::canonical_reference_id(id, references))
            .map(str::to_owned);
        let private_exists = profile
            .get("privateLineage")
            .and_then(|value| value.get("members"))
            .and_then(serde_json::Value::as_array)
            .is_some_and(|members| !members.is_empty());
        if selected_family != current_family && selected_family.is_some() && private_exists {
            profile.insert(
                "_pendingFamilyArticleId".to_owned(),
                selected_family.map_or(serde_json::Value::Null, serde_json::Value::String),
            );
            set_optional_json_string(profile, "familyArticleId", current_family);
        }
        let nationalities = json_string_ids(profile.get("nationalityArticleIds"));
        let affiliations = json_string_ids(profile.get("affiliationArticleIds"));
        let religions = json_string_ids(profile.get("religionArticleIds"));
        set_optional_json_string(profile, "countryArticleId", nationalities.first().cloned());
        set_optional_json_string(
            profile,
            "primaryAffiliationArticleId",
            affiliations.first().cloned(),
        );
        set_optional_json_string(profile, "religionArticleId", religions.first().cloned());
        profile.insert(
            "organizationArticleIds".to_owned(),
            string_values(
                affiliations
                    .iter()
                    .filter(|id| {
                        references.iter().any(|option| {
                            option.id == **id
                                && contains_any(
                                    &option.category,
                                    &["organization", "order", "guild", "company"],
                                )
                        })
                    })
                    .cloned()
                    .collect(),
            ),
        );
        profile.insert(
            "factionArticleIds".to_owned(),
            string_values(
                affiliations
                    .iter()
                    .filter(|id| {
                        references
                            .iter()
                            .any(|option| option.id == **id && option.category == "faction")
                    })
                    .cloned()
                    .collect(),
            ),
        );
        let pending = profile
            .get("_pendingFamilyArticleId")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        if let Some(pending) = pending {
            ui.label(
                RichText::new(tr(
                    language,
                    "가문을 배정하면 개인 가계도가 삭제됩니다.",
                    "Assigning a Family deletes the private lineage.",
                ))
                .size(9.0)
                .color(colors.danger),
            );
            ui.horizontal(|ui| {
                if ui
                    .button(tr(language, "삭제 후 배정", "Delete and Assign"))
                    .clicked()
                {
                    profile.insert(
                        "familyArticleId".to_owned(),
                        serde_json::Value::String(pending),
                    );
                    profile.remove("privateLineage");
                    clear_legacy_person_lineage(profile);
                    profile.remove("_pendingFamilyArticleId");
                }
                if ui.button(tr(language, "취소", "Cancel")).clicked() {
                    profile.remove("_pendingFamilyArticleId");
                }
            });
        }
        if profile
            .get("familyArticleId")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|id| !id.is_empty())
        {
            ui.label(
                RichText::new(tr(
                    language,
                    "가계도는 배정된 가문 문서에서만 편집할 수 있습니다.",
                    "This lineage can only be edited in the assigned Family document.",
                ))
                .size(9.0)
                .color(colors.muted),
            );
        }
    });
    let has_linked_family = profile
        .as_ref()
        .and_then(|profile| profile.get("familyArticleId"))
        .and_then(serde_json::Value::as_str)
        .and_then(|id| u_fields::canonical_reference_id(id, references))
        .is_some();
    if !has_linked_family {
        theme::surface_frame(dark).show(ui, |ui| {
            section_title(
                ui,
                tr(language, "개인 가계도 편집", "Edit Private Lineage"),
                colors,
            );
            let profile = json_object_mut(profile);
            let mut preview_article = world
                .articles
                .iter()
                .find(|article| article.id == article_id)
                .cloned()
                .unwrap_or_else(|| Article {
                    id: article_id.to_owned(),
                    title: article_title.to_owned(),
                    wiki_aliases: Vec::new(),
                    redirect_target_article_id: None,
                    category: "person".to_owned(),
                    category_id: None,
                    summary: String::new(),
                    content: String::new(),
                    calendar_profile: None,
                    document_sections: Vec::new(),
                    tags: Vec::new(),
                    linked_map_entity_ids: Vec::new(),
                    source_map_id: None,
                    source_entity_id: None,
                    profiles: ArticleProfiles::default(),
                });
            preview_article.profiles.person = Some(serde_json::Value::Object(profile.clone()));
            if let Some(graph) = build_person_genealogy_graph(world, &preview_article) {
                let mut collapsed = std::collections::HashSet::new();
                let _ = genealogy_graph_ui(ui, language, colors, &graph, &mut collapsed);
                ui.separator();
            }
            let private = profile
                .entry("privateLineage".to_owned())
                .or_insert_with(|| serde_json::json!({ "members": [] }));
            let private = private.as_object_mut().expect("private lineage object");
            let members = private
                .entry("members".to_owned())
                .or_insert_with(|| serde_json::Value::Array(Vec::new()))
                .as_array_mut()
                .expect("private lineage members");
            lineage_members_editor(
                ui,
                language,
                colors,
                members,
                references,
                Some((article_id, article_title)),
            );
        });
    }
}

fn family_genealogy_profile_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    profile: &mut Option<serde_json::Value>,
    references: &[UReferenceOption],
    display_calendar: &CalendarProfile,
    orbital_period_days: f64,
    calendar_options: &[(String, CalendarProfile)],
) {
    let colors = theme::palette(dark);
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(
            ui,
            tr(language, "가문 가계도 편집", "Edit Family Genealogy"),
            colors,
        );
        let profile = json_object_mut(profile);
        calendar_date_popup_editor(
            ui,
            language,
            tr(language, "형성 시기", "Formation Period"),
            profile,
            "formationPeriod",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        calendar_date_popup_editor(
            ui,
            language,
            tr(language, "몰락/해체 시기", "Fall / Dissolution Period"),
            profile,
            "dissolutionPeriod",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        ui.separator();
        let members = profile
            .entry("members".to_owned())
            .or_insert_with(|| serde_json::Value::Array(Vec::new()))
            .as_array_mut()
            .expect("family members");
        lineage_members_editor(ui, language, colors, members, references, None);
    });
}

fn lineage_members_editor(
    ui: &mut egui::Ui,
    language: Language,
    colors: theme::Palette,
    members: &mut Vec<serde_json::Value>,
    references: &[UReferenceOption],
    private_focus: Option<(&str, &str)>,
) {
    let people = genealogy_reference_options(references, false);
    if members.is_empty() && private_focus.is_some() {
        let (article_id, title) = private_focus.expect("private focus");
        if ui
            .add_sized(
                [ui.available_width(), 26.0],
                egui::Button::new(tr(
                    language,
                    "+ 개인 가계도 생성",
                    "+ Create Private Lineage",
                )),
            )
            .clicked()
        {
            members.push(serde_json::json!({
                "id": format!("private-member-{article_id}"), "articleId": article_id,
                "name": title, "parentIds": [], "partnerIds": [], "important": true, "summary": "",
            }));
        }
        return;
    }
    let snapshot = members.clone();
    let labels = snapshot
        .iter()
        .filter_map(|member| {
            let id = member.get("id")?.as_str()?.to_owned();
            let name = member
                .get("articleId")
                .and_then(serde_json::Value::as_str)
                .and_then(|article_id| {
                    people
                        .iter()
                        .find(|option| option.id == article_id)
                        .map(|option| option.title.clone())
                })
                .unwrap_or_else(|| json_text(member.get("name")));
            Some((
                id,
                if name.is_empty() {
                    tr(language, "미지정", "Unassigned").to_owned()
                } else {
                    name
                },
            ))
        })
        .collect::<Vec<_>>();
    let mut remove = None;
    for (index, member) in members.iter_mut().enumerate() {
        if index > 0 {
            ui.separator();
        }
        let object = member.as_object_mut().expect("lineage member object");
        let member_id = object
            .get("id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_owned();
        editable_json_text(
            ui,
            tr(language, "표시 이름", "Display Name"),
            object,
            "name",
        );
        let current_article = object
            .get("articleId")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        let pending_article = object
            .get("_pendingArticleId")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        let mut selector = serde_json::Map::new();
        if let Some(article_id) = &current_article {
            selector.insert(
                "articleId".to_owned(),
                serde_json::Value::String(article_id.clone()),
            );
        }
        u_fields::u_input_single(
            ui,
            language,
            ("lineage-person", &member_id),
            tr(language, "연결 인물", "Linked Person"),
            &mut selector,
            "articleId",
            None,
            references,
            &["person"],
        );
        let selected_article = selector
            .get("articleId")
            .and_then(serde_json::Value::as_str)
            .and_then(|id| u_fields::canonical_reference_id(id, references))
            .map(str::to_owned);
        if selected_article != current_article {
            match selected_article {
                Some(id) => {
                    object.insert(
                        "_pendingArticleId".to_owned(),
                        serde_json::Value::String(id),
                    );
                }
                None => {
                    object.remove("articleId");
                    object.remove("_pendingArticleId");
                }
            }
        }
        if let Some(pending) = pending_article.or_else(|| {
            object
                .get("_pendingArticleId")
                .and_then(serde_json::Value::as_str)
                .map(str::to_owned)
        }) {
            ui.horizontal(|ui| {
                ui.label(
                    RichText::new(tr(
                        language,
                        "가계도 소유권 변경 확인",
                        "Confirm lineage ownership change",
                    ))
                    .size(8.5)
                    .color(colors.danger),
                );
                if ui.button(tr(language, "적용", "Apply")).clicked() {
                    object.insert("articleId".to_owned(), serde_json::Value::String(pending));
                    object.remove("_pendingArticleId");
                }
                if ui.button(tr(language, "취소", "Cancel")).clicked() {
                    object.remove("_pendingArticleId");
                }
            });
        }
        let is_focus = private_focus
            .is_some_and(|(article_id, _)| current_article.as_deref() == Some(article_id));
        if private_focus.is_some() && !is_focus {
            let mut relationship = object
                .get("relationshipType")
                .and_then(serde_json::Value::as_str)
                .unwrap_or("sibling")
                .to_owned();
            ui.horizontal(|ui| {
                ui.add_sized(
                    [u_fields::FIELD_LABEL_WIDTH, u_fields::FIELD_HEIGHT],
                    egui::Label::new(RichText::new(tr(language, "관계", "Relationship")).size(9.5)),
                );
                egui::ComboBox::from_id_salt(("private-lineage-relation", &member_id))
                    .selected_text(relationship_type_label(language, &relationship))
                    .width(ui.available_width())
                    .show_ui(ui, |ui| {
                        for key in PRIVATE_RELATIONSHIP_TYPES {
                            ui.selectable_value(
                                &mut relationship,
                                (*key).to_owned(),
                                relationship_type_label(language, key),
                            );
                        }
                    });
            });
            object.insert(
                "relationshipType".to_owned(),
                serde_json::Value::String(relationship),
            );
        }
        for (key, ko, en) in [
            ("parentIds", "부모", "Parents"),
            ("partnerIds", "배우자/동반자", "Spouses/Partners"),
        ] {
            let mut selected = json_string_ids(object.get(key));
            ui.menu_button(
                format!("{} · {}", tr(language, ko, en), selected.len()),
                |ui| {
                    for (candidate_id, candidate_label) in &labels {
                        if candidate_id == &member_id {
                            continue;
                        }
                        let mut checked = selected.contains(candidate_id);
                        if ui.checkbox(&mut checked, candidate_label).changed() {
                            if checked {
                                selected.push(candidate_id.clone());
                            } else {
                                selected.retain(|id| id != candidate_id);
                            }
                        }
                    }
                },
            );
            object.insert(
                key.to_owned(),
                serde_json::Value::Array(
                    selected
                        .into_iter()
                        .map(serde_json::Value::String)
                        .collect(),
                ),
            );
        }
        if ui
            .add_enabled(
                !is_focus,
                egui::Button::new(
                    RichText::new(tr(language, "삭제", "Delete")).color(colors.danger),
                ),
            )
            .clicked()
        {
            remove = Some(index);
        }
    }
    if let Some(index) = remove {
        members.remove(index);
    }
    if ui
        .add_sized(
            [ui.available_width(), 26.0],
            egui::Button::new(tr(language, "+ 구성원", "+ Member")),
        )
        .clicked()
    {
        let mut next_index = members.len() + 1;
        while members.iter().any(|member| {
            member.get("id").and_then(serde_json::Value::as_str)
                == Some(&format!("family-member-{next_index}"))
        }) {
            next_index += 1;
        }
        members.push(serde_json::json!({
            "id": format!("family-member-{next_index}"), "name": "", "parentIds": [],
            "partnerIds": [], "important": false, "summary": "",
        }));
    }
    normalize_lineage_json_members(members);
}

