fn script_type_label(language: Language, value: &str) -> &'static str {
    match (language, value) {
        (Language::Korean, "pictographic") => "상형문자",
        (Language::Korean, "ideographic") => "표의문자",
        (Language::Korean, "logographic") => "표어문자",
        (Language::Korean, "segmental") => "표음-분절문자",
        (Language::Korean, "syllabic") => "표음-음절문자",
        (Language::Korean, _) => "미지정",
        (Language::English, "pictographic") => "Pictographic",
        (Language::English, "ideographic") => "Ideographic",
        (Language::English, "logographic") => "Logographic",
        (Language::English, "segmental") => "Phonographic - Segmental",
        (Language::English, "syllabic") => "Phonographic - Syllabic",
        (Language::English, _) => "Unspecified",
    }
}

