fn person_rpg_profile_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    person: Option<&serde_json::Value>,
    rpg: &mut Option<serde_json::Value>,
    rules: &RpgRuleSet,
    references: &[UReferenceOption],
) {
    let colors = theme::palette(dark);
    let rpg = json_object_mut(rpg);
    let mut relationship_values = rpg
        .get("relationshipValues")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .unwrap_or_default();
    let mut relationships = Vec::new();
    if let Some(person) = person {
        for id in json_string_ids(person.get("affiliationArticleIds"))
            .into_iter()
            .chain(json_string_ids(person.get("nationalityArticleIds")))
        {
            relationships.push((
                format!("loyalty:{id}"),
                tr(language, "충성심", "Loyalty"),
                id,
            ));
        }
        for id in json_string_ids(person.get("religionArticleIds")) {
            relationships.push((format!("faith:{id}"), tr(language, "신앙심", "Faith"), id));
        }
    }
    relationships.sort_by(|left, right| left.0.cmp(&right.0));
    relationships.dedup_by(|left, right| left.0 == right.0);
    if !relationships.is_empty() {
        theme::surface_frame(dark).show(ui, |ui| {
            section_title(
                ui,
                tr(language, "관계 수치 편집", "Edit Relationship Values"),
                colors,
            );
            for (key, kind, source_id) in &relationships {
                let source = references
                    .iter()
                    .find(|option| option.id == *source_id)
                    .map(|option| option.title.as_str())
                    .unwrap_or(source_id);
                let mut value = relationship_values
                    .get(key)
                    .and_then(serde_json::Value::as_f64)
                    .unwrap_or_default();
                ui.horizontal(|ui| {
                    ui.add_sized(
                        [78.0, 26.0],
                        egui::Label::new(RichText::new(*kind).size(9.5)),
                    );
                    ui.add_sized(
                        [ui.available_width() * 0.55, 26.0],
                        egui::Label::new(RichText::new(source).size(9.5).color(colors.muted)),
                    );
                    if ui
                        .add(egui::DragValue::new(&mut value).range(-1_000_000.0..=1_000_000.0))
                        .changed()
                    {
                        relationship_values.insert(key.clone(), serde_json::json!(value));
                    }
                });
            }
        });
    }
    rpg.insert(
        "relationshipValues".to_owned(),
        serde_json::Value::Object(relationship_values),
    );

    let mut values = rpg
        .get("values")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .unwrap_or_default();
    for group in rules.groups.iter().filter(|group| {
        group.parent_id == "character_attributes" || group.parent_id == "character_proficiencies"
    }) {
        theme::surface_frame(dark).show(ui, |ui| {
            ui.horizontal(|ui| {
                section_title(ui, group.label(language), colors);
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    ui.menu_button("+", |ui| {
                        for definition in &group.definitions {
                            if !values.contains_key(&definition.id)
                                && ui.button(definition.label(language)).clicked()
                            {
                                values.insert(
                                    definition.id.clone(),
                                    match definition.value_kind {
                                        RpgValueKind::Text => {
                                            serde_json::Value::String(String::new())
                                        }
                                        _ => serde_json::json!(0),
                                    },
                                );
                                ui.close();
                            }
                        }
                    });
                });
            });
            let mut remove = None;
            for definition in &group.definitions {
                let Some(value) = values.get_mut(&definition.id) else {
                    continue;
                };
                if rpg_value_editor_row(
                    ui,
                    language,
                    definition.label(language),
                    definition.value_kind,
                    value,
                    colors,
                ) {
                    remove = Some(definition.id.clone());
                }
            }
            if let Some(key) = remove {
                values.remove(&key);
            }
            if group
                .definitions
                .iter()
                .all(|definition| !values.contains_key(&definition.id))
            {
                ui.label(
                    RichText::new(tr(
                        language,
                        "설정된 수치가 없습니다.",
                        "No values assigned.",
                    ))
                    .size(9.0)
                    .color(colors.muted),
                );
            }
        });
    }
    rpg.insert("values".to_owned(), serde_json::Value::Object(values));
}

fn rpg_value_editor_row(
    ui: &mut egui::Ui,
    language: Language,
    label: &str,
    kind: RpgValueKind,
    value: &mut serde_json::Value,
    colors: theme::Palette,
) -> bool {
    let mut remove = false;
    ui.horizontal(|ui| {
        ui.add_sized(
            [112.0, 26.0],
            egui::Label::new(RichText::new(label).size(9.5).color(colors.text)),
        );
        match kind {
            RpgValueKind::Integer => {
                let mut number = value
                    .as_i64()
                    .or_else(|| value.as_str()?.parse().ok())
                    .unwrap_or_default();
                if ui
                    .add(egui::DragValue::new(&mut number).range(-1_000_000..=1_000_000))
                    .changed()
                {
                    *value = serde_json::json!(number);
                }
            }
            RpgValueKind::Percent => {
                let mut number = value
                    .as_f64()
                    .or_else(|| value.as_str()?.trim_end_matches('%').parse().ok())
                    .unwrap_or_default();
                if ui
                    .add(
                        egui::DragValue::new(&mut number)
                            .range(-100_000.0..=100_000.0)
                            .suffix("%"),
                    )
                    .changed()
                {
                    *value = serde_json::json!(number);
                }
            }
            RpgValueKind::Text => {
                let mut text = value
                    .as_str()
                    .map(str::to_owned)
                    .unwrap_or_else(|| json_text(Some(value)));
                if ui
                    .add_sized(
                        [(ui.available_width() - 30.0).max(80.0), 26.0],
                        egui::TextEdit::singleline(&mut text),
                    )
                    .changed()
                {
                    *value = serde_json::Value::String(text);
                }
            }
        }
        if ui
            .small_button("×")
            .on_hover_text(tr(language, "수치 제거", "Remove value"))
            .clicked()
        {
            remove = true;
        }
    });
    remove
}

fn item_rpg_editors(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    rpg: &mut Option<serde_json::Value>,
    rules: &RpgRuleSet,
) {
    let colors = theme::palette(dark);
    let definitions = rules
        .groups
        .iter()
        .filter(|group| group.parent_id == "equipment_attributes")
        .flat_map(|group| group.definitions.iter())
        .map(|definition| {
            (
                definition.id.clone(),
                definition.label(language).to_owned(),
                definition.value_kind,
            )
        })
        .collect::<Vec<_>>();
    let rpg = json_object_mut(rpg);
    let mut values = rpg
        .get("values")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .unwrap_or_default();
    theme::surface_frame(dark).show(ui, |ui| {
        ui.horizontal(|ui| {
            section_title(
                ui,
                tr(language, "물건 수치 편집", "Edit Item Attributes"),
                colors,
            );
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                ui.menu_button("＋", |ui| {
                    for (id, label, kind) in &definitions {
                        if !values.contains_key(id) && ui.button(label).clicked() {
                            values.insert(
                                id.clone(),
                                match kind {
                                    RpgValueKind::Text => serde_json::Value::String(String::new()),
                                    _ => serde_json::json!(0),
                                },
                            );
                            ui.close();
                        }
                    }
                    if definitions.iter().all(|(id, _, _)| values.contains_key(id)) {
                        ui.label(
                            RichText::new(tr(
                                language,
                                "추가 가능한 수치가 없습니다.",
                                "No more attributes are available.",
                            ))
                            .size(9.0)
                            .color(colors.muted),
                        );
                    }
                });
            });
        });
        let keys = values.keys().cloned().collect::<Vec<_>>();
        let mut remove = None;
        for key in keys {
            let definition = definitions.iter().find(|(id, _, _)| id == &key);
            let label = definition
                .map(|(_, label, _)| label.as_str())
                .unwrap_or_else(|| stat_label(language, &key));
            let kind = definition
                .map(|(_, _, kind)| *kind)
                .unwrap_or(RpgValueKind::Text);
            ui.horizontal(|ui| {
                ui.add_sized(
                    [112.0, 26.0],
                    egui::Label::new(RichText::new(label).size(9.5)),
                );
                if let Some(value) = values.get_mut(&key) {
                    match kind {
                        RpgValueKind::Integer => {
                            let mut number = value
                                .as_i64()
                                .or_else(|| value.as_str()?.parse().ok())
                                .unwrap_or_default();
                            if ui
                                .add(
                                    egui::DragValue::new(&mut number).range(-1_000_000..=1_000_000),
                                )
                                .changed()
                            {
                                *value = serde_json::json!(number);
                            }
                        }
                        RpgValueKind::Percent => {
                            let mut number = value
                                .as_f64()
                                .or_else(|| value.as_str()?.trim_end_matches('%').parse().ok())
                                .unwrap_or_default();
                            if ui
                                .add(
                                    egui::DragValue::new(&mut number)
                                        .range(-100_000.0..=100_000.0)
                                        .suffix("%"),
                                )
                                .changed()
                            {
                                *value = serde_json::json!(number);
                            }
                        }
                        RpgValueKind::Text => {
                            let mut text = value
                                .as_str()
                                .map(str::to_owned)
                                .unwrap_or_else(|| json_text(Some(value)));
                            if ui
                                .add_sized(
                                    [ui.available_width() - 30.0, 26.0],
                                    egui::TextEdit::singleline(&mut text),
                                )
                                .changed()
                            {
                                *value = serde_json::Value::String(text);
                            }
                        }
                    }
                }
                if ui
                    .small_button("×")
                    .on_hover_text(tr(language, "수치 삭제", "Remove attribute"))
                    .clicked()
                {
                    remove = Some(key.clone());
                }
            });
        }
        if values.is_empty() {
            ui.label(
                RichText::new(tr(
                    language,
                    "등록된 물건 수치가 없습니다.",
                    "No item attributes have been assigned.",
                ))
                .size(9.5)
                .color(colors.muted),
            );
        }
        if let Some(key) = remove {
            values.remove(&key);
        }
    });
    rpg.insert("values".to_owned(), serde_json::Value::Object(values));

    let mut attacks = rpg
        .get("attackProfiles")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    combat_profiles_editor(ui, dark, language, &mut attacks, true);
    rpg.insert(
        "attackProfiles".to_owned(),
        serde_json::Value::Array(attacks),
    );

    let mut defenses = rpg
        .get("defenseProfiles")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_else(|| {
            rpg.get("armorProfile")
                .filter(|value| !value.is_null())
                .cloned()
                .into_iter()
                .collect()
        });
    combat_profiles_editor(ui, dark, language, &mut defenses, false);
    rpg.insert(
        "defenseProfiles".to_owned(),
        serde_json::Value::Array(defenses),
    );
    rpg.remove("armorProfile");
}

fn combat_profiles_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    profiles: &mut Vec<serde_json::Value>,
    attack: bool,
) {
    let colors = theme::palette(dark);
    theme::surface_frame(dark).show(ui, |ui| {
        ui.horizontal(|ui| {
            section_title(
                ui,
                if attack {
                    tr(language, "공격 편집", "Edit Attacks")
                } else {
                    tr(language, "방어 편집", "Edit Defenses")
                },
                colors,
            );
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui.small_button("＋").on_hover_text(if attack {
                    tr(language, "공격 방식 추가", "Add attack profile")
                } else {
                    tr(language, "방어 방식 추가", "Add defense profile")
                }).clicked() {
                    profiles.push(if attack {
                        serde_json::json!({ "id": format!("attack-{}", profiles.len() + 1), "name": "", "damage": "", "methods": [], "attributes": [] })
                    } else {
                        serde_json::json!({ "id": format!("defense-{}", profiles.len() + 1), "name": "", "defense": "", "methods": [], "attributes": [] })
                    });
                }
            });
        });
        let mut remove = None;
        for (index, profile) in profiles.iter_mut().enumerate() {
            if !profile.is_object() { *profile = serde_json::json!({}); }
            let profile = profile.as_object_mut().expect("combat profile object");
            if index > 0 { ui.separator(); }
            ui.horizontal(|ui| {
                ui.label(RichText::new(format!("{} {}", if attack { tr(language, "공격", "Attack") } else { tr(language, "방어", "Defense") }, index + 1)).size(9.5).strong());
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    if ui.small_button("×").on_hover_text(tr(language, "방식 삭제", "Remove profile")).clicked() { remove = Some(index); }
                });
            });
            editable_json_text(ui, tr(language, "기술명", "Technique"), profile, "name");
            editable_json_text(
                ui,
                if attack { tr(language, "피해량", "Damage") } else { tr(language, "방어력", "Defense") },
                profile,
                if attack { "damage" } else { "defense" },
            );
            editable_json_list(
                ui,
                if attack { tr(language, "피해 수단", "Damage Methods") } else { tr(language, "방어 수단", "Defense Methods") },
                profile,
                "methods",
            );
            editable_json_list(
                ui,
                if attack { tr(language, "피해 속성", "Damage Attributes") } else { tr(language, "방어 속성", "Defense Attributes") },
                profile,
                "attributes",
            );
        }
        if profiles.is_empty() {
            ui.label(RichText::new(if attack {
                tr(language, "등록된 공격 방식이 없습니다.", "No attack profiles have been assigned.")
            } else {
                tr(language, "등록된 방어 방식이 없습니다.", "No defense profiles have been assigned.")
            }).size(9.5).color(colors.muted));
        }
        if let Some(index) = remove { profiles.remove(index); }
    });
}

