fn item_panels(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    colors: theme::Palette,
    article: &Article,
    _world: &LoadedWorld,
    rules: &RpgRuleSet,
) {
    let rpg = article.profiles.rpg.as_ref();
    if let Some(values) = rpg
        .and_then(|value| value.get("values"))
        .and_then(serde_json::Value::as_object)
    {
        theme::surface_frame(dark).show(ui, |ui| {
            section_title(ui, tr(language, "물건 수치", "Item Attributes"), colors);
            ui.horizontal_wrapped(|ui| {
                for (id, value) in values {
                    let definition = rules
                        .groups
                        .iter()
                        .flat_map(|group| group.definitions.iter())
                        .find(|definition| definition.id == *id);
                    let label = definition
                        .map(|definition| definition.label(language))
                        .unwrap_or_else(|| stat_label(language, id));
                    let mut display = json_text(Some(value));
                    if definition
                        .is_some_and(|definition| definition.value_kind == RpgValueKind::Percent)
                        && display != "-"
                        && !display.ends_with('%')
                    {
                        display.push('%');
                    }
                    stat_box(ui, label, &display, colors);
                }
            });
        });
    }
    let attacks = rpg
        .and_then(|value| value.get("attackProfiles"))
        .and_then(serde_json::Value::as_array);
    if attacks.is_some_and(|values| !values.is_empty()) {
        theme::surface_frame(dark).show(ui, |ui| {
            section_title(ui, tr(language, "공격", "Attacks"), colors);
            if let Some(attacks) = attacks {
                for attack in attacks {
                    technique_row(
                        ui,
                        &json_text(attack.get("name")),
                        &json_text(attack.get("damage")),
                        &json_list(attack.get("methods")),
                        &json_list(attack.get("attributes")),
                        colors,
                    );
                }
            }
        });
    }
    let defenses = rpg
        .and_then(|value| value.get("defenseProfiles"))
        .and_then(serde_json::Value::as_array);
    let legacy_armor = rpg.and_then(|value| value.get("armorProfile"));
    if defenses.is_some_and(|values| !values.is_empty())
        || legacy_armor.is_some_and(|value| !value.is_null())
    {
        theme::surface_frame(dark).show(ui, |ui| {
            section_title(ui, tr(language, "방어", "Defenses"), colors);
            if let Some(defenses) = defenses {
                for defense in defenses {
                    technique_row(
                        ui,
                        &json_text(defense.get("name")),
                        &json_text(defense.get("defense")),
                        &json_list(defense.get("methods")),
                        &json_list(defense.get("attributes")),
                        colors,
                    );
                }
            } else if let Some(armor) = legacy_armor.filter(|value| !value.is_null()) {
                technique_row(
                    ui,
                    tr(language, "방어", "Defense"),
                    &json_text(armor.get("defense")),
                    &json_object_enabled(armor.get("methodDefense")),
                    &json_list(armor.get("attributes")),
                    colors,
                );
            }
        });
    }
}

fn person_relation_ids(article: &Article, keys: &[&str]) -> Vec<String> {
    let Some(profile) = article.profiles.person.as_ref() else {
        return Vec::new();
    };
    keys.iter()
        .flat_map(|key| match profile.get(*key) {
            Some(serde_json::Value::String(id)) if !id.is_empty() => vec![id.clone()],
            Some(serde_json::Value::Array(ids)) => ids
                .iter()
                .filter_map(serde_json::Value::as_str)
                .filter(|id| !id.is_empty())
                .map(str::to_owned)
                .collect(),
            _ => Vec::new(),
        })
        .collect()
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum GenealogyRole {
    Focus,
    Partner,
    Sibling,
    Important,
    Member,
}

#[derive(Clone)]
struct GenealogyNode {
    id: String,
    article_id: Option<String>,
    name: String,
    birth: String,
    death: String,
    generation: i32,
    role: GenealogyRole,
    relationship_type: Option<String>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum GenealogyEdgeKind {
    ParentChild,
    Partner,
    Related,
}

#[derive(Clone)]
struct GenealogyEdge {
    from: String,
    to: String,
    kind: GenealogyEdgeKind,
}

#[derive(Clone)]
struct GenealogyGraph {
    nodes: Vec<GenealogyNode>,
    edges: Vec<GenealogyEdge>,
    family_view: bool,
    linguistic_view: bool,
}

fn build_language_genealogy_graph(world: &LoadedWorld, focus: &Article) -> Option<GenealogyGraph> {
    if canonical_language_category(&focus.category) == "writing_system" {
        return None;
    }
    let mut root_id = focus.id.clone();
    let mut ancestors = std::collections::HashSet::new();
    while ancestors.insert(root_id.clone()) {
        let Some(article) = world.articles.iter().find(|article| article.id == root_id) else {
            break;
        };
        let Some(parent_id) = language_parent_article_id(article) else {
            break;
        };
        root_id = parent_id;
    }

    let mut visible = std::collections::HashSet::new();
    let mut pending = vec![root_id];
    while let Some(parent_id) = pending.pop() {
        if !visible.insert(parent_id.clone()) {
            continue;
        }
        pending.extend(
            world
                .articles
                .iter()
                .filter(|article| {
                    language_parent_article_id(article).as_deref() == Some(parent_id.as_str())
                })
                .map(|article| article.id.clone()),
        );
    }
    visible.insert(focus.id.clone());

    let mut graph = GenealogyGraph {
        nodes: Vec::new(),
        edges: Vec::new(),
        family_view: false,
        linguistic_view: true,
    };
    for article in world
        .articles
        .iter()
        .filter(|article| visible.contains(&article.id))
    {
        let category = canonical_language_category(&article.category);
        if category == "writing_system" {
            continue;
        }
        let profile = article.profiles.language.as_ref();
        let native_name = profile
            .and_then(|profile| {
                profile
                    .get("nativeName")
                    .or_else(|| profile.get("selfName"))
            })
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_owned();
        graph.nodes.push(GenealogyNode {
            id: article.id.clone(),
            article_id: Some(article.id.clone()),
            name: article.title.clone(),
            birth: category.to_owned(),
            death: native_name,
            generation: language_lineage_level(category),
            role: if article.id == focus.id {
                GenealogyRole::Focus
            } else {
                GenealogyRole::Member
            },
            relationship_type: None,
        });
        if let Some(parent_id) =
            language_parent_article_id(article).filter(|parent_id| visible.contains(parent_id))
        {
            push_genealogy_edge(
                &mut graph,
                &parent_id,
                &article.id,
                GenealogyEdgeKind::ParentChild,
            );
        }
    }
    (!graph.nodes.is_empty()).then_some(graph)
}

fn language_lineage_level(category: &str) -> i32 {
    match category {
        "language_family" => 0,
        "language_branch" => 1,
        "language_group" => 2,
        "language" => 3,
        "dialect" => 4,
        _ => 5,
    }
}

fn language_lineage_category_label(language: Language, category: &str) -> &'static str {
    match category {
        "language_family" => tr(language, "어족", "Language Family"),
        "language_branch" => tr(language, "어파", "Language Branch"),
        "language_group" => tr(language, "어군", "Language Group"),
        "language" => tr(language, "언어", "Language"),
        "dialect" => tr(language, "방언", "Dialect"),
        _ => tr(language, "계통", "Lineage"),
    }
}

fn language_lineage_level_label(language: Language, level: i32) -> &'static str {
    match level {
        0 => tr(language, "어족", "Language Family"),
        1 => tr(language, "어파", "Language Branch"),
        2 => tr(language, "어군", "Language Group"),
        3 => tr(language, "언어", "Language"),
        4 => tr(language, "방언", "Dialect"),
        _ => tr(language, "계통", "Lineage"),
    }
}

fn build_person_genealogy_graph(world: &LoadedWorld, focus: &Article) -> Option<GenealogyGraph> {
    let profile = focus.profiles.person.as_ref()?;
    if let Some(family_id) = profile
        .get("familyArticleId")
        .and_then(serde_json::Value::as_str)
        .filter(|id| !id.is_empty())
    {
        if let Some(family) = world
            .articles
            .iter()
            .find(|article| article.id == family_id)
        {
            if let Some(members) = family
                .profiles
                .family
                .as_ref()
                .and_then(|value| value.get("members"))
                .and_then(serde_json::Value::as_array)
            {
                if let Some(graph) = build_person_member_genealogy_graph(world, focus, members) {
                    return Some(graph);
                }
            }
        }
        return None;
    }
    if let Some(members) = profile
        .get("privateLineage")
        .and_then(|value| value.get("members"))
        .and_then(serde_json::Value::as_array)
    {
        if let Some(graph) = build_person_member_genealogy_graph(world, focus, members) {
            return Some(graph);
        }
    }
    let mut graph = GenealogyGraph {
        nodes: Vec::new(),
        edges: Vec::new(),
        family_view: false,
        linguistic_view: false,
    };
    insert_person_genealogy_node(&mut graph, world, &focus.id, 0, GenealogyRole::Focus);
    let mut ancestors = std::collections::HashSet::new();
    collect_person_ancestors(&mut graph, world, &focus.id, 0, 0, &mut ancestors);
    let mut descendants = std::collections::HashSet::new();
    collect_person_descendants(&mut graph, world, &focus.id, 0, 0, &mut descendants);
    for spouse in person_relation_ids(focus, &["spouseArticleIds"]) {
        insert_person_genealogy_node(&mut graph, world, &spouse, 0, GenealogyRole::Partner);
        push_genealogy_edge(&mut graph, &focus.id, &spouse, GenealogyEdgeKind::Partner);
    }
    let parents = person_relation_ids(focus, &["fatherArticleId", "motherArticleId"]);
    for parent_id in parents {
        if let Some(parent) = world
            .articles
            .iter()
            .find(|article| article.id == parent_id)
        {
            for sibling in person_relation_ids(parent, &["childArticleIds"])
                .into_iter()
                .filter(|id| id != &focus.id)
            {
                insert_person_genealogy_node(
                    &mut graph,
                    world,
                    &sibling,
                    0,
                    GenealogyRole::Sibling,
                );
                push_genealogy_edge(
                    &mut graph,
                    &parent_id,
                    &sibling,
                    GenealogyEdgeKind::ParentChild,
                );
            }
        }
    }
    assign_person_relationship_labels(&mut graph, &focus.id);
    (graph.nodes.len() > 1).then_some(graph)
}

fn build_person_member_genealogy_graph(
    world: &LoadedWorld,
    focus: &Article,
    members: &[serde_json::Value],
) -> Option<GenealogyGraph> {
    let member_map = members
        .iter()
        .filter_map(|member| {
            member
                .get("id")
                .and_then(serde_json::Value::as_str)
                .map(|id| (id.to_owned(), member))
        })
        .collect::<std::collections::HashMap<_, _>>();
    let focus_member = members.iter().find(|member| {
        member.get("articleId").and_then(serde_json::Value::as_str) == Some(focus.id.as_str())
    })?;
    let focus_id = focus_member.get("id").and_then(serde_json::Value::as_str)?;
    let mut children = std::collections::HashMap::<String, Vec<String>>::new();
    for member in members {
        let Some(id) = member.get("id").and_then(serde_json::Value::as_str) else {
            continue;
        };
        for parent in json_string_ids(member.get("parentIds")) {
            children.entry(parent).or_default().push(id.to_owned());
        }
    }
    let mut visible = std::collections::HashSet::from([focus_id.to_owned()]);
    visible.extend(members.iter().filter_map(|member| {
        member
            .get("relationshipType")
            .and_then(serde_json::Value::as_str)
            .filter(|value| !value.is_empty())?;
        member.get("id")?.as_str().map(str::to_owned)
    }));
    let mut ancestors = json_string_ids(focus_member.get("parentIds"));
    while let Some(id) = ancestors.pop() {
        if !visible.insert(id.clone()) {
            continue;
        }
        if let Some(member) = member_map.get(&id) {
            ancestors.extend(json_string_ids(member.get("parentIds")));
        }
    }
    let mut descendants = children.get(focus_id).cloned().unwrap_or_default();
    while let Some(id) = descendants.pop() {
        if !visible.insert(id.clone()) {
            continue;
        }
        descendants.extend(children.get(&id).cloned().unwrap_or_default());
    }
    let focus_parents = json_string_ids(focus_member.get("parentIds"))
        .into_iter()
        .collect::<std::collections::HashSet<_>>();
    let mut sibling_ids = std::collections::HashSet::new();
    for member in members {
        let Some(id) = member.get("id").and_then(serde_json::Value::as_str) else {
            continue;
        };
        if id != focus_id
            && json_string_ids(member.get("parentIds"))
                .iter()
                .any(|parent| focus_parents.contains(parent))
        {
            visible.insert(id.to_owned());
            sibling_ids.insert(id.to_owned());
        }
    }
    let related = visible.iter().cloned().collect::<Vec<_>>();
    let mut partner_ids = std::collections::HashSet::new();
    for id in related {
        if let Some(member) = member_map.get(&id) {
            for partner in json_string_ids(member.get("partnerIds")) {
                if member_map.contains_key(&partner) {
                    visible.insert(partner.clone());
                    partner_ids.insert(partner);
                }
            }
        }
    }
    let mut generation_cache = std::collections::HashMap::new();
    let focus_generation = family_member_generation(
        focus_id,
        &member_map,
        &mut generation_cache,
        &mut std::collections::HashSet::new(),
    );
    let mut graph = GenealogyGraph {
        nodes: Vec::new(),
        edges: Vec::new(),
        family_view: false,
        linguistic_view: false,
    };
    for member in members {
        let Some(id) = member.get("id").and_then(serde_json::Value::as_str) else {
            continue;
        };
        if !visible.contains(id) {
            continue;
        }
        let article_id = member
            .get("articleId")
            .and_then(serde_json::Value::as_str)
            .filter(|id| !id.is_empty());
        let relationship_type = member
            .get("relationshipType")
            .and_then(serde_json::Value::as_str)
            .filter(|value| !value.is_empty())
            .map(str::to_owned);
        let generation = relationship_type
            .as_deref()
            .map(private_relationship_generation)
            .unwrap_or_else(|| {
                family_member_generation(
                    id,
                    &member_map,
                    &mut generation_cache,
                    &mut std::collections::HashSet::new(),
                ) - focus_generation
            });
        graph.nodes.push(GenealogyNode {
            id: id.to_owned(),
            article_id: article_id.map(str::to_owned),
            name: article_id
                .map(|article_id| resolve_article_title(world, article_id).to_owned())
                .unwrap_or_else(|| json_text(member.get("name"))),
            birth: article_id
                .and_then(|article_id| {
                    world
                        .articles
                        .iter()
                        .find(|article| article.id == article_id)
                })
                .and_then(|article| article.profiles.person.as_ref())
                .map_or_else(
                    || json_text(member.get("birthYear")),
                    |profile| json_text(profile.get("birthYear")),
                ),
            death: article_id
                .and_then(|article_id| {
                    world
                        .articles
                        .iter()
                        .find(|article| article.id == article_id)
                })
                .and_then(|article| article.profiles.person.as_ref())
                .map_or_else(
                    || json_text(member.get("deathYear")),
                    |profile| json_text(profile.get("deathYear")),
                ),
            generation,
            role: if id == focus_id {
                GenealogyRole::Focus
            } else if sibling_ids.contains(id) {
                GenealogyRole::Sibling
            } else if partner_ids.contains(id) {
                GenealogyRole::Partner
            } else {
                GenealogyRole::Member
            },
            relationship_type: relationship_type.clone(),
        });
        for parent in json_string_ids(member.get("parentIds")) {
            if visible.contains(&parent) {
                push_genealogy_edge(&mut graph, &parent, id, GenealogyEdgeKind::ParentChild);
            }
        }
        for partner in json_string_ids(member.get("partnerIds")) {
            if visible.contains(&partner) {
                push_genealogy_edge(&mut graph, id, &partner, GenealogyEdgeKind::Partner);
            }
        }
        if id != focus_id
            && let Some(key) = relationship_type.as_deref()
        {
            match private_relationship_generation(key) {
                -1 => push_genealogy_edge(&mut graph, id, focus_id, GenealogyEdgeKind::ParentChild),
                1 => push_genealogy_edge(&mut graph, focus_id, id, GenealogyEdgeKind::ParentChild),
                _ => push_genealogy_edge(&mut graph, focus_id, id, GenealogyEdgeKind::Related),
            }
        }
    }
    assign_person_relationship_labels(&mut graph, focus_id);
    (graph.nodes.len() > 1).then_some(graph)
}

fn assign_person_relationship_labels(graph: &mut GenealogyGraph, focus_id: &str) {
    let parent_ids = |child_id: &str| {
        graph
            .edges
            .iter()
            .filter(|edge| edge.kind == GenealogyEdgeKind::ParentChild && edge.to == child_id)
            .map(|edge| edge.from.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let focus_parents = parent_ids(focus_id);
    let focus_birth = graph
        .nodes
        .iter()
        .find(|node| node.id == focus_id)
        .and_then(|node| node.birth.trim().parse::<i32>().ok());
    let mut direct_children = graph
        .edges
        .iter()
        .filter(|edge| edge.kind == GenealogyEdgeKind::ParentChild && edge.from == focus_id)
        .filter_map(|edge| graph.nodes.iter().find(|node| node.id == edge.to))
        .collect::<Vec<_>>();
    direct_children.sort_by(|left, right| {
        let left_year = left.birth.trim().parse::<i32>().ok();
        let right_year = right.birth.trim().parse::<i32>().ok();
        left_year
            .cmp(&right_year)
            .then_with(|| left.name.cmp(&right.name))
    });
    let child_rank = direct_children
        .iter()
        .enumerate()
        .map(|(index, node)| (node.id.clone(), index))
        .collect::<std::collections::HashMap<_, _>>();
    let inferred = graph
        .nodes
        .iter()
        .map(|node| {
            let relation = if node.id == focus_id {
                "self"
            } else if graph.edges.iter().any(|edge| {
                edge.kind == GenealogyEdgeKind::Partner
                    && ((edge.from == focus_id && edge.to == node.id)
                        || (edge.to == focus_id && edge.from == node.id))
            }) {
                "spouse"
            } else if graph.edges.iter().any(|edge| {
                edge.kind == GenealogyEdgeKind::ParentChild
                    && edge.from == node.id
                    && edge.to == focus_id
            }) {
                "parent"
            } else if let Some(rank) = child_rank.get(&node.id) {
                match rank {
                    0 => "first_child",
                    1 => "second_child",
                    2 => "third_child",
                    _ => "child",
                }
            } else if node.generation == 0 {
                let node_parents = parent_ids(&node.id);
                let shared = !focus_parents.is_disjoint(&node_parents);
                let half = shared && node_parents != focus_parents;
                let node_birth = node.birth.trim().parse::<i32>().ok();
                match (half, focus_birth, node_birth) {
                    (true, Some(focus), Some(candidate)) if candidate < focus => {
                        "older_half_sibling"
                    }
                    (true, Some(focus), Some(candidate)) if candidate > focus => {
                        "younger_half_sibling"
                    }
                    (true, _, _) => "half_sibling",
                    (false, Some(focus), Some(candidate)) if candidate < focus => "older_sibling",
                    (false, Some(focus), Some(candidate)) if candidate > focus => "younger_sibling",
                    _ => "sibling",
                }
            } else if node.generation < 0 {
                "ancestor"
            } else {
                "descendant"
            };
            (node.id.clone(), relation.to_owned())
        })
        .collect::<std::collections::HashMap<_, _>>();
    for node in &mut graph.nodes {
        if node.relationship_type.is_none() {
            node.relationship_type = inferred.get(&node.id).cloned();
        }
    }
}

fn insert_person_genealogy_node(
    graph: &mut GenealogyGraph,
    world: &LoadedWorld,
    article_id: &str,
    generation: i32,
    role: GenealogyRole,
) {
    if let Some(existing) = graph.nodes.iter_mut().find(|node| node.id == article_id) {
        if role == GenealogyRole::Focus || existing.role == GenealogyRole::Member {
            existing.role = role;
        }
        existing.generation = existing.generation.min(generation);
        return;
    }
    let article = world
        .articles
        .iter()
        .find(|article| article.id == article_id);
    let profile = article.and_then(|article| article.profiles.person.as_ref());
    graph.nodes.push(GenealogyNode {
        id: article_id.to_owned(),
        article_id: article.map(|article| article.id.clone()),
        name: article.map_or_else(|| article_id.to_owned(), |article| article.title.clone()),
        birth: json_text(profile.and_then(|value| value.get("birthYear"))),
        death: json_text(profile.and_then(|value| value.get("deathYear"))),
        generation,
        role,
        relationship_type: None,
    });
}

fn collect_person_ancestors(
    graph: &mut GenealogyGraph,
    world: &LoadedWorld,
    current_id: &str,
    generation: i32,
    depth: usize,
    visited: &mut std::collections::HashSet<String>,
) {
    if depth >= 4 || !visited.insert(current_id.to_owned()) {
        return;
    }
    let Some(current) = world
        .articles
        .iter()
        .find(|article| article.id == current_id)
    else {
        return;
    };
    for parent in person_relation_ids(current, &["fatherArticleId", "motherArticleId"]) {
        insert_person_genealogy_node(graph, world, &parent, generation - 1, GenealogyRole::Member);
        push_genealogy_edge(graph, &parent, current_id, GenealogyEdgeKind::ParentChild);
        collect_person_ancestors(graph, world, &parent, generation - 1, depth + 1, visited);
    }
}

fn collect_person_descendants(
    graph: &mut GenealogyGraph,
    world: &LoadedWorld,
    current_id: &str,
    generation: i32,
    depth: usize,
    visited: &mut std::collections::HashSet<String>,
) {
    if depth >= 4 || !visited.insert(current_id.to_owned()) {
        return;
    }
    let Some(current) = world
        .articles
        .iter()
        .find(|article| article.id == current_id)
    else {
        return;
    };
    for child in person_relation_ids(current, &["childArticleIds"]) {
        insert_person_genealogy_node(graph, world, &child, generation + 1, GenealogyRole::Member);
        push_genealogy_edge(graph, current_id, &child, GenealogyEdgeKind::ParentChild);
        collect_person_descendants(graph, world, &child, generation + 1, depth + 1, visited);
    }
}

fn push_genealogy_edge(graph: &mut GenealogyGraph, from: &str, to: &str, kind: GenealogyEdgeKind) {
    if from == to
        || graph.edges.iter().any(|edge| {
            edge.kind == kind
                && ((edge.from == from && edge.to == to)
                    || (kind == GenealogyEdgeKind::Partner && edge.from == to && edge.to == from))
        })
    {
        return;
    }
    graph.edges.push(GenealogyEdge {
        from: from.to_owned(),
        to: to.to_owned(),
        kind,
    });
}

fn build_family_genealogy_graph(world: &LoadedWorld, article: &Article) -> Option<GenealogyGraph> {
    let members = article
        .profiles
        .family
        .as_ref()
        .and_then(|profile| profile.get("members"))
        .and_then(serde_json::Value::as_array)
        .filter(|members| !members.is_empty())?;
    let member_map = members
        .iter()
        .filter_map(|member| {
            member
                .get("id")
                .and_then(serde_json::Value::as_str)
                .map(|id| (id.to_owned(), member))
        })
        .collect::<std::collections::HashMap<_, _>>();
    let mut generation_cache = std::collections::HashMap::new();
    let mut graph = GenealogyGraph {
        nodes: Vec::new(),
        edges: Vec::new(),
        family_view: true,
        linguistic_view: false,
    };
    for member in members {
        let id = member
            .get("id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        if id.is_empty() {
            continue;
        }
        let generation = family_member_generation(
            id,
            &member_map,
            &mut generation_cache,
            &mut std::collections::HashSet::new(),
        );
        let article_id = member
            .get("articleId")
            .and_then(serde_json::Value::as_str)
            .filter(|id| !id.is_empty());
        graph.nodes.push(GenealogyNode {
            id: id.to_owned(),
            article_id: article_id.map(str::to_owned),
            name: article_id
                .map(|id| resolve_article_title(world, id).to_owned())
                .unwrap_or_else(|| json_text(member.get("name"))),
            birth: json_text(member.get("birthYear")),
            death: json_text(member.get("deathYear")),
            generation,
            role: if member
                .get("important")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false)
            {
                GenealogyRole::Important
            } else {
                GenealogyRole::Member
            },
            relationship_type: None,
        });
        for parent in json_string_ids(member.get("parentIds")) {
            push_genealogy_edge(&mut graph, &parent, id, GenealogyEdgeKind::ParentChild);
        }
        for partner in json_string_ids(member.get("partnerIds")) {
            push_genealogy_edge(&mut graph, id, &partner, GenealogyEdgeKind::Partner);
        }
    }
    Some(graph)
}

fn family_member_generation(
    id: &str,
    members: &std::collections::HashMap<String, &serde_json::Value>,
    cache: &mut std::collections::HashMap<String, i32>,
    visiting: &mut std::collections::HashSet<String>,
) -> i32 {
    if let Some(generation) = cache.get(id) {
        return *generation;
    }
    if !visiting.insert(id.to_owned()) {
        return 0;
    }
    let generation = members
        .get(id)
        .map(|member| {
            json_string_ids(member.get("parentIds"))
                .into_iter()
                .map(|parent| family_member_generation(&parent, members, cache, visiting) + 1)
                .max()
                .unwrap_or(0)
        })
        .unwrap_or(0);
    visiting.remove(id);
    cache.insert(id.to_owned(), generation);
    generation
}

fn json_string_ids(value: Option<&serde_json::Value>) -> Vec<String> {
    value
        .and_then(serde_json::Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(serde_json::Value::as_str)
                .filter(|id| !id.is_empty())
                .map(str::to_owned)
                .collect()
        })
        .unwrap_or_default()
}

fn genealogy_parent_couple<'a>(
    graph: &'a GenealogyGraph,
    parent_id: &'a str,
    child_id: &str,
) -> Option<(&'a str, &'a str)> {
    graph
        .edges
        .iter()
        .filter(|edge| edge.kind == GenealogyEdgeKind::Partner)
        .filter_map(|edge| {
            if edge.from == parent_id {
                Some(edge.to.as_str())
            } else if edge.to == parent_id {
                Some(edge.from.as_str())
            } else {
                None
            }
        })
        .find(|partner| {
            graph.edges.iter().any(|edge| {
                edge.kind == GenealogyEdgeKind::ParentChild
                    && edge.from == *partner
                    && edge.to == child_id
            })
        })
        .map(|partner| (parent_id, partner))
}

fn genealogy_generation_layout(
    graph: &GenealogyGraph,
    nodes: &[&GenealogyNode],
    positioned: &std::collections::HashMap<String, Rect>,
    row: Rect,
) -> Vec<(String, Rect)> {
    let mut ordered = nodes.to_vec();
    ordered.sort_by(|left, right| {
        genealogy_role_order(left.role)
            .cmp(&genealogy_role_order(right.role))
            .then_with(|| left.name.cmp(&right.name))
    });
    let ids = ordered
        .iter()
        .map(|node| node.id.as_str())
        .collect::<std::collections::HashSet<_>>();
    let mut unused = ids.clone();
    let mut units = Vec::<Vec<&GenealogyNode>>::new();
    for node in ordered {
        if !unused.remove(node.id.as_str()) {
            continue;
        }
        let partner = graph.edges.iter().find_map(|edge| {
            if edge.kind != GenealogyEdgeKind::Partner {
                return None;
            }
            let candidate = if edge.from == node.id {
                edge.to.as_str()
            } else if edge.to == node.id {
                edge.from.as_str()
            } else {
                return None;
            };
            (ids.contains(candidate) && unused.contains(candidate)).then_some(candidate)
        });
        let mut unit = vec![node];
        if let Some(partner_id) = partner
            && let Some(partner) = nodes.iter().copied().find(|node| node.id == partner_id)
        {
            unused.remove(partner_id);
            unit.push(partner);
            unit.sort_by(|left, right| {
                let left_focus = left.role == GenealogyRole::Focus;
                let right_focus = right.role == GenealogyRole::Focus;
                right_focus
                    .cmp(&left_focus)
                    .then_with(|| left.name.cmp(&right.name))
            });
        }
        units.push(unit);
    }

    let node_gap = 6.0_f32;
    let unit_gap = 12.0_f32;
    let node_count = nodes.len().max(1);
    let node_width = ((row.width()
        - node_gap * units.iter().filter(|unit| unit.len() > 1).count() as f32
        - unit_gap * units.len().saturating_sub(1) as f32)
        / node_count as f32)
        .clamp(54.0, 126.0);
    let parent_anchor = |unit: &[&GenealogyNode]| {
        let parents = unit
            .iter()
            .flat_map(|node| {
                graph
                    .edges
                    .iter()
                    .filter(move |edge| {
                        edge.kind == GenealogyEdgeKind::ParentChild && edge.to == node.id
                    })
                    .filter_map(|edge| positioned.get(&edge.from).map(Rect::center))
            })
            .collect::<Vec<_>>();
        (!parents.is_empty())
            .then(|| parents.iter().map(|point| point.x).sum::<f32>() / parents.len() as f32)
    };
    let unit_count = units.len().max(1);
    let mut anchored = units
        .into_iter()
        .enumerate()
        .map(|(index, unit)| {
            let fallback = row.left() + row.width() * (index as f32 + 0.5) / unit_count as f32;
            let anchor = if unit.iter().any(|node| node.role == GenealogyRole::Focus) {
                row.center().x
            } else if unit.iter().all(|node| node.role == GenealogyRole::Sibling) {
                row.center().x - row.width() * 0.30
            } else {
                parent_anchor(&unit).unwrap_or(fallback)
            };
            (anchor, unit)
        })
        .collect::<Vec<_>>();
    anchored.sort_by(|left, right| {
        left.0
            .total_cmp(&right.0)
            .then_with(|| genealogy_birth_order(left.1[0]).cmp(&genealogy_birth_order(right.1[0])))
            .then_with(|| left.1[0].name.cmp(&right.1[0].name))
    });

    let mut placements = Vec::<(f32, f32, Vec<&GenealogyNode>)>::new();
    let mut cursor = row.left();
    let mut clusters = Vec::<(f32, Vec<Vec<&GenealogyNode>>)>::new();
    for (anchor, unit) in anchored {
        if let Some((cluster_anchor, cluster_units)) = clusters.last_mut()
            && (anchor - *cluster_anchor).abs() <= 1.0
        {
            cluster_units.push(unit);
        } else {
            clusters.push((anchor, vec![unit]));
        }
    }
    for (anchor, cluster_units) in clusters {
        let widths = cluster_units
            .iter()
            .map(|unit| {
                node_width * unit.len() as f32 + node_gap * unit.len().saturating_sub(1) as f32
            })
            .collect::<Vec<_>>();
        let cluster_width =
            widths.iter().sum::<f32>() + unit_gap * cluster_units.len().saturating_sub(1) as f32;
        let mut start = (anchor - cluster_width * 0.5).max(cursor);
        for (unit, width) in cluster_units.into_iter().zip(widths) {
            placements.push((start, width, unit));
            start += width + unit_gap;
        }
        cursor = start;
    }
    if let Some((start, width, _)) = placements.last() {
        let overflow = (*start + *width - row.right()).max(0.0);
        if overflow > 0.0 {
            for placement in &mut placements {
                placement.0 -= overflow;
            }
        }
    }
    if let Some((start, _, _)) = placements.first() {
        let underflow = (row.left() - *start).max(0.0);
        if underflow > 0.0 {
            for placement in &mut placements {
                placement.0 += underflow;
            }
        }
    }

    let mut result = Vec::with_capacity(nodes.len());
    for (start, _, unit) in placements {
        let mut x = start;
        for node in unit {
            result.push((
                node.id.clone(),
                Rect::from_min_size(Pos2::new(x, row.top()), Vec2::new(node_width, row.height())),
            ));
            x += node_width + node_gap;
        }
    }
    result
}

fn genealogy_birth_order(node: &GenealogyNode) -> (i64, &str) {
    let year = node.birth.trim().parse::<i64>().unwrap_or(i64::MAX);
    (year, node.name.as_str())
}

fn genealogy_graph_ui(
    ui: &mut egui::Ui,
    language: Language,
    colors: theme::Palette,
    graph: &GenealogyGraph,
    collapsed: &mut std::collections::HashSet<String>,
) -> Option<String> {
    collapsed.retain(|id| graph.nodes.iter().any(|node| &node.id == id));
    let mut hidden = std::collections::HashSet::new();
    let mut frontier = collapsed.iter().cloned().collect::<Vec<_>>();
    while let Some(parent) = frontier.pop() {
        for edge in graph
            .edges
            .iter()
            .filter(|edge| edge.kind == GenealogyEdgeKind::ParentChild && edge.from == parent)
        {
            if hidden.insert(edge.to.clone()) {
                frontier.push(edge.to.clone());
            }
        }
    }
    for id in collapsed.iter() {
        hidden.remove(id);
    }
    let mut generations = std::collections::BTreeMap::<i32, Vec<&GenealogyNode>>::new();
    for node in graph.nodes.iter().filter(|node| !hidden.contains(&node.id)) {
        generations.entry(node.generation).or_default().push(node);
    }
    let height = (generations.len() as f32 * 98.0 + 4.0).clamp(104.0, 860.0);
    let (canvas, _) =
        ui.allocate_exact_size(Vec2::new(ui.available_width(), height), Sense::hover());
    let mut node_rects = std::collections::HashMap::<String, Rect>::new();
    let mut y = canvas.top() + 2.0;
    for (generation, nodes) in &generations {
        ui.painter().text(
            Pos2::new(canvas.left() + 2.0, y + 6.0),
            Align2::LEFT_CENTER,
            if graph.linguistic_view {
                language_lineage_level_label(language, *generation).to_owned()
            } else {
                genealogy_generation_label(language, *generation, graph.family_view)
            },
            scaled_font_id(ui, 8.5),
            colors.muted,
        );
        y += 15.0;
        let row_rect = Rect::from_min_size(
            Pos2::new(canvas.left() + 2.0, y),
            Vec2::new((canvas.width() - 4.0).max(1.0), 60.0),
        );
        for (id, rect) in genealogy_generation_layout(graph, nodes, &node_rects, row_rect) {
            node_rects.insert(id, rect);
        }
        y += 82.0;
    }
    for edge in graph
        .edges
        .iter()
        .filter(|edge| edge.kind != GenealogyEdgeKind::ParentChild)
    {
        let (Some(from), Some(to)) = (node_rects.get(&edge.from), node_rects.get(&edge.to)) else {
            continue;
        };
        let (start, end) = if from.center().x <= to.center().x {
            (
                Pos2::new(from.right(), from.center().y),
                Pos2::new(to.left(), to.center().y),
            )
        } else {
            (
                Pos2::new(from.left(), from.center().y),
                Pos2::new(to.right(), to.center().y),
            )
        };
        let color = if edge.kind == GenealogyEdgeKind::Partner {
            colors.accent
        } else {
            colors.border
        };
        ui.painter()
            .line_segment([start, end], Stroke::new(1.8, color));
        ui.painter()
            .circle_filled((start + end.to_vec2()) * 0.5, 2.4, color);
    }
    for edge in graph
        .edges
        .iter()
        .filter(|edge| edge.kind == GenealogyEdgeKind::ParentChild)
    {
        let Some(end_rect) = node_rects.get(&edge.to) else {
            continue;
        };
        let parent_ids = genealogy_parent_couple(graph, &edge.from, &edge.to);
        if parent_ids
            .as_ref()
            .is_some_and(|(_, partner)| edge.from.as_str() > *partner)
        {
            continue;
        }
        let start = if let Some((parent, partner)) = parent_ids {
            let (Some(parent_rect), Some(partner_rect)) =
                (node_rects.get(parent), node_rects.get(partner))
            else {
                continue;
            };
            Pos2::new(
                (parent_rect.center().x + partner_rect.center().x) * 0.5,
                parent_rect.bottom().max(partner_rect.bottom()),
            )
        } else if let Some(parent_rect) = node_rects.get(&edge.from) {
            parent_rect.center_bottom()
        } else {
            continue;
        };
        let end = end_rect.center_top();
        let middle = (start.y + end.y) * 0.5;
        ui.painter().line_segment(
            [start, Pos2::new(start.x, middle)],
            Stroke::new(1.2, colors.border),
        );
        ui.painter().line_segment(
            [Pos2::new(start.x, middle), Pos2::new(end.x, middle)],
            Stroke::new(1.2, colors.border),
        );
        ui.painter().line_segment(
            [Pos2::new(end.x, middle), end],
            Stroke::new(1.2, colors.border),
        );
    }
    let parent_ids = graph
        .edges
        .iter()
        .filter(|edge| edge.kind == GenealogyEdgeKind::ParentChild)
        .map(|edge| edge.from.as_str())
        .collect::<std::collections::HashSet<_>>();
    let mut navigate = None;
    for node in graph.nodes.iter().filter(|node| !hidden.contains(&node.id)) {
        let Some(rect) = node_rects.get(&node.id).copied() else {
            continue;
        };
        let response = ui.interact(
            rect,
            ui.id().with(("genealogy-node", &node.id)),
            if node.article_id.is_some() {
                Sense::click()
            } else {
                Sense::hover()
            },
        );
        let focus = node.role == GenealogyRole::Focus;
        ui.painter().rect(
            rect,
            CornerRadius::same(4),
            if focus {
                colors.selected
            } else {
                colors.surface
            },
            Stroke::new(
                if focus { 1.8 } else { 1.0 },
                if focus { colors.accent } else { colors.border },
            ),
            egui::StrokeKind::Inside,
        );
        ui.painter().text(
            Pos2::new(rect.center().x, rect.top() + 10.0),
            Align2::CENTER_CENTER,
            if graph.linguistic_view {
                language_lineage_category_label(language, &node.birth)
            } else if graph.family_view {
                ""
            } else if let Some(relationship_type) = node.relationship_type.as_deref() {
                relationship_type_label(language, relationship_type)
            } else {
                genealogy_role_label(language, node.role)
            },
            scaled_font_id(ui, 7.5),
            if focus { colors.accent } else { colors.muted },
        );
        ui.painter().text(
            Pos2::new(rect.center().x, rect.center().y),
            Align2::CENTER_CENTER,
            &node.name,
            scaled_font_id(ui, 10.2),
            colors.title,
        );
        ui.painter().text(
            Pos2::new(rect.center().x, rect.bottom() - 9.0),
            Align2::CENTER_CENTER,
            if graph.linguistic_view {
                if node.death.trim().is_empty() {
                    "-".to_owned()
                } else {
                    node.death.clone()
                }
            } else {
                format!("{} - {}", node.birth, node.death)
            },
            scaled_font_id(ui, 7.5),
            colors.muted,
        );
        let mut collapse_clicked = false;
        if parent_ids.contains(node.id.as_str()) {
            let button = Rect::from_min_size(
                Pos2::new(rect.right() - 17.0, rect.top() + 3.0),
                Vec2::splat(14.0),
            );
            let collapse_response = ui.interact(
                button,
                ui.id().with(("genealogy-collapse", &node.id)),
                Sense::click(),
            );
            ui.painter().rect_filled(button, 3.0, colors.panel_alt);
            ui.painter().text(
                button.center(),
                Align2::CENTER_CENTER,
                if collapsed.contains(&node.id) {
                    "+"
                } else {
                    "−"
                },
                scaled_font_id(ui, 10.0),
                colors.text,
            );
            if collapse_response.clicked() {
                collapse_clicked = true;
                if !collapsed.remove(&node.id) {
                    collapsed.insert(node.id.clone());
                }
            }
        }
        if response.clicked() && !collapse_clicked && !focus && node.article_id.is_some() {
            navigate = Some(node.name.clone());
        }
    }
    navigate
}

fn genealogy_role_order(role: GenealogyRole) -> u8 {
    match role {
        GenealogyRole::Focus => 0,
        GenealogyRole::Partner => 1,
        GenealogyRole::Sibling => 2,
        GenealogyRole::Important => 3,
        GenealogyRole::Member => 4,
    }
}

fn genealogy_role_label(language: Language, role: GenealogyRole) -> &'static str {
    match role {
        GenealogyRole::Focus => tr(language, "중심 인물", "Focus"),
        GenealogyRole::Partner => tr(language, "배우자", "Partner"),
        GenealogyRole::Sibling => tr(language, "형제자매", "Sibling"),
        GenealogyRole::Important => tr(language, "주요 구성원", "Key Member"),
        GenealogyRole::Member => tr(language, "구성원", "Member"),
    }
}

fn genealogy_generation_label(language: Language, generation: i32, family: bool) -> String {
    if family {
        return format!("{} {}", tr(language, "세대", "Generation"), generation + 1);
    }
    match generation.cmp(&0) {
        std::cmp::Ordering::Less => format!(
            "{} {}",
            tr(language, "선조", "Ancestors"),
            generation.unsigned_abs()
        ),
        std::cmp::Ordering::Equal => tr(language, "현재 세대", "Current Generation").to_owned(),
        std::cmp::Ordering::Greater => {
            format!("{} {}", tr(language, "후손", "Descendants"), generation)
        }
    }
}

fn territory_inset(
    ui: &mut egui::Ui,
    world: &LoadedWorld,
    article: &Article,
    colors: theme::Palette,
    _year: i32,
) {
    let owner = article.source_entity_id.as_deref().and_then(|id| {
        world
            .map
            .factions
            .iter()
            .position(|faction| faction.id == id)
    });
    let (rect, _) = ui.allocate_exact_size(Vec2::new(ui.available_width(), 112.0), Sense::hover());
    ui.painter().rect_filled(rect, 4.0, colors.panel_alt);
    if let Some(owner) = owner {
        let cell = Vec2::new(
            rect.width() / world.map.grid_width.max(1) as f32,
            rect.height() / world.map.grid_height.max(1) as f32,
        );
        for y in 0..world.map.grid_height {
            let mut x = 0;
            while x < world.map.grid_width {
                let index = y * world.map.grid_width + x;
                if world.map.territory_owners.get(index).copied() != Some(owner as i32) {
                    x += 1;
                    continue;
                }
                let mut end = x + 1;
                while end < world.map.grid_width
                    && world
                        .map
                        .territory_owners
                        .get(y * world.map.grid_width + end)
                        .copied()
                        == Some(owner as i32)
                {
                    end += 1;
                }
                ui.painter().rect_filled(
                    Rect::from_min_max(
                        Pos2::new(
                            rect.left() + x as f32 * cell.x,
                            rect.top() + y as f32 * cell.y,
                        ),
                        Pos2::new(
                            rect.left() + end as f32 * cell.x,
                            rect.top() + (y + 1) as f32 * cell.y,
                        ),
                    ),
                    0.0,
                    colors.accent.gamma_multiply(0.72),
                );
                x = end;
            }
        }
    } else {
        ui.painter().text(
            rect.center(),
            Align2::CENTER_CENTER,
            "-",
            FontId::proportional(16.0),
            colors.muted,
        );
    }
    ui.painter().rect_stroke(
        rect,
        4.0,
        Stroke::new(1.0, colors.border),
        egui::StrokeKind::Inside,
    );
}

fn disease_effect_panel(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    colors: theme::Palette,
    article: &Article,
) {
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(ui, tr(language, "증상", "Symptoms"), colors);
        let profile = article.profiles.disease.as_ref();
        let symptoms = profile
            .and_then(|value| value.get("symptoms"))
            .map(|value| json_list(Some(value)))
            .filter(|value| value != "-")
            .or_else(|| {
                profile
                    .and_then(|value| value.get("symptomNotes"))
                    .map(|value| json_text(Some(value)))
            })
            .unwrap_or_else(|| "-".to_owned());
        let aftereffects = profile
            .and_then(|value| {
                value
                    .get("aftereffects")
                    .or_else(|| value.get("disabilities"))
            })
            .map(|value| json_list(Some(value)))
            .unwrap_or_else(|| "-".to_owned());
        let debuffs = parse_disease_debuffs(profile.and_then(|value| value.get("debuffs")));
        let debuff_text = if debuffs.is_empty() {
            "-".to_owned()
        } else {
            debuffs
                .iter()
                .map(|debuff| disease_debuff_summary(language, debuff))
                .collect::<Vec<_>>()
                .join(", ")
        };
        info_row(ui, tr(language, "증상", "Symptoms"), symptoms, false);
        info_row(
            ui,
            tr(language, "후유증", "Aftereffects"),
            aftereffects,
            false,
        );
        info_row(ui, tr(language, "디버프", "Debuffs"), debuff_text, false);
    });
}

fn profile_sections(profile: Option<&serde_json::Value>, key: &str) -> Vec<ProfileSection> {
    profile
        .and_then(|value| value.get(key))
        .cloned()
        .and_then(|value| serde_json::from_value(value).ok())
        .unwrap_or_default()
}

fn profile_section_order(sections: &[ProfileSection]) -> Vec<(String, usize)> {
    fn visit(
        sections: &[ProfileSection],
        parent_id: Option<&str>,
        depth: usize,
        visited: &mut std::collections::HashSet<String>,
        output: &mut Vec<(String, usize)>,
    ) {
        let mut children = sections
            .iter()
            .filter(|section| section.parent_id.as_deref() == parent_id)
            .collect::<Vec<_>>();
        children.sort_by_key(|section| section.order);
        for child in children {
            if !visited.insert(child.id.clone()) {
                continue;
            }
            output.push((child.id.clone(), depth));
            visit(sections, Some(&child.id), depth + 1, visited, output);
        }
    }
    let mut visited = std::collections::HashSet::new();
    let mut output = Vec::new();
    visit(sections, None, 0, &mut visited, &mut output);
    for section in sections {
        if visited.insert(section.id.clone()) {
            output.push((section.id.clone(), 0));
        }
    }
    output
}

fn religion_profile_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    target: &mut Option<serde_json::Value>,
    references: &[UReferenceOption],
    display_calendar: &CalendarProfile,
    orbital_period_days: f64,
    calendar_options: &[(String, CalendarProfile)],
) {
    let colors = theme::palette(dark);
    let profile = json_object_mut(target);
    theme::surface_frame(dark).show(ui, |ui| {
        section_title(
            ui,
            tr(language, "종교 정보 편집", "Edit Religion Information"),
            colors,
        );
        editable_json_text(
            ui,
            tr(language, "계통", "Tradition / Lineage"),
            profile,
            "traditionLineage",
        );
        reference_or_custom_editor(
            ui,
            language,
            profile,
            "founderArticleId",
            "founder",
            tr(language, "창시자", "Founder"),
            references,
            &["person"],
        );
        calendar_date_popup_editor(
            ui,
            language,
            tr(language, "창시 시기", "Founding Period"),
            profile,
            "foundingPeriod",
            display_calendar,
            orbital_period_days,
            calendar_options,
        );
        reference_or_custom_editor(
            ui,
            language,
            profile,
            "holyCityArticleId",
            "holyCity",
            tr(language, "성도", "Holy City"),
            references,
            &["location", "city"],
        );
        reference_or_text_list_editor(
            ui,
            language,
            profile,
            "distributionRegionArticleIds",
            "distributionRegions",
            tr(language, "분포 지역", "Distribution Regions"),
            references,
            &["location", "city", "village", "country"],
        );
        editable_json_text(
            ui,
            tr(language, "신도 규모", "Adherent Population"),
            profile,
            "adherentPopulation",
        );
        reference_or_text_list_editor(
            ui,
            language,
            profile,
            "religiousInstitutionArticleIds",
            "religiousInstitutions",
            tr(language, "종교 기관", "Religious Institutions"),
            references,
            &["organization"],
        );
        reference_or_text_list_editor(
            ui,
            language,
            profile,
            "scriptureArticleIds",
            "scriptures",
            tr(language, "경전", "Scriptures"),
            references,
            &["item"],
        );
        reference_or_text_list_editor(
            ui,
            language,
            profile,
            "denominationArticleIds",
            "majorDenominations",
            tr(language, "주요 종파", "Major Denominations"),
            references,
            &["religion", "organization"],
        );
    });

    let mut sections = profile_sections(
        Some(&serde_json::Value::Object(profile.clone())),
        "doctrineSections",
    );
    let mut add_parent: Option<Option<String>> = None;
    let mut remove_id: Option<String> = None;
    let mut move_request: Option<(String, i32)> = None;
    theme::surface_frame(dark).show(ui, |ui| {
        ui.horizontal(|ui| {
            section_title(ui, tr(language, "교리", "Doctrine"), colors);
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui
                    .add_sized([30.0, 26.0], egui::Button::new("＋"))
                    .on_hover_text(tr(language, "최상위 교리 추가", "Add top-level doctrine"))
                    .clicked()
                {
                    add_parent = Some(None);
                }
            });
        });
        ui.separator();
        let order = profile_section_order(&sections);
        if order.is_empty() {
            ui.label(RichText::new("-").color(colors.muted));
        }
        for (id, depth) in order {
            let Some(index) = sections.iter().position(|section| section.id == id) else {
                continue;
            };
            let parent_id = sections[index].parent_id.clone();
            let mut siblings = sections
                .iter()
                .filter(|section| section.parent_id == parent_id)
                .collect::<Vec<_>>();
            siblings.sort_by_key(|section| section.order);
            let sibling_index = siblings
                .iter()
                .position(|section| section.id == id)
                .unwrap_or(0);
            let sibling_count = siblings.len();
            ui.horizontal(|ui| {
                ui.add_space(depth as f32 * 16.0);
                ui.add_sized(
                    [(ui.available_width() - 124.0).max(90.0), 27.0],
                    egui::TextEdit::singleline(&mut sections[index].title),
                );
                if ui
                    .add_sized([28.0, 27.0], egui::Button::new("＋"))
                    .on_hover_text(tr(language, "하위 교리 추가", "Add child doctrine"))
                    .clicked()
                {
                    add_parent = Some(Some(id.clone()));
                }
                if ui
                    .add_enabled(sibling_index > 0, egui::Button::new("↑"))
                    .clicked()
                {
                    move_request = Some((id.clone(), -1));
                }
                if ui
                    .add_enabled(sibling_index + 1 < sibling_count, egui::Button::new("↓"))
                    .clicked()
                {
                    move_request = Some((id.clone(), 1));
                }
                if ui
                    .add_sized(
                        [28.0, 27.0],
                        egui::Button::new(RichText::new("×").color(colors.danger)),
                    )
                    .on_hover_text(tr(language, "교리 삭제", "Delete doctrine"))
                    .clicked()
                {
                    remove_id = Some(id.clone());
                }
            });
            ui.horizontal(|ui| {
                ui.add_space(depth as f32 * 16.0);
                ui.add_sized(
                    [ui.available_width(), 58.0],
                    egui::TextEdit::multiline(&mut sections[index].content),
                );
            });
        }
    });
    if let Some(parent_id) = add_parent {
        let order = sections
            .iter()
            .filter(|section| section.parent_id == parent_id)
            .count();
        let mut serial = sections.len() + 1;
        let id = loop {
            let candidate = format!("doctrine-{serial}");
            if sections.iter().all(|section| section.id != candidate) {
                break candidate;
            }
            serial += 1;
        };
        sections.push(ProfileSection {
            id,
            title: tr(language, "새 항목", "New Section").to_owned(),
            content: String::new(),
            parent_id,
            order,
        });
    }
    if let Some((id, direction)) = move_request {
        if let Some(section) = sections.iter().find(|section| section.id == id).cloned() {
            let mut siblings = sections
                .iter()
                .filter(|candidate| candidate.parent_id == section.parent_id)
                .map(|candidate| candidate.id.clone())
                .collect::<Vec<_>>();
            siblings.sort_by_key(|candidate| {
                sections
                    .iter()
                    .find(|section| section.id == *candidate)
                    .map(|section| section.order)
                    .unwrap_or(0)
            });
            if let Some(index) = siblings.iter().position(|candidate| candidate == &id) {
                let target_index = index as i32 + direction;
                if target_index >= 0 && (target_index as usize) < siblings.len() {
                    let target_id = siblings[target_index as usize].clone();
                    let target_order = sections
                        .iter()
                        .find(|candidate| candidate.id == target_id)
                        .map(|candidate| candidate.order)
                        .unwrap_or(section.order);
                    for candidate in &mut sections {
                        if candidate.id == id {
                            candidate.order = target_order;
                        }
                        if candidate.id == target_id {
                            candidate.order = section.order;
                        }
                    }
                }
            }
        }
    }
    if let Some(remove_id) = remove_id {
        let mut removed = std::collections::HashSet::from([remove_id]);
        loop {
            let previous = removed.len();
            for section in &sections {
                if section
                    .parent_id
                    .as_ref()
                    .is_some_and(|parent| removed.contains(parent))
                {
                    removed.insert(section.id.clone());
                }
            }
            if previous == removed.len() {
                break;
            }
        }
        sections.retain(|section| !removed.contains(&section.id));
    }
    profile.insert(
        "doctrineSections".to_owned(),
        serde_json::to_value(sections).unwrap_or_else(|_| serde_json::Value::Array(Vec::new())),
    );
    profile.remove("doctrine");
}

