fn profile_sections_editor(
    ui: &mut egui::Ui,
    dark: bool,
    language: Language,
    profile: &mut serde_json::Map<String, serde_json::Value>,
    key: &str,
    title: &str,
) {
    let colors = theme::palette(dark);
    let mut sections = profile_sections(Some(&serde_json::Value::Object(profile.clone())), key);
    let mut add_parent: Option<Option<String>> = None;
    let mut remove_id: Option<String> = None;
    let mut move_request: Option<(String, i32)> = None;
    theme::surface_frame(dark).show(ui, |ui| {
        ui.horizontal(|ui| {
            section_title(ui, title, colors);
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui
                    .add_sized([30.0, 26.0], egui::Button::new("＋"))
                    .on_hover_text(tr(language, "최상위 항목 추가", "Add top-level section"))
                    .clicked()
                {
                    add_parent = Some(None);
                }
            });
        });
        ui.separator();
        let order = profile_section_order(&sections);
        if order.is_empty() {
            ui.label(RichText::new("-").color(colors.muted));
        }
        for (id, depth) in order {
            let Some(index) = sections.iter().position(|section| section.id == id) else {
                continue;
            };
            let parent_id = sections[index].parent_id.clone();
            let mut siblings = sections
                .iter()
                .filter(|section| section.parent_id == parent_id)
                .collect::<Vec<_>>();
            siblings.sort_by_key(|section| section.order);
            let sibling_index = siblings
                .iter()
                .position(|section| section.id == id)
                .unwrap_or(0);
            let sibling_count = siblings.len();
            ui.horizontal(|ui| {
                ui.add_space(depth as f32 * 16.0);
                ui.add_sized(
                    [(ui.available_width() - 124.0).max(90.0), 27.0],
                    egui::TextEdit::singleline(&mut sections[index].title),
                );
                if ui
                    .add_sized([28.0, 27.0], egui::Button::new("＋"))
                    .on_hover_text(tr(language, "하위 항목 추가", "Add child section"))
                    .clicked()
                {
                    add_parent = Some(Some(id.clone()));
                }
                if ui
                    .add_enabled(sibling_index > 0, egui::Button::new("↑"))
                    .clicked()
                {
                    move_request = Some((id.clone(), -1));
                }
                if ui
                    .add_enabled(sibling_index + 1 < sibling_count, egui::Button::new("↓"))
                    .clicked()
                {
                    move_request = Some((id.clone(), 1));
                }
                if ui
                    .add_sized(
                        [28.0, 27.0],
                        egui::Button::new(RichText::new("×").color(colors.danger)),
                    )
                    .on_hover_text(tr(language, "항목 삭제", "Delete section"))
                    .clicked()
                {
                    remove_id = Some(id.clone());
                }
            });
            ui.horizontal(|ui| {
                ui.add_space(depth as f32 * 16.0);
                ui.add_sized(
                    [ui.available_width(), 58.0],
                    egui::TextEdit::multiline(&mut sections[index].content),
                );
            });
        }
    });
    if let Some(parent_id) = add_parent {
        let order = sections
            .iter()
            .filter(|section| section.parent_id == parent_id)
            .count();
        let mut serial = sections.len() + 1;
        let id = loop {
            let candidate = format!("profile-section-{serial}");
            if sections.iter().all(|section| section.id != candidate) {
                break candidate;
            }
            serial += 1;
        };
        sections.push(ProfileSection {
            id,
            title: tr(language, "새 항목", "New Section").to_owned(),
            content: String::new(),
            parent_id,
            order,
        });
    }
    if let Some((id, direction)) = move_request {
        if let Some(section) = sections.iter().find(|section| section.id == id).cloned() {
            let mut siblings = sections
                .iter()
                .filter(|candidate| candidate.parent_id == section.parent_id)
                .map(|candidate| candidate.id.clone())
                .collect::<Vec<_>>();
            siblings.sort_by_key(|candidate| {
                sections
                    .iter()
                    .find(|section| section.id == *candidate)
                    .map(|section| section.order)
                    .unwrap_or(0)
            });
            if let Some(index) = siblings.iter().position(|candidate| candidate == &id) {
                let target_index = index as i32 + direction;
                if target_index >= 0 && (target_index as usize) < siblings.len() {
                    let target_id = siblings[target_index as usize].clone();
                    let target_order = sections
                        .iter()
                        .find(|candidate| candidate.id == target_id)
                        .map(|candidate| candidate.order)
                        .unwrap_or(section.order);
                    for candidate in &mut sections {
                        if candidate.id == id {
                            candidate.order = target_order;
                        }
                        if candidate.id == target_id {
                            candidate.order = section.order;
                        }
                    }
                }
            }
        }
    }
    if let Some(remove_id) = remove_id {
        let mut removed = std::collections::HashSet::from([remove_id]);
        loop {
            let previous = removed.len();
            for section in &sections {
                if section
                    .parent_id
                    .as_ref()
                    .is_some_and(|parent| removed.contains(parent))
                {
                    removed.insert(section.id.clone());
                }
            }
            if previous == removed.len() {
                break;
            }
        }
        sections.retain(|section| !removed.contains(&section.id));
    }
    profile.insert(
        key.to_owned(),
        serde_json::to_value(sections).unwrap_or_else(|_| serde_json::Value::Array(Vec::new())),
    );
}

