fn stat_box(ui: &mut egui::Ui, label: &str, value: &str, colors: theme::Palette) {
    let (rect, _) = ui.allocate_exact_size(Vec2::new(72.0, 50.0), Sense::hover());
    ui.painter().rect(
        rect,
        CornerRadius::same(5),
        colors.surface,
        Stroke::new(1.0, colors.border),
        egui::StrokeKind::Inside,
    );
    ui.painter().line_segment(
        [
            Pos2::new(rect.left(), rect.center().y),
            Pos2::new(rect.right(), rect.center().y),
        ],
        Stroke::new(1.0, colors.border),
    );
    ui.painter().text(
        Pos2::new(rect.center().x, rect.top() + 12.5),
        Align2::CENTER_CENTER,
        label,
        scaled_font_id(ui, 9.0),
        colors.muted,
    );
    ui.painter().text(
        Pos2::new(rect.center().x, rect.bottom() - 12.5),
        Align2::CENTER_CENTER,
        value,
        scaled_font_id(ui, 12.0),
        colors.title,
    );
}

fn relationship_stat(
    ui: &mut egui::Ui,
    width: f32,
    kind: &str,
    source: &str,
    value: &str,
    colors: theme::Palette,
) {
    let (rect, _) = ui.allocate_exact_size(Vec2::new(width, 72.0), Sense::hover());
    ui.painter().rect(
        rect,
        CornerRadius::same(5),
        colors.surface,
        Stroke::new(1.0, colors.border),
        egui::StrokeKind::Inside,
    );
    for ratio in [1.0 / 3.0, 2.0 / 3.0] {
        let y = rect.top() + rect.height() * ratio;
        ui.painter().line_segment(
            [Pos2::new(rect.left(), y), Pos2::new(rect.right(), y)],
            Stroke::new(1.0, colors.border),
        );
    }
    for (index, text) in [kind, source, value].into_iter().enumerate() {
        ui.painter().text(
            Pos2::new(
                rect.center().x,
                rect.top() + rect.height() * (index as f32 + 0.5) / 3.0,
            ),
            Align2::CENTER_CENTER,
            text,
            scaled_font_id(ui, if index == 2 { 12.0 } else { 9.0 }),
            if index == 2 {
                colors.title
            } else {
                colors.muted
            },
        );
    }
}

