fn ownership_date_editor(
    ui: &mut egui::Ui,
    language: Language,
    display_calendar: &CalendarProfile,
    orbital_period_days: f64,
    calendar_options: &[(String, CalendarProfile)],
    period: &mut ItemOwnershipPeriod,
    start: bool,
) {
    let (key, label) = if start {
        ("start", tr(language, "시작", "Start"))
    } else {
        ("end", tr(language, "종료", "End"))
    };
    let mut value = serde_json::Map::new();
    let specified = if start {
        period.start_specified
    } else {
        period.end_year.is_some()
    };
    let year = if start {
        Some(period.start_year)
    } else {
        period.end_year
    };
    let absolute = if start {
        period.start_absolute_day
    } else {
        period.end_absolute_day
    };
    let calendar_id = if start {
        period.start_calendar_id.as_ref()
    } else {
        period.end_calendar_id.as_ref()
    };
    let show_time = if start {
        period.start_show_time
    } else {
        period.end_show_time
    };
    if specified {
        let year = year.unwrap_or_default();
        value.insert(key.to_owned(), serde_json::json!(year));
        value.insert(
            format!("{key}AbsoluteDay"),
            serde_json::json!(absolute.unwrap_or_else(|| calendar::absolute_day(
                TimelineMoment::new(year, 0.0),
                orbital_period_days
            ))),
        );
    }
    if let Some(calendar_id) = calendar_id {
        value.insert(
            format!("{key}CalendarId"),
            serde_json::Value::String(calendar_id.clone()),
        );
    }
    value.insert(format!("{key}ShowTime"), serde_json::json!(show_time));
    u_fields::u_date_json(
        ui,
        language,
        ("ownership-date", &period.id, start),
        label,
        &mut value,
        key,
        display_calendar,
        orbital_period_days,
        calendar_options,
    );
    let absolute_key = format!("{key}AbsoluteDay");
    let calendar_key = format!("{key}CalendarId");
    let show_time_key = format!("{key}ShowTime");
    let result_absolute = value.get(&absolute_key).and_then(serde_json::Value::as_f64);
    let result_moment = result_absolute
        .map(|day| calendar::timeline_moment_from_absolute_day(day, orbital_period_days));
    if start {
        period.start_specified = result_moment.is_some();
        period.start_absolute_day = result_absolute;
        period.start_year = result_moment
            .map(|moment| moment.world_year)
            .unwrap_or_default();
        period.start_calendar_id = value
            .get(&calendar_key)
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        period.start_show_time = value
            .get(&show_time_key)
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
    } else {
        period.end_absolute_day = result_absolute;
        period.end_year = result_moment.map(|moment| moment.world_year);
        period.end_calendar_id = value
            .get(&calendar_key)
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned);
        period.end_show_time = value
            .get(&show_time_key)
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
    }
}

fn ownership_label(world: &LoadedWorld, period: &ItemOwnershipPeriod) -> String {
    world
        .articles
        .iter()
        .find(|article| article.id == period.owner_id)
        .map(|article| article.title.clone())
        .or_else(|| {
            world
                .maps
                .iter()
                .chain(std::iter::once(&world.map))
                .flat_map(|map| map.factions.iter())
                .find(|faction| faction.id == period.owner_id)
                .map(|faction| faction.name.clone())
        })
        .unwrap_or_else(|| {
            if period.owner_id.is_empty() {
                "-".to_owned()
            } else {
                period.owner_id.clone()
            }
        })
}

fn ownership_validation_errors(
    periods: &[ItemOwnershipPeriod],
) -> std::collections::HashSet<String> {
    let mut errors = std::collections::HashSet::new();
    for period in periods {
        if period.owner_id.trim().is_empty()
            || !period.start_specified
            || period.end_year.is_some_and(|end| end < period.start_year)
        {
            errors.insert(period.id.clone());
        }
    }
    let mut chronological = periods.iter().collect::<Vec<_>>();
    chronological.sort_by_key(|period| period.start_year);
    for pair in chronological.windows(2) {
        let previous = pair[0];
        let next = pair[1];
        if previous.end_year.is_none_or(|end| end >= next.start_year) {
            errors.insert(previous.id.clone());
            errors.insert(next.id.clone());
        }
    }
    errors
}

fn next_ownership_id(periods: &[ItemOwnershipPeriod]) -> String {
    let mut serial = periods.len() + 1;
    loop {
        let candidate = format!("ownership-{serial}");
        if periods.iter().all(|period| period.id != candidate) {
            return candidate;
        }
        serial += 1;
    }
}

