    #[test]
    fn native_project_save_round_trips_world_and_editor_data() {
        let world = LoadedWorld::load_demo(Language::English).expect("English demo must load");
        let flag = HeraldryDesign::flag();
        let emblem = HeraldryDesign::emblem();
        let custom_entries = vec![(0usize, "Resolve".to_owned())];
        let save = NativeProjectSaveRef {
            format_version: "urdr-native-1.0",
            language: Language::English,
            active_map_source_id: None,
            world: &world,
            flag_design: &flag,
            emblem_design: &emblem,
            rpg_overrides: vec![RpgOverrideRecord {
                group: 0,
                entry: 0,
                name: "Vitality".to_owned(),
            }],
            rpg_custom_entries: &custom_entries,
            rpg_rule_set: &default_rpg_rule_set(),
            show_table_of_contents: false,
        };
        let encoded = serde_json::to_vec(&save).expect("native save must serialize");
        let decoded: NativeProjectSave =
            serde_json::from_slice(&encoded).expect("native save must deserialize");
        assert_eq!(decoded.format_version, "urdr-native-1.0");
        assert_eq!(decoded.language, Language::English);
        assert_eq!(decoded.world.title, world.title);
        assert!(decoded.world.rpg_enabled);
        assert_eq!(decoded.world.day_length_hours, 24.0);
        assert_eq!(decoded.world.orbital_period_days, world.orbital_period_days);
        assert_eq!(decoded.rpg_overrides[0].name, "Vitality");
        assert_eq!(decoded.flag_design.layers.len(), flag.layers.len());
        assert!(!decoded.show_table_of_contents);
    }

