    #[test]
    fn disease_debuff_targets_follow_active_rpg_definitions() {
        let overrides = std::collections::HashMap::from([((0usize, 0usize), "생명력".to_owned())]);
        let custom = vec![
            (0usize, "균형".to_owned()),
            (2usize, "주문 저항".to_owned()),
        ];
        let rules = migrate_legacy_rpg_rules(&overrides, &custom);
        let without_magic = active_rpg_definition_names(Language::Korean, false, &rules);
        assert!(without_magic.contains(&"생명력".to_owned()));
        assert!(without_magic.contains(&"균형".to_owned()));
        assert!(!without_magic.contains(&"마법력".to_owned()));
        assert!(!without_magic.contains(&"주문 저항".to_owned()));
        let with_magic = active_rpg_definition_names(Language::Korean, true, &rules);
        assert!(with_magic.contains(&"마법력".to_owned()));
        assert!(with_magic.contains(&"주문 저항".to_owned()));
    }

