    #[test]
    fn ownership_validation_rejects_reversed_and_overlapping_periods() {
        let valid = vec![
            ownership_test_period("a", "p1", 10, Some(19)),
            ownership_test_period("b", "p2", 20, None),
        ];
        assert!(ownership_validation_errors(&valid).is_empty());
        let invalid = vec![
            ownership_test_period("a", "p1", 10, Some(22)),
            ownership_test_period("b", "p2", 20, Some(18)),
        ];
        let errors = ownership_validation_errors(&invalid);
        assert!(errors.contains("a") && errors.contains("b"));
        assert_eq!(next_ownership_id(&valid), "ownership-3");
    }

    #[test]
    fn native_genealogy_assignment_moves_ownership_and_clears_private_graph() {
        let mut world = LoadedWorld::load_demo(Language::Korean).expect("Korean demo must load");
        let person_id = world
            .articles
            .iter()
            .find(|article| article.title == "세르마 라디엔")
            .map(|article| article.id.clone())
            .expect("private-lineage person");
        let family_id = "demo-family-silver-tide".to_owned();
        let person = world
            .articles
            .iter_mut()
            .find(|article| article.id == person_id)
            .expect("person");
        let profile = person
            .profiles
            .person
            .as_mut()
            .and_then(serde_json::Value::as_object_mut)
            .expect("person profile");
        assert!(profile.get("privateLineage").is_some());
        profile.insert(
            "familyArticleId".to_owned(),
            serde_json::Value::String(family_id.clone()),
        );
        synchronize_genealogy_after_edit(&mut world, &person_id, "person");
        let person = world
            .articles
            .iter()
            .find(|article| article.id == person_id)
            .expect("person after assignment");
        let profile = person
            .profiles
            .person
            .as_ref()
            .and_then(serde_json::Value::as_object)
            .expect("person profile after assignment");
        assert!(profile.get("privateLineage").is_none());
        assert_eq!(
            profile
                .get("familyArticleId")
                .and_then(serde_json::Value::as_str),
            Some(family_id.as_str())
        );
        let family = world
            .articles
            .iter()
            .find(|article| article.id == family_id)
            .expect("target family");
        assert!(
            family
                .profiles
                .family
                .as_ref()
                .and_then(|profile| profile.get("members"))
                .and_then(serde_json::Value::as_array)
                .is_some_and(|members| {
                    members.iter().any(|member| {
                        member.get("articleId").and_then(serde_json::Value::as_str)
                            == Some(person_id.as_str())
                    })
                })
        );
        let family = world
            .articles
            .iter_mut()
            .find(|article| article.id == family_id)
            .expect("target family mutable");
        remove_person_from_family_profile(
            family.profiles.family.as_mut().expect("family profile"),
            &person_id,
        );
        synchronize_genealogy_after_edit(&mut world, &family_id, "family");
        let person = world
            .articles
            .iter()
            .find(|article| article.id == person_id)
            .expect("person after removal");
        assert!(
            person
                .profiles
                .person
                .as_ref()
                .and_then(|profile| profile.get("familyArticleId"))
                .is_none()
        );
    }

    #[test]
    fn native_lineage_normalization_preserves_partners_and_rejects_parent_cycles() {
        let mut members = vec![
            serde_json::json!({ "id": "a", "name": "A", "parentIds": ["b"], "partnerIds": ["c"] }),
            serde_json::json!({ "id": "b", "name": "B", "parentIds": ["a"], "partnerIds": [] }),
            serde_json::json!({ "id": "c", "name": "C", "parentIds": [], "partnerIds": [] }),
        ];
        normalize_lineage_json_members(&mut members);
        let a_parents = json_string_ids(members[0].get("parentIds"));
        let b_parents = json_string_ids(members[1].get("parentIds"));
        assert!(!(a_parents.contains(&"b".to_owned()) && b_parents.contains(&"a".to_owned())));
        assert!(json_string_ids(members[2].get("partnerIds")).contains(&"a".to_owned()));
    }

