    #[test]
    fn environment_pin_rename_preserves_stable_coordinates() {
        let mut pins = vec![EnvironmentPin {
            id: "pin-a".to_owned(),
            name: "Old Name".to_owned(),
            point: Point { x: 12.5, y: 37.75 },
        }];
        let original_point = pins[0].point;
        assert!(rename_environment_pin(&mut pins, 0, " New Name "));
        assert_eq!(pins[0].name, "New Name");
        assert_eq!(pins[0].point.x, original_point.x);
        assert_eq!(pins[0].point.y, original_point.y);
        assert!(!rename_environment_pin(&mut pins, 0, "   "));
        assert_eq!(pins[0].point.x, original_point.x);
        assert_eq!(pins[0].point.y, original_point.y);
    }

    #[test]
    fn legacy_language_vocabulary_moves_to_project_dictionary_once() {
        let mut world = LoadedWorld::load_demo(Language::Korean).expect("demo");
        let language_index = world
            .articles
            .iter()
            .position(|article| article.category == "language")
            .expect("language article");
        let language_id = world.articles[language_index].id.clone();
        world
            .dictionaries
            .retain(|book| book.language_article_id != language_id);
        let profile = world.articles[language_index]
            .profiles
            .language
            .as_mut()
            .and_then(serde_json::Value::as_object_mut)
            .expect("language profile");
        profile.remove("languageType");
        profile.insert(
            "classification".to_owned(),
            serde_json::json!({ "languageType": "agglutinative" }),
        );
        profile.insert(
            "vocabulary".to_owned(),
            serde_json::json!([{
                "id": "legacy-word", "term": "ur", "pronunciation": "uɾ",
                "meaning": "world", "partOfSpeech": "noun", "etymology": "proto",
                "usageNote": "formal", "relatedTerms": ["urd"]
            }]),
        );

        world.migrate_language_document_data();
        let profile = world.articles[language_index]
            .profiles
            .language
            .as_ref()
            .expect("migrated profile");
        assert_eq!(
            profile
                .get("languageType")
                .and_then(serde_json::Value::as_str),
            Some("agglutinative")
        );
        assert!(profile.get("classification").is_none());
        assert!(profile.get("vocabulary").is_none());
        let book = world
            .dictionaries
            .iter()
            .find(|book| book.language_article_id == language_id)
            .expect("migrated dictionary");
        assert_eq!(book.words.len(), 1);
        assert_eq!(book.words[0].related_terms, vec!["urd"]);

        world.migrate_language_document_data();
        let book = world
            .dictionaries
            .iter()
            .find(|book| book.language_article_id == language_id)
            .expect("stable dictionary");
        assert_eq!(book.words.len(), 1, "migration must be idempotent");
    }

