    #[test]
    fn environment_period_tracks_calendar_date_precision() {
        let world = LoadedWorld::load_demo(Language::English).expect("English demo");
        let calendar = world
            .timeline_calendar_article_id
            .as_deref()
            .and_then(|id| world.articles.iter().find(|article| article.id == id))
            .and_then(|article| article.calendar_profile.as_ref())
            .expect("timeline calendar");
        assert_eq!(
            environment_layer_period_label(
                Language::English,
                calendar,
                0,
                EnvironmentLayer::Temperature,
            ),
            "Annual Avg. Temperature"
        );
        if calendar.date_units.len() > 1 {
            let monthly = environment_layer_period_label(
                Language::English,
                calendar,
                1,
                EnvironmentLayer::Humidity,
            );
            assert!(monthly.starts_with(&calendar.date_units[1].name));
        }
        let time_precision = calendar.date_units.len() + calendar.time_units.len();
        let finest_date = calendar.date_units.last().expect("date unit");
        let hourly = environment_layer_period_label(
            Language::English,
            calendar,
            time_precision,
            EnvironmentLayer::WindSpeed,
        );
        assert!(hourly.starts_with(&finest_date.name));
    }

    #[test]
    fn regenerated_demos_use_canonical_discipline_and_item_trees() {
        for language in [Language::Korean, Language::English] {
            let world = LoadedWorld::load_demo(language).expect("regenerated demo");
            let discipline_root = world
                .categories
                .iter()
                .find(|category| category.id == "wiki-category-disciplines")
                .expect("discipline root");
            assert_eq!(
                discipline_root.parent_id.as_deref(),
                Some("wiki-category-civilization-root")
            );
            for key in [
                "discipline_natural_science",
                "discipline_formal_science",
                "discipline_applied_science",
                "discipline_social_science",
                "discipline_humanities",
                "discipline_other",
            ] {
                let leaf = world
                    .categories
                    .iter()
                    .find(|category| category_system_key(category).as_deref() == Some(key))
                    .expect("discipline leaf");
                assert_eq!(leaf.parent_id.as_deref(), Some(discipline_root.id.as_str()));
                assert!(world.articles.iter().any(|article| article.category == key));
            }
            for (key, parent) in [
                ("weapon", "wiki-category-item-root"),
                ("armor", "wiki-category-item-root"),
                ("accessory", "wiki-category-item-root"),
                ("item", "wiki-category-item-root"),
                ("weapon_unique", "wiki-category-unique-item-root"),
                ("armor_unique", "wiki-category-unique-item-root"),
                ("accessory_unique", "wiki-category-unique-item-root"),
                ("item_unique", "wiki-category-unique-item-root"),
            ] {
                let leaf = world
                    .categories
                    .iter()
                    .find(|category| category_system_key(category).as_deref() == Some(key))
                    .expect("item leaf");
                assert_eq!(leaf.parent_id.as_deref(), Some(parent));
                assert!(
                    !world.categories.iter().any(|category| {
                        category.parent_id.as_deref() == Some(leaf.id.as_str())
                    })
                );
                assert!(world.articles.iter().any(|article| article.category == key));
            }
            assert!(world.categories.iter().all(|category| {
                !category_system_key(category).is_some_and(|key| key.starts_with("technology"))
            }));
            assert!(world.dictionaries.len() >= 3);
            assert!(world.dictionaries.iter().all(|book| book.words.len() >= 3));
            assert_eq!(world.generated_glyphs.len(), 3);
            assert_eq!(world.character_charts.len(), 1);
        }
    }

