    #[test]
    fn generated_map_commit_is_append_only_and_preserves_existing_records() {
        let world = LoadedWorld::load_demo(Language::English).expect("English demo");
        let mut maps = world.maps;
        let existing = serde_json::to_vec(&maps).expect("serialize existing maps");
        let mut generated = maps[0].clone();
        generated.title = "Independent Map".to_owned();
        generated.source_id = maps[0].source_id.clone();

        let index = append_generated_map(&mut maps, generated);

        assert_eq!(index, maps.len() - 1);
        assert_eq!(maps[index].title, "Independent Map");
        assert_ne!(maps[index].source_id, maps[0].source_id);
        assert_eq!(
            maps[index].region_id.as_deref(),
            Some(format!("region-{}", maps[index].source_id).as_str())
        );
        assert_eq!(
            maps[index].map_view_id.as_deref(),
            Some(format!("view-{}", maps[index].source_id).as_str())
        );
        assert_eq!(
            serde_json::to_vec(&maps[..index]).expect("serialize preserved maps"),
            existing,
        );
    }

    #[test]
    fn pointer_panel_and_map_info_button_share_the_right_anchor() {
        for viewport in [
            Rect::from_min_max(Pos2::new(0.0, 0.0), Pos2::new(800.0, 600.0)),
            Rect::from_min_max(Pos2::new(224.0, 48.0), Pos2::new(1_920.0, 1_080.0)),
        ] {
            let panel_width = 268.0;
            let (position, right) = map_overlay_anchor_geometry(viewport, panel_width);
            assert!((position.x + panel_width - right).abs() < f32::EPSILON);
            assert!(
                (right - (viewport.right() - theme::Metrics::MAP_EDGE_INSET)).abs() < f32::EPSILON
            );
            let (fixed_pointer, fixed_buttons, fixed_panel, fixed_right) =
                map_overlay_fixed_geometry(viewport, panel_width);
            assert_eq!(fixed_pointer, position);
            assert_eq!(fixed_right, right);
            let icon_pair_width = theme::Metrics::MAP_OVERLAY_ICON_SIZE * 2.0 + 4.0;
            assert!((fixed_buttons.x + icon_pair_width - right).abs() < f32::EPSILON);
            assert_eq!(fixed_panel.x, fixed_pointer.x);
            assert!(fixed_panel.y > fixed_buttons.y);
        }
    }

    #[test]
    fn map_wheel_zoom_keeps_the_world_point_under_the_cursor() {
        let viewport = Rect::from_min_size(Pos2::ZERO, Vec2::new(1_000.0, 500.0));
        let scene = Rect::from_min_size(Pos2::ZERO, Vec2::new(800.0, 800.0));
        let pointer = Pos2::new(750.0, 125.0);
        let aligned = viewport_aligned_scene_rect(scene, viewport.size());
        let fraction = Vec2::new(0.75, 0.25);
        let anchor_before = aligned.min + aligned.size() * fraction;
        let zoomed = cursor_centered_scene_zoom(scene, viewport, pointer, 48.0, 0.45..=24.0);
        let anchor_after = zoomed.min + zoomed.size() * fraction;

        assert!(zoomed.width() < aligned.width());
        assert!((anchor_before.x - anchor_after.x).abs() < 0.001);
        assert!((anchor_before.y - anchor_after.y).abs() < 0.001);
    }

    #[test]
    fn wheel_zoom_does_not_trigger_regional_refinement() {
        let before = crate::diagnostics::thread_pipeline_call_counters();
        let scene = Rect::from_min_size(Pos2::ZERO, Vec2::new(500.0, 300.0));
        let viewport = Rect::from_min_size(Pos2::ZERO, Vec2::new(1_000.0, 600.0));
        let _ = cursor_centered_scene_zoom(scene, viewport, viewport.center(), 120.0, 1.0..=48.0);
        let after = crate::diagnostics::thread_pipeline_call_counters();
        assert_eq!(
            after.regional_refinement_calls,
            before.regional_refinement_calls
        );
    }

