    #[test]
    fn place_metrics_show_exact_or_nearest_records_without_interpolation() {
        let records = vec![
            PlaceMetricRecord {
                world_year: 500,
                date_specified: true,
                absolute_day: None,
                calendar_id: None,
                show_time: false,
                population: Some(1_000.0),
                economy: Some(1_000.0),
            },
            PlaceMetricRecord {
                world_year: 1_000,
                date_specified: true,
                absolute_day: None,
                calendar_id: None,
                show_time: false,
                population: Some(2_000.0),
                economy: Some(2_000.0),
            },
        ];
        let (left, right, exact) = metric_neighbors(&records, 500);
        assert!(exact);
        assert_eq!(left.unwrap().population, Some(1_000.0));
        assert!(right.is_none());
        let (left, right, exact) = metric_neighbors(&records, 100);
        assert!(!exact);
        assert!(left.is_none());
        assert_eq!(right.unwrap().world_year, 500);
        let (left, right, exact) = metric_neighbors(&records, 750);
        assert!(!exact);
        assert_eq!(left.unwrap().world_year, 500);
        assert_eq!(right.unwrap().world_year, 1_000);
        let (left, right, exact) = metric_neighbors(&records, 2_000);
        assert!(!exact);
        assert_eq!(left.unwrap().world_year, 1_000);
        assert!(right.is_none());
    }

    #[test]
    fn genealogy_layout_keeps_couples_together_and_children_below_their_midpoint() {
        let node = |id: &str, generation: i32, role: GenealogyRole| GenealogyNode {
            id: id.to_owned(),
            article_id: None,
            name: id.to_owned(),
            birth: "-".to_owned(),
            death: "-".to_owned(),
            generation,
            role,
            relationship_type: None,
        };
        let mut graph = GenealogyGraph {
            nodes: vec![
                node("father", -1, GenealogyRole::Member),
                node("mother", -1, GenealogyRole::Member),
                node("sibling", 0, GenealogyRole::Sibling),
                node("focus", 0, GenealogyRole::Focus),
                node("spouse", 0, GenealogyRole::Partner),
                node("child", 1, GenealogyRole::Member),
            ],
            edges: vec![
                GenealogyEdge {
                    from: "father".to_owned(),
                    to: "mother".to_owned(),
                    kind: GenealogyEdgeKind::Partner,
                },
                GenealogyEdge {
                    from: "father".to_owned(),
                    to: "focus".to_owned(),
                    kind: GenealogyEdgeKind::ParentChild,
                },
                GenealogyEdge {
                    from: "mother".to_owned(),
                    to: "focus".to_owned(),
                    kind: GenealogyEdgeKind::ParentChild,
                },
                GenealogyEdge {
                    from: "focus".to_owned(),
                    to: "spouse".to_owned(),
                    kind: GenealogyEdgeKind::Partner,
                },
                GenealogyEdge {
                    from: "focus".to_owned(),
                    to: "child".to_owned(),
                    kind: GenealogyEdgeKind::ParentChild,
                },
                GenealogyEdge {
                    from: "spouse".to_owned(),
                    to: "child".to_owned(),
                    kind: GenealogyEdgeKind::ParentChild,
                },
            ],
            family_view: false,
            linguistic_view: false,
        };
        assign_person_relationship_labels(&mut graph, "focus");
        assert_eq!(
            graph
                .nodes
                .iter()
                .find(|node| node.id == "spouse")
                .and_then(|node| node.relationship_type.as_deref()),
            Some("spouse")
        );
        assert_eq!(
            graph
                .nodes
                .iter()
                .find(|node| node.id == "child")
                .and_then(|node| node.relationship_type.as_deref()),
            Some("first_child")
        );
        let mut positioned = std::collections::HashMap::new();
        for generation in [-1, 0, 1] {
            let nodes = graph
                .nodes
                .iter()
                .filter(|node| node.generation == generation)
                .collect::<Vec<_>>();
            for (id, rect) in genealogy_generation_layout(
                &graph,
                &nodes,
                &positioned,
                Rect::from_min_size(
                    Pos2::new(0.0, (generation + 1) as f32 * 100.0),
                    Vec2::new(800.0, 60.0),
                ),
            ) {
                positioned.insert(id, rect);
            }
        }
        let focus = positioned["focus"];
        let spouse = positioned["spouse"];
        let sibling = positioned["sibling"];
        let child = positioned["child"];
        assert!(sibling.center().x < focus.center().x);
        assert!(focus.center().x < spouse.center().x);
        assert!((focus.right() - spouse.left()).abs() <= 6.1);
        assert!((child.center().x - (focus.center().x + spouse.center().x) * 0.5).abs() < 0.1);
        assert!(positioned["father"].bottom() < focus.top());
        assert!(focus.bottom() < child.top());
        assert_eq!(
            genealogy_parent_couple(&graph, "focus", "child"),
            Some(("focus", "spouse"))
        );
    }

